#######################################
#  Save SYSTEM LOGGING
#####################################



def save_system_activity(
    category,
    message,
    severity="INFO",
    spa_id=None,
    related_type=None,
    related_id=None,
    created_by=None
):
    try:
        conn = get_db_connection()
        cur = conn.cursor()

        cur.execute("""
            INSERT INTO system_logs (
                spa_id,
                category,
                severity,
                message,
                related_type,
                related_id,
                created_by
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s)
        """, (
            spa_id,
            category,
            severity,
            message,
            related_type,
            related_id,
            created_by
        ))

        conn.commit()
        cur.close()
        conn.close()

    except Exception as e:
        print(f"[SYSTEM LOGGING ERROR] {e}", flush=True)








