def build_booking_help_context(
    title,
    description,
    primary_page_key
):
    topics = [
        dict(topic)
        for topic in BOOKING_HELP_TOPICS
    ]

    topics.sort(
        key=lambda topic: (
            topic["page_key"] != primary_page_key
        )
    )

    return {
        "title": title,
        "description": description,
        "topics": topics
    }


