@app.route("/api/help-topics")
@login_required
def help_topics_api():

    search_text = request.args.get(
        "q",
        ""
    ).strip()

    language = get_current_language()

    conn = get_db_connection()
    cur = conn.cursor()

    try:

        sql = """
            WITH ranked_help_pages AS (

                SELECT
                    help_page_id,
                    page_key,
                    display_name,
                    title,
                    content,
                    language_code,
                    display_order,

                    ROW_NUMBER() OVER (
                        PARTITION BY page_key
                        ORDER BY
                            CASE
                                WHEN language_code = %s THEN 0
                                WHEN language_code = 'EN' THEN 1
                                ELSE 2
                            END,
                            help_page_id DESC
                    ) AS language_rank

                FROM help_pages

                WHERE is_active = TRUE
                  AND language_code IN (%s, 'EN')
            )

            SELECT
                page_key,

                COALESCE(
                    NULLIF(title, ''),
                    NULLIF(display_name, ''),
                    page_key
                ) AS topic_title

            FROM ranked_help_pages

            WHERE language_rank = 1
        """

        params = [
            language,
            language
        ]

        if search_text:

            like_search = f"%{search_text}%"

            sql += """
                AND (
                       page_key ILIKE %s
                    OR display_name ILIKE %s
                    OR title ILIKE %s
                    OR content ILIKE %s
                )
            """

            params.extend([
                like_search,
                like_search,
                like_search,
                like_search
            ])

        sql += """
            ORDER BY
                LOWER(
                    COALESCE(
                        NULLIF(display_name, ''),
                        NULLIF(title, ''),
                        page_key
                    )
                ),
                page_key

            LIMIT 200
        """

        cur.execute(
            sql,
            tuple(params)
        )

        rows = cur.fetchall()

        topics = [
            {
                "page_key": row[0],
                "title": row[1]
            }
            for row in rows
        ]

        return jsonify({
            "success": True,
            "topics": topics
        })

    except Exception:

        app.logger.exception(
            "Unable to load help topics."
        )

        return jsonify({
            "success": False,
            "message": "Help topics could not be loaded."
        }), 500

    finally:
        cur.close()
        conn.close()







