@app.route("/api/help-page/<page_key>")
@login_required
def help_page_api(page_key):

    page_key = str(
        page_key or ""
    ).strip()

    language = get_current_language()

    if not page_key:
        return jsonify({
            "success": False,
            "message": "No help topic was selected."
        }), 400

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute(
            """
            SELECT
                page_key,
                title,
                content,
                language_code
            FROM help_pages
            WHERE page_key = %s
              AND is_active = TRUE
              AND language_code IN (%s, 'EN')
            ORDER BY
                CASE
                    WHEN language_code = %s THEN 0
                    WHEN language_code = 'EN' THEN 1
                    ELSE 2
                END
            LIMIT 1
            """,
            (
                page_key,
                language,
                language
            )
        )

        help_page = cur.fetchone()

        if help_page is None:
            return jsonify({
                "success": False,
                "message": "The help article was not found."
            }), 404

        return jsonify({
            "success": True,


        "article": {
            "page_key": help_page[0],
            "title": help_page[1],
            "content": help_page[2],
            "language_code": help_page[3]
        }
    })

    except Exception:

        app.logger.exception(
            "Unable to load help article."
        )

        return jsonify({
            "success": False,
            "message": (
                "The selected help article could not be loaded."
            )
        }), 500

    finally:
        cur.close()
        conn.close()

