def master_admin_required(f):
    @wraps(f)
    def decorated_function(*args, **kwargs):
        user_role = (
            session.get("role")
            or session.get("user_role")
        )

        if user_role != "master_admin":
            abort(403)

        return f(*args, **kwargs)

    return decorated_function









