#
#   MASTER ADMIN BUSINESS LIST
#
#
###################################



@app.route("/master-admin/businesses")
@login_required
@master_admin_required
def master_admin_businesses():

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute(
            """
            SELECT
                spa_id,                              -- 0
                spa_name,                            -- 1
                registration_number,                 -- 2
                subscription_status,                 -- 3
                active,                              -- 4
                sms_agreement_status,                 -- 5
                sms_10dlc_status,                    -- 6
                sms_number_assignment_status,        -- 7
                sms_marketing_allowed,               -- 8
                sms_service_suspended,               -- 9
                sms_marketing_suspended              -- 10
            FROM spas
            ORDER BY
                spa_name
            """
        )

        rows = cur.fetchall()

        businesses = []

        for row in rows:

            agreement_status = (
                row[5] or "not_sent"
            )

            ten_dlc_status = (
                row[6] or "not_submitted"
            )

            assignment_status = (
                row[7] or "not_assigned"
            )

            sms_service_enabled = (
                agreement_status == "accepted"
                and ten_dlc_status == "approved"
                and assignment_status == "assigned"
                and not bool(row[9])
            )

            sms_marketing_enabled = (
                sms_service_enabled
                and bool(row[8])
                and not bool(row[10])
            )

            businesses.append(
                {
                    "spa_id": row[0],
                    "spa_name": row[1],
                    "registration_number": row[2],
                    "subscription_status": row[3],
                    "active": bool(row[4]),

                    "sms_agreement_status": agreement_status,
                    "sms_10dlc_status": ten_dlc_status,
                    "sms_number_assignment_status": (
                        assignment_status
                    ),

                    "sms_marketing_allowed": bool(row[8]),
                    "sms_service_suspended": bool(row[9]),
                    "sms_marketing_suspended": bool(row[10]),

                    "sms_service_enabled": (
                        sms_service_enabled
                    ),
                    "sms_marketing_enabled": (
                        sms_marketing_enabled
                    )
                }
            )

        return render_template(
            "master_admin/businesses/businesses.html",
            businesses=businesses
        )

    except Exception as error:

        print(
            "[MASTER ADMIN BUSINESS LIST ERROR]",
            error,
            flush=True
        )

        flash(
            "The business directory could not be loaded.",
            "error"
        )

        return redirect(
            url_for("master_admin_home")
        )

    finally:
        cur.close()
        conn.close()














##################################
#
#   THOUSANDS SEPARATER
#
#
#
####################################

@app.template_filter("currency")
def currency_filter(value):
    try:
        return "${:,.2f}".format(float(value or 0))
    except (TypeError, ValueError):
        return "$0.00"


@app.template_filter("number")
def number_filter(value):
    try:
        return "{:,.2f}".format(float(value or 0))
    except (TypeError, ValueError):
        return "0.00"


@app.template_filter("integer")
def integer_filter(value):
    try:
        return "{:,.0f}".format(float(value or 0))
    except (TypeError, ValueError):
        return "0"








######################################
#
#   BUILD REGISTRATION NUMBER
#
#
##########################################



def build_registration_number(spa_name, spa_id):
    words = spa_name.split()

    initials = "".join(
        word[0].upper()
        for word in words
        if word and word[0].isalnum()
    )

    initials = initials[:3]

    if not initials:
        initials = "BUS"

    return f"PSP-{initials}-{spa_id:06d}"












