#
######################################

import re


def sms_contains_marketing_content(message_body):
    text = (message_body or "").lower()

    marketing_patterns = [
        r"\bfree gift\b",
        r"\bfree product\b",
        r"\bdiscount\b",
        r"\bcoupon\b",
        r"\bpromo(?:tion)?\b",
        r"\bspecial offer\b",
        r"\blimited[- ]time\b",
        r"\bsave \$?\d+",
        r"\b\d+%\s*off\b",
        r"\bbuy one\b",
        r"\bbook (?:now|today)\b",
        r"\bcomplimentary\b",
        r"\bdeal\b",
        r"\bsale\b"
    ]

    return any(
        re.search(pattern, text)
        for pattern in marketing_patterns
    )




