def get_approved_sms_template(
    spa_id,
    template_type,
    language_code=None,
    template_id=None
):
    language_code = normalize_language_code(language_code or get_default_language())
    default_language = normalize_language_code(get_default_language())

    conn = get_db_connection()
    cur = conn.cursor()

    if template_id:
        cur.execute("""
            SELECT
                template_id,
                message_text
            FROM messaging_templates
            WHERE template_id = %s
              AND spa_id = %s
              AND channel = 'sms'
              AND is_active = TRUE
              AND approved_for_use = TRUE
              AND COALESCE(is_archived, FALSE) = FALSE
            LIMIT 1
        """, (template_id, spa_id))

        row = cur.fetchone()

        cur.close()
        conn.close()

        return row

    cur.execute("""
        SELECT
            template_id,
            message_text
        FROM messaging_templates
        WHERE spa_id = %s
          AND channel = 'sms'
          AND template_type = %s
          AND language_code = %s
          AND is_active = TRUE
          AND approved_for_use = TRUE
          AND COALESCE(is_archived, FALSE) = FALSE
        ORDER BY updated_at DESC, template_id DESC
        LIMIT 1
    """, (spa_id, template_type, language_code))

    row = cur.fetchone()

    if not row and language_code != default_language:
        cur.execute("""
            SELECT
                template_id,
                message_text
            FROM messaging_templates
            WHERE spa_id = %s
              AND channel = 'sms'
              AND template_type = %s
              AND language_code = %s
              AND is_active = TRUE
              AND approved_for_use = TRUE
              AND COALESCE(is_archived, FALSE) = FALSE
            ORDER BY updated_at DESC, template_id DESC
            LIMIT 1
        """, (spa_id, template_type, default_language))

        row = cur.fetchone()

    cur.close()
    conn.close()

    return row







