##################################


def log_sms_message(
    spa_id,
    business_unit_id,
    client_id,
    recipient_phone,
    message_body,
    message_type,
    direction,
    status,
    sms_phone_number_id=None,
    sender_phone=None,
    receiving_phone=None,
    provider_message_id=None,
    provider_status=None,
    provider_error_code=None,
    provider_error_message=None
):
    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        INSERT INTO sms_messages (
            spa_id,
            business_unit_id,
            client_id,
            recipient_phone,
            message_body,
            message_type,
            direction,
            status,
            sms_phone_number_id,
            sender_phone,
            receiving_phone,
            provider_message_id,
            provider_status,
            provider_error_code,
            provider_error_message,
            created_at
        )
        VALUES (
            %s, %s, %s, %s, %s,
            %s, %s, %s, %s, %s,
            %s, %s, %s, %s, %s,
            NOW()
        )
    """, (
        spa_id,
        business_unit_id,
        client_id,
        recipient_phone,
        message_body,
        message_type,
        direction,
        status,
        sms_phone_number_id,
        sender_phone,
        receiving_phone,
        provider_message_id,
        provider_status,
        provider_error_code,
        provider_error_message
    ))

    conn.commit()
    cur.close()
    conn.close()





