def send_email_message(
    spa_id,
    client_id,
    recipient_email,
    subject,
    message_body,
    message_type
):
    result = send_email(
        to=recipient_email,
        subject=subject,
        body=message_body
    )

    # Later we can move this to a shared communication log table.
    log_email_message(
        spa_id=spa_id,
        client_id=client_id,
        recipient_email=recipient_email,
        subject=subject,
        message_body=message_body,
        message_type=message_type,
        status="sent"
    )

    return result




##################################
#
#      GET SMS ELIGIBLE CLIENTS
#
##################################


def get_sms_eligible_clients(
    spa_id,
    business_unit_id,
    search="",
    client_status="",
    show_all=False
):
    clients = []

    if not search and not show_all:
        return clients

    conn = get_db_connection()
    cur = conn.cursor()

    query = """
        SELECT
            c.client_id,
            c.first_name,
            c.last_name,
            c.phone,
            cs.status_name
        FROM clients c
        LEFT JOIN client_statuses cs
            ON c.client_status = cs.status_name
        WHERE c.spa_id = %s
          AND c.business_unit_id = %s
          AND c.sms_opt_in = TRUE
          AND COALESCE(c.sms_opt_out, FALSE) = FALSE
          AND c.active_client = TRUE
          AND c.phone IS NOT NULL
          AND TRIM(c.phone) <> ''
    """

    params = [
        spa_id,
        business_unit_id
    ]

    if search:
        query += """
          AND (
               LOWER(c.first_name) LIKE %s
               OR LOWER(c.last_name) LIKE %s
               OR c.phone LIKE %s
          )
        """
        params.extend([
            f"%{search.lower()}%",
            f"%{search.lower()}%",
            f"%{search}%"
        ])

    if client_status:
        query += " AND c.client_status = %s"
        params.append(client_status)

    query += " ORDER BY c.last_name, c.first_name"

    cur.execute(query, params)
    clients = cur.fetchall()

    cur.close()
    conn.close()

    return clients




