#
#      GET CLIENT STATUSES
#
##################################


DEFAULT_CLIENT_STATUSES = (
    "Current",
    "Previous",
    "Prior Client",
    "Inactive",
    "Event Contact",
)


def seed_client_status_defaults(cursor, spa_id):
    """
    Create the standard tenant-owned Client Status options.

    This helper is safe to call repeatedly. Existing options are
    matched without regard to capitalization or surrounding spaces.
    """

    for status_name in DEFAULT_CLIENT_STATUSES:
        cursor.execute("""
            INSERT INTO client_statuses (
                spa_id,
                status_name,
                is_active
            )
            SELECT
                %s,
                %s,
                TRUE
            WHERE NOT EXISTS (
                SELECT 1
                FROM client_statuses
                WHERE spa_id = %s
                  AND LOWER(BTRIM(status_name))
                      = LOWER(BTRIM(%s))
            )
        """, (
            spa_id,
            status_name,
            spa_id,
            status_name,
        ))


def get_client_statuses(spa_id):
    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            client_status_id,
            status_name
        FROM client_statuses
        WHERE spa_id = %s
        ORDER BY status_name
    """, (spa_id,))

    statuses = cur.fetchall()

    cur.close()
    conn.close()

    return statuses





##################################
#
#     GET EMAIL ELIGIBLE CLIENTS
#
##################################


def get_email_eligible_clients(
    spa_id,
    business_unit_id,
    search="",
    client_status="",
    show_all=False
):
    clients = []

    # Allow a status selection to load clients even when
    # there is no search and Show All was not selected.
    if not search and not show_all and not client_status:
        return clients

    conn = get_db_connection()
    cur = conn.cursor()

    query = """
        SELECT
            c.client_id,
            c.first_name,
            c.last_name,
            c.email,
            cs.status_name
        FROM clients c
        LEFT JOIN client_statuses cs
            ON TRIM(c.client_status) = TRIM(cs.status_name)
           AND cs.spa_id = c.spa_id
        WHERE c.spa_id = %s
          AND c.business_unit_id = %s
          AND c.email_opt_in = TRUE
          AND COALESCE(c.email_opt_out, FALSE) = FALSE
          AND c.email IS NOT NULL
          AND TRIM(c.email) <> ''
    """

    params = [
        spa_id,
        business_unit_id
    ]

    if search:
        query += """
          AND (
               LOWER(c.first_name) LIKE %s
               OR LOWER(c.last_name) LIKE %s
               OR LOWER(c.email) LIKE %s
          )
        """

        search_value = f"%{search.lower()}%"

        params.extend([
            search_value,
            search_value,
            search_value
        ])

    if client_status:
        query += """
          AND cs.client_status_id = %s
        """
        params.append(client_status)

    query += """
        ORDER BY
            c.last_name,
            c.first_name
    """

    cur.execute(query, params)
    clients = cur.fetchall()

    cur.close()
    conn.close()

    return clients


