def get_default_language():
    languages = get_supported_languages(active_only=True)

    for lang in languages:
        if lang["is_default"]:
            return lang["language_code"]

    return "EN"







##################################
#
#   SUPPORTED LANGUAGES
#
##################################





from psycopg2.extras import RealDictCursor

def get_supported_languages(active_only=True):
    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=RealDictCursor)

    if active_only:
        cur.execute("""
            SELECT
                language_code,
                language_name,
                native_name,
                locale_code,
                is_default
            FROM supported_languages
            WHERE is_active = TRUE
            ORDER BY display_order, language_name
        """)
    else:
        cur.execute("""
            SELECT
                language_code,
                language_name,
                native_name,
                locale_code,
                is_active,
                is_default
            FROM supported_languages
            ORDER BY display_order, language_name
        """)

    rows = cur.fetchall()

    cur.close()
    conn.close()

    return rows










##################################
#
#   NORMALIZE LANGUAGE CODE
#
##################################





def normalize_language_code(language_code):
    code = (language_code or "").strip().upper()

    supported_languages = get_supported_languages(active_only=True)

    supported_codes = {
        lang["language_code"]
        for lang in supported_languages
    }

    if code in supported_codes:
        return code

    return get_default_language()





##################################
#
#   GET LANGUAGE NAME
#
##################################

def get_language_name(language_code):
    code = normalize_language_code(language_code)

    languages = get_supported_languages(active_only=True)

    for lang in languages:
        if lang["language_code"] == code:
            return lang["native_name"]

    return code
























