#     ENRICH SMS MERGE DATA
#
#################################

def enrich_sms_merge_data(spa_id, template_type, merge_data):
    merge_data = merge_data or {}

    if template_type == "appointment_reminder":
        return enrich_appointment_reminder_merge_data(spa_id, merge_data)

    return merge_data







##################################
#
#     ENRICH APPOINTMENT REMINDER MERGE
#
#################################
def enrich_appointment_reminder_merge_data(spa_id, merge_data):
    reminder_id = merge_data.get("reminder_id")

    if not reminder_id:
        return merge_data

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            c.first_name,
            c.last_name,
            a.appointment_date,
            a.appointment_time,
            a.service_type,
            s.spa_name,
            s.owner_phone,
            NULL AS spa_website
        FROM reminder_queue rq
        JOIN clients c
          ON rq.client_id = c.client_id
         AND rq.spa_id = c.spa_id
        LEFT JOIN appointments a
          ON rq.appointment_id = a.appointment_id
         AND rq.spa_id = a.spa_id
        LEFT JOIN spas s
          ON rq.spa_id = s.spa_id
        WHERE rq.spa_id = %s
          AND rq.reminder_id = %s
        LIMIT 1
    """, (spa_id, reminder_id))

    row = cur.fetchone()

    cur.close()
    conn.close()

    if not row:
        return merge_data

    (
        first_name,
        last_name,
        appointment_date,
        appointment_time,
        service_name,
        spa_name,
        spa_phone,
        spa_website
    ) = row

    merge_data.update({
        "client_first_name": first_name or "",
        "client_last_name": last_name or "",
        "client_full_name": f"{first_name or ''} {last_name or ''}".strip(),
        "appointment_date": appointment_date.strftime("%m/%d/%Y") if appointment_date else "",
        "appointment_time": appointment_time.strftime("%I:%M %p") if appointment_time else "",
        "service_name": service_name or "",
        "spa_name": spa_name or "",
        "spa_phone": spa_phone or "",
        "spa_website": spa_website or ""
    })

    return merge_data





################################
#       SEND BIRTHDAY
#
#
#
#
##############################



def send_birthday_reminder_sms(reminder_id, spa_id):
    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                rq.reminder_id,
                rq.client_id,
                rq.recipient_phone,
                c.business_unit_id,
                c.first_name,
                c.birth_date,
                s.spa_name
            FROM reminder_queue rq
            JOIN clients c
              ON rq.client_id = c.client_id
             AND rq.spa_id = c.spa_id
            JOIN spas s
              ON rq.spa_id = s.spa_id
            WHERE rq.reminder_id = %s
              AND rq.spa_id = %s
              AND rq.reminder_type = 'birthday'
              AND rq.send_method = 'sms'
        """, (
            reminder_id,
            spa_id
        ))

        row = cur.fetchone()

        if not row:
            return False, {
                "success": False,
                "status": "not_found",
                "error": "Birthday reminder not found."
            }

        (
            reminder_id,
            client_id,
            recipient_phone,
            business_unit_id,
            first_name,
            birth_date,
            spa_name
        ) = row

        if not recipient_phone:
            cur.execute("""
                UPDATE reminder_queue
                SET status = 'skipped',
                    error_message = %s
                WHERE reminder_id = %s
                  AND spa_id = %s
            """, (
                "Missing phone number",
                reminder_id,
                spa_id
            ))

            conn.commit()

            return False, {
                "success": False,
                "status": "skipped",
                "error": "Missing phone number."
            }

        merge_data = build_birthday_message_merge_data(
            client_id=client_id,
            first_name=first_name,
            birth_date=birth_date,
            spa_name=spa_name
        )

        merge_data["reminder_id"] = reminder_id

        try:
            result = send_communication(
                spa_id=spa_id,
                business_unit_id=business_unit_id,
                channel="sms",
                recipient=recipient_phone,
                template_type="birthday_message",
                merge_data=merge_data,
                client_id=client_id,
                message_type="marketing"
            )

        except Exception as error:
            result = {
                "success": False,
                "status": "failed",
                "provider_message_id": None,
                "provider_status": None,
                "provider_error_code": None,
                "provider_error_message": str(error),
                "error": str(error),
                "message_body": ""
            }

        success = bool(result.get("success"))

        final_message_body = (
            result.get("message_body")
            or result.get("final_message_body")
            or ""
        )

        result_status = (
            result.get("status")
            or ("sent" if success else "failed")
        )

        error_message = (
            result.get("provider_error_message")
            or result.get("error")
            or "Birthday reminder SMS failed."
        )

        if success:
            cur.execute("""
                UPDATE reminder_queue
                SET status = 'sent',
                    sent_at = NOW(),
                    error_message = NULL
                WHERE reminder_id = %s
                  AND spa_id = %s
            """, (
                reminder_id,
                spa_id
            ))

        else:
            cur.execute("""
                UPDATE reminder_queue
                SET status = 'failed',
                    error_message = %s
                WHERE reminder_id = %s
                  AND spa_id = %s
            """, (
                error_message,
                reminder_id,
                spa_id
            ))

        conn.commit()

        try:
            log_sms_message(
                spa_id=spa_id,
                business_unit_id=business_unit_id,
                client_id=client_id,
                recipient_phone=recipient_phone,
                message_body=final_message_body,
                message_type="birthday",
                direction="outbound",
                status=result_status,
                sms_phone_number_id=result.get(
                    "sms_phone_number_id"
                ),
                sender_phone=result.get(
                    "sender_phone"
                ),
                receiving_phone=result.get(
                    "receiving_phone"
                ),
                provider_message_id=result.get(
                    "provider_message_id"
                ),
                provider_status=result.get(
                    "provider_status"
                ),
                provider_error_code=result.get(
                    "provider_error_code"
                ),
                provider_error_message=(
                    error_message if not success else None
                )
            )

        except Exception as log_error:
            print(
                "[BIRTHDAY REMINDER SMS LOG ERROR]",
                log_error,
                flush=True
            )

        return success, result

    except Exception:
        conn.rollback()
        raise

    finally:
        cur.close()
        conn.close()










