def save_messaging_onboarding(spa_id, **fields):
    conn = get_db_connection()
    cur = conn.cursor()

    allowed_fields = [
        "legal_business_name",
        "dba_name",
        "ein",
        "business_type",
        "industry",
        "years_in_business",

        "owner_name",
        "owner_email",
        "owner_phone",
        "business_address1",
        "business_address2",
        "city",
        "state",
        "postal_code",
        "country",

        "website_url",
        "privacy_policy_url",
        "terms_url",
        "sms_policy_url",
        "opt_in_method",
        "consent_language",
        "sample_message_1",
        "sample_message_2",

        "opt_in_method_primary",
        "consent_language",
        "frequency_disclosed",
        "rates_disclosed",
        "stop_disclosed",
        "help_disclosed",
        "privacy_linked",
        "terms_linked",
        "double_opt_in",
        "consent_record_retention",
        "opt_in_screenshot",
        "consent_last_reviewed"
    ]

    clean_fields = {
        key: value
        for key, value in fields.items()
        if key in allowed_fields
    }

    cur.execute("""
        SELECT onboarding_id
        FROM messaging_onboarding
        WHERE spa_id = %s
    """, (spa_id,))

    existing = cur.fetchone()

    if existing:
        if clean_fields:
            set_clause = ", ".join(
                [f"{key} = %s" for key in clean_fields.keys()]
            )

            values = list(clean_fields.values())
            values.append(spa_id)

            cur.execute(f"""
                UPDATE messaging_onboarding
                SET {set_clause}
                WHERE spa_id = %s
            """, values)

    else:
        columns = ["spa_id"] + list(clean_fields.keys())
        placeholders = ["%s"] * len(columns)
        values = [spa_id] + list(clean_fields.values())

        cur.execute(f"""
            INSERT INTO messaging_onboarding
            ({", ".join(columns)})
            VALUES ({", ".join(placeholders)})
        """, values)

    conn.commit()
    cur.close()
    conn.close()


