def resolve_sms_phone_number(
    spa_id,
    business_unit_id,
    provider="telnyx"
):
    """
    Resolve the active default SMS sender for a workspace.

    A workspace assignment takes priority over a spa-level
    default assignment. Sending fails closed when no active
    assignment exists.
    """

    if not spa_id:
        raise ValueError(
            "resolve_sms_phone_number requires spa_id."
        )

    if not business_unit_id:
        raise ValueError(
            "resolve_sms_phone_number requires business_unit_id."
        )

    normalized_provider = (
        provider or "telnyx"
    ).strip().lower()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                sms_phone_number_id,
                spa_id,
                business_unit_id,
                provider,
                phone_number,
                messaging_profile_id,
                campaign_id
            FROM sms_phone_numbers
            WHERE spa_id = %s
              AND provider = %s
              AND is_active = TRUE
              AND is_default = TRUE
              AND (
                    business_unit_id = %s
                    OR business_unit_id IS NULL
                  )
            ORDER BY
                CASE
                    WHEN business_unit_id = %s THEN 0
                    ELSE 1
                END,
                sms_phone_number_id
            LIMIT 1
        """, (
            spa_id,
            normalized_provider,
            business_unit_id,
            business_unit_id
        ))

        row = cur.fetchone()

    finally:
        cur.close()
        conn.close()

    if not row:
        raise PermissionError(
            "SMS sending is unavailable because this workspace "
            "does not have an active phone-number assignment."
        )

    return {
        "sms_phone_number_id": row[0],
        "spa_id": row[1],
        "business_unit_id": row[2],
        "provider": row[3],
        "phone_number": row[4],
        "messaging_profile_id": row[5],
        "campaign_id": row[6]
    }


def send_compliant_sms(
    spa_id,
    business_unit_id,
    client_id,
    recipient_phone,
    message_body,
    message_type="manual"
):
    if not spa_id:
        raise ValueError(
            "send_compliant_sms requires spa_id."
        )

    if not business_unit_id:
        raise ValueError(
            "send_compliant_sms requires business_unit_id."
        )

    sms_permissions = get_sms_business_permissions(
        spa_id
    )

    print(
        "[SMS COMPLIANCE CHECK]",
        {
            "spa_id": spa_id,
            "message_type": message_type,
            "service_enabled": sms_permissions.get(
                "service_sms_enabled"
            ),
            "marketing_enabled": sms_permissions.get(
                "marketing_sms_enabled"
            ),
            "reason": sms_permissions.get("reason")
        },
        flush=True
    )

    normalized_message_type = (
        message_type or "manual"
    ).strip().lower()

    marketing_message_types = {
        "marketing",
        "promotion",
        "promotional",
        "campaign",
        "mass_marketing"
    }

    explicitly_marketing = (
        normalized_message_type
        in marketing_message_types
    )

    marketing_content_detected = (
        sms_contains_marketing_content(
            message_body
        )
    )

    is_marketing_message = (
        explicitly_marketing
        or marketing_content_detected
    )

    if is_marketing_message:

        if not sms_permissions[
            "marketing_sms_enabled"
        ]:
            raise PermissionError(
                (
                "This message contains promotional "
                "content, but SMS marketing is not "
                "approved for this business."
                )
            )

    else:

        if not sms_permissions[
            "service_sms_enabled"
        ]:
            raise PermissionError(
                sms_permissions["reason"]
                or "SMS service is currently unavailable."
            )

    sender = resolve_sms_phone_number(
        spa_id=spa_id,
        business_unit_id=business_unit_id,
        provider="telnyx"
    )

    final_message = message_body

    result = send_sms_message(
        from_phone=sender["phone_number"],
        to_phone=recipient_phone,
        message_body=final_message
    )

    if not isinstance(result, dict):
        result = {
            "provider_result": result
        }

    result["spa_id"] = spa_id
    result["business_unit_id"] = business_unit_id
    result["client_id"] = client_id
    result["sms_phone_number_id"] = sender[
        "sms_phone_number_id"
    ]
    result["sender_phone"] = sender["phone_number"]
    result["receiving_phone"] = recipient_phone
    result["provider"] = sender["provider"]
    result["message_type"] = normalized_message_type
    result["final_message_body"] = final_message
    result["is_marketing_message"] = (
        is_marketing_message
    )

    return result















