def get_system_setting_int(setting_key, default_value):
    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT setting_value
        FROM system_settings
        WHERE setting_key = %s
        LIMIT 1
    """, (setting_key,))

    row = cur.fetchone()

    cur.close()
    conn.close()

    if not row:
        return default_value

    try:
        return int(row[0])
    except (TypeError, ValueError):
        return default_value







