def get_status_id(status_name):
    from flask import g

    spa_id = g.spa_id

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT gift_certificate_status_id
        FROM gift_certificate_statuses
        WHERE status_name = %s
          AND spa_id = %s
    """, (status_name, spa_id))

    result = cur.fetchone()

    cur.close()
    conn.close()

    return result[0] if result else None



