def parse_bool(value):
    if value is None:
        return None

    value = str(value).strip().lower()

    if value in ("true", "yes", "y", "1", "on"):
        return True
    if value in ("false", "no", "n", "0", "off"):
        return False
    if value in ("none", "", "null"):
        return None

    return None
