@app.context_processor
def inject_spa_name():
    try:
        spa_id = current_spa_id()
        if not spa_id:
            return dict(spa_name="")

        conn = get_db_connection()
        cur = conn.cursor()

        cur.execute("""
            SELECT spa_name
            FROM spas
            WHERE spa_id = %s
        """, (spa_id,))

        spa = cur.fetchone()

        cur.close()
        conn.close()

        return dict(spa_name=spa[0] if spa else "")

    except:
        return dict(spa_name="")







