#
#    SMS PLACEHOLDERS
#
#   ---------------------

def apply_sms_placeholders(message, data):
    if not message:
        return ""

    for key, value in data.items():
        message = message.replace(
            "{" + key + "}",
            str(value or "")
        )

    return message







