import os
import requests

def send_email(
    to,
    subject,
    body,
    html_body=None,
    add_footer=True
):
    if add_footer:
        final_body = add_email_footer(body)
    else:
        final_body = (body or "").strip()

    mailgun_api_key = os.environ.get(
        "MAILGUN_API_KEY",
        ""
    ).strip()

    mailgun_domain = os.environ.get(
        "MAILGUN_DOMAIN",
        ""
    ).strip()

    mailgun_from = os.environ.get(
        "MAILGUN_FROM",
        ""
    ).strip()

    mailgun_payload = {
        "from": mailgun_from,
        "to": [to],
        "subject": subject,
        "text": final_body
    }

    final_html_body = (
        str(html_body or "").strip()
    )

    if final_html_body:
        mailgun_payload["html"] = (
            final_html_body
        )

    response = requests.post(
        (
            "https://api.mailgun.net/v3/"
            f"{mailgun_domain}/messages"
        ),
        auth=(
            "api",
            mailgun_api_key
        ),
        data=mailgun_payload,
        timeout=20
    )

    return response






