def current_dropdown_spa_id():
    """
    Resolve the tenant selected for dropdown administration.

    Regular users use the request-scoped spa. Master Admin uses the
    business selected in the session without changing platform-wide
    current_spa_id() behavior.
    """
    if is_master_admin():
        return session.get("spa_id")

    return current_spa_id()


@app.route("/dropdowns/<dropdown_key>", methods=["GET", "POST"])
@login_required
@spa_required
def manage_dropdown(dropdown_key):
    spa_id = current_dropdown_spa_id()

    if not spa_id:
        flash(
            "Select a business before managing dropdowns.",
            "error",
        )
        return redirect(url_for("admin"))

    config = DROPDOWN_CONFIG.get(dropdown_key)

    if not config:
        flash("Invalid dropdown selected.", "error")
        return redirect(url_for("admin"))

    table = config["table"]
    pk = config["pk"]
    value_col = config["value"]
    extra_col = config.get("extra_value")
    active_col = config.get("active_column")
    spa_scoped = config.get("spa_scoped", True)

    conn = None
    cur = None
    dropdown_labels = {}
    rows = []

    try:
        conn = get_db_connection()
        cur = conn.cursor()

        cur.execute("""
            SELECT dropdown_key, display_label
            FROM spa_dropdown_labels
            WHERE spa_id = %s
        """, (spa_id,))

        label_rows = cur.fetchall()
        dropdown_labels = {
            row[0]: row[1]
            for row in label_rows
        }

        if request.method == "POST":
            value = request.form.get(
                "value",
                "",
            ).strip()

            extra_value = None

            if extra_col:
                extra_value = (
                    request.form.get(
                        "extra_value",
                        "",
                    ).strip()
                    or None
                )

            if not value:
                flash(
                    f"{config['label']} is required.",
                    "error",
                )
                return redirect(
                    url_for(
                        "manage_dropdown",
                        dropdown_key=dropdown_key,
                    )
                )

            select_columns = [pk]

            if active_col:
                select_columns.append(active_col)

            duplicate_conditions = [
                (
                    f"LOWER(BTRIM({value_col})) "
                    "= LOWER(BTRIM(%s))"
                )
            ]
            duplicate_params = [value]

            if spa_scoped:
                duplicate_conditions.append(
                    "spa_id = %s"
                )
                duplicate_params.append(spa_id)

            cur.execute(
                f"""
                    SELECT {", ".join(select_columns)}
                    FROM {table}
                    WHERE {
                        " AND ".join(
                            duplicate_conditions
                        )
                    }
                    LIMIT 1
                """,
                duplicate_params,
            )

            existing = cur.fetchone()

            if existing:
                existing_id = existing[0]
                existing_is_active = (
                    existing[1]
                    if active_col
                    else True
                )

                if active_col and not existing_is_active:
                    update_parts = [
                        f"{active_col} = TRUE"
                    ]
                    update_params = []

                    if extra_col:
                        update_parts.append(
                            f"{extra_col} = %s"
                        )
                        update_params.append(
                            extra_value
                        )

                    update_conditions = [
                        f"{pk} = %s"
                    ]
                    update_params.append(existing_id)

                    if spa_scoped:
                        update_conditions.append(
                            "spa_id = %s"
                        )
                        update_params.append(spa_id)

                    cur.execute(
                        f"""
                            UPDATE {table}
                            SET {", ".join(update_parts)}
                            WHERE {
                                " AND ".join(
                                    update_conditions
                                )
                            }
                        """,
                        update_params,
                    )

                    conn.commit()

                    flash(
                        (
                            f"{value} already existed and "
                            "has been reactivated."
                        ),
                        "success",
                    )

                else:
                    flash(
                        (
                            f"{value} already exists in "
                            f"{config['title']}."
                        ),
                        "error",
                    )

                return redirect(
                    url_for(
                        "manage_dropdown",
                        dropdown_key=dropdown_key,
                    )
                )

            insert_columns = [value_col]
            insert_values = [value]

            if spa_scoped:
                insert_columns.insert(0, "spa_id")
                insert_values.insert(0, spa_id)

            if extra_col:
                insert_columns.append(extra_col)
                insert_values.append(extra_value)

            placeholders = ", ".join(
                ["%s"] * len(insert_values)
            )

            cur.execute(
                f"""
                    INSERT INTO {table} (
                        {", ".join(insert_columns)}
                    )
                    VALUES ({placeholders})
                """,
                insert_values,
            )

            conn.commit()

            flash(
                f"{config['title']} item added.",
                "success",
            )

            return redirect(
                url_for(
                    "manage_dropdown",
                    dropdown_key=dropdown_key,
                )
            )

        select_columns = [pk, value_col]

        if extra_col:
            select_columns.append(extra_col)

        list_conditions = []
        list_params = []

        if spa_scoped:
            list_conditions.append("spa_id = %s")
            list_params.append(spa_id)

        query = f"""
            SELECT {", ".join(select_columns)}
            FROM {table}
        """

        if list_conditions:
            query += (
                " WHERE "
                + " AND ".join(list_conditions)
            )

        query += f" ORDER BY {value_col}"

        cur.execute(query, list_params)
        rows = cur.fetchall()

    except IntegrityError as error:
        if conn:
            conn.rollback()

        print(
            "[DROPDOWN INTEGRITY ERROR]",
            type(error).__name__,
        )

        flash(
            (
                f"That {config['label'].lower()} already "
                "exists or conflicts with another item."
            ),
            "error",
        )

        return redirect(
            url_for(
                "manage_dropdown",
                dropdown_key=dropdown_key,
            )
        )

    except Exception as error:
        if conn:
            conn.rollback()

        print(
            "[DROPDOWN SAVE ERROR]",
            repr(error),
        )

        flash(
            (
                f"{config['title']} could not be saved. "
                "No changes were made."
            ),
            "error",
        )

        return redirect(
            url_for(
                "manage_dropdown",
                dropdown_key=dropdown_key,
            )
        )

    finally:
        if cur:
            cur.close()

        if conn:
            conn.close()

    return render_template(
        "manage_dropdown.html",
        dropdown_key=dropdown_key,
        config=config,
        rows=rows,
        dropdown_labels=dropdown_labels,
    )


@app.route("/dropdowns/<dropdown_key>/delete/<int:item_id>", methods=["POST"])
@login_required
@spa_required
def delete_dropdown_item(dropdown_key, item_id):
    spa_id = current_dropdown_spa_id()

    if not spa_id:
        flash(
            "Select a business before managing dropdowns.",
            "error",
        )
        return redirect(url_for("admin"))

    config = DROPDOWN_CONFIG.get(dropdown_key)

    if not config:
        flash("Invalid dropdown selected.", "error")
        return redirect(url_for("admin"))

    table = config["table"]
    pk = config["pk"]

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute(f"""
        DELETE FROM {table}
        WHERE {pk} = %s
          AND spa_id = %s
    """, (item_id, spa_id))

    if cur.rowcount == 0:
        flash("Item not found or not authorized.", "error")
    else:
        flash("Item deleted.", "success")

    conn.commit()
    cur.close()
    conn.close()

    return redirect(url_for("manage_dropdown", dropdown_key=dropdown_key))





