def public_website_about_photo():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if not business_unit_id:
        abort(403)

    public_website_url = (
        _get_public_website_url_for_workspace(
            spa_id,
            business_unit_id
        )
    )

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                about_image_url,
                about_image_public_id,
                about_image_alt
            FROM public_website_settings
            WHERE spa_id = %s
              AND business_unit_id = %s
        """, (
            spa_id,
            business_unit_id,
        ))

        row = cur.fetchone()

        if not row:
            defaults = (
                PUBLIC_WEBSITE_DEFAULTS.copy()
            )

            cur.execute("""
                INSERT INTO public_website_settings (
                    spa_id,
                    business_unit_id,
                    website_tagline,
                    hero_headline,
                    hero_description,
                    intro_heading,
                    intro_description,
                    show_about_section,
                    about_heading,
                    about_description,
                    about_image_url,
                    about_image_public_id,
                    about_image_alt,
                    services_heading,
                    services_description,
                    booking_heading,
                    booking_description
                )
                VALUES (
                    %s, %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s, %s,
                    %s, %s, %s, %s,
                    %s
                )
                ON CONFLICT (
                    spa_id,
                    business_unit_id
                )
                DO NOTHING
            """, (
                spa_id,
                business_unit_id,
                defaults["website_tagline"],
                defaults["hero_headline"],
                defaults["hero_description"],
                defaults["intro_heading"],
                defaults["intro_description"],
                defaults["show_about_section"],
                defaults["about_heading"],
                defaults["about_description"],
                defaults["about_image_url"] or None,
                None,
                defaults["about_image_alt"] or None,
                defaults["services_heading"],
                defaults["services_description"],
                defaults["booking_heading"],
                defaults["booking_description"],
            ))

            conn.commit()

            cur.execute("""
                SELECT
                    about_image_url,
                    about_image_public_id,
                    about_image_alt
                FROM public_website_settings
                WHERE spa_id = %s
                  AND business_unit_id = %s
            """, (
                spa_id,
                business_unit_id,
            ))

            row = cur.fetchone()

        if not row:
            raise RuntimeError(
                "Public website settings could not "
                "be initialized."
            )

        settings = {
            "about_image_url": row[0] or "",
            "about_image_public_id": row[1] or "",
            "about_image_alt": row[2] or "",
        }

        if request.method == "POST":
            action = (
                request.form.get("action")
                or "upload"
            ).strip().lower()

            if action == "remove":
                public_id_to_remove = (
                    settings["about_image_public_id"]
                )

                cur.execute("""
                    UPDATE public_website_settings
                    SET
                        about_image_url = NULL,
                        about_image_public_id = NULL,
                        updated_at = NOW()
                    WHERE spa_id = %s
                      AND business_unit_id = %s
                """, (
                    spa_id,
                    business_unit_id,
                ))

                conn.commit()

                if public_id_to_remove:
                    try:
                        remove_cloudinary_image(
                            public_id_to_remove
                        )

                    except Exception:
                        app.logger.exception(
                            "Cloudinary About photo "
                            "cleanup failed."
                        )

                        flash(
                            (
                                "The photo was removed from "
                                "the website, but Cloudinary "
                                "cleanup could not be completed."
                            ),
                            "warning"
                        )

                flash(
                    "About photo removed.",
                    "success"
                )

                return redirect(
                    url_for(
                        "public_website_about_photo"
                    )
                )

            if action != "upload":
                flash(
                    "Invalid About photo action.",
                    "error"
                )

                return redirect(
                    url_for(
                        "public_website_about_photo"
                    )
                )

            uploaded_file = request.files.get(
                "about_image_file"
            )

            image_alt = (
                request.form.get(
                    "about_image_alt"
                )
                or ""
            ).strip()

            settings["about_image_alt"] = image_alt

            upload_error = (
                validate_about_image_upload(
                    uploaded_file
                )
            )

            if upload_error:
                flash(
                    upload_error,
                    "error"
                )

                return render_template(
                    "public_website_about_photo.html",
                    settings=settings,
                    public_website_url=(
                        public_website_url
                    )
                )

            if not image_alt:
                flash(
                    (
                        "About Image Alt Text is "
                        "required."
                    ),
                    "error"
                )

                return render_template(
                    "public_website_about_photo.html",
                    settings=settings,
                    public_website_url=(
                        public_website_url
                    )
                )

            if len(image_alt) > 250:
                flash(
                    (
                        "About Image Alt Text must be "
                        "250 characters or fewer."
                    ),
                    "error"
                )

                return render_template(
                    "public_website_about_photo.html",
                    settings=settings,
                    public_website_url=(
                        public_website_url
                    )
                )

            try:
                upload_result = (
                    upload_about_image_to_cloudinary(
                        uploaded_file,
                        spa_id,
                        business_unit_id
                    )
                )

            except Exception:
                app.logger.exception(
                    "Could not upload About photo."
                )

                flash(
                    (
                        "The About photo could not be "
                        "uploaded. Please try again."
                    ),
                    "error"
                )

                return render_template(
                    "public_website_about_photo.html",
                    settings=settings,
                    public_website_url=(
                        public_website_url
                    )
                )

            cur.execute("""
                UPDATE public_website_settings
                SET
                    about_image_url = %s,
                    about_image_public_id = %s,
                    about_image_alt = %s,
                    updated_at = NOW()
                WHERE spa_id = %s
                  AND business_unit_id = %s
            """, (
                upload_result["secure_url"],
                upload_result["public_id"],
                image_alt,
                spa_id,
                business_unit_id,
            ))

            conn.commit()

            flash(
                "About photo uploaded successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "public_website_about_photo"
                )
            )

        return render_template(
            "public_website_about_photo.html",
            settings=settings,
            public_website_url=public_website_url
        )

    finally:
        cur.close()
        conn.close()


