@app.route(
    "/public-website-menu-items/"
    "<int:menu_item_id>/toggle",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def toggle_public_website_menu_item(
    menu_item_id
):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if not business_unit_id:
        abort(403)

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                item_name,
                is_active
            FROM public_website_menu_items
            WHERE menu_item_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
        """, (
            menu_item_id,
            spa_id,
            business_unit_id
        ))

        row = cur.fetchone()

        if not row:
            flash(
                "Menu item not found.",
                "error"
            )

            return redirect(
                url_for(
                    "public_website_menu_items"
                )
            )

        new_status = not bool(row[1])

        cur.execute("""
            UPDATE public_website_menu_items
            SET
                is_active = %s,
                updated_at = NOW()
            WHERE menu_item_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
        """, (
            new_status,
            menu_item_id,
            spa_id,
            business_unit_id
        ))

        conn.commit()

        flash(
            (
                f"{row[0]} is now "
                f"{'shown' if new_status else 'hidden'}."
            ),
            "success"
        )

    finally:
        cur.close()
        conn.close()

    return redirect(
        url_for(
            "public_website_menu_items"
        )
    )


