@app.route("/public-website-services")
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def public_website_services():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if not business_unit_id:
        abort(403)

    status_filter = (
        request.args.get("status")
        or "all"
    ).strip().lower()

    if status_filter not in {
        "shown",
        "hidden",
        "all"
    }:
        status_filter = "all"

    query = """
        SELECT
            snt.service_type_id,
            snt.service_name,
            snt.default_duration_minutes,
            snt.default_price,
            COALESCE(
                pws.public_description,
                ''
            ) AS public_description,
            COALESCE(
                pws.show_on_public_website,
                FALSE
            ) AS show_on_public_website,
            pws.website_sort_order

        FROM service_name_types snt

        LEFT JOIN public_website_services pws
          ON pws.service_type_id =
                snt.service_type_id
         AND pws.spa_id =
                snt.spa_id
         AND pws.business_unit_id = %s

        WHERE snt.spa_id = %s
          AND snt.is_active = TRUE
    """

    params = [
        business_unit_id,
        spa_id,
    ]

    if status_filter == "shown":
        query += """
          AND COALESCE(
                pws.show_on_public_website,
                FALSE
              ) = TRUE
        """

    elif status_filter == "hidden":
        query += """
          AND COALESCE(
                pws.show_on_public_website,
                FALSE
              ) = FALSE
        """

    query += """
        ORDER BY
            COALESCE(
                pws.show_on_public_website,
                FALSE
            ) DESC,
            pws.website_sort_order NULLS LAST,
            snt.service_name,
            snt.service_type_id
    """

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute(
            query,
            tuple(params)
        )

        services = cur.fetchall()

        cur.execute("""
            SELECT
                COUNT(*) FILTER (
                    WHERE COALESCE(
                        pws.show_on_public_website,
                        FALSE
                    ) = TRUE
                ),
                COUNT(*) FILTER (
                    WHERE COALESCE(
                        pws.show_on_public_website,
                        FALSE
                    ) = FALSE
                )

            FROM service_name_types snt

            LEFT JOIN public_website_services pws
              ON pws.service_type_id =
                    snt.service_type_id
             AND pws.spa_id =
                    snt.spa_id
             AND pws.business_unit_id = %s

            WHERE snt.spa_id = %s
              AND snt.is_active = TRUE
        """, (
            business_unit_id,
            spa_id,
        ))

        count_row = cur.fetchone()

        shown_count = count_row[0] or 0
        hidden_count = count_row[1] or 0

    finally:
        cur.close()
        conn.close()

    public_website_url = (
        _get_public_website_url_for_workspace(
            spa_id,
            business_unit_id
        )
    )

    public_services_url = (
        f"{public_website_url}#services"
        if public_website_url
        else ""
    )

    return render_template(
        "public_website_services.html",
        services=services,
        status_filter=status_filter,
        shown_count=shown_count,
        hidden_count=hidden_count,
        public_services_url=public_services_url
    )


@app.route(
    "/public-website-services/"
    "<int:service_type_id>/edit",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def edit_public_website_service(
    service_type_id
):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if not business_unit_id:
        abort(403)

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                snt.service_type_id,
                snt.service_name,
                snt.default_duration_minutes,
                snt.default_price,
                COALESCE(
                    pws.public_description,
                    ''
                ),
                COALESCE(
                    pws.show_on_public_website,
                    FALSE
                ),
                pws.website_sort_order

            FROM service_name_types snt

            LEFT JOIN public_website_services pws
              ON pws.service_type_id =
                    snt.service_type_id
             AND pws.spa_id =
                    snt.spa_id
             AND pws.business_unit_id = %s

            WHERE snt.service_type_id = %s
              AND snt.spa_id = %s
              AND snt.is_active = TRUE

            LIMIT 1
        """, (
            business_unit_id,
            service_type_id,
            spa_id,
        ))

        service = cur.fetchone()

        if not service:
            flash(
                "Website service not found.",
                "error"
            )

            return redirect(
                url_for(
                    "public_website_services"
                )
            )

        if request.method == "POST":
            public_description = (
                request.form.get(
                    "public_description"
                )
                or ""
            ).strip()

            show_on_public_website = (
                "show_on_public_website"
                in request.form
            )

            website_sort_order_raw = (
                request.form.get(
                    "website_sort_order"
                )
                or ""
            ).strip()

            if len(public_description) > 500:
                flash(
                    (
                        "Public website description "
                        "must be 500 characters or fewer."
                    ),
                    "error"
                )

                return render_template(
                    "public_website_service_form.html",
                    service=service,
                    submitted=request.form
                )

            website_sort_order = None

            if website_sort_order_raw:
                try:
                    website_sort_order = int(
                        website_sort_order_raw
                    )
                except (
                    TypeError,
                    ValueError
                ):
                    flash(
                        (
                            "Website display order "
                            "must be a number."
                        ),
                        "error"
                    )

                    return render_template(
                        "public_website_service_form.html",
                        service=service,
                        submitted=request.form
                    )

                if not 1 <= website_sort_order <= 999:
                    flash(
                        (
                            "Website display order must "
                            "be between 1 and 999."
                        ),
                        "error"
                    )

                    return render_template(
                        "public_website_service_form.html",
                        service=service,
                        submitted=request.form
                    )

            cur.execute("""
                INSERT INTO public_website_services (
                    spa_id,
                    business_unit_id,
                    service_type_id,
                    public_description,
                    show_on_public_website,
                    website_sort_order
                )
                VALUES (
                    %s,
                    %s,
                    %s,
                    %s,
                    %s,
                    %s
                )

                ON CONFLICT (
                    spa_id,
                    business_unit_id,
                    service_type_id
                )

                DO UPDATE SET
                    public_description =
                        EXCLUDED.public_description,
                    show_on_public_website =
                        EXCLUDED.show_on_public_website,
                    website_sort_order =
                        EXCLUDED.website_sort_order,
                    updated_at = NOW()
            """, (
                spa_id,
                business_unit_id,
                service_type_id,
                public_description or None,
                show_on_public_website,
                website_sort_order,
            ))

            conn.commit()

            flash(
                "Website service updated successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "public_website_services"
                )
            )

        return render_template(
            "public_website_service_form.html",
            service=service,
            submitted=None
        )

    finally:
        cur.close()
        conn.close()


