@app.route("/service-types")
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def service_types():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if not business_unit_id:
        abort(403)

    status_filter = (
        request.args.get("status")
        or "active"
    ).strip().lower()

    if status_filter not in {
        "active",
        "archived",
        "all"
    }:
        status_filter = "active"

    query = """
        SELECT
            service_type_id,
            service_name,
            default_duration_minutes,
            default_price,
            is_active
        FROM service_name_types
        WHERE spa_id = %s
    """



    params = [spa_id]

    if status_filter == "active":
        query += """
            AND is_active = TRUE
        """

    elif status_filter == "archived":
        query += """
            AND is_active = FALSE
        """

    query += """
        ORDER BY
            is_active DESC,
            service_name,
            service_type_id
    """

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute(
            query,
            tuple(params)
        )

        services = cur.fetchall()

        cur.execute("""
            SELECT
                COUNT(*) FILTER (
                    WHERE is_active = TRUE
                ) AS active_count,

                COUNT(*) FILTER (
                    WHERE is_active = FALSE
                ) AS archived_count
            FROM service_name_types
            WHERE spa_id = %s
        """, (spa_id,))

        count_row = cur.fetchone()

        active_count = count_row[0] or 0
        archived_count = count_row[1] or 0

    finally:
        cur.close()
        conn.close()

    public_website_url = (
        _get_public_website_url_for_workspace(
            spa_id,
            business_unit_id
        )
    )

    public_services_url = (
        f"{public_website_url}#services"
        if public_website_url
        else ""
    )

    return render_template(
        "service_types.html",
        services=services,
        status_filter=status_filter,
        active_count=active_count,
        archived_count=archived_count,
        public_services_url=public_services_url
    )





