############################################
#
#   SERVICE CATALOG - ARCHIVE
#
############################################


@app.route(
    "/service-types/<int:service_type_id>/archive",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def archive_service_type(service_type_id):
    spa_id = current_spa_id()
    user_id = session.get("user_id")

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                service_name,
                is_active
            FROM service_name_types
            WHERE service_type_id = %s
              AND spa_id = %s
            FOR UPDATE
        """, (
            service_type_id,
            spa_id
        ))

        service = cur.fetchone()

        if not service:
            conn.rollback()

            flash(
                "Service could not be found.",
                "error"
            )

        elif not service[1]:
            conn.rollback()

            flash(
                "This service is already archived.",
                "warning"
            )

        else:
            cur.execute("""
                UPDATE service_name_types
                SET is_active = FALSE
                WHERE service_type_id = %s
                  AND spa_id = %s
            """, (
                service_type_id,
                spa_id
            ))

            cur.execute("""
                UPDATE provider_service_types
                SET
                    is_active = FALSE,
                    is_publicly_bookable = FALSE,
                    updated_at = CURRENT_TIMESTAMP,
                    updated_by = %s
                WHERE spa_id = %s
                  AND service_type_id = %s
                  AND is_active = TRUE
            """, (
                user_id,
                spa_id,
                service_type_id
            ))

            conn.commit()

            flash(
                f"{service[0]} was archived successfully.",
                "success"
            )

    except Exception as error:
        conn.rollback()

        print(
            "ARCHIVE SERVICE ERROR:",
            error
        )

        flash(
            "The service could not be archived.",
            "error"
        )

    finally:
        cur.close()
        conn.close()

    return redirect(
        url_for(
            "service_types",
            status="active"
        )
    )


