################################
#
#   MASTER ADMIN ADD
#
#
############################################


@app.route(
    "/master-admin/businesses/add",
    methods=["GET", "POST"]
)
@login_required
@master_admin_required
def master_admin_add_business():

    if request.method == "GET":
        return render_template(
            "master_admin/businesses/add_business.html",
            form_data={},
            error_message=None
        )

    # -----------------------------------------
    # Read submitted form
    # -----------------------------------------
    form_data = request.form.to_dict()

    spa_name = request.form.get("spa_name", "").strip()
    owner_first_name = request.form.get(
        "owner_first_name",
        ""
    ).strip()
    owner_last_name = request.form.get(
        "owner_last_name",
        ""
    ).strip()
    owner_phone = request.form.get(
        "owner_phone",
        ""
    ).strip()
    owner_email = request.form.get(
        "owner_email",
        ""
    ).strip().lower()

    timezone_name = request.form.get(
        "timezone_name",
        "America/Chicago"
    ).strip()

    subscription_status = request.form.get(
        "subscription_status",
        "Trial"
    ).strip()

    temporary_password = request.form.get(
        "temporary_password",
        ""
    )

    confirm_password = request.form.get(
        "confirm_password",
        ""
    )

    # Never send passwords back to the template
    form_data.pop("temporary_password", None)
    form_data.pop("confirm_password", None)

    # -----------------------------------------
    # Validation
    # -----------------------------------------
    if not spa_name:
        return render_template(
            "master_admin/businesses/add_business.html",
            form_data=form_data,
            error_message="Business name is required."
        )

    if not owner_first_name or not owner_last_name:
        return render_template(
            "master_admin/businesses/add_business.html",
            form_data=form_data,
            error_message=(
                "Administrator first and last name are required."
            )
        )

    if not owner_email:
        return render_template(
            "master_admin/businesses/add_business.html",
            form_data=form_data,
            error_message="Administrator email is required."
        )

    if len(temporary_password) < 10:
        return render_template(
            "master_admin/businesses/add_business.html",
            form_data=form_data,
            error_message=(
                "Temporary password must contain at least "
                "10 characters."
            )
        )

    if temporary_password != confirm_password:
        return render_template(
            "master_admin/businesses/add_business.html",
            form_data=form_data,
            error_message="The temporary passwords do not match."
        )

    conn = None
    cur = None

    try:
        conn = get_db_connection()
        cur = conn.cursor()

        # -----------------------------------------
        # Prevent duplicate business
        # -----------------------------------------
        cur.execute(
            """
            SELECT spa_id
            FROM spas
            WHERE LOWER(spa_name) = LOWER(%s)
            LIMIT 1
            """,
            (spa_name,)
        )

        if cur.fetchone():
            return render_template(
                "master_admin/businesses/add_business.html",
                form_data=form_data,
                error_message=(
                    "A business with this name already exists."
                )
            )

        # -----------------------------------------
        # Prevent duplicate administrator login
        # -----------------------------------------
        cur.execute(
            """
            SELECT user_id
            FROM users
            WHERE LOWER(email) = LOWER(%s)
               OR LOWER(username) = LOWER(%s)
            LIMIT 1
            """,
            (owner_email, owner_email)
        )

        if cur.fetchone():
            return render_template(
                "master_admin/businesses/add_business.html",
                form_data=form_data,
                error_message=(
                    "A user with this email address already exists."
                )
            )

        # -----------------------------------------
        # Resolve Enterprise foundation defaults
        # -----------------------------------------
        cur.execute("""
            SELECT
                st.subscription_tier_id,
                ot.organization_type_id

            FROM subscription_tiers st
            CROSS JOIN organization_types ot

            WHERE st.tier_code = 'solo'
              AND st.is_active = TRUE
              AND ot.type_code = 'solo_owner'
              AND ot.is_active = TRUE

            LIMIT 1
        """)

        enterprise_defaults = cur.fetchone()

        if not enterprise_defaults:
            raise RuntimeError(
                "Required Solo / Solo Owner "
                "Enterprise defaults were not found."
            )

        subscription_tier_id = (
            enterprise_defaults[0]
        )

        organization_type_id = (
            enterprise_defaults[1]
        )

        # -----------------------------------------
        # Create business
        # -----------------------------------------
        cur.execute(
            """
            INSERT INTO spas (
                spa_name,
                owner_first_name,
                owner_last_name,
                owner_phone,
                owner_email,
                timezone_name,
                subscription_status,
                subscription_tier_id,
                organization_type_id,
                active
            )
            VALUES (
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                %s,
                TRUE
            )
            RETURNING spa_id
            """,
            (
                spa_name,
                owner_first_name,
                owner_last_name,
                owner_phone or None,
                owner_email,
                timezone_name,
                subscription_status,
                subscription_tier_id,
                organization_type_id
            )
        )

        spa_id = cur.fetchone()[0]

        seed_client_status_defaults(
            cur,
            spa_id,
        )

        registration_number = build_registration_number(
            spa_name,
            spa_id
        )

        cur.execute(
            """
            UPDATE spas
            SET registration_number = %s
            WHERE spa_id = %s
            """,
            (
                registration_number,
                spa_id
            )
        )



        # -----------------------------------------
        # Create business administrator
        # -----------------------------------------
        password_hash = generate_password_hash(
            temporary_password
        )

        cur.execute(
            """
            INSERT INTO users (
                spa_id,
                first_name,
                last_name,
                email,
                username,
                password_hash,
                role,
                active,
                preferred_language
            )
            VALUES (
                %s, %s, %s, %s, %s, %s,
                'admin', TRUE, 'EN'
            )
            RETURNING user_id
            """,
            (
                spa_id,
                owner_first_name,
                owner_last_name,
                owner_email,
                owner_email,
                password_hash
            )
        )

        user_id = cur.fetchone()[0]

        # -----------------------------------------
        # Provision Enterprise workspace,
        # booking, and public website foundation.
        #
        # This remains inside the same transaction.
        # Any failure rolls back the entire business.
        # -----------------------------------------
        foundation = (
            _provision_new_business_workspace_foundation(
                cur,
                spa_id=spa_id,
                administrator_user_id=user_id,
                business_name=spa_name,
                actor_user_id=session.get("user_id"),
                contact_email=owner_email,
                contact_phone=owner_phone
            )
        )

        conn.commit()

        flash(
            (
                f"{spa_name} was created successfully. "
                f"Registration Number: {registration_number}. "
                f"Business ID: {spa_id}. "
                f"Administrator ID: {user_id}. "
                f"Workspace ID: "
                f"{foundation['business_unit_id']}."
            ),
            "success"
        )

        return redirect(url_for("master_admin_home"))

    except Exception as error:
        if conn:
            conn.rollback()

        print(
            "[MASTER ADMIN CREATE BUSINESS ERROR]",
            error
        )

        return render_template(
            "master_admin/businesses/add_business.html",
            form_data=form_data,
            error_message=(
                "The business could not be created. "
                "No changes were saved."
            )
        )

    finally:
        if cur:
            cur.close()

        if conn:
            conn.close()









