@app.route("/login", methods=["GET", "POST"])
def login():
    if request.method == "POST":
        email = request.form.get("email", "").strip().lower()
        password = request.form.get("password", "")

        conn = get_db_connection()
        cur = conn.cursor()

        cur.execute("""
            SELECT user_id, spa_id, first_name, last_name, email, password_hash, role
            FROM users
            WHERE LOWER(email) = %s
              AND active = TRUE
        """, (email,))

        user = cur.fetchone()

        cur.close()
        conn.close()

        if not user:
            log_scheduler("Login failed: user account not found.")
            flash("Invalid email or password.", "error")
            return render_template("login.html")

        password_match = check_password_hash(user[5], password)

        if not password_match:
            log_scheduler("Login failed: invalid password.")
            flash("Invalid email or password.", "error")
            return render_template("login.html")

        role = user[6]

        session.clear()
        session["user_id"] = user[0]
        session["spa_id"] = user[1]
        session["first_name"] = user[2]
        session["last_name"] = user[3]
        session["email"] = user[4]
        session["role"] = role


        session["show_login_splash"] = True

        flash("Logged in successfully.", "success")


        if role == "master_admin":
            return redirect(
                url_for("master_admin_home")
            )

        return redirect(
            url_for("morning_briefing")
        )

    return render_template("login.html")










