@app.route(
    "/admin/messaging-compliance/templates/<int:template_id>/duplicate",
    methods=["POST"]
)
@login_required
@spa_required
def duplicate_messaging_template(template_id):

    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            channel,
            template_type,
            template_name,
            language_code,
            subject_text,
            message_text
        FROM messaging_templates
        WHERE template_id = %s
          AND spa_id = %s
          AND COALESCE(is_archived, FALSE) = FALSE
        LIMIT 1
    """, (template_id, spa_id))

    original = cur.fetchone()

    if not original:
        cur.close()
        conn.close()
        flash("Template not found or cannot be duplicated.", "warning")
        return redirect(url_for("template_review", channel="sms"))

    channel = original[0]

    required_permission = (
        "can_manage_sms_templates"
        if channel == "sms"
        else "can_manage_email_templates"
    )

    access = current_workspace_access()

    if not access.get(required_permission, False):
        cur.close()
        conn.close()
        abort(403)

    template_type = original[1]
    template_name = original[2] or "Template"
    language_code = original[3] or "en"
    subject_text = original[4]
    message_text = original[5]

    copy_base = f"{template_name} Copy"

    cur.execute("""
        SELECT template_name
        FROM messaging_templates
        WHERE spa_id = %s
        AND channel = %s
        AND template_type = %s
        AND COALESCE(is_archived, FALSE) = FALSE
    """, (
        spa_id,
        channel,
        template_type
    ))

    existing_names = {
        row[0].strip()
        for row in cur.fetchall()
        if row[0]
    }

    if copy_base not in existing_names:
        new_template_name = copy_base
    else:
        counter = 2

        while f"{copy_base} {counter}" in existing_names:
            counter += 1

        new_template_name = f"{copy_base} {counter}"


    cur.execute("""
        INSERT INTO messaging_templates
        (
            spa_id,
            channel,
            template_type,
            template_name,
            language_code,
            subject_text,
            message_text,
            is_active,
            approved_for_use,
            is_archived,
            ai_score,
            ai_review,
            ai_risk_level,
            created_at,
            updated_at
        )
        VALUES
        (
            %s, %s, %s, %s, %s, %s, %s,
            FALSE, FALSE, FALSE,
            NULL, NULL, NULL,
            NOW(), NOW()
        )
        RETURNING template_id
    """, (
        spa_id,
        channel,
        template_type,
        new_template_name,
        language_code,
        subject_text,
        message_text
    ))

    new_template_id = cur.fetchone()[0]

    conn.commit()


    cur.close()
    conn.close()

    flash("Template duplicated. Review and save before using.", "success")

    return redirect(url_for(
        "edit_messaging_template_by_id",
        template_id=new_template_id
    ))































