def get_current_language():
    user_id = session.get("user_id")

    if not user_id:
        return "EN"

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT preferred_language
        FROM users
        WHERE user_id = %s
    """, (user_id,))

    row = cur.fetchone()

    cur.close()
    conn.close()

    language = row[0] if row and row[0] else "EN"
    language = language.strip().upper()

    if language not in ("EN", "ES"):
        language = "EN"

    return language







