@app.route("/help/<page_key>")
@login_required
@spa_required
def view_help_page(page_key):


    conn = get_db_connection()
    cur = conn.cursor()

    # 1. Try the user's preferred language first
    requested_language = get_current_language()

    cur.execute("""
        SELECT title, content, language_code
        FROM help_pages
        WHERE page_key = %s
        AND language_code = %s
        AND is_active = TRUE
        ORDER BY help_page_id DESC
        LIMIT 1
    """, (page_key, requested_language))

    page = cur.fetchone()

    # 2. Fallback to English
    if not page and requested_language.upper() != "EN":
        cur.execute("""
            SELECT title, content, language_code
            FROM help_pages
            WHERE page_key = %s
              AND language_code = 'EN'
              AND is_active = TRUE
            ORDER BY help_page_id DESC
            LIMIT 1
        """, (page_key,))

        page = cur.fetchone()

    cur.close()
    conn.close()

    if not page:
        flash("Help page not found.", "warning")
        return redirect(url_for("help_center"))

    return render_template(
        "help_page.html",
        page=page,
        page_key=page_key,
        selected_language=page[2]
    )



