#   -------------------------
#
#
#    HELP
#
#
#
#   -------------------------



@app.route("/help")
@login_required
@spa_required
def help_center():

    search = request.args.get(
        "search",
        ""
    ).strip()

    language = get_current_language()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        sql = """
            WITH ranked_help_pages AS (
                SELECT
                    help_page_id,
                    page_key,
                    display_name,
                    title,
                    language_code,
                    display_order,
                    content,

                    ROW_NUMBER() OVER (
                        PARTITION BY page_key
                        ORDER BY
                            CASE
                                WHEN language_code = %s THEN 0
                                WHEN language_code = 'EN' THEN 1
                                ELSE 2
                            END,
                            help_page_id DESC
                    ) AS language_rank

                FROM help_pages

                WHERE is_active = TRUE
                  AND language_code IN (%s, 'EN')
            )

            SELECT
                page_key,
                display_name,
                title,
                language_code,
                display_order

            FROM ranked_help_pages

            WHERE language_rank = 1
        """

        params = [
            language,
            language
        ]

        if search:
            search_term = f"%{search}%"

            sql += """
                AND (
                       page_key ILIKE %s
                    OR display_name ILIKE %s
                    OR title ILIKE %s
                    OR content ILIKE %s
                )
            """

            params.extend([
                search_term,
                search_term,
                search_term,
                search_term
            ])

        sql += """
            ORDER BY
                LOWER(
                    COALESCE(
                        NULLIF(display_name, ''),
                        NULLIF(title, ''),
                        page_key
                    )
                ),
                page_key
        """

        cur.execute(
            sql,
            tuple(params)
        )

        pages = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    return render_template(
        "help_center.html",
        pages=pages,
        search=search
    )






