@app.route("/sms-email-terms", methods=["GET", "POST"])
@login_required
@spa_required
def sms_email_terms():

    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    # Load help page content
    cur.execute("""
        SELECT title, content
        FROM help_pages
        WHERE page_key = %s
          AND spa_id = %s
          AND is_active = TRUE
    """, ("sms_email_terms", spa_id))

    page = cur.fetchone()

    if not page:
        cur.close()
        conn.close()

        flash("Terms page not found.", "warning")
        return redirect(url_for("home"))

    if request.method == "POST":

        access = current_workspace_access()

        if not access.get(
            "can_manage_messaging_compliance",
            False
        ):
            cur.close()
            conn.close()
            abort(403)

        agreed = "agree_terms" in request.form

        if not agreed:
            flash("You must agree to continue.", "warning")

            cur.close()
            conn.close()

            return render_template(
                "help_page.html",
                page=page,
                page_key="sms_email_terms"
            )

        cur.execute("""
            UPDATE spas
            SET owner_agreed_sms_email_terms = TRUE,
                owner_agreed_sms_email_terms_at = NOW(),
                owner_agreed_sms_email_terms_version = %s
            WHERE spa_id = %s
        """, ("v1.0", spa_id))

        conn.commit()

        cur.close()
        conn.close()

        flash("Terms accepted successfully.", "success")

        return redirect(url_for("home"))

    cur.close()
    conn.close()

    return render_template(
        "help_page.html",
        page=page,
        page_key="sms_email_terms"
    )








