@app.route("/godaddy-imports")
@login_required
@spa_required
@require_workspace_permission("can_manage_booking_imports")
def godaddy_imports():
    spa_id = current_spa_id()

    review_filter = request.args.get("review", "").strip().lower()
    from_coach = request.args.get("from_coach", "").strip() == "1"

    conn = get_db_connection()
    cur = conn.cursor()

    query = """
        SELECT
            a.appointment_id,
            a.appointment_date,
            a.appointment_time,
            c.first_name,
            c.last_name,
            c.phone,
            c.email,
            a.appointment_for,
            a.provider_name_at_booking,
            a.external_service_name,
            a.external_order_id,
            a.status,
            a.notes,
            COALESCE(a.import_reviewed, FALSE) AS import_reviewed
        FROM appointments a
        JOIN clients c
            ON a.client_id = c.client_id
        AND a.spa_id = c.spa_id
        WHERE a.spa_id = %s
        AND a.external_source = 'godaddy'
    """

    params = [spa_id]

    if review_filter == "unreviewed":
        query += """
            AND COALESCE(a.import_reviewed, FALSE) = FALSE
        """

    query += """
        ORDER BY a.appointment_date DESC, a.appointment_time DESC
    """

    cur.execute(query, tuple(params))
    imports = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "godaddy_imports.html",
        imports=imports,
        review_filter=review_filter,
        import_count=len(imports),
        from_coach=from_coach
    )










