##################################################################
#
#   HELPER   SEND SMS MESSAGE
#
#################################################################


# ==========================================================
# Internal provider wrapper.
#
# Called only by send_compliant_sms().
#
# This function abstracts the SMS provider (Telnyx today,
# future providers tomorrow) from the application.
# ==========================================================


def send_sms_message(
    from_phone,
    to_phone,
    message_body
):
    """
    Low-level SMS delivery function.

    Business compliance and sender ownership must be verified
    by send_compliant_sms() before this function is called.
    """

    if not from_phone:
        raise ValueError(
            "send_sms_message requires from_phone."
        )

    if not to_phone:
        raise ValueError(
            "send_sms_message requires to_phone."
        )

    sms_enabled = (
        os.getenv("SMS_ENABLED", "false").lower()
        == "true"
    )

    final_message_body = message_body

    if not sms_enabled:
        return {
            "success": False,
            "status": "logged",
            "provider_message_id": None,
            "provider_status": None,
            "provider_error_code": None,
            "provider_error_message": (
                "SMS sending is disabled by the "
                "Peach Suite Pro system switch."
            ),
            "sender_phone": from_phone,
            "receiving_phone": to_phone,
            "final_message_body": final_message_body
        }

    try:
        result = send_sms_telnyx(
            from_phone,
            to_phone,
            final_message_body
        )

        message_data = result.get(
            "data",
            result
        )

        provider_message_id = message_data.get("id")
        provider_status = message_data.get(
            "record_type",
            "accepted"
        )

        print(
            "[SMS DELIVERY ACCEPTED]",
            {
                "provider": "telnyx",
                "provider_message_id": provider_message_id,
                "provider_status": provider_status
            },
            flush=True
        )

        return {
            "success": True,
            "status": "sent",
            "provider_message_id": provider_message_id,
            "provider_status": provider_status,
            "provider_error_code": None,
            "provider_error_message": None,
            "sender_phone": from_phone,
            "receiving_phone": to_phone,
            "final_message_body": final_message_body
        }

    except Exception as error:
        print(
            "[SMS DELIVERY ERROR]",
            type(error).__name__,
            str(error),
            flush=True
        )

        return {
            "success": False,
            "status": "failed",
            "provider_message_id": None,
            "provider_status": None,
            "provider_error_code": None,
            "provider_error_message": str(error),
            "sender_phone": from_phone,
            "receiving_phone": to_phone,
            "final_message_body": final_message_body
        }


