#   ------------------------------------------------
#
#    >>>>>>>>>>>>  GO DADDY  <<<<<<<<<<<<<<<<<
#
#    GoDaddy TEST CREATE APPOINTMENT
#
#      GODADDY IMPORT
#               PARSER VERSION GODADDY_V2
#   -----------------------------------------------




def import_godaddy_booking(body, spa_id, subject=""):
    booking = parse_godaddy_booking_email(body)

    print(
        "[GODADDY IMPORT] Provider:",
        booking.get("provider_name_at_booking")
    )


    price_at_booking = booking.get("subtotal") or booking.get("order_total")
    from datetime import datetime

    conn = get_db_connection()
    cur = conn.cursor()

    # 1. Prevent duplicate appointment
    cur.execute("""
        SELECT appointment_id
        FROM appointments
        WHERE spa_id = %s
          AND external_source = %s
          AND external_order_id = %s
    """, (spa_id, "godaddy", booking["order_number"]))

    existing = cur.fetchone()

    if existing:
        cur.close()
        conn.close()
        return {
            "status": "duplicate",
            "message": "This GoDaddy booking was already imported.",
            "order_number": booking["order_number"]
        }

    # Resolve the spa's default active workspace.
    # Scheduled imports do not have a logged-in session,
    # so current_business_unit_id() cannot be used here.
    cur.execute("""
        SELECT business_unit_id
        FROM business_units
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY
            CASE
                WHEN is_default = TRUE THEN 0
                ELSE 1
            END,
            business_unit_id
        LIMIT 1
    """, (spa_id,))

    business_unit_row = cur.fetchone()

    if not business_unit_row:
        cur.close()
        conn.close()

        raise RuntimeError(
            "No active business unit was found "
            "for the GoDaddy booking import."
        )

    business_unit_id = business_unit_row[0]


    # 2. Find existing client by email first
    client = None

    if booking.get("email"):
        cur.execute("""
            SELECT client_id
            FROM clients
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND LOWER(email) = LOWER(%s)
            LIMIT 1
        """, (
            spa_id,
            business_unit_id,
            booking["email"]
        ))

        client = cur.fetchone()

    # If no email match, try phone
    if not client and booking.get("phone"):
        cur.execute("""
            SELECT client_id
            FROM clients
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND phone = %s
            LIMIT 1
        """, (
            spa_id,
            business_unit_id,
            booking["phone"]
        ))

        client = cur.fetchone()

    # 3. Create client if not found
    if client:
        client_id = client[0]
    else:
        name_parts = booking["customer_name"].split(" ", 1)
        first_name = name_parts[0]
        last_name = name_parts[1] if len(name_parts) > 1 else ""

        cur.execute("""
            INSERT INTO clients (
                spa_id,
                business_unit_id,
                first_name,
                last_name,
                phone,
                email
            )
            VALUES (%s, %s, %s, %s, %s, %s)
            RETURNING client_id
        """, (
            spa_id,
            business_unit_id,
            first_name,
            last_name,
            booking["phone"],
            booking["email"]
        ))

        client_id = cur.fetchone()[0]


    # Parser returns True/False
    paid_at_checkout = bool(booking.get("paid_at_checkout"))





    # 4. Insert appointment
    cur.execute("""
        INSERT INTO appointments (
            spa_id,
            business_unit_id,
            client_id,
            appointment_for,
            appointment_date,
            appointment_time,
            duration_minutes,
            external_service_name,
            provider_name_at_booking,
            status,
            notes,
            external_source,
            external_order_id,
            external_email_subject,
            external_email_body,
            price_at_booking,
            subtotal,
            order_total,
            paid_at_checkout,
            imported_at,
            import_reviewed,
            parser_version,
            import_status
        )
        VALUES (%s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s, %s, %s
        )
        RETURNING appointment_id
    """, (
        spa_id,
        business_unit_id,
        client_id,
        booking.get("customer_name"),
        booking["appointment_datetime"].date(),
        booking["appointment_datetime"].time(),
        booking["duration_minutes"],
        booking["service"],
        booking.get("provider_name_at_booking"),
        "booked",
        (
            f"Imported from GoDaddy. "
            f"Service: {booking['service']}. "
            f"Payment status: {booking['payment_status']}"
        ),
        "godaddy",
        booking["order_number"],
        subject,
        body,
        price_at_booking,
        booking.get("subtotal"),
        booking.get("order_total"),
        paid_at_checkout,
        datetime.now(),
        False,
        "godaddy_v3",
        "Imported"
    ))

    appointment_id = cur.fetchone()[0]


    conn.commit()
    cur.close()
    conn.close()

    return {
        "status": "imported",
        "message": "GoDaddy booking imported successfully.",
        "order_number": booking["order_number"],
        "client_id": client_id,
        "appointment_id":appointment_id
    }








