@app.route(
    "/client/<int:client_id>/messaging-settings",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission("can_manage_contact_preferences")
def client_messaging_settings(client_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if not sms_email_terms_accepted(spa_id):
        flash(
            "You must accept the SMS and Email Terms and Conditions before using messaging features.",
            "warning"
        )
        return redirect(url_for("sms_email_terms"))

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            client_id,
            first_name,
            last_name,
            phone,
            email,
            ok_to_call,
            sms_opt_in,
            sms_opt_out,
            email_opt_in,
            email_opt_out
        FROM clients
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
    """, (
        client_id,
        spa_id,
        business_unit_id
    ))

    client = cur.fetchone()

    if not client:
        cur.close()
        conn.close()
        flash("Client not found.", "error")
        return redirect(url_for("clients_home"))

    if request.method == "POST":
        ok_to_call = request.form.get("ok_to_call") == "on"

        sms_opt_in = request.form.get("sms_opt_in") == "on"
        sms_opt_out = request.form.get("sms_opt_out") == "on"

        email_opt_in = request.form.get("email_opt_in") == "on"
        email_opt_out = request.form.get("email_opt_out") == "on"

        phone = client[3]
        email = client[4]

        cur.execute("""
            UPDATE clients
            SET
                ok_to_call = %s,
                sms_opt_in = %s,
                sms_opt_out = %s,
                email_opt_in = %s,
                email_opt_out = %s
            WHERE client_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
        """, (
            ok_to_call,
            sms_opt_in,
            sms_opt_out,
            email_opt_in,
            email_opt_out,
            client_id,
            spa_id,
            business_unit_id
        ))

        if phone:
            cur.execute("""
                INSERT INTO sms_consent_log (
                    spa_id,
                    business_unit_id,
                    client_id,
                    phone_number,
                    consent_given,
                    consent_method,
                    consent_text
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s)
            """, (
                spa_id,
                business_unit_id,
                client_id,
                phone,
                sms_opt_in,
                "manual_admin_update",
                "Messaging preference updated by staff."
            ))

        if email:
            cur.execute("""
                INSERT INTO email_consent_log (
                    spa_id,
                    business_unit_id,
                    client_id,
                    email,
                    consent_given,
                    consent_method
                )
                VALUES (%s, %s, %s, %s, %s, %s)
            """, (
                spa_id,
                business_unit_id,
                client_id,
                email,
                email_opt_in,
                "manual_admin_update"
            ))

        conn.commit()
        cur.close()
        conn.close()

        flash("Messaging settings updated.", "success")
        return redirect(url_for("client_messaging_settings", client_id=client_id))

    cur.execute("""
        SELECT
            phone_number,
            consent_given,
            consent_method,
            consent_text,
            created_at
        FROM sms_consent_log
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND client_id = %s
        ORDER BY created_at DESC
        LIMIT 20
    """, (
        spa_id,
        business_unit_id,
        client_id
    ))

    sms_logs = cur.fetchall()

    cur.execute("""
        SELECT
            email,
            consent_given,
            consent_method,
            created_at
        FROM email_consent_log
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND client_id = %s
        ORDER BY created_at DESC
        LIMIT 20
    """, (
        spa_id,
        business_unit_id,
        client_id
    ))

    email_logs = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "client_messaging_settings.html",
        client=client,
        sms_logs=sms_logs,
        email_logs=email_logs
    )










