@app.route(
    "/sms/preview/<int:client_id>",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission("can_send_sms")
def sms_preview(client_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if not sms_email_terms_accepted(spa_id):
        flash(
            "You must accept the SMS and Email Terms and Conditions "
            "before using messaging features.",
            "warning"
        )
        return redirect(url_for("sms_email_terms"))

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                client_id,
                first_name,
                last_name,
                phone,
                email,
                sms_opt_in,
                sms_opt_out
            FROM clients
            WHERE client_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
              AND active_client = TRUE
        """, (
            client_id,
            spa_id,
            business_unit_id
        ))

        client = cur.fetchone()

    finally:
        cur.close()
        conn.close()

    if not client:
        flash("Client not found.", "error")
        return redirect(url_for("clients_home"))

    message_body = request.form.get(
        "message_body",
        ""
    ).strip()

    if message_body:
        message_body = apply_sms_placeholders(
            message_body,
            {
                "first_name": client[1] or "",
                "last_name": client[2] or "",
                "phone": client[3] or "",
                "email": client[4] or "",
                "spa_name": "",
                "appointment_date": "",
                "appointment_time": "",
                "service_name": ""
            }
        )

    action = request.form.get("action")

    if (
        request.method == "POST"
        and action == "send"
        and message_body
    ):
        if not client[3]:
            flash(
                "SMS not sent. This client does not have a phone number.",
                "error"
            )
            return redirect(
                url_for(
                    "sms_preview",
                    client_id=client_id
                )
            )

        if not client[5] or client[6]:
            flash(
                "SMS not sent. This client has not opted in "
                "to service SMS messaging.",
                "error"
            )
            return redirect(
                url_for(
                    "edit_client_contact_preferences",
                    client_id=client_id
                )
            )

        try:
            result = send_compliant_sms(
                spa_id=spa_id,
                business_unit_id=business_unit_id,
                client_id=client[0],
                recipient_phone=client[3],
                message_body=message_body,
                message_type="manual"
            )

        except Exception as send_error:
            result = {
                "success": False,
                "status": "failed",
                "provider_message_id": None,
                "provider_status": None,
                "provider_error_code": None,
                "provider_error_message": str(send_error),
                "final_message_body": message_body
            }

        success = bool(result.get("success"))

        status = (
            result.get("status")
            or ("sent" if success else "failed")
        )

        final_message_body = result.get(
            "final_message_body",
            message_body
        )

        try:
            log_sms_message(
                spa_id=spa_id,
                business_unit_id=business_unit_id,
                client_id=client[0],
                recipient_phone=client[3],
                message_body=final_message_body,
                message_type="manual",
                direction="outbound",
                status=status,
                sms_phone_number_id=result.get(
                    "sms_phone_number_id"
                ),
                sender_phone=result.get(
                    "sender_phone"
                ),
                receiving_phone=result.get(
                    "receiving_phone"
                ),
                provider_message_id=result.get(
                    "provider_message_id"
                ),
                provider_status=result.get(
                    "provider_status"
                ),
                provider_error_code=result.get(
                    "provider_error_code"
                ),
                provider_error_message=(
                    result.get("provider_error_message")
                    or result.get("error")
                )
            )

        except Exception as log_error:
            print(
                "[MANUAL SMS LOG ERROR]",
                log_error,
                flush=True
            )

        if success:
            flash(
                "SMS sent successfully.",
                "success"
            )

            return redirect(
                url_for(
                    "sms_conversation",
                    client_id=client_id
                )
            )

        error_message = (
            result.get("provider_error_message")
            or result.get("error")
            or "SMS failed to send."
        )

        flash(
            error_message,
            "error"
        )

    return render_template(
        "sms_preview.html",
        client=client,
        message_body=message_body
    )

