def get_active_messaging_templates(spa_id, channel):
    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            template_id,
            template_type,
            template_name,
            message_text,
            subject_text,
            language_code
        FROM messaging_templates
        WHERE spa_id = %s
          AND channel = %s
          AND is_active = TRUE
          AND approved_for_use = TRUE
          AND COALESCE(is_archived, FALSE) = FALSE
        ORDER BY template_type, template_name
    """, (spa_id, channel))

    templates = cur.fetchall()

    cur.close()
    conn.close()

    return templates


def get_active_messaging_template_types(spa_id, channel):
    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT DISTINCT
            template_type,
            template_type
        FROM messaging_templates
        WHERE spa_id = %s
          AND channel = %s
          AND is_active = TRUE
          AND approved_for_use = TRUE
          AND COALESCE(is_archived, FALSE) = FALSE
        ORDER BY template_type
    """, (spa_id, channel))

    template_types = cur.fetchall()

    cur.close()
    conn.close()

    return template_types





