@app.route("/sms")
@login_required
@spa_required
@require_workspace_permission("can_send_sms")

def sms_home():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    language_code = get_request_language()

    appointment_id = request.args.get(
        "appointment_id",
        type=int
    )

    template_id = request.args.get("template_id")
    template_type = request.args.get("template_type")


    if not sms_email_terms_accepted(spa_id):
        flash(
            "You must accept the SMS and Email Terms and Conditions before using messaging features",
            "warning"
        )
        return redirect(url_for("sms_email_terms"))

    selected_template_type = request.args.get("template_type", "").strip()
    selected_template_id = request.args.get("template_id", "").strip()
    search = request.args.get("search", "").strip()
    show_all = request.args.get("show_all") == "1"
    client_status = request.args.get("client_status", "").strip()

    sms_templates = get_active_messaging_templates(spa_id, "sms")
    sms_template_types = get_active_messaging_template_types(spa_id, "sms")


    # Automatically select the appointment reminder template
    # when arriving from an appointment.
    if (
        appointment_id
        and selected_template_type == "appointment_reminder"
        and not selected_template_id
    ):
        for template in sms_templates:
            if template[1] == "appointment_reminder":
                selected_template_id = str(template[0])
                break

    conn = get_db_connection()
    cur = conn.cursor()

    appointment_context = None

    if appointment_id:
        cur.execute("""
            SELECT
                a.appointment_id,
                a.client_id,
                c.first_name,
                c.last_name,
                c.phone,
                a.appointment_date,
                a.appointment_time,
                COALESCE(
                    s.service_name,
                    a.external_service_name
                ) AS service_name
            FROM appointments a
            JOIN clients c
            ON a.client_id = c.client_id
            AND a.spa_id = c.spa_id
            AND a.business_unit_id = c.business_unit_id
            LEFT JOIN service_name_types s
            ON a.service_type_id = s.service_type_id
            AND a.spa_id = s.spa_id
            WHERE a.appointment_id = %s
            AND a.spa_id = %s
            AND a.business_unit_id = %s
        """, (
            appointment_id,
            spa_id,
            business_unit_id
        ))

        appointment_row = cur.fetchone()

        if appointment_row:
            appointment_context = {
                "appointment_id": appointment_row[0],
                "client_id": appointment_row[1],
                "client_first_name": appointment_row[2],
                "client_last_name": appointment_row[3],
                "phone": appointment_row[4],
                "appointment_date": appointment_row[5],
                "appointment_time": appointment_row[6],
                "service_name": appointment_row[7]
            }

    client_statuses = get_client_statuses(spa_id)


    clients = get_sms_eligible_clients(
        spa_id=spa_id,
        business_unit_id=business_unit_id,
        search=search,
        client_status=client_status,
        show_all=True if appointment_context else show_all
    )

    if appointment_context:
        appointment_client_id = appointment_context[
            "client_id"
        ]

        clients = [
            client
            for client in clients
            if client[0] == appointment_client_id
        ]

    cur.close()
    conn.close()

    return render_template(
        "sms_home.html",
        sms_templates=sms_templates,
        sms_template_types=sms_template_types,
        selected_template_type=selected_template_type,
        selected_template_id=selected_template_id,
        client_statuses=client_statuses,
        clients=clients,
        search=search,
        show_all=show_all,
        client_status=client_status,
        appointment_context=appointment_context
    )






















