@app.route("/sms/group-send", methods=["POST"])
@login_required
@spa_required
@require_workspace_permission("can_send_sms")

def sms_group_send():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    language_code = get_request_language()

    if not sms_email_terms_accepted(spa_id):
        flash(
            "You must accept the SMS and Email Terms and Conditions before using messaging features.",
            "warning"
        )
        return redirect(url_for("sms_email_terms"))

    template_type = request.form.get("template_type")
    template_id_raw = request.form.get("template_id")
    client_ids = request.form.getlist("client_ids")

    appointment_id = request.form.get(
        "appointment_id",
        type=int
    )

    template_id = int(template_id_raw) if template_id_raw else None

    if not template_type:
        flash("SMS template is required.", "error")
        return redirect(url_for(
            "sms_home",
            language_code=language_code,
            template_id=template_id
        ))

    if not client_ids:
        flash("Please select at least one client.", "error")
        return redirect(url_for(
            "sms_home",
            template_type=template_type,
            template_id=template_id,
            language_code=language_code
        ))

    if len(client_ids) > 5:
        flash("You can send SMS to a maximum of 5 clients at a time.", "error")
        return redirect(url_for(
            "sms_home",
            template_type=template_type,
            template_id=template_id,
            language_code=language_code
        ))

    client_ids = [int(x) for x in client_ids]

    appointment_context = None

    if appointment_id:
        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                SELECT
                    a.appointment_id,
                    a.client_id,
                    a.appointment_date,
                    a.appointment_time,
                    COALESCE(
                        s.service_name,
                        a.external_service_name
                    ) AS service_name
                FROM appointments a
                LEFT JOIN service_name_types s
                ON a.service_type_id = s.service_type_id
                AND a.spa_id = s.spa_id
                WHERE a.appointment_id = %s
                AND a.spa_id = %s
                AND a.business_unit_id = %s
            """, (
                appointment_id,
                spa_id,
                business_unit_id
            ))

            appointment_row = cur.fetchone()

            if appointment_row:
                appointment_context = {
                    "appointment_id": appointment_row[0],
                    "client_id": appointment_row[1],
                    "appointment_date": appointment_row[2],
                    "appointment_time": appointment_row[3],
                    "service_name": appointment_row[4]
                }

        finally:
            cur.close()
            conn.close()


    sent_count = 0
    failed_count = 0

    try:
        clients = get_sms_clients_by_ids(
            spa_id=spa_id,
            business_unit_id=business_unit_id,
            client_ids=client_ids
        )

        if not clients:
            flash("No eligible SMS clients found.", "error")
            return redirect(url_for(
                "sms_home",
                template_type=template_type,
                template_id=template_id,
                language_code=language_code
            ))

        for client in clients:
            (
                client_id,
                first_name,
                last_name,
                phone,
                sms_opt_in,
                sms_opt_out
            ) = client

            merge_data = {
                "client_id": client_id,
                "language_code": language_code,
                "client_first_name": first_name,
                "client_full_name": f"{first_name} {last_name}".strip(),
                "spa_name": get_spa_name(spa_id),
            }

            if (
                appointment_context
                and appointment_context["client_id"] == client_id
            ):
                appointment_merge_data = (
                    build_appointment_reminder_merge_data(
                        spa_id=spa_id,
                        business_unit_id=business_unit_id,
                        client_id=client_id,
                        appointment_date=appointment_context[
                            "appointment_date"
                        ],
                        appointment_time=appointment_context[
                            "appointment_time"
                        ],
                        service_name=appointment_context[
                            "service_name"
                        ],
                        spa_name=get_spa_name(spa_id),
                        spa_phone=None,
                        spa_website=None
                    )
                )

                merge_data.update(
                    appointment_merge_data
                )

                merge_data["appointment_id"] = (
                    appointment_context["appointment_id"]
                )

            print(
                "SMS SEND LANGUAGE:",
                language_code,
                "TEMPLATE ID:",
                template_id,
                "TYPE:",
                template_type,
                flush=True
            )

            result = send_communication(
                spa_id=spa_id,
                business_unit_id=business_unit_id,
                channel="sms",
                recipient=phone,
                template_type=template_type,
                merge_data=merge_data,
                client_id=client_id,
                message_type="group_send",
                language_code=language_code,
                template_id=template_id
            )

            log_sms_message(
                spa_id=spa_id,
                business_unit_id=business_unit_id,
                client_id=client_id,
                recipient_phone=phone,
                message_body=result.get("message_body",""),
                message_type="group_send",
                direction="outbound",
                status="sent" if result.get("success") else "failed",
                sms_phone_number_id=result.get(
                    "sms_phone_number_id"
                ),
                sender_phone=result.get(
                    "sender_phone"
                ),
                receiving_phone=result.get(
                    "receiving_phone"
                ),
                provider_message_id=result.get("provider_message_id"),
                provider_status=result.get("provider_status"),
                provider_error_code=result.get("provider_error_code"),
                provider_error_message=result.get("error")
            )


            if result.get("success"):

                # Record a successful appointment-specific reminder
                # so Coach does not recommend it again.
                if (
                    appointment_context
                    and appointment_context["client_id"] == client_id
                    and template_type == "appointment_reminder"
                ):
                    reminder_conn = get_db_connection()
                    reminder_cur = reminder_conn.cursor()

                    try:
                        reminder_cur.execute("""
                            INSERT INTO appointment_reminders (
                                spa_id,
                                appointment_id,
                                client_id,
                                channel,
                                reminder_type,
                                status,
                                appointment_date_at_send,
                                appointment_time_at_send,
                                recipient,
                                message_body,
                                sent_at
                            )
                            SELECT
                                %s,
                                %s,
                                %s,
                                'sms',
                                'appointment_reminder',
                                'sent',
                                %s,
                                %s,
                                %s,
                                %s,
                                NOW()
                            WHERE NOT EXISTS (
                                SELECT 1
                                FROM appointment_reminders
                                WHERE spa_id = %s
                                AND appointment_id = %s
                                AND status = 'sent'
                                AND appointment_date_at_send = %s
                                AND appointment_time_at_send = %s
                            )
                        """, (
                            spa_id,
                            appointment_context["appointment_id"],
                            client_id,
                            appointment_context["appointment_date"],
                            appointment_context["appointment_time"],
                            phone,
                            result.get("message_body", ""),
                            spa_id,
                            appointment_context["appointment_id"],
                            appointment_context["appointment_date"],
                            appointment_context["appointment_time"]
                        ))

                        reminder_conn.commit()

                    finally:
                        reminder_cur.close()
                        reminder_conn.close()

                sent_count += 1

            else:
                failed_count += 1

        flash(f"SMS sent: {sent_count}. Failed: {failed_count}.", "success")
        return redirect(url_for("sms_history_all"))

    except PermissionError as error:
        print(
            "SMS GROUP SEND BLOCKED:",
            error,
            flush=True
        )

        flash(
            (
                "No SMS messages were sent. "
                f"{error}"
            ),
            "warning"
        )

        return redirect(
            request.referrer or "/sms"
        )


    except Exception as error:
        print(
            "SMS GROUP SEND ERROR:",
            error,
            flush=True
        )

        flash(
            (
                "SMS messages could not be sent because "
                "of an unexpected error."
            ),
            "error"
        )

        return redirect(
            request.referrer or "/sms"
        )


        return redirect(url_for(
            "sms_home",
            template_type=template_type,
            template_id=template_id,
            language_code=language_code
        ))










