@app.route("/sms/history/<int:client_id>")
@login_required
@spa_required
@require_workspace_permission("can_view_sms_history")
def sms_history(client_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    spa_timezone = get_spa_timezone(spa_id)

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                first_name,
                last_name
            FROM clients
            WHERE client_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
        """, (
            client_id,
            spa_id,
            business_unit_id
        ))

        client = cur.fetchone()

        if not client:
            flash(
                "Client not found.",
                "error"
            )
            return redirect(url_for("clients_home"))

        cur.execute("""
            SELECT
                sm.created_at AT TIME ZONE %s AS created_at,  -- 0
                sm.direction,                                 -- 1
                c.first_name,                                 -- 2
                c.last_name,                                  -- 3
                sm.recipient_phone,                           -- 4
                sm.message_body,                              -- 5
                sm.status,                                    -- 6
                sm.provider_error_code,                       -- 7
                sm.provider_error_message,                    -- 8
                sm.sms_message_id,                            -- 9
                sm.client_id                                  -- 10
            FROM sms_messages sm

            JOIN clients c
              ON c.client_id = sm.client_id
             AND c.spa_id = sm.spa_id
             AND c.business_unit_id = sm.business_unit_id

            WHERE sm.spa_id = %s
              AND sm.business_unit_id = %s
              AND sm.client_id = %s

            ORDER BY sm.created_at DESC
        """, (
            spa_timezone,
            spa_id,
            business_unit_id,
            client_id
        ))

        sms_logs = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    return render_template(
        "sms_history.html",
        client=client,
        client_id=client_id,
        sms_logs=sms_logs
    )







