@app.route("/email-automation-queue")
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_communication_automation"
)
def email_automation_queue():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    status_filter = (
        request.args.get("status", "")
        or ""
    ).strip().lower()

    allowed_statuses = {
        "pending",
        "processing",
        "sent",
        "failed",
        "cancelled"
    }

    if status_filter not in allowed_statuses:
        status_filter = ""

    conn = get_db_connection()
    cur = conn.cursor(
        cursor_factory=RealDictCursor
    )

    try:
        query = """
            SELECT
                eq.email_queue_id,
                eq.business_unit_id,
                eq.client_id,
                eq.appointment_id,
                eq.email_type,
                eq.recipient_email,
                eq.recipient_name,
                eq.subject_line,
                eq.text_body,
                eq.status,
                eq.scheduled_for,
                eq.next_attempt_at,
                eq.attempt_count,
                eq.maximum_attempts,
                eq.provider_message_id,
                eq.error_message AS last_error,
                eq.last_attempt_at AS processing_started_at,
                eq.sent_at,
                eq.created_at,
                eq.updated_at,

                a.appointment_for,
                a.appointment_date,
                a.appointment_time,

                c.first_name AS client_first_name,
                c.last_name AS client_last_name

            FROM email_queue eq

            LEFT JOIN appointments a
                ON eq.appointment_id =
                    a.appointment_id
               AND eq.spa_id = a.spa_id

            LEFT JOIN clients c
                ON eq.client_id = c.client_id
               AND eq.spa_id = c.spa_id

            WHERE eq.spa_id = %s
              AND eq.business_unit_id = %s
        """

        params = [
            spa_id,
            business_unit_id
        ]

        if status_filter:
            query += """
                AND eq.status = %s
            """
            params.append(status_filter)

        query += """
            ORDER BY
                CASE eq.status
                    WHEN 'pending' THEN 1
                    WHEN 'processing' THEN 2
                    WHEN 'failed' THEN 3
                    WHEN 'sent' THEN 4
                    WHEN 'cancelled' THEN 5
                    ELSE 6
                END,

                CASE
                    WHEN eq.status = 'pending'
                    THEN eq.scheduled_for
                END ASC,

                eq.created_at DESC,
                eq.email_queue_id DESC
        """

        cur.execute(
            query,
            tuple(params)
        )

        queue_rows = cur.fetchall()

        cur.execute("""
            SELECT
                status,
                COUNT(*) AS status_count
            FROM email_queue
            WHERE spa_id = %s
              AND business_unit_id = %s
            GROUP BY status
        """, (
            spa_id,
            business_unit_id
        ))

        status_counts = {
            row["status"]: row["status_count"]
            for row in cur.fetchall()
        }

        total_count = sum(
            status_counts.values()
        )

        return render_template(
            "email_automation_queue.html",
            queue_rows=queue_rows,
            status_filter=status_filter,
            status_counts=status_counts,
            total_count=total_count
        )

    finally:
        cur.close()
        conn.close()


#   --------------------------------------
#
#   EMAIL AUTOMATION QUEUE ACTIONS
#
#   --------------------------------------

def _email_queue_action_redirect():
    return_status = (
        request.form.get("return_status", "")
        or ""
    ).strip().lower()

    allowed_statuses = {
        "pending",
        "processing",
        "sent",
        "failed",
        "cancelled"
    }

    if return_status in allowed_statuses:
        return redirect(
            url_for(
                "email_automation_queue",
                status=return_status
            )
        )

    return redirect(
        url_for("email_automation_queue")
    )


@app.route(
    "/email-automation-queue/"
    "<int:email_queue_id>/send-now",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_communication_automation"
)
def send_email_queue_now(email_queue_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                status,
                attempt_count,
                maximum_attempts
            FROM email_queue
            WHERE email_queue_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
        """, (
            email_queue_id,
            spa_id,
            business_unit_id
        ))

        email_record = cur.fetchone()

        if not email_record:
            flash(
                "Email queue record not found.",
                "warning"
            )
            return _email_queue_action_redirect()

        (
            status,
            attempt_count,
            maximum_attempts
        ) = email_record

        if status == "sent":
            flash(
                "This email has already been sent.",
                "warning"
            )
            return _email_queue_action_redirect()

        if status == "processing":
            flash(
                "This email is already being processed.",
                "warning"
            )
            return _email_queue_action_redirect()

        if status == "cancelled":
            flash(
                "A cancelled email cannot be sent.",
                "warning"
            )
            return _email_queue_action_redirect()

        if status == "failed":
            flash(
                "Use Retry for a failed email.",
                "warning"
            )
            return _email_queue_action_redirect()

        if status != "pending":
            flash(
                "This email is not available to send.",
                "warning"
            )
            return _email_queue_action_redirect()

        if (
            attempt_count is not None
            and maximum_attempts is not None
            and attempt_count >= maximum_attempts
        ):
            flash(
                "This email has reached its maximum "
                "attempts. Reset it with Retry.",
                "warning"
            )
            return _email_queue_action_redirect()

        cur.execute("""
            UPDATE email_queue
            SET
                scheduled_for = CURRENT_TIMESTAMP,
                next_attempt_at = CURRENT_TIMESTAMP,
                error_message = NULL,
                updated_at = CURRENT_TIMESTAMP
            WHERE email_queue_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
              AND status = 'pending'
        """, (
            email_queue_id,
            spa_id,
            business_unit_id
        ))

        conn.commit()

    finally:
        cur.close()
        conn.close()

    summary = process_email_automation_queue(
        batch_size=1,
        email_queue_id=email_queue_id
    )

    if summary["sent_count"] == 1:
        flash(
            "Email sent successfully.",
            "success"
        )

    elif summary["retry_count"] == 1:
        flash(
            "The send attempt failed. The email "
            "was scheduled for another attempt.",
            "warning"
        )

    elif summary["failed_count"] == 1:
        flash(
            "The email could not be sent and is "
            "now marked failed.",
            "error"
        )

    else:
        flash(
            "The email was not sent. Review its "
            "current queue status.",
            "warning"
        )

    return _email_queue_action_redirect()


@app.route(
    "/email-automation-queue/"
    "<int:email_queue_id>/retry",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_communication_automation"
)
def retry_email_queue_item(email_queue_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            UPDATE email_queue
            SET
                status = 'pending',
                scheduled_for = CURRENT_TIMESTAMP,
                next_attempt_at = CURRENT_TIMESTAMP,
                attempt_count = 0,
                last_attempt_at = NULL,
                provider_message_id = NULL,
                provider_status = NULL,
                error_message = NULL,
                updated_at = CURRENT_TIMESTAMP
            WHERE email_queue_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
              AND status = 'failed'
            RETURNING email_queue_id
        """, (
            email_queue_id,
            spa_id,
            business_unit_id
        ))

        reset_record = cur.fetchone()

        if not reset_record:
            conn.rollback()

            flash(
                "Only failed emails can be retried.",
                "warning"
            )

            return _email_queue_action_redirect()

        conn.commit()

    finally:
        cur.close()
        conn.close()

    summary = process_email_automation_queue(
        batch_size=1,
        email_queue_id=email_queue_id
    )

    if summary["sent_count"] == 1:
        flash(
            "Email retry completed successfully.",
            "success"
        )

    elif summary["retry_count"] == 1:
        flash(
            "The retry was unsuccessful. Another "
            "attempt has been scheduled.",
            "warning"
        )

    elif summary["failed_count"] == 1:
        flash(
            "The email retry failed.",
            "error"
        )

    else:
        flash(
            "The email was reset, but it was not "
            "processed. Review its queue status.",
            "warning"
        )

    return _email_queue_action_redirect()


@app.route(
    "/email-automation-queue/"
    "<int:email_queue_id>/cancel",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_communication_automation"
)
def cancel_email_queue_item(email_queue_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            UPDATE email_queue
            SET
                status = 'cancelled',
                provider_status = 'cancelled_by_user',
                updated_at = CURRENT_TIMESTAMP
            WHERE email_queue_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
              AND status = 'pending'
            RETURNING email_queue_id
        """, (
            email_queue_id,
            spa_id,
            business_unit_id
        ))

        cancelled_record = cur.fetchone()

        if not cancelled_record:
            conn.rollback()

            flash(
                "Only pending emails can be cancelled.",
                "warning"
            )

            return _email_queue_action_redirect()

        conn.commit()

        flash(
            "Pending email cancelled.",
            "success"
        )

    finally:
        cur.close()
        conn.close()

    return _email_queue_action_redirect()


@app.route("/reminder_queue")
@login_required
@spa_required
@require_workspace_permission("can_manage_communication_automation")

def reminder_queue():
    spa_id = current_spa_id()

    sms_permissions = get_sms_business_permissions(spa_id)

    sms_marketing_10dlc_approved = bool(
        sms_permissions.get("marketing_sms_enabled")
    )




    requested_status = request.args.get("status")

    if requested_status is None:
        status_filter = "pending"
    else:
        status_filter = requested_status.strip().lower()

    valid_status_filters = {
        "all",
        "pending",
        "sent",
        "failed",
        "skipped"
    }

    if status_filter not in valid_status_filters:
        status_filter = "pending"

    conn = get_db_connection()
    cur = conn.cursor()

    query = """
        SELECT
            rq.reminder_id,
            rq.reminder_type,
            rq.send_method,
            rq.recipient_phone,
            rq.recipient_email,
            rq.message_body,
            rq.scheduled_for,
            rq.status,
            rq.sent_at,
            rq.error_message,
            c.first_name,
            c.last_name
        FROM reminder_queue rq
        LEFT JOIN clients c
            ON rq.client_id = c.client_id
           AND rq.spa_id = c.spa_id
        WHERE rq.spa_id = %s
    """

    params = [spa_id]

    if status_filter != "all":
        query += " AND rq.status = %s"
        params.append(status_filter)

    query += """
        ORDER BY
            rq.status,
            rq.scheduled_for ASC,
            rq.created_at DESC
    """

    cur.execute(query, params)
    reminders = cur.fetchall()

    cur.execute("""
        SELECT status, COUNT(*)
        FROM reminder_queue
        WHERE spa_id = %s
        GROUP BY status
    """, (spa_id,))

    status_counts = dict(cur.fetchall())

    cur.close()
    conn.close()

    return render_template(
        "reminder_queue.html",
        reminders=reminders,
        status_filter=status_filter,
        status_counts=status_counts,
        sms_marketing_10dlc_approved=(
            sms_marketing_10dlc_approved
        )
    )






