@app.route("/reminder_queue/generate-appointments", methods=["POST"])
@login_required
@spa_required
@require_workspace_permission("can_manage_communication_automation")

def generate_appointment_reminders():
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                a.appointment_id,
                a.client_id,
                a.appointment_date,
                a.appointment_time,
                c.first_name,
                c.last_name,
                c.phone,
                c.sms_opt_in,
                c.sms_opt_out
            FROM appointments a
            JOIN clients c
                ON a.client_id = c.client_id
               AND a.spa_id = c.spa_id
            WHERE a.spa_id = %s
              AND a.appointment_date >= CURRENT_DATE
              AND a.appointment_date <= CURRENT_DATE + INTERVAL '7 days'
            ORDER BY a.appointment_date, a.appointment_time
        """, (spa_id,))

        appointments = cur.fetchall()

        created_count = 0
        skipped_count = 0

        for appt in appointments:
            (
                appointment_id,
                client_id,
                appointment_date,
                appointment_time,
                first_name,
                last_name,
                phone,
                sms_opt_in,
                sms_opt_out
            ) = appt

            if (
                not phone
                or not sms_opt_in
                or sms_opt_out
            ):
                skipped_count += 1
                continue

            cur.execute("""
                SELECT 1
                FROM reminder_queue
                WHERE spa_id = %s
                  AND appointment_id = %s
                  AND reminder_type = 'appointment_reminder'
                  AND send_method = 'sms'
                  AND status IN ('pending', 'sent')
            """, (spa_id, appointment_id))

            existing = cur.fetchone()

            if existing:
                skipped_count += 1
                continue

            message_body = apply_sms_placeholders(
                "Hi {first_name}, this is Clear Skin Esthetics. This is a reminder of your appointment on {appointment_date} at {appointment_time}. Reply STOP to opt out.",
                {
                    "first_name": first_name,
                    "last_name": last_name,
                    "appointment_date": appointment_date,
                    "appointment_time": appointment_time
                }
            )

            cur.execute("""
                INSERT INTO reminder_queue (
                    spa_id,
                    client_id,
                    appointment_id,
                    reminder_type,
                    send_method,
                    recipient_phone,
                    message_body,
                    scheduled_for,
                    status
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s,
                        (%s::date + %s::time - INTERVAL '24 hours'),
                        'pending')
            """, (
                spa_id,
                client_id,
                appointment_id,
                "appointment_reminder",
                "sms",
                phone,
                message_body,
                appointment_date,
                appointment_time
            ))

            created_count += 1

        conn.commit()

        flash(
            f"Appointment reminders generated: {created_count}. Skipped: {skipped_count}.",
            "success"
        )

    finally:
        cur.close()
        conn.close()

    return redirect(url_for("reminder_queue"))






#   --------------------------------------
#
#
#   REMINDER QUEUE SEND PENDING
#
#
#   --------------------------------------

@app.route("/reminder_queue/send-pending", methods=["POST"])
@login_required
@spa_required
@require_workspace_permission("can_send_sms")

def send_pending_reminders():
    spa_id = current_spa_id()

    if not sms_email_terms_accepted(spa_id):
        flash(
            "You must accept the SMS and Email Terms and Conditions "
            "before using messaging features.",
            "warning"
        )
        return redirect(url_for("sms_email_terms"))

    conn = get_db_connection()
    cur = conn.cursor()

    sent_count = 0
    failed_count = 0
    skipped_count = 0

    try:
        cur.execute("""
            SELECT
                reminder_id,
                reminder_type,
                send_method
            FROM reminder_queue
            WHERE spa_id = %s
              AND status = 'pending'
              AND scheduled_for <= NOW()
            ORDER BY scheduled_for ASC
        """, (spa_id,))

        reminders = cur.fetchall()

        for reminder in reminders:
            (
                reminder_id,
                reminder_type,
                send_method
            ) = reminder

            reminder_type = (
                reminder_type or ""
            ).strip().lower()

            send_method = (
                send_method or ""
            ).strip().lower()

            if send_method != "sms":
                cur.execute("""
                    UPDATE reminder_queue
                    SET status = 'skipped',
                        error_message = %s
                    WHERE reminder_id = %s
                      AND spa_id = %s
                """, (
                    "Only SMS reminders are currently supported.",
                    reminder_id,
                    spa_id
                ))

                conn.commit()
                skipped_count += 1
                continue

            try:
                if reminder_type == "appointment_reminder":
                    success, result = (
                        send_appointment_reminder_sms(
                            reminder_id=reminder_id,
                            spa_id=spa_id
                        )
                    )

                elif reminder_type == "birthday":
                    success, result = (
                        send_birthday_reminder_sms(
                            reminder_id=reminder_id,
                            spa_id=spa_id
                        )
                    )

                else:
                    cur.execute("""
                        UPDATE reminder_queue
                        SET status = 'skipped',
                            error_message = %s
                        WHERE reminder_id = %s
                          AND spa_id = %s
                    """, (
                        (
                            "This reminder type is not connected "
                            "to the SMS sending pipeline."
                        ),
                        reminder_id,
                        spa_id
                    ))

                    conn.commit()
                    skipped_count += 1
                    continue

                if success:
                    sent_count += 1
                    continue

                if isinstance(result, dict):
                    result_status = (
                        result.get("status") or "failed"
                    ).strip().lower()

                    result_error = (
                        result.get("provider_error_message")
                        or result.get("error")
                        or "Reminder SMS failed."
                    )
                else:
                    result_status = "failed"
                    result_error = str(result)

                if result_status == "skipped":
                    skipped_count += 1

                else:
                    # The helper normally updates failed reminders.
                    # This handles unusual results such as a missing
                    # appointment or client relationship.
                    if result_status == "not_found":
                        cur.execute("""
                            UPDATE reminder_queue
                            SET status = 'failed',
                                error_message = %s
                            WHERE reminder_id = %s
                              AND spa_id = %s
                        """, (
                            result_error,
                            reminder_id,
                            spa_id
                        ))

                        conn.commit()

                    failed_count += 1

            except Exception as error:
                print(
                    "[REMINDER QUEUE SEND ERROR]",
                    {
                        "spa_id": spa_id,
                        "reminder_id": reminder_id,
                        "reminder_type": reminder_type,
                        "error": str(error)
                    },
                    flush=True
                )

                cur.execute("""
                    UPDATE reminder_queue
                    SET status = 'failed',
                        error_message = %s
                    WHERE reminder_id = %s
                      AND spa_id = %s
                """, (
                    str(error),
                    reminder_id,
                    spa_id
                ))

                conn.commit()
                failed_count += 1

        if failed_count == 0 and skipped_count == 0:
            flash_category = "success"
        elif sent_count == 0 and failed_count > 0:
            flash_category = "error"
        else:
            flash_category = "warning"

        flash(
            (
                "Pending reminders processed. "
                f"Sent: {sent_count}. "
                f"Failed: {failed_count}. "
                f"Skipped: {skipped_count}."
            ),
            flash_category
        )

    except Exception as error:
        conn.rollback()

        print(
            "[REMINDER QUEUE PROCESSING ERROR]",
            error,
            flush=True
        )

        flash(
            f"The Reminder Queue could not be processed: {error}",
            "error"
        )

    finally:
        cur.close()
        conn.close()

    return redirect(url_for("reminder_queue"))






