@app.route("/reminder_queue/send-one/<int:reminder_id>", methods=["POST"])
@login_required
@spa_required
@require_workspace_permission("can_send_sms")

def send_one_reminder(reminder_id):
    spa_id = current_spa_id()

    if not sms_email_terms_accepted(spa_id):
        flash(
            "You must accept the SMS and Email Terms and Conditions before using messaging features.",
            "warning"
        )
        return redirect(url_for("sms_email_terms"))

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                reminder_id,
                client_id,
                reminder_type,
                send_method,
                recipient_phone,
                recipient_email,
                message_body,
                status
            FROM reminder_queue
            WHERE reminder_id = %s
              AND spa_id = %s
        """, (reminder_id, spa_id))

        reminder = cur.fetchone()

        if not reminder:
            flash("Reminder not found.", "warning")
            return redirect(url_for("reminder_queue"))

        (
            reminder_id,
            client_id,
            reminder_type,
            send_method,
            recipient_phone,
            recipient_email,
            message_body,
            status
        ) = reminder

        if status == "sent":
            flash("This reminder has already been sent.", "warning")
            return redirect(url_for("reminder_queue"))

        if send_method == "sms":
            if reminder_type == "appointment_reminder":
                success, result = send_appointment_reminder_sms(
                    reminder_id=reminder_id,
                    spa_id=spa_id
                )

                if success:
                    flash("Appointment reminder SMS sent.", "success")
                else:
                    reminder_error = (
                        result.get("provider_error_message")
                        or result.get("error")
                        or "SMS could not be sent."
                    )

                    flash(
                        "Appointment reminder SMS failed: "
                        f"{reminder_error}",
                        "error"
                    )

                return redirect(url_for("reminder_queue"))

            if reminder_type == "birthday":
                sms_permissions = get_sms_business_permissions(
                    spa_id
                )

                if not sms_permissions.get(
                    "marketing_sms_enabled"
                ):
                    error_message = (
                        "Birthday SMS is unavailable. "
                        "Approved marketing SMS 10DLC is required."
                    )

                    cur.execute("""
                        UPDATE reminder_queue
                        SET status = 'skipped',
                            error_message = %s
                        WHERE reminder_id = %s
                        AND spa_id = %s
                    """, (
                        error_message,
                        reminder_id,
                        spa_id
                    ))

                    conn.commit()

                    flash(error_message, "error")

                    return redirect(
                        url_for("reminder_queue")
                    )

                success, result = send_birthday_reminder_sms(
                    reminder_id=reminder_id,
                    spa_id=spa_id
                )

                if success:
                    flash(
                        "Birthday SMS sent.",
                        "success"
                    )
                else:
                    if isinstance(result, dict):
                        error_message = (
                            result.get("provider_error_message")
                            or result.get("error")
                            or "Birthday SMS failed."
                        )
                    else:
                        error_message = str(result)

                    flash(
                        f"Birthday SMS failed: {error_message}",
                        "error"
                    )

                return redirect(
                    url_for("reminder_queue")
                )


            flash("This SMS reminder type is not connected to the new messaging pipeline yet.", "warning")
            return redirect(url_for("reminder_queue"))


        else:
            flash("Only SMS reminders are supported right now.", "warning")

    finally:
        cur.close()
        conn.close()

    return redirect(url_for("reminder_queue"))





##############################################
#
#   PREPARE APPOINTMENT REMINDER
#
#
###########################################



@app.route(
    "/appointments/<int:appointment_id>/prepare-reminder"
)
@login_required
@spa_required
@require_workspace_permission("can_send_sms")

def prepare_appointment_reminder(appointment_id):
    spa_id = current_spa_id()

    if not sms_email_terms_accepted(spa_id):
        flash(
            "You must accept the SMS and Email Terms and "
            "Conditions before using messaging features.",
            "warning"
        )
        return redirect(url_for("sms_email_terms"))

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        # Confirm that the appointment belongs to this spa.
        cur.execute("""
            SELECT
                appointment_id
            FROM appointments
            WHERE appointment_id = %s
              AND spa_id = %s
        """, (
            appointment_id,
            spa_id
        ))

        appointment = cur.fetchone()

        if not appointment:
            flash("Appointment not found.", "warning")
            return redirect(url_for("appointments"))

        # Find the prepared appointment reminder.
        cur.execute("""
            SELECT
                reminder_id,
                status,
                send_method
            FROM reminder_queue
            WHERE spa_id = %s
              AND appointment_id = %s
              AND reminder_type = 'appointment_reminder'
            ORDER BY
                CASE
                    WHEN status = 'pending' THEN 1
                    WHEN status = 'failed' THEN 2
                    WHEN status = 'sent' THEN 3
                    ELSE 4
                END,
                reminder_id DESC
            LIMIT 1
        """, (
            spa_id,
            appointment_id
        ))

        reminder = cur.fetchone()

        if not reminder:
            flash(
                "No prepared reminder was found for this "
                "appointment. Review the Reminder Queue.",
                "warning"
            )
            return redirect(
                url_for(
                    "reminder_queue",
                    fromcoach=1
                )
            )

        reminder_id, status, send_method = reminder

        if status == "sent":
            flash(
                "The reminder queue shows that this appointment "
                "reminder has already been sent.",
                "warning"
            )
            return redirect(
                url_for(
                    "reminder_queue",
                    reminder_id=reminder_id,
                    fromcoach=1
                )
            )

        if send_method != "sms":
            flash(
                "This reminder is not currently prepared for SMS.",
                "warning"
            )
            return redirect(
                url_for(
                    "reminder_queue",
                    reminder_id=reminder_id,
                    fromcoach=1
                )
            )

        flash(
            "Coach prepared the appointment reminder for review.",
            "success"
        )

        return redirect(
            url_for(
                "reminder_queue",
                reminder_id=reminder_id,
                fromcoach=1
            )
        )

    finally:
        cur.close()
        conn.close()











