#   --------------------------------------
#
#
#   REMINDER QUEUE > BIRTHDAY REMINDER
#
#     AND   DEF
#   --------------------------------------



def generate_birthday_reminders(spa_id):
    today = get_spa_today()
    end_date = today + timedelta(days=45)

    conn = get_db_connection()
    cur = conn.cursor()

    created_count = 0

    try:
        cur.execute("""
            SELECT
                client_id,
                first_name,
                last_name,
                phone,
                birth_date
            FROM clients
            WHERE spa_id = %s
              AND active_client = TRUE
              AND birth_date IS NOT NULL
              AND phone IS NOT NULL
              AND TRIM(phone) <> ''
              AND COALESCE(sms_opt_in, FALSE) = TRUE
              AND COALESCE(sms_opt_out, FALSE) = FALSE
              AND COALESCE(
                  sms_marketing_status,
                  'opt_out'
              ) = 'opt_in'
              ORDER BY
                EXTRACT(MONTH FROM birth_date),
                EXTRACT(DAY FROM birth_date),
                last_name,
                first_name
        """, (spa_id,))

        clients = cur.fetchall()

        def birthday_for_year(birth_date, year):
            try:
                return birth_date.replace(year=year)
            except ValueError:
                # Handles February 29 during a non-leap year.
                return birth_date.replace(
                    year=year,
                    month=2,
                    day=28
                )

        for client in clients:
            (
                client_id,
                first_name,
                last_name,
                phone,
                birth_date
            ) = client

            next_birthday = birthday_for_year(
                birth_date,
                today.year
            )

            if next_birthday < today:
                next_birthday = birthday_for_year(
                    birth_date,
                    today.year + 1
                )

            if not (
                today
                <= next_birthday
                <= end_date
            ):
                continue

            cur.execute("""
                SELECT 1
                FROM reminder_queue
                WHERE spa_id = %s
                  AND client_id = %s
                  AND reminder_type = 'birthday'
                  AND send_method = 'sms'
                  AND DATE(scheduled_for) = %s
                  AND status IN (
                      'pending',
                      'sent',
                      'failed'
                  )
                LIMIT 1
            """, (
                spa_id,
                client_id,
                next_birthday
            ))

            existing = cur.fetchone()

            if existing:
                continue

            message_body = (
                f"Birthday SMS for {first_name} will use "
                "the active Birthday Message template."
            )

            cur.execute("""
                INSERT INTO reminder_queue (
                    spa_id,
                    client_id,
                    reminder_type,
                    send_method,
                    recipient_phone,
                    message_body,
                    scheduled_for,
                    status
                )
                VALUES (
                    %s,
                    %s,
                    'birthday',
                    'sms',
                    %s,
                    %s,
                    (%s::date + TIME '09:00'),
                    'pending'
                )
            """, (
                spa_id,
                client_id,
                phone,
                message_body,
                next_birthday
            ))

            created_count += 1

        conn.commit()

        return created_count

    except Exception:
        conn.rollback()
        raise

    finally:
        cur.close()
        conn.close()














