############################################################
#    EMAIL TEMPLATE ARCHIVE
#
#
#
#       6-30-26
#
############################################################


@app.route(
    "/admin/messaging-compliance/templates/archive/<int:template_id>",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission("can_manage_messaging_compliance")
def archive_messaging_template(template_id):
    spa_id = current_spa_id()
    language_code = get_request_language()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT channel, template_name
        FROM messaging_templates
        WHERE template_id = %s
          AND spa_id = %s
        LIMIT 1
    """, (template_id, spa_id))

    row = cur.fetchone()

    if not row:
        cur.close()
        conn.close()
        flash("Template not found.", "warning")
        return redirect(url_for(
            "template_review",
            channel="sms",
            language_code=language_code
        ))

    channel = row[0]
    template_name = row[1] or "Default"

    if template_name.strip().lower() == "default":
        cur.close()
        conn.close()
        flash("Default templates cannot be archived.", "warning")
        return redirect(url_for(
            "template_review",
            channel=channel,
            language_code=language_code
        ))

    cur.execute("""
        UPDATE messaging_templates
        SET
            is_archived = TRUE,
            is_active = FALSE,
            updated_at = NOW()
        WHERE template_id = %s
          AND spa_id = %s
    """, (template_id, spa_id))

    conn.commit()
    cur.close()
    conn.close()

    flash("Template archived.", "success")

    return redirect(url_for(
        "template_review",
        channel=channel,
        language_code=language_code
    ))










