@app.route(
    "/admin/messaging-compliance/templates/<int:template_id>/enable",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission("can_manage_messaging_compliance")
def enable_messaging_template(template_id):
    spa_id = current_spa_id()
    language_code = get_request_language()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT channel, approved_for_use, COALESCE(is_archived, FALSE)
        FROM messaging_templates
        WHERE template_id = %s
          AND spa_id = %s
        LIMIT 1
    """, (template_id, spa_id))

    template = cur.fetchone()

    if not template:
        cur.close()
        conn.close()
        flash("Template not found.", "warning")
        return redirect(url_for(
            "template_review",
            channel="sms",
            language_code=language_code
        ))

    channel = template[0]
    approved_for_use = template[1]
    is_archived = template[2]

    if is_archived:
        cur.close()
        conn.close()
        flash("Archived templates must be restored before they can be enabled.", "warning")
        return redirect(url_for(
            "template_review",
            channel=channel,
            language_code=language_code
        ))

    if not approved_for_use:
        cur.close()
        conn.close()
        flash("Template must be approved for use before it can be enabled.", "warning")
        return redirect(url_for(
            "template_review",
            channel=channel,
            language_code=language_code
        ))

    cur.execute("""
        UPDATE messaging_templates
        SET
            is_active = TRUE,
            updated_at = NOW()
        WHERE template_id = %s
          AND spa_id = %s
    """, (template_id, spa_id))

    conn.commit()

    cur.close()
    conn.close()

    flash("Template enabled.", "success")

    return redirect(url_for(
        "template_review",
        channel=channel,
        language_code=language_code
    ))







