@app.route("/spa-management/business-goals", methods=["GET", "POST"])
@login_required
@spa_required
def business_goals():
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    if request.method == "POST":
        daily_revenue_goal = request.form.get("daily_revenue_goal") or 0
        weekly_revenue_goal = request.form.get("weekly_revenue_goal") or 0
        monthly_revenue_goal = request.form.get("monthly_revenue_goal") or 0
        average_ticket_goal = request.form.get("average_ticket_goal") or 0

        new_clients_goal = request.form.get("new_clients_goal") or 0
        completion_rate_goal = request.form.get("completion_rate_goal") or 95
        cancellation_rate_goal = request.form.get("cancellation_rate_goal") or 5
        no_show_goal = request.form.get("no_show_goal") or 2

        inactive_client_days = request.form.get("inactive_client_days") or 90
        low_inventory_threshold = request.form.get("low_inventory_threshold") or 5

        cur.execute("""
            INSERT INTO spa_business_goals (
                spa_id,
                daily_revenue_goal,
                weekly_revenue_goal,
                monthly_revenue_goal,
                average_ticket_goal,
                new_clients_goal,
                completion_rate_goal,
                cancellation_rate_goal,
                no_show_goal,
                inactive_client_days,
                low_inventory_threshold,
                updated_at
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s, CURRENT_TIMESTAMP)
            ON CONFLICT (spa_id)
            DO UPDATE SET
                daily_revenue_goal = EXCLUDED.daily_revenue_goal,
                weekly_revenue_goal = EXCLUDED.weekly_revenue_goal,
                monthly_revenue_goal = EXCLUDED.monthly_revenue_goal,
                average_ticket_goal = EXCLUDED.average_ticket_goal,
                new_clients_goal = EXCLUDED.new_clients_goal,
                completion_rate_goal = EXCLUDED.completion_rate_goal,
                cancellation_rate_goal = EXCLUDED.cancellation_rate_goal,
                no_show_goal = EXCLUDED.no_show_goal,
                inactive_client_days = EXCLUDED.inactive_client_days,
                low_inventory_threshold = EXCLUDED.low_inventory_threshold,
                updated_at = CURRENT_TIMESTAMP
        """, (
            spa_id,
            daily_revenue_goal,
            weekly_revenue_goal,
            monthly_revenue_goal,
            average_ticket_goal,
            new_clients_goal,
            completion_rate_goal,
            cancellation_rate_goal,
            no_show_goal,
            inactive_client_days,
            low_inventory_threshold
        ))

        conn.commit()
        cur.close()
        conn.close()

        flash("Business goals updated successfully.", "success")
        return redirect(url_for("business_goals"))

    cur.execute("""
        SELECT
            daily_revenue_goal,
            weekly_revenue_goal,
            monthly_revenue_goal,
            average_ticket_goal,
            new_clients_goal,
            completion_rate_goal,
            cancellation_rate_goal,
            no_show_goal,
            inactive_client_days,
            low_inventory_threshold
        FROM spa_business_goals
        WHERE spa_id = %s
    """, (spa_id,))

    goals = cur.fetchone()

    cur.close()
    conn.close()

    return render_template("business_goals.html", goals=goals)






























#   --------------------------------------------------
#
#   >>>>>  CLIENT CONTACT PREFERENCES   <<<<<<<<<<<<<<<
#
#
#
#
#
#
#
#   --------------------------------------------------



@app.route("/client-contact-preferences")
@login_required
@spa_required
def client_contact_preferences():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to view client contact preferences.",
            "error"
        )
        return redirect(url_for("dashboard"))

    search = request.args.get("search", "").strip()
    filter_status = request.args.get(
        "filter_status",
        ""
    ).strip()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        # -----------------------------------------
        # Business SMS / 10DLC availability
        # -----------------------------------------
        sms_10dlc_approved = False
        sms_marketing_10dlc_approved = False

        cur.execute(
            """
            SELECT
                sms_10dlc_status,
                sms_number_assignment_status,
                sms_marketing_allowed,
                sms_service_suspended,
                sms_marketing_suspended
            FROM spas
            WHERE spa_id = %s
            """,
            (spa_id,)
        )

        messaging_status = cur.fetchone()

        if messaging_status:
            sms_10dlc_approved = (
                messaging_status[0] == "approved"
                and messaging_status[1] == "assigned"
                and not messaging_status[3]
            )

            sms_marketing_10dlc_approved = (
                sms_10dlc_approved
                and messaging_status[2]
                and not messaging_status[4]
            )

        # -----------------------------------------
        # Client contact preferences
        # -----------------------------------------
        query = """
            SELECT
                c.client_id,                              -- 0
                c.first_name,                             -- 1
                c.last_name,                              -- 2
                c.phone,                                  -- 3
                c.email,                                  -- 4
                COALESCE(c.sms_opt_in, FALSE),            -- 5
                COALESCE(c.sms_opt_out, FALSE),           -- 6
                COALESCE(c.email_opt_in, FALSE),          -- 7
                COALESCE(c.email_opt_out, FALSE),         -- 8
                COALESCE(c.ok_to_call, TRUE),             -- 9
                COALESCE(
                    c.sms_marketing_status,
                    'opt_out'
                ),                                        -- 10
                COALESCE(
                    c.email_marketing_status,
                    'not_set'
                )                                         -- 11
            FROM clients c
            WHERE c.spa_id = %s
              AND c.business_unit_id = %s
              AND c.active_client = TRUE
        """

        params = [
            spa_id,
            business_unit_id
        ]

        if search:
            query += """
                AND (
                    c.first_name ILIKE %s
                    OR c.last_name ILIKE %s
                    OR c.phone ILIKE %s
                    OR c.email ILIKE %s
                )
            """

            like_search = f"%{search}%"

            params.extend(
                [
                    like_search,
                    like_search,
                    like_search,
                    like_search
                ]
            )

        # -----------------------------------------
        # Communication filters
        # -----------------------------------------
        if filter_status == "sms_yes":
            query += """
                AND c.sms_opt_in = TRUE
                AND COALESCE(c.sms_opt_out, FALSE) = FALSE
            """

        elif filter_status == "sms_no":
            query += """
                AND COALESCE(c.sms_opt_out, FALSE) = TRUE
            """

        elif filter_status == "sms_unset":
            query += """
                AND COALESCE(c.sms_opt_in, FALSE) = FALSE
                AND COALESCE(c.sms_opt_out, FALSE) = FALSE
            """

        elif filter_status == "email_yes":
            query += """
                AND c.email_opt_in = TRUE
                AND COALESCE(c.email_opt_out, FALSE) = FALSE
            """

        elif filter_status == "email_no":
            query += """
                AND COALESCE(c.email_opt_out, FALSE) = TRUE
            """

        elif filter_status == "email_unset":
            query += """
                AND COALESCE(c.email_opt_in, FALSE) = FALSE
                AND COALESCE(c.email_opt_out, FALSE) = FALSE
            """

        # -----------------------------------------
        # Marketing filters
        # -----------------------------------------
        elif filter_status == "sms_marketing_yes":
            query += """
                AND COALESCE(
                    c.sms_marketing_status,
                    'opt_out'
                ) = 'opt_in'
            """

        elif filter_status == "sms_marketing_no":
            query += """
                AND COALESCE(
                    c.sms_marketing_status,
                    'opt_out'
                ) = 'opt_out'
            """

        elif filter_status == "sms_marketing_unset":
            query += """
                AND COALESCE(
                    c.sms_marketing_status,
                    'opt_out'
                ) = 'not_set'
            """

        elif filter_status == "email_marketing_yes":
            query += """
                AND COALESCE(
                    c.email_marketing_status,
                    'not_set'
                ) = 'opt_in'
            """

        elif filter_status == "email_marketing_no":
            query += """
                AND COALESCE(
                    c.email_marketing_status,
                    'not_set'
                ) = 'opt_out'
            """

        elif filter_status == "email_marketing_unset":
            query += """
                AND COALESCE(
                    c.email_marketing_status,
                    'not_set'
                ) = 'not_set'
            """

        # -----------------------------------------
        # Phone and missing-data filters
        # -----------------------------------------
        elif filter_status == "phone_yes":
            query += """
                AND COALESCE(c.ok_to_call, TRUE) = TRUE
            """

        elif filter_status == "phone_no":
            query += """
                AND COALESCE(c.ok_to_call, TRUE) = FALSE
            """

        elif filter_status == "missing_phone":
            query += """
                AND (
                    c.phone IS NULL
                    OR TRIM(c.phone) = ''
                )
            """

        elif filter_status == "missing_email":
            query += """
                AND (
                    c.email IS NULL
                    OR TRIM(c.email) = ''
                )
            """

        query += """
            ORDER BY
                c.last_name,
                c.first_name
        """

        cur.execute(query, params)
        clients = cur.fetchall()

        return render_template(
            "client_contact_preferences.html",
            clients=clients,
            search=search,
            filter_status=filter_status,
            sms_10dlc_approved=sms_10dlc_approved,
            sms_marketing_10dlc_approved=(
                sms_marketing_10dlc_approved
            )
        )

    finally:
        cur.close()
        conn.close()












########################################
#   -------------------------------
#
#   EDIT PREFERENCES
#   FOR SMS - EMAIL -CALL
#
#   ------------------------------
#########################################



@app.route(
    "/client-contact-preferences/edit/<int:client_id>",
    methods=["GET", "POST"]
)
@login_required
@spa_required
def edit_client_contact_preferences(client_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    user_id = session.get("user_id")

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to edit client contact preferences.",
            "error"
        )
        return redirect(
            url_for("client_contact_preferences")
        )

    valid_statuses = {
        "opt_in",
        "opt_out",
        "not_set"
    }

    def status_from_pair(opt_in, opt_out):
        if opt_out:
            return "opt_out"

        if opt_in:
            return "opt_in"

        return "not_set"

    def status_label(status):
        return {
            "opt_in": "Opted In",
            "opt_out": "Opted Out",
            "not_set": "Not Set"
        }.get(status, "Not Set")

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        # -----------------------------------------
        # Business SMS / 10DLC availability
        # -----------------------------------------
        sms_10dlc_approved = False
        sms_marketing_10dlc_approved = False

        cur.execute(
            """
            SELECT
                sms_10dlc_status,
                sms_number_assignment_status,
                sms_marketing_allowed,
                sms_service_suspended,
                sms_marketing_suspended
            FROM spas
            WHERE spa_id = %s
            """,
            (spa_id,)
        )

        messaging_status = cur.fetchone()

        if messaging_status:
            sms_10dlc_status = messaging_status[0]
            sms_number_assignment_status = messaging_status[1]
            sms_marketing_allowed = messaging_status[2]
            sms_service_suspended = messaging_status[3]
            sms_marketing_suspended = messaging_status[4]

            sms_10dlc_approved = (
                sms_10dlc_status == "approved"
                and sms_number_assignment_status == "assigned"
                and not sms_service_suspended
            )

            sms_marketing_10dlc_approved = (
                sms_10dlc_approved
                and sms_marketing_allowed
                and not sms_marketing_suspended
            )

        if request.method == "POST":

            # -----------------------------------------
            # Read the single status controls
            # -----------------------------------------
            phone_status = request.form.get(
                "phone_status",
                "opt_in"
            )

            email_status = request.form.get(
                "email_status",
                "opt_in"
            )

            email_marketing_status = request.form.get(
                "email_marketing_status",
                "not_set"
            )

            sms_status = request.form.get(
                "sms_status",
                "opt_out"
            )

            sms_marketing_status = request.form.get(
                "sms_marketing_status",
                "opt_out"
            )

            # -----------------------------------------
            # Validate submitted values
            # -----------------------------------------
            if phone_status not in {"opt_in", "opt_out"}:
                phone_status = "opt_in"

            if email_status not in valid_statuses:
                email_status = "opt_in"

            if email_marketing_status not in valid_statuses:
                email_marketing_status = "not_set"

            if sms_status not in valid_statuses:
                sms_status = "opt_out"

            if sms_marketing_status not in valid_statuses:
                sms_marketing_status = "opt_out"

            # The server enforces SMS locking.
            # Hidden form values alone are not trusted.
            if not sms_10dlc_approved:
                sms_status = "opt_out"

            if not sms_marketing_10dlc_approved:
                sms_marketing_status = "opt_out"

            # -----------------------------------------
            # Convert statuses to existing booleans
            # -----------------------------------------
            ok_to_call = phone_status == "opt_in"

            email_opt_in = email_status == "opt_in"
            email_opt_out = email_status == "opt_out"

            sms_opt_in = sms_status == "opt_in"
            sms_opt_out = sms_status == "opt_out"

            # -----------------------------------------
            # Read existing preferences
            # -----------------------------------------
            cur.execute(
                """
                SELECT
                    sms_opt_in,
                    sms_opt_out,
                    email_opt_in,
                    email_opt_out,
                    ok_to_call,
                    COALESCE(
                        sms_marketing_status,
                        'opt_out'
                    ),
                    COALESCE(
                        email_marketing_status,
                        'not_set'
                    )
                FROM clients
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
                  AND active_client = TRUE
                """,
                (
                    client_id,
                    spa_id,
                    business_unit_id
                )
            )

            old_prefs = cur.fetchone()

            if not old_prefs:
                flash("Client not found.", "error")
                return redirect(
                    url_for("client_contact_preferences")
                )

            old_sms_status = status_from_pair(
                old_prefs[0],
                old_prefs[1]
            )

            old_email_status = status_from_pair(
                old_prefs[2],
                old_prefs[3]
            )

            old_phone_status = (
                "opt_in"
                if old_prefs[4]
                else "opt_out"
            )

            old_sms_marketing_status = old_prefs[5]
            old_email_marketing_status = old_prefs[6]

            # -----------------------------------------
            # Save preferences
            # -----------------------------------------
            cur.execute(
                """
                UPDATE clients
                SET
                    sms_opt_in = %s,
                    sms_opt_out = %s,
                    email_opt_in = %s,
                    email_opt_out = %s,
                    ok_to_call = %s,
                    sms_marketing_status = %s,
                    email_marketing_status = %s
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
                  AND active_client = TRUE
                """,
                (
                    sms_opt_in,
                    sms_opt_out,
                    email_opt_in,
                    email_opt_out,
                    ok_to_call,
                    sms_marketing_status,
                    email_marketing_status,
                    client_id,
                    spa_id,
                    business_unit_id
                )
            )

            if cur.rowcount != 1:
                conn.rollback()
                flash(
                    "Client not found or not authorized.",
                    "error"
                )
                return redirect(
                    url_for("client_contact_preferences")
                )

            # -----------------------------------------
            # Consent history
            # One record per channel change
            # -----------------------------------------
            if old_sms_status != sms_status:
                add_consent_record(
                    cur,
                    spa_id,
                    client_id,
                    "SMS",
                    sms_status == "opt_in",
                    "Admin Updated",
                    (
                        "SMS communication changed from "
                        f"{status_label(old_sms_status)} to "
                        f"{status_label(sms_status)}."
                    ),
                    user_id,
                    business_unit_id=business_unit_id
                )

            if old_email_status != email_status:
                add_consent_record(
                    cur,
                    spa_id,
                    client_id,
                    "Email",
                    email_status == "opt_in",
                    "Admin Updated",
                    (
                        "Email communication changed from "
                        f"{status_label(old_email_status)} to "
                        f"{status_label(email_status)}."
                    ),
                    user_id,
                    business_unit_id=business_unit_id
                )

            if old_phone_status != phone_status:
                add_consent_record(
                    cur,
                    spa_id,
                    client_id,
                    "Phone",
                    phone_status == "opt_in",
                    "Admin Updated",
                    (
                        "Phone preference changed from "
                        f"{status_label(old_phone_status)} to "
                        f"{status_label(phone_status)}."
                    ),
                    user_id,
                    business_unit_id=business_unit_id
                )

            if (
                old_sms_marketing_status
                != sms_marketing_status
            ):
                add_consent_record(
                    cur,
                    spa_id,
                    client_id,
                    "SMS Marketing",
                    sms_marketing_status == "opt_in",
                    "Admin Updated",
                    (
                        "SMS marketing changed from "
                        f"{status_label(old_sms_marketing_status)} "
                        "to "
                        f"{status_label(sms_marketing_status)}."
                    ),
                    user_id,
                    business_unit_id=business_unit_id
                )

            if (
                old_email_marketing_status
                != email_marketing_status
            ):
                add_consent_record(
                    cur,
                    spa_id,
                    client_id,
                    "Email Marketing",
                    email_marketing_status == "opt_in",
                    "Admin Updated",
                    (
                        "Email marketing changed from "
                        f"{status_label(old_email_marketing_status)} "
                        "to "
                        f"{status_label(email_marketing_status)}."
                    ),
                    user_id,
                    business_unit_id=business_unit_id
                )

            conn.commit()

            flash(
                "Contact preferences updated.",
                "success"
            )

            return redirect(
                url_for("client_contact_preferences")
            )

        # -----------------------------------------
        # GET — Load client preferences
        # -----------------------------------------
        cur.execute(
            """
            SELECT
                client_id,
                first_name,
                last_name,
                phone,
                email,
                sms_opt_in,
                sms_opt_out,
                email_opt_in,
                email_opt_out,
                ok_to_call,
                COALESCE(
                    sms_marketing_status,
                    'opt_out'
                ),
                COALESCE(
                    email_marketing_status,
                    'not_set'
                )
            FROM clients
            WHERE client_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
              AND active_client = TRUE
            """,
            (
                client_id,
                spa_id,
                business_unit_id
            )
        )

        client = cur.fetchone()

        if not client:
            flash("Client not found.", "error")
            return redirect(
                url_for("client_contact_preferences")
            )

        return render_template(
            "edit_client_contact_preferences.html",
            client=client,
            sms_10dlc_approved=sms_10dlc_approved,
            sms_marketing_10dlc_approved=(
                sms_marketing_10dlc_approved
            )
        )

    except Exception as error:
        conn.rollback()

        print(
            "[CONTACT PREFERENCES ERROR]",
            error,
            flush=True
        )

        flash(
            "Contact preferences could not be updated.",
            "error"
        )

        return redirect(
            url_for("client_contact_preferences")
        )

    finally:
        cur.close()
        conn.close()













