    cur.execute("""
        SELECT
            consent_type,
            consent_status,
            consent_source,
            consent_note,
            created_at
        FROM consent_records
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
        ORDER BY created_at DESC
    """, (
        client_id,
        spa_id,
        business_unit_id
    ))

    records = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "client_consent_history.html",
        client=client,
        records=records
    )








