    cur = conn.cursor()

    cur.execute("""
        SELECT product_id, sku, product_name, vendor_company
        FROM inventory_products
        WHERE product_id = %s
          AND spa_id = %s
          AND active = TRUE
    """, (product_id, spa_id))

