# =========================================================
# INVENTORY — PHONE SCANNER SESSION
# =========================================================




@app.route(
    "/inventory/phone-scanner/session",
    methods=["POST"]
)
@login_required
@spa_required
def create_inventory_phone_scan_session():
    spa_id = current_spa_id()
    user_id = session["user_id"]

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        # Close any older scanner session opened by this user.
        cur.execute("""
            UPDATE inventory_scan_sessions
            SET
                status = 'closed',
                closed_at = CURRENT_TIMESTAMP
            WHERE spa_id = %s
              AND created_by = %s
              AND status = 'active'
        """, (
            spa_id,
            user_id,
        ))

        session_token = secrets.token_urlsafe(32)

        pairing_code = None

        # Find an unused six-digit pairing code.
        for _ in range(20):
            proposed_code = str(
                secrets.randbelow(900000) + 100000
            )

            cur.execute("""
                SELECT 1
                FROM inventory_scan_sessions
                WHERE pairing_code = %s
                  AND status = 'active'
                  AND expires_at > CURRENT_TIMESTAMP
            """, (proposed_code,))

            if cur.fetchone() is None:
                pairing_code = proposed_code
                break

        if pairing_code is None:
            raise RuntimeError(
                "Could not generate a scanner pairing code."
            )

        cur.execute("""
            INSERT INTO inventory_scan_sessions (
                spa_id,
                created_by,
                session_token,
                pairing_code,
                status,
                expires_at,
                last_activity_at
            )
            VALUES (
                %s,
                %s,
                %s,
                %s,
                'active',
                CURRENT_TIMESTAMP + INTERVAL '20 minutes',
                CURRENT_TIMESTAMP
            )
            RETURNING
                scan_session_id,
                expires_at
        """, (
            spa_id,
            user_id,
            session_token,
            pairing_code,
        ))

        row = cur.fetchone()

        conn.commit()

        phone_url = url_for(
            "inventory_phone_scanner",
            token=session_token,
            _external=True
        )

        return jsonify({
            "status": "success",
            "scan_session_id": row[0],
            "pairing_code": pairing_code,
            "phone_url": phone_url,
            "poll_url": url_for(
                "poll_inventory_phone_scan",
                scan_session_id=row[0]
            ),
            "close_url": url_for(
                "close_inventory_phone_scan_session",
                scan_session_id=row[0]
            ),
            "expires_at": row[1].isoformat(),
        })

    except Exception:
        conn.rollback()

        app.logger.exception(
            "Failed to create inventory phone scanner session."
        )

        return jsonify({
            "status": "error",
            "message": (
                "The phone scanner session could not be created."
            )
        }), 500

    finally:
        cur.close()
        conn.close()













# =========================================================
# INVENTORY — PHONE SCANNER PAGE
# =========================================================




@app.route(
    "/inventory/phone-scanner/<token>"
)
def inventory_phone_scanner(token):
    token = str(token or "").strip()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            UPDATE inventory_scan_sessions
            SET
                status = 'expired',
                closed_at = CURRENT_TIMESTAMP
            WHERE session_token = %s
              AND status = 'active'
              AND expires_at <= CURRENT_TIMESTAMP
        """, (token,))

        cur.execute("""
            SELECT
                scan_session_id,
                pairing_code,
                expires_at
            FROM inventory_scan_sessions
            WHERE session_token = %s
              AND status = 'active'
              AND expires_at > CURRENT_TIMESTAMP
        """, (token,))

        scanner_session = cur.fetchone()

        conn.commit()

    finally:
        cur.close()
        conn.close()

    if scanner_session is None:
        return render_template(
            "inventory_phone_scanner_expired.html"
        ), 410

    return render_template(
        "inventory_phone_scanner.html",
        scanner_token=token,
        pairing_code=scanner_session[1],
        expires_at=scanner_session[2]
    )















# =========================================================
# INVENTORY — PHONE SUBMITS A BARCODE
# ====
# =====================================================




@app.route(
    "/inventory/phone-scanner/<token>/submit",
    methods=["POST"]
)
def submit_inventory_phone_scan(token):
    data = request.get_json(silent=True) or {}

    barcode = str(
        data.get("barcode") or ""
    ).strip()

    if not barcode:
        return jsonify({
            "status": "error",
            "message": "No barcode was received."
        }), 400

    if len(barcode) > 255:
        return jsonify({
            "status": "error",
            "message": "The scanned barcode is too long."
        }), 400

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                scan_session_id,
                spa_id
            FROM inventory_scan_sessions
            WHERE session_token = %s
              AND status = 'active'
              AND expires_at > CURRENT_TIMESTAMP
            FOR UPDATE
        """, (token,))

        scanner_session = cur.fetchone()

        if scanner_session is None:
            conn.rollback()

            return jsonify({
                "status": "expired",
                "message": (
                    "This scanner session has expired "
                    "or was closed."
                )
            }), 410

        scan_session_id = scanner_session[0]
        spa_id = scanner_session[1]

        # Prevent the camera callback from sending the same
        # barcode repeatedly within a short period.
        cur.execute("""
            SELECT 1
            FROM inventory_scan_events
            WHERE scan_session_id = %s
              AND barcode = %s
              AND created_at >=
                    CURRENT_TIMESTAMP - INTERVAL '2 seconds'
            LIMIT 1
        """, (
            scan_session_id,
            barcode,
        ))

        duplicate_scan = cur.fetchone()

        if duplicate_scan:
            conn.commit()

            return jsonify({
                "status": "duplicate",
                "barcode": barcode
            })

        cur.execute("""
            INSERT INTO inventory_scan_events (
                scan_session_id,
                spa_id,
                barcode,
                status
            )
            VALUES (
                %s,
                %s,
                %s,
                'pending'
            )
            RETURNING scan_event_id
        """, (
            scan_session_id,
            spa_id,
            barcode,
        ))

        scan_event_id = cur.fetchone()[0]

        cur.execute("""
            UPDATE inventory_scan_sessions
            SET last_activity_at = CURRENT_TIMESTAMP
            WHERE scan_session_id = %s
        """, (scan_session_id,))

        conn.commit()

        return jsonify({
            "status": "success",
            "scan_event_id": scan_event_id,
            "barcode": barcode
        })

    except Exception:
        conn.rollback()

        app.logger.exception(
            "Failed to receive inventory phone scan."
        )

        return jsonify({
            "status": "error",
            "message": "The barcode could not be sent."
        }), 500

    finally:
        cur.close()
        conn.close()








# =========================================================
# INVENTORY — DESKTOP POLLS FOR PHONE SCANS
# =========================================================




@app.route(
    "/inventory/phone-scanner/session/"
    "<int:scan_session_id>/poll"
)
@login_required
@spa_required
def poll_inventory_phone_scan(scan_session_id):
    spa_id = current_spa_id()
    user_id = session["user_id"]

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            UPDATE inventory_scan_sessions
            SET
                status = 'expired',
                closed_at = CURRENT_TIMESTAMP
            WHERE scan_session_id = %s
              AND spa_id = %s
              AND created_by = %s
              AND status = 'active'
              AND expires_at <= CURRENT_TIMESTAMP
        """, (
            scan_session_id,
            spa_id,
            user_id,
        ))

        cur.execute("""
            SELECT status
            FROM inventory_scan_sessions
            WHERE scan_session_id = %s
              AND spa_id = %s
              AND created_by = %s
        """, (
            scan_session_id,
            spa_id,
            user_id,
        ))

        session_row = cur.fetchone()

        if session_row is None:
            conn.rollback()

            return jsonify({
                "status": "not_found"
            }), 404

        if session_row[0] != "active":
            conn.commit()

            return jsonify({
                "status": session_row[0]
            })

        cur.execute("""
            SELECT
                scan_event_id,
                barcode
            FROM inventory_scan_events
            WHERE scan_session_id = %s
              AND spa_id = %s
              AND status = 'pending'
            ORDER BY scan_event_id ASC
            LIMIT 1
            FOR UPDATE SKIP LOCKED
        """, (
            scan_session_id,
            spa_id,
        ))

        scan_event = cur.fetchone()

        if scan_event is None:
            conn.commit()

            return jsonify({
                "status": "waiting"
            })

        cur.execute("""
            UPDATE inventory_scan_events
            SET
                status = 'processed',
                processed_at = CURRENT_TIMESTAMP
            WHERE scan_event_id = %s
              AND spa_id = %s
        """, (
            scan_event[0],
            spa_id,
        ))

        cur.execute("""
            UPDATE inventory_scan_sessions
            SET last_activity_at = CURRENT_TIMESTAMP
            WHERE scan_session_id = %s
              AND spa_id = %s
        """, (
            scan_session_id,
            spa_id,
        ))

        conn.commit()

        return jsonify({
            "status": "scan_received",
            "barcode": scan_event[1]
        })

    except Exception:
        conn.rollback()

        app.logger.exception(
            "Failed to poll inventory phone scanner."
        )

        return jsonify({
            "status": "error"
        }), 500

    finally:
        cur.close()
        conn.close()









