@app.route("/loan_contributions/export/csv")
@login_required
@spa_required
def export_loan_contributions_csv():
    spa_id = current_spa_id()

    start_date = request.args.get("start_date", "").strip()
    end_date = request.args.get("end_date", "").strip()

    rows = get_loan_contribution_rows(
        spa_id=spa_id,
        start_date=start_date or None,
        end_date=end_date or None
    )

    output = io.StringIO()
    writer = csv.writer(output)

    writer.writerow([
        "Date",
        "Type",
        "Description",
        "Amount",
        "Payment Method",
        "Loan",
        "Notes"
    ])

    for row in rows:
        writer.writerow([
            row[0].strftime("%Y-%m-%d") if row[0] else "",
            row[1] or "",
            row[2] or "",
            f"{float(row[3]):.2f}" if row[3] is not None else "0.00",
            row[4] or "",
            row[5] or "",
            row[6] or ""
        ])

    csv_data = output.getvalue()
    output.close()

    return Response(
        csv_data,
        mimetype="text/csv",
        headers={
            "Content-Disposition": "attachment; filename=loan_contributions.csv"
        }
    )


#   --------------------------------------
#     LOAN CONTRIBUTIONS EXPORT   EXCEL
#
#   --------------------------------------

@app.route("/loan_contributions/export/excel")
@login_required
@spa_required
def export_loan_contributions_excel():
    spa_id = current_spa_id()

    start_date = request.args.get("start_date", "").strip()
    end_date = request.args.get("end_date", "").strip()

    rows = get_loan_contribution_rows(
        spa_id=spa_id,
        start_date=start_date or None,
        end_date=end_date or None
    )

    wb = Workbook()
    ws = wb.active
    ws.title = "Loans & Contributions"

    headers = [
        "Date",
        "Type",
        "Description",
        "Amount",
        "Payment Method",
        "Loan",
        "Notes"
    ]

    ws.append(headers)

    for row in rows:
        ws.append([
            row[0].strftime("%Y-%m-%d") if row[0] else "",
            row[1] or "",
            row[2] or "",
            float(row[3]) if row[3] is not None else 0.00,
            row[4] or "",
            row[5] or "",
            row[6] or ""
        ])

    # make columns fit nicely
    for column in ws.columns:
        max_length = 0
        column_letter = column[0].column_letter

        for cell in column:
            try:
                max_length = max(max_length, len(str(cell.value)))
            except:
                pass

        ws.column_dimensions[column_letter].width = max_length + 2

    # format amount column
    for cell in ws["D"][1:]:
        cell.number_format = "$#,##0.00"

    file_data = io.BytesIO()
    wb.save(file_data)
    file_data.seek(0)

    return send_file(
        file_data,
        as_attachment=True,
        download_name="loan_contributions.xlsx",
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    )















