@app.route("/client_management")
@login_required
@spa_required
def client_management():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to view clients.",
            "error"
        )
        return redirect(url_for("dashboard"))

    search = request.args.get("search", "").strip()
    show_all = request.args.get("show_all")
    today = get_spa_today()

    conn = get_db_connection()
    cur = conn.cursor()

    rows = []
    record_count = 0

    if search:
        cur.execute("""
            SELECT
                c.client_id,
                c.first_name,
                c.last_name,
                c.phone,
                c.email,
                c.birth_date,

                (
                    SELECT MAX(a1.appointment_date)
                    FROM appointments a1
                    WHERE a1.client_id = c.client_id
                      AND a1.spa_id = c.spa_id
                      AND a1.business_unit_id = c.business_unit_id
                      AND a1.appointment_date <= %s
                ) AS last_visit_date,

                (
                    SELECT MIN(a2.appointment_date)
                    FROM appointments a2
                    WHERE a2.client_id = c.client_id
                      AND a2.spa_id = c.spa_id
                      AND a2.business_unit_id = c.business_unit_id
                      AND a2.appointment_date >= %s
                ) AS next_visit_date,

                c.ok_to_text,
                c.sms_opt_in,
                c.sms_opt_out,
                c.ok_to_email,
                c.email_opt_in,
                c.email_opt_out

            FROM clients c
            WHERE c.spa_id = %s
              AND c.business_unit_id = %s
              AND c.active_client = TRUE
              AND (
                   LOWER(c.first_name) LIKE %s
                   OR LOWER(c.last_name) LIKE %s
                   OR c.phone LIKE %s
              )
            ORDER BY c.last_name, c.first_name
        """, (
            today,
            today,
            spa_id,
            business_unit_id,
            f"%{search.lower()}%",
            f"%{search.lower()}%",
            f"%{search}%"
        ))

        rows = cur.fetchall()
        record_count = len(rows)

    elif show_all:
        cur.execute("""
            SELECT
                c.client_id,
                c.first_name,
                c.last_name,
                c.phone,
                c.email,
                c.birth_date,

                (
                    SELECT MAX(a1.appointment_date)
                    FROM appointments a1
                    WHERE a1.client_id = c.client_id
                      AND a1.spa_id = c.spa_id
                      AND a1.business_unit_id = c.business_unit_id
                      AND a1.appointment_date <= %s
                ) AS last_visit_date,

                (
                    SELECT MIN(a2.appointment_date)
                    FROM appointments a2
                    WHERE a2.client_id = c.client_id
                      AND a2.spa_id = c.spa_id
                      AND a2.business_unit_id = c.business_unit_id
                      AND a2.appointment_date >= %s
                ) AS next_visit_date,

                c.ok_to_text,
                c.sms_opt_in,
                c.sms_opt_out,
                c.ok_to_email,
                c.email_opt_in,
                c.email_opt_out

            FROM clients c
            WHERE c.spa_id = %s
              AND c.business_unit_id = %s
              AND c.active_client = TRUE
            ORDER BY c.last_name, c.first_name
        """, (
            today,
            today,
            spa_id,
            business_unit_id
        ))

        rows = cur.fetchall()
        record_count = len(rows)

    cur.close()
    conn.close()

    return render_template(
        "client_management.html",
        clients=rows,
        record_count=record_count,
        search=search,
        show_all=show_all
    )












