#  -----------------------------------


#  --------------------------------------
#
#  SCHEDULE APPOINTMENT START
#
#  spa id and route good
#  -----------------------------------



@app.route(
    "/schedule_appointment_start",
    methods=["GET", "POST"]
)
@login_required
@spa_required
def schedule_appointment_start():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to schedule an appointment.",
            "error"
        )
        return redirect(url_for("appointments"))

    clients = []
    searched = False
    show_all = False

    selected_date = (
        request.args.get("selected_date")
        or request.form.get("selected_date")
        or ""
    )

    client_name = ""
    birth_date = ""

    if request.method == "POST":
        searched = True

        client_name = request.form.get(
            "client_name",
            ""
        ).strip()

        birth_date = request.form.get(
            "birth_date",
            ""
        ).strip()

        action = request.form.get(
            "action",
            "search"
        )

        show_all = action == "show_all"

        conn = get_db_connection()
        cur = conn.cursor()

        try:
            query = """
                SELECT
                    client_id,
                    first_name,
                    last_name,
                    birth_date,
                    phone
                FROM clients
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND active_client = TRUE
            """

            params = [
                spa_id,
                business_unit_id
            ]

            if not show_all:
                if client_name:
                    query += """
                        AND (
                            first_name ILIKE %s
                            OR last_name ILIKE %s
                            OR (
                                first_name || ' ' || last_name
                            ) ILIKE %s
                        )
                    """

                    name_search = f"%{client_name}%"

                    params.extend([
                        name_search,
                        name_search,
                        name_search
                    ])

                if birth_date:
                    query += """
                        AND birth_date = %s
                    """

                    params.append(birth_date)

            query += """
                ORDER BY
                    last_name,
                    first_name
            """

            if show_all or client_name or birth_date:
                cur.execute(
                    query,
                    tuple(params)
                )

                clients = cur.fetchall()

        finally:
            cur.close()
            conn.close()

    return render_template(
        "schedule_appointment_start.html",
        clients=clients,
        searched=searched,
        show_all=show_all,
        selected_date=selected_date,
        client_name=client_name,
        birth_date=birth_date
    )






