@app.route("/birthday_offers_home")
@login_required
@spa_required
@require_workspace_permission("can_send_email")
def birthday_offers_home():
    spa_id = current_spa_id()
    spa_now = get_spa_now()
    today = spa_now.date()
    end_date = today + timedelta(days=45)

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            c.client_id,
            c.first_name,
            c.last_name,
            c.phone,
            c.email,
            c.birth_date,
            cbo.offer_sent,
            cbo.offer_sent_date,
            cbo.sent_status,
            cbo.notes
        FROM clients c
        LEFT JOIN client_birthday_offers cbo
            ON c.client_id = cbo.client_id
           AND c.spa_id = cbo.spa_id
           AND cbo.birthday_year = %s
        WHERE c.spa_id = %s
          AND c.birth_date IS NOT NULL
          AND c.active_client = TRUE
        ORDER BY c.last_name, c.first_name
    """, (today.year, spa_id))

    rows = cur.fetchall()

    cur.close()
    conn.close()

    upcoming_birthdays = []

    for row in rows:
        (
            client_id,
            first_name,
            last_name,
            phone,
            email,
            birth_date,
            offer_sent,
            offer_sent_date,
            sent_status,
            notes
        ) = row

        this_year_birthday = birth_date.replace(year=today.year)

        if this_year_birthday < today:
            next_birth_date = birth_date.replace(year=today.year + 1)
        else:
            next_birth_date = this_year_birthday

        if today <= next_birth_date <= end_date:
            days_until = (next_birth_date - today).days

            upcoming_birthdays.append({
                "client_id": client_id,
                "first_name": first_name,
                "last_name": last_name,
                "phone": phone,
                "email": email,
                "birth_date": birth_date,
                "next_birth_date": next_birth_date,
                "days_until": days_until,
                "offer_sent": bool(offer_sent),
                "offer_sent_date": offer_sent_date,
                "sent_status": sent_status,
                "notes": notes,
                "acknowledged_by": notes
            })

    return render_template(
        "birthday_offers_home.html",
        upcoming_birthdays=upcoming_birthdays,
        today=today
    )












