@app.route("/employees")
@login_required
@spa_required
def employees_home():
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=RealDictCursor)

    cur.execute("""
        SELECT
            e.employee_id,
            e.first_name,
            e.last_name,
            e.employee_nickname,
            er.role_name,
            e.provider_color_code,
            e.phone,
            e.email,
            e.hire_date,
            e.license_expiration_date,
            e.is_active,
            e.created_at
        FROM employees e
        LEFT JOIN employee_roles er
            ON er.employee_role_id = e.employee_role_id
           AND er.spa_id = e.spa_id
        WHERE e.spa_id = %s
        ORDER BY
            e.is_active DESC,
            e.last_name ASC,
            e.first_name ASC
    """, (spa_id,))

    employees = cur.fetchall()


    cur.execute("""
        SELECT COUNT(*) AS total
        FROM employees
        WHERE spa_id = %s
    """, (spa_id,))

    total_employees = cur.fetchone()["total"]

    cur.execute("""
        SELECT COUNT(*) AS total
        FROM employees
        WHERE spa_id = %s
          AND is_active = TRUE
    """, (spa_id,))

    active_employees = cur.fetchone()["total"]

    cur.close()
    conn.close()

    return render_template(
        "employees_home.html",
        employees=employees,
        total_employees=total_employees,
        active_employees=active_employees
    )





