@app.route("/add_employee_compensation", methods=["GET", "POST"])
@login_required
@spa_required
def add_employee_compensation():
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    # Load employees
    cur.execute("""
        SELECT employee_id, first_name || ' ' || last_name AS employee_name
        FROM employees
        WHERE spa_id = %s
        ORDER BY first_name, last_name
    """, (spa_id,))
    employees = cur.fetchall()

    # Load compensation types for all 4 dropdowns
    cur.execute("""
        SELECT compensation_type_id, compensation_type_name
        FROM compensation_types
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY compensation_type_name
    """, (spa_id,))
    compensation_types = cur.fetchall()

    if request.method == "POST":
        payment_date = request.form.get("payment_date")
        employee_id = request.form.get("employee_id") or None
        notes = (request.form.get("notes") or "").strip()

        # Gather up to 4 compensation lines
        detail_lines = []

        for i in range(1, 5):
            comp_type_id = request.form.get(f"comp_type_{i}") or None
            amount_raw = request.form.get(f"amount_{i}") or "0"

            try:
                amount = float(amount_raw)
            except ValueError:
                amount = 0

            if comp_type_id and amount > 0:
                detail_lines.append((comp_type_id, amount))

        # Validation
        if not payment_date:
            flash("Payment date is required.", "error")

        elif not employee_id:
            flash("Employee is required.", "error")

        elif not detail_lines:
            flash(
                "Enter at least one compensation line "
                "with type and amount.",
                "error"
            )

        else:
            # -----------------------------------------
            # Verify submitted employee belongs to
            # the current spa.
            # -----------------------------------------
            cur.execute("""
                SELECT 1
                FROM employees
                WHERE employee_id = %s
                  AND spa_id = %s
                LIMIT 1
            """, (
                employee_id,
                spa_id
            ))

            employee_is_authorized = (
                cur.fetchone() is not None
            )

            submitted_type_ids = [
                comp_type_id
                for comp_type_id, amount
                in detail_lines
            ]

            cur.execute("""
                SELECT compensation_type_id
                FROM compensation_types
                WHERE spa_id = %s
                  AND is_active = TRUE
                  AND compensation_type_id = ANY(%s::int[])
            """, (
                spa_id,
                submitted_type_ids
            ))

            authorized_type_ids = {
                str(row[0])
                for row in cur.fetchall()
            }

            compensation_types_are_authorized = (
                authorized_type_ids
                == {
                    str(comp_type_id)
                    for comp_type_id
                    in submitted_type_ids
                }
            )

            if not employee_is_authorized:
                flash(
                    "Employee not found or not authorized.",
                    "error"
                )

            elif not compensation_types_are_authorized:
                flash(
                    (
                        "One or more compensation types "
                        "are not authorized."
                    ),
                    "error"
                )

            else:
                # Insert header
                cur.execute("""
                    INSERT INTO employee_compensation (
                        spa_id,
                        employee_id,
                        compensation_date,
                        notes
                    )
                    VALUES (%s, %s, %s, %s)
                    RETURNING compensation_id
                """, (
                    spa_id,
                    employee_id,
                    payment_date,
                    notes
                ))

                compensation_id = (
                    cur.fetchone()[0]
                )

                # Insert detail lines
                for comp_type_id, amount in detail_lines:
                    cur.execute("""
                        INSERT INTO employee_compensation_lines (
                            compensation_id,
                            compensation_type_id,
                            amount
                        )
                        VALUES (%s, %s, %s)
                    """, (
                        compensation_id,
                        comp_type_id,
                        amount
                    ))

                conn.commit()
                cur.close()
                conn.close()

                flash(
                    "Compensation saved successfully.",
                    "success"
                )

                return redirect(
                    url_for(
                        "employee_compensation_report"
                    )
                )

    cur.close()
    conn.close()

    return render_template(
        "add_employee_compensation.html",
        employees=employees,
        compensation_types=compensation_types
    )





