#   -----------------------------------------
#       EDIT   EMPLOYEE COMPENSATION HISTORY
#
#
#
#  route good 4/27
#   -----------------------------------------



@app.route("/edit_employee_compensation/<int:compensation_id>", methods=["GET", "POST"])
@login_required
@spa_required
def edit_employee_compensation(compensation_id):
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    # Load employees
    cur.execute("""
        SELECT employee_id, first_name || ' ' || last_name AS employee_name
        FROM employees
        WHERE spa_id = %s
        ORDER BY first_name, last_name
    """, (spa_id,))
    employees = cur.fetchall()

    # Load active compensation types
    cur.execute("""
        SELECT compensation_type_id, compensation_type_name
        FROM compensation_types
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY compensation_type_name
    """, (spa_id,))
    compensation_types = cur.fetchall()

    if request.method == "POST":
        payment_date = request.form.get("payment_date")
        employee_id = request.form.get("employee_id") or None
        notes = (request.form.get("notes") or "").strip()

        detail_lines = []

        for i in range(1, 5):
            comp_type_id = request.form.get(f"comp_type_{i}") or None
            amount_raw = request.form.get(f"amount_{i}") or "0"

            try:
                amount = float(amount_raw)
            except ValueError:
                amount = 0

            if comp_type_id and amount > 0:
                detail_lines.append((comp_type_id, amount))

        # Validation
        if not payment_date:
            flash("Payment date is required.", "error")
        elif not employee_id:
            flash("Employee is required.", "error")
        elif not detail_lines:
            flash("Enter at least one compensation line with type and amount.", "error")
        else:
            # -----------------------------------------
            # Verify submitted employee and
            # compensation types belong to this spa.
            # -----------------------------------------
            cur.execute("""
                SELECT 1
                FROM employees
                WHERE employee_id = %s
                  AND spa_id = %s
                LIMIT 1
            """, (
                employee_id,
                spa_id
            ))

            employee_is_authorized = (
                cur.fetchone() is not None
            )

            submitted_type_ids = [
                comp_type_id
                for comp_type_id, amount
                in detail_lines
            ]

            cur.execute("""
                SELECT compensation_type_id
                FROM compensation_types
                WHERE spa_id = %s
                  AND is_active = TRUE
                  AND compensation_type_id = ANY(%s::int[])
            """, (
                spa_id,
                submitted_type_ids
            ))

            authorized_type_ids = {
                str(row[0])
                for row in cur.fetchall()
            }

            compensation_types_are_authorized = (
                authorized_type_ids
                == {
                    str(comp_type_id)
                    for comp_type_id
                    in submitted_type_ids
                }
            )

            if not employee_is_authorized:
                flash(
                    "Employee not found or not authorized.",
                    "error"
                )

            elif not compensation_types_are_authorized:
                flash(
                    (
                        "One or more compensation types "
                        "are not authorized."
                    ),
                    "error"
                )

            else:
                # Update only a compensation record
                # owned by the current spa.
                cur.execute("""
                    UPDATE employee_compensation
                    SET employee_id = %s,
                        compensation_date = %s,
                        notes = %s
                    WHERE compensation_id = %s
                      AND spa_id = %s
                """, (
                    employee_id,
                    payment_date,
                    notes,
                    compensation_id,
                    spa_id
                ))

                if cur.rowcount == 0:
                    conn.rollback()

                    cur.close()
                    conn.close()

                    flash(
                        (
                            "Compensation record not found "
                            "or not authorized."
                        ),
                        "error"
                    )

                    return redirect(
                        url_for(
                            "employee_compensation_history"
                        )
                    )

                # Safe now: ownership of the parent
                # compensation record was confirmed.
                cur.execute("""
                    DELETE FROM employee_compensation_lines
                    WHERE compensation_id = %s
                """, (
                    compensation_id,
                ))

                for comp_type_id, amount in detail_lines:
                    cur.execute("""
                        INSERT INTO employee_compensation_lines (
                            compensation_id,
                            compensation_type_id,
                            amount
                        )
                        VALUES (%s, %s, %s)
                    """, (
                        compensation_id,
                        comp_type_id,
                        amount
                    ))

                conn.commit()
                cur.close()
                conn.close()

                flash(
                    "Compensation updated successfully.",
                    "success"
                )

                return redirect(
                    url_for(
                        "employee_compensation_history"
                    )
                )

    # Load header record
    cur.execute("""
        SELECT compensation_id, employee_id, compensation_date, notes
        FROM employee_compensation
        WHERE compensation_id = %s
          AND spa_id = %s
    """, (compensation_id, spa_id))
    compensation = cur.fetchone()

    if not compensation:
        cur.close()
        conn.close()

        flash(
            "Compensation record not found or not authorized.",
            "error"
        )

        return redirect(
            url_for(
                "employee_compensation_history"
            )
        )

    # Safe now: ownership of the parent record
    # has been confirmed for the current spa.
    cur.execute("""
        SELECT compensation_type_id, amount
        FROM employee_compensation_lines
        WHERE compensation_id = %s
        ORDER BY compensation_type_id
    """, (
        compensation_id,
    ))

    existing_lines = cur.fetchall()

    cur.close()
    conn.close()

    # Pad to 4 rows for form display
    detail_rows = list(existing_lines)
    while len(detail_rows) < 4:
        detail_rows.append((None, ""))

    return render_template(
        "edit_employee_compensation.html",
        compensation=compensation,
        employees=employees,
        compensation_types=compensation_types,
        detail_rows=detail_rows
    )














