@app.route("/employees/add", methods=["GET", "POST"])
@login_required
@spa_required
def add_employee():
    spa_id = current_spa_id()
    conn = get_db_connection()
    cur = conn.cursor()

    if request.method == "POST":
        first_name = request.form.get("first_name")
        last_name = request.form.get("last_name")
        address_line1 = request.form.get("address_line1")
        address_line2 = request.form.get("address_line2")
        city = request.form.get("city")
        state = request.form.get("state")
        zip_code = request.form.get("zip_code")
        phone = request.form.get("phone")
        email = request.form.get("email")
        job_title = request.form.get("job_title")
        hire_date = request.form.get("hire_date")
        termination_date = request.form.get("termination_date")
        status = request.form.get("status")
        birthday = request.form.get("birthday")
        ssn_on_file = True if request.form.get("ssn_on_file") == "on" else False
        esthetician_license_number = request.form.get("esthetician_license_number")
        license_expiration_date = request.form.get("license_expiration_date")
        year_graduated = request.form.get("year_graduated")
        certifications = request.form.get("certifications")
        pay_type = request.form.get("pay_type")
        pay_rate = request.form.get("pay_rate")
        notes = request.form.get("notes")
        employee_nickname = request.form.get("employee_nickname", "").strip()
        employee_role_id = request.form.get("employee_role_id")
        provider_color_code = request.form.get("provider_color_code", "").strip()
        is_active = request.form.get("is_active") == "on"

        if not first_name or not last_name:
            flash("First name and last name are required.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("add_employee"))

        cur.execute("""
            INSERT INTO employees (
                spa_id,
                first_name,
                last_name,
                employee_nickname,
                employee_role_id,
                provider_color_code,
                is_active,
                address_line1,
                address_line2,
                city,
                state,
                zip_code,
                phone,
                email,
                job_title,
                hire_date,
                termination_date,
                status,
                birthday,
                ssn_on_file,
                esthetician_license_number,
                license_expiration_date,
                year_graduated,
                certifications,
                pay_type,
                pay_rate,
                notes
            )
            VALUES (
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s, %s, %s, %s,
                    %s, %s
            )
        """, (
            spa_id,
            first_name,
            last_name,
            employee_nickname or None,
            employee_role_id,
            provider_color_code or None,
            is_active,
            address_line1,
            address_line2,
            city,
            state,
            zip_code,
            phone,
            email,
            job_title,
            hire_date or None,
            termination_date or None,
            status,
            birthday or None,
            ssn_on_file,
            esthetician_license_number,
            license_expiration_date or None,
            year_graduated or None,
            certifications,
            pay_type,
            pay_rate or None,
            notes
        ))

        conn.commit()
        cur.close()
        conn.close()

        flash("Employee added successfully.", "success")
        return redirect(url_for("employees_home"))

    cur.execute("""
        SELECT
            employee_role_id,
            role_name
        FROM employee_roles
        WHERE spa_id = %s
        AND is_active = TRUE
        ORDER BY display_order, role_name
    """, (spa_id,))

    employee_roles = cur.fetchall()

    cur.execute("""
        SELECT status_name
        FROM employee_status
        WHERE spa_id = %s
        ORDER BY status_name ASC
    """, (spa_id,))
    statuses = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "add_employee.html",
        statuses=statuses,
        employee_roles=employee_roles
        )












