@app.route("/employees/<int:employee_id>")
@login_required
@spa_required
def employee_command_center(employee_id):
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor(cursor_factory=RealDictCursor)

    cur.execute("""
        SELECT
            e.employee_id,
            e.first_name,
            e.last_name,
            e.employee_nickname,
            e.employee_role_id,
            er.role_name,
            e.provider_color_code,
            e.is_active,
            e.address_line1,
            e.address_line2,
            e.city,
            e.state,
            e.zip_code,
            e.phone,
            e.email,
            e.job_title,
            e.hire_date,
            e.termination_date,
            e.status,
            e.birthday,
            e.ssn_on_file,
            e.esthetician_license_number,
            e.license_expiration_date,
            e.year_graduated,
            e.certifications,
            e.pay_type,
            e.pay_rate,
            e.notes,
            e.created_at
        FROM employees e
        LEFT JOIN employee_roles er
            ON er.employee_role_id = e.employee_role_id
           AND er.spa_id = e.spa_id
        WHERE e.employee_id = %s
          AND e.spa_id = %s
    """, (employee_id, spa_id))

    employee = cur.fetchone()

    if not employee:
        cur.close()
        conn.close()

        flash("Employee not found.", "error")
        return redirect(url_for("employees_home"))

    cur.close()
    conn.close()

    return render_template(
        "employee_command_center.html",
        employee=employee,
        today=date.today()
    )







