@app.route("/expenses")
@login_required
@spa_required
def expenses_home():
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            expense_id,
            expense_date,
            vendor_name,
            category,
            description,
            amount,
            payment_method,
            receipt_file,
            notes,
            created_at
        FROM expenses
        WHERE spa_id = %s
        ORDER BY expense_date DESC, expense_id DESC
        LIMIT 25
    """, (spa_id,))
    expenses = cur.fetchall()

    cur.execute("""
        SELECT COALESCE(SUM(amount), 0)
        FROM expenses
        WHERE spa_id = %s
          AND expense_date = CURRENT_DATE
    """, (spa_id,))
    today_total = cur.fetchone()[0]

    cur.execute("""
        SELECT COALESCE(SUM(amount), 0)
        FROM expenses
        WHERE spa_id = %s
          AND DATE_TRUNC('month', expense_date) = DATE_TRUNC('month', CURRENT_DATE)
    """, (spa_id,))
    month_total = cur.fetchone()[0]

    cur.close()
    conn.close()

    return render_template(
        "expenses_home.html",
        expenses=expenses,
        today_total=today_total,
        month_total=month_total
    )




















