def _load_expense_form_options(cur, spa_id):
    """
    Load active expense lookup values for one spa only.
    """

    cur.execute("""
        SELECT vendors_name
        FROM vendor_name
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY vendors_name
    """, (spa_id,))

    vendors = cur.fetchall()

    cur.execute("""
        SELECT expense_cat_name
        FROM expense_categories
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY expense_cat_name
    """, (spa_id,))

    categories = cur.fetchall()

    cur.execute("""
        SELECT payment_method
        FROM payment_methods
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY payment_method
    """, (spa_id,))

    payment_methods = cur.fetchall()

    return vendors, categories, payment_methods


def _validate_expense_lookup_values(
    cur,
    spa_id,
    vendor_name,
    category,
    payment_method
):
    """
    Prevent manually submitted lookup values from crossing spas.
    """

    cur.execute("""
        SELECT 1
        FROM vendor_name
        WHERE spa_id = %s
          AND vendors_name = %s
          AND is_active = TRUE
        LIMIT 1
    """, (
        spa_id,
        vendor_name
    ))

    if cur.fetchone() is None:
        return (
            "The selected vendor is not available "
            "for this business."
        )

    if category:
        cur.execute("""
            SELECT 1
            FROM expense_categories
            WHERE spa_id = %s
              AND expense_cat_name = %s
              AND is_active = TRUE
            LIMIT 1
        """, (
            spa_id,
            category
        ))

        if cur.fetchone() is None:
            return (
                "The selected expense category is not "
                "available for this business."
            )

    if payment_method:
        cur.execute("""
            SELECT 1
            FROM payment_methods
            WHERE spa_id = %s
              AND payment_method = %s
              AND is_active = TRUE
            LIMIT 1
        """, (
            spa_id,
            payment_method
        ))

        if cur.fetchone() is None:
            return (
                "The selected payment method is not "
                "available for this business."
            )

    return None



@app.route("/expenses/add", methods=["GET", "POST"])
@login_required
@spa_required
def add_expense():
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    if request.method == "POST":
        expense_date = (
            request.form.get("expense_date")
            or ""
        ).strip()

        vendor_name = (
            request.form.get("vendor_name")
            or ""
        ).strip()

        category = (
            request.form.get("category")
            or ""
        ).strip()

        description = (
            request.form.get("description")
            or ""
        ).strip()

        amount_value = (
            request.form.get("amount")
            or ""
        ).strip()

        payment_method = (
            request.form.get("payment_method")
            or ""
        ).strip()

        receipt_file = (
            request.form.get("receipt_file")
            or ""
        ).strip()

        notes = (
            request.form.get("notes")
            or ""
        ).strip()

        if (
            not expense_date
            or not vendor_name
            or not amount_value
        ):
            flash(
                (
                    "Expense date, vendor name, and "
                    "amount are required."
                ),
                "error"
            )

            cur.close()
            conn.close()

            return redirect(
                url_for("add_expense")
            )

        try:
            amount = Decimal(amount_value)

        except Exception:
            flash(
                "Amount must be a valid number.",
                "error"
            )

            cur.close()
            conn.close()

            return redirect(
                url_for("add_expense")
            )

        lookup_error = (
            _validate_expense_lookup_values(
                cur,
                spa_id,
                vendor_name,
                category,
                payment_method
            )
        )

        if lookup_error:
            flash(lookup_error, "error")

            cur.close()
            conn.close()

            return redirect(
                url_for("add_expense")
            )

        cur.execute("""
            INSERT INTO expenses (
                spa_id,
                expense_date,
                vendor_name,
                category,
                description,
                amount,
                payment_method,
                receipt_file,
                notes
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s
            )
        """, (
            spa_id,
            expense_date,
            vendor_name,
            category or None,
            description or None,
            amount,
            payment_method or None,
            receipt_file or None,
            notes or None
        ))

        conn.commit()

        cur.close()
        conn.close()

        flash(
            "Expense added successfully.",
            "success"
        )

        return redirect(
            url_for("expenses_home")
        )

    (
        vendors,
        categories,
        payment_methods
    ) = _load_expense_form_options(
        cur,
        spa_id
    )

    cur.close()
    conn.close()

    return render_template(
        "add_expense.html",
        today=date.today().isoformat(),
        vendors=vendors,
        categories=categories,
        payment_methods=payment_methods
    )



