@app.route(
    "/expenses/report",
    methods=["GET"]
)
@login_required
@spa_required
def expense_report():
    spa_id = current_spa_id()

    start_date = (
        request.args.get("start_date", "")
        or ""
    ).strip()

    end_date = (
        request.args.get("end_date", "")
        or ""
    ).strip()

    category = (
        request.args.get("category", "")
        or ""
    ).strip()

    vendor_name = (
        request.args.get("vendor_name", "")
        or ""
    ).strip()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            expense_cat_id,
            expense_cat_name
        FROM expense_categories
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY expense_cat_name
    """, (spa_id,))

    category_options = cur.fetchall()

    cur.execute("""
        SELECT
            vendor_id,
            vendors_name
        FROM vendor_name
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY vendors_name
    """, (spa_id,))

    vendor_options = cur.fetchall()

    query = """
        SELECT
            expense_id,
            expense_date,
            vendor_name,
            category,
            description,
            amount,
            payment_method,
            receipt_file,
            notes,
            created_at
        FROM expenses
        WHERE spa_id = %s
    """

    params = [spa_id]

    if start_date:
        query += " AND expense_date >= %s"
        params.append(start_date)

    if end_date:
        query += " AND expense_date <= %s"
        params.append(end_date)

    if category:
        query += " AND category = %s"
        params.append(category)

    if vendor_name:
        query += " AND vendor_name = %s"
        params.append(vendor_name)

    query += """
        ORDER BY expense_date DESC, created_at DESC
    """

    cur.execute(query, tuple(params))
    expenses = cur.fetchall()

    total_query = """
        SELECT COALESCE(SUM(amount), 0)
        FROM expenses
        WHERE spa_id = %s
    """

    total_params = [spa_id]

    if start_date:
        total_query += " AND expense_date >= %s"
        total_params.append(start_date)

    if end_date:
        total_query += " AND expense_date <= %s"
        total_params.append(end_date)

    if category:
        total_query += " AND category = %s"
        total_params.append(category)

    if vendor_name:
        total_query += " AND vendor_name = %s"
        total_params.append(vendor_name)

    cur.execute(
        total_query,
        tuple(total_params)
    )

    report_total = cur.fetchone()[0]

    category_totals_query = """
        SELECT
            category,
            COALESCE(SUM(amount), 0)
        FROM expenses
        WHERE spa_id = %s
    """

    category_totals_params = [spa_id]

    if start_date:
        category_totals_query += (
            " AND expense_date >= %s"
        )

        category_totals_params.append(
            start_date
        )

    if end_date:
        category_totals_query += (
            " AND expense_date <= %s"
        )

        category_totals_params.append(
            end_date
        )

    if category:
        category_totals_query += (
            " AND category = %s"
        )

        category_totals_params.append(
            category
        )

    if vendor_name:
        category_totals_query += (
            " AND vendor_name = %s"
        )

        category_totals_params.append(
            vendor_name
        )

    category_totals_query += """
        GROUP BY category
        ORDER BY category
    """

    cur.execute(
        category_totals_query,
        tuple(category_totals_params)
    )

    category_totals_rows = cur.fetchall()

    category_totals = {}

    for row in category_totals_rows:
        category_name = (
            row[0]
            if row[0]
            else "Uncategorized"
        )

        category_totals[
            category_name
        ] = row[1]

    cur.close()
    conn.close()

    return render_template(
        "expense_report.html",
        start_date=start_date,
        end_date=end_date,
        category=category,
        vendor_name=vendor_name,
        category_options=category_options,
        vendor_options=vendor_options,
        expenses=expenses,
        report_total=report_total,
        category_totals=category_totals
    )



