@app.route(
    "/expenses/edit/<int:expense_id>",
    methods=["GET", "POST"]
)
@login_required
@spa_required
def edit_expense(expense_id):
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    if request.method == "POST":
        expense_date = (
            request.form.get("expense_date")
            or ""
        ).strip()

        vendor_name = (
            request.form.get("vendor_name")
            or ""
        ).strip()

        category = (
            request.form.get("category")
            or ""
        ).strip()

        description = (
            request.form.get("description")
            or ""
        ).strip()

        amount_value = (
            request.form.get("amount")
            or ""
        ).strip()

        payment_method = (
            request.form.get("payment_method")
            or ""
        ).strip()

        receipt_file = (
            request.form.get("receipt_file")
            or ""
        ).strip()

        notes = (
            request.form.get("notes")
            or ""
        ).strip()

        if (
            not expense_date
            or not vendor_name
            or not amount_value
        ):
            flash(
                (
                    "Expense date, vendor name, and "
                    "amount are required."
                ),
                "error"
            )

            cur.close()
            conn.close()

            return redirect(
                url_for(
                    "edit_expense",
                    expense_id=expense_id
                )
            )

        try:
            amount = Decimal(amount_value)

        except Exception:
            flash(
                "Amount must be a valid number.",
                "error"
            )

            cur.close()
            conn.close()

            return redirect(
                url_for(
                    "edit_expense",
                    expense_id=expense_id
                )
            )

        lookup_error = (
            _validate_expense_lookup_values(
                cur,
                spa_id,
                vendor_name,
                category,
                payment_method
            )
        )

        if lookup_error:
            flash(lookup_error, "error")

            cur.close()
            conn.close()

            return redirect(
                url_for(
                    "edit_expense",
                    expense_id=expense_id
                )
            )

        cur.execute("""
            UPDATE expenses
            SET
                expense_date = %s,
                vendor_name = %s,
                category = %s,
                description = %s,
                amount = %s,
                payment_method = %s,
                receipt_file = %s,
                notes = %s
            WHERE spa_id = %s
              AND expense_id = %s
        """, (
            expense_date,
            vendor_name,
            category or None,
            description or None,
            amount,
            payment_method or None,
            receipt_file or None,
            notes or None,
            spa_id,
            expense_id
        ))

        if cur.rowcount == 0:
            conn.rollback()

            cur.close()
            conn.close()

            flash(
                (
                    "Expense not found or "
                    "not authorized."
                ),
                "error"
            )

            return redirect(
                url_for("expenses_home")
            )

        conn.commit()

        cur.close()
        conn.close()

        flash(
            "Expense updated successfully.",
            "success"
        )

        return redirect(
            url_for("expenses_home")
        )

    cur.execute("""
        SELECT
            expense_id,
            expense_date,
            vendor_name,
            category,
            description,
            amount,
            payment_method,
            receipt_file,
            notes,
            created_at
        FROM expenses
        WHERE spa_id = %s
          AND expense_id = %s
    """, (
        spa_id,
        expense_id
    ))

    expense = cur.fetchone()

    if not expense:
        cur.close()
        conn.close()

        flash(
            "Expense not found.",
            "error"
        )

        return redirect(
            url_for("expenses_home")
        )

    (
        vendors,
        categories,
        payment_methods
    ) = _load_expense_form_options(
        cur,
        spa_id
    )

    cur.close()
    conn.close()

    return render_template(
        "edit_expense.html",
        expense=expense,
        vendors=vendors,
        categories=categories,
        payment_methods=payment_methods
    )



