from flask import Response, request
import csv
import io

@app.route("/export_expense_report_csv")
@login_required
@spa_required
def export_expense_report_csv():
    spa_id = current_spa_id()
    start_date = request.args.get("start_date")
    end_date = request.args.get("end_date")
    category = request.args.get("category")
    vendor_name = request.args.get("vendor_name")

    conn = get_db_connection()
    cur = conn.cursor()

    query = """
        SELECT
            expense_date,
            vendor_name,
            category,
            description,
            amount,
            payment_method,
            notes
        FROM expenses
        WHERE spa_id =%s
           AND 1=1
    """
    params = [spa_id]

    if start_date:
        query += " AND expense_date >= %s"
        params.append(start_date)

    if end_date:
        query += " AND expense_date <= %s"
        params.append(end_date)

    if category:
        query += " AND category = %s"
        params.append(category)

    if vendor_name:
        query += " AND vendor_name = %s"
        params.append(vendor_name)

    query += " ORDER BY expense_date DESC, expense_id DESC"

    cur.execute(query, tuple(params))
    rows = cur.fetchall()

    cur.close()
    conn.close()

    output = io.StringIO()
    writer = csv.writer(output)

    # Header row
    writer.writerow([
        "Expense Date",
        "Vendor Name",
        "Category",
        "Description",
        "Amount",
        "Payment Method",
        "Notes"
    ])

    # Data rows
    for row in rows:
        writer.writerow(row)

    csv_data = output.getvalue()
    output.close()

    return Response(
        csv_data,
        mimetype="text/csv",
        headers={
            "Content-Disposition": "attachment; filename=expense_report.csv"
        }
    )



#  ------------------------------------------
#        EXPORT EXPENSES TO XLSX FORMAT
#  ------------------------------------------

from flask import send_file, request
from openpyxl import Workbook
from openpyxl.styles import Font
from io import BytesIO
from collections import defaultdict

@app.route("/export_expense_report_xlsx")
@login_required
@spa_required
def export_expense_report_xlsx():
    spa_id = current_spa_id()
    start_date = request.args.get("start_date")
    end_date = request.args.get("end_date")
    category = request.args.get("category")
    vendor_name = request.args.get("vendor_name")

    conn = get_db_connection()
    cur = conn.cursor()

    query = """
        SELECT
            expense_date,
            vendor_name,
            category,
            description,
            amount,
            payment_method,
            notes
        FROM expenses
        WHERE spa_id =%s
           AND 1=1
    """
    params = [spa_id]

    if start_date:
        query += " AND expense_date >= %s"
        params.append(start_date)

    if end_date:
        query += " AND expense_date <= %s"
        params.append(end_date)

    if category:
        query += " AND category = %s"
        params.append(category)

    if vendor_name:
        query += " AND vendor_name = %s"
        params.append(vendor_name)

    query += " ORDER BY expense_date DESC, expense_id DESC"

    cur.execute(query, tuple(params))
    rows = cur.fetchall()

    cur.close()
    conn.close()

    wb = Workbook()
    ws = wb.active
    ws.title = "Expense Report"

    # Title
    ws["A1"] = "Expense Report"
    ws["A1"].font = Font(bold=True, size=14)

    # Date range
    if start_date and end_date:
        ws["A2"] = f"Date Range: {start_date} to {end_date}"
    elif start_date:
        ws["A2"] = f"Date Range: From {start_date}"
    elif end_date:
        ws["A2"] = f"Date Range: Through {end_date}"
    else:
        ws["A2"] = "Date Range: All Expenses"

    # Headers
    headers = [
        "Expense Date",
        "Vendor Name",
        "Category",
        "Description",
        "Amount",
        "Payment Method",
        "Notes"
    ]

    header_row = 4
    for col_num, header in enumerate(headers, 1):
        cell = ws.cell(row=header_row, column=col_num, value=header)
        cell.font = Font(bold=True)

    # Data rows
    data_start_row = 5
    grand_total = 0
    category_totals = defaultdict(float)

    for row_index, row in enumerate(rows, start=data_start_row):
        expense_date, vendor_name, category, description, amount, payment_method, notes = row

        ws.cell(row=row_index, column=1, value=expense_date)
        ws.cell(row=row_index, column=2, value=vendor_name)
        ws.cell(row=row_index, column=3, value=category)
        ws.cell(row=row_index, column=4, value=description)
        ws.cell(row=row_index, column=5, value=float(amount) if amount is not None else 0)
        ws.cell(row=row_index, column=6, value=payment_method)
        ws.cell(row=row_index, column=7, value=notes)

        ws.cell(row=row_index, column=5).number_format = '$#,##0.00'

        amt = float(amount) if amount is not None else 0
        grand_total += amt
        category_totals[category or "Uncategorized"] += amt

    # Grand total
    total_row = data_start_row + len(rows) + 1
    ws.cell(row=total_row, column=4, value="GRAND TOTAL").font = Font(bold=True)
    ws.cell(row=total_row, column=5, value=grand_total).font = Font(bold=True)
    ws.cell(row=total_row, column=5).number_format = '$#,##0.00'

    # Category totals section
    category_start_row = total_row + 3
    ws.cell(row=category_start_row, column=1, value="Category Totals").font = Font(bold=True, size=12)

    ws.cell(row=category_start_row + 1, column=1, value="Category").font = Font(bold=True)
    ws.cell(row=category_start_row + 1, column=2, value="Total").font = Font(bold=True)

    current_row = category_start_row + 2
    for category, total in sorted(category_totals.items()):
        ws.cell(row=current_row, column=1, value=category)
        ws.cell(row=current_row, column=2, value=total)
        ws.cell(row=current_row, column=2).number_format = '$#,##0.00'
        current_row += 1

    # Column widths
    widths = {
        "A": 15,
        "B": 22,
        "C": 20,
        "D": 30,
        "E": 14,
        "F": 18,
        "G": 30
    }

    for col, width in widths.items():
        ws.column_dimensions[col].width = width

    # Filename
    filename = "expense_report.xlsx"
    if start_date and end_date:
        filename = f"expense_report_{start_date}_to_{end_date}.xlsx"
    elif start_date:
        filename = f"expense_report_from_{start_date}.xlsx"
    elif end_date:
        filename = f"expense_report_to_{end_date}.xlsx"

    output = BytesIO()
    wb.save(output)
    output.seek(0)

    return send_file(
        output,
        as_attachment=True,
        download_name=filename,
        mimetype="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"
    )













###############################################################
#######################################################
##################################################
#
#   AUTOMATIC EXPENSES. - -  RECURRING EXPENSES
#
#
################################


######################
#
#   ADVANCE AUTOMATIC EXPENSE DATE
#
######################


def advance_automatic_expense_date(current_date, frequency):
    if frequency == "weekly":
        return current_date + timedelta(days=7)

    months_to_add = {
        "monthly": 1,
        "quarterly": 3,
        "annual": 12,
    }.get(frequency)

    if months_to_add is None:
        raise ValueError(
            f"Unsupported recurring expense frequency: {frequency}"
        )

    month_index = (
        current_date.month - 1 + months_to_add
    )

    new_year = (
        current_date.year + month_index // 12
    )

    new_month = (
        month_index % 12 + 1
    )

    last_day_of_month = calendar.monthrange(
        new_year,
        new_month
    )[1]

    new_day = min(
        current_date.day,
        last_day_of_month
    )

    return date(
        new_year,
        new_month,
        new_day
    )





###################################################
#
#   POST AUTOMATIC EXPENSE PAYMENT -  RECURRING EXPENSE
#
##############################################################
####################################################



def post_automatic_expense_payment(
    automatic_expense_id,
    spa_id,
    posting_type,
    require_due=False,
    create_coach_alert=False
):
    if posting_type not in {"scheduled", "extra"}:
        return {
            "success": False,
            "message": "Invalid recurring expense posting type."
        }

    posted_date = get_spa_now(spa_id).date()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                ae.automatic_expense_id,       -- 0
                ae.expense_name,               -- 1
                ae.vendor_name,                -- 2
                ae.amount,                     -- 3
                ae.description,                -- 4
                ae.notes,                      -- 5
                ae.frequency,                  -- 6
                ae.next_post_date,             -- 7
                ae.end_date,                   -- 8
                ae.is_active,                  -- 9
                ec.expense_cat_name,           -- 10
                pm.payment_method              -- 11
            FROM automatic_expenses ae

            LEFT JOIN expense_categories ec
              ON ae.expense_cat_id = ec.expense_cat_id
             AND ae.spa_id = ec.spa_id

            LEFT JOIN payment_methods pm
              ON ae.payment_method_id = pm.payment_method_id
             AND ae.spa_id = pm.spa_id

            WHERE ae.automatic_expense_id = %s
              AND ae.spa_id = %s

            FOR UPDATE OF ae
        """, (
            automatic_expense_id,
            spa_id,
        ))

        recurring_expense = cur.fetchone()

        if recurring_expense is None:
            conn.rollback()

            return {
                "success": False,
                "message": "Recurring expense not found."
            }

        expense_name = recurring_expense[1]
        vendor_name = (
            recurring_expense[2]
            or expense_name
        )
        amount = recurring_expense[3]
        description = (
            recurring_expense[4]
            or expense_name
        )
        original_notes = recurring_expense[5]
        frequency = recurring_expense[6]
        scheduled_date = recurring_expense[7]
        end_date = recurring_expense[8]
        is_active = recurring_expense[9]
        category_name = (
            recurring_expense[10]
            or "Recurring Expense"
        )
        payment_method = recurring_expense[11]

        if posting_type == "scheduled":
            if not is_active:
                conn.rollback()

                return {
                    "success": False,
                    "message": (
                        "This recurring expense is not active."
                    )
                }

            if scheduled_date is None:
                conn.rollback()

                return {
                    "success": False,
                    "message": (
                        "This recurring expense does not have "
                        "a scheduled posting date."
                    )
                }


            if (
                require_due
                and scheduled_date > posted_date
            ):
                conn.rollback()

                return {
                    "success": False,
                    "not_due": True,
                    "message": (
                        "This recurring expense is not due yet."
                    )
                }

            cur.execute("""
                SELECT
                    occurrence_id,
                    occurrence_status,
                    expense_id
                FROM automatic_expense_occurrences
                WHERE spa_id = %s
                  AND automatic_expense_id = %s
                  AND scheduled_date = %s
                  AND posting_type = 'scheduled'
            """, (
                spa_id,
                automatic_expense_id,
                scheduled_date,
            ))

            existing_occurrence = cur.fetchone()

            if (
                existing_occurrence
                and existing_occurrence[1] == "posted"
            ):
                conn.rollback()

                return {
                    "success": False,
                    "already_posted": True,
                    "message": (
                        "The current scheduled payment "
                        "has already been posted."
                    )
                }

        else:
            existing_occurrence = None
            scheduled_date = posted_date


        expense_date = (
            scheduled_date
            if posting_type == "scheduled"
            else posted_date
        )

        posting_description = (
            "Scheduled recurring payment"
            if posting_type == "scheduled"
            else "Extra recurring payment"
        )

        notes_parts = []

        if original_notes:
            notes_parts.append(original_notes)

        notes_parts.append(
            f"{posting_description}: {expense_name}."
        )

        expense_notes = "\n".join(notes_parts)

        cur.execute("""
            INSERT INTO expenses (
                spa_id,
                expense_date,
                vendor_name,
                category,
                description,
                amount,
                payment_method,
                receipt_file,
                notes
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s, %s, NULL, %s
            )
            RETURNING expense_id
        """, (
            spa_id,
            expense_date,
            vendor_name,
            category_name,
            description,
            amount,
            payment_method,
            expense_notes,
        ))

        expense_id = cur.fetchone()[0]

        occurrence_id = None

        if existing_occurrence:
            occurrence_id = existing_occurrence[0]

            cur.execute("""
                UPDATE automatic_expense_occurrences
                SET
                    expense_id = %s,
                    occurrence_status = 'posted',
                    error_message = NULL,
                    processed_at = CURRENT_TIMESTAMP,
                    posting_type = 'scheduled'
                WHERE occurrence_id = %s
                  AND spa_id = %s
            """, (
                expense_id,
                existing_occurrence[0],
                spa_id,
            ))

        else:
            cur.execute("""
                INSERT INTO automatic_expense_occurrences (
                    spa_id,
                    automatic_expense_id,
                    scheduled_date,
                    expense_id,
                    occurrence_status,
                    error_message,
                    processed_at,
                    posting_type
                )
                VALUES (
                    %s, %s, %s, %s,
                    'posted', NULL,
                    CURRENT_TIMESTAMP,
                    %s
                )
                RETURNING occurrence_id
            """, (
                spa_id,
                automatic_expense_id,
                scheduled_date,
                expense_id,
                posting_type,
            ))

            occurrence_id = cur.fetchone()[0]

        next_post_date = recurring_expense[7]

        if posting_type == "scheduled":
            next_post_date = advance_automatic_expense_date(
                recurring_expense[7],
                frequency
            )

            if (
                end_date
                and next_post_date > end_date
            ):
                cur.execute("""
                    UPDATE automatic_expenses
                    SET
                        next_post_date = NULL,
                        last_processed_date = %s,
                        last_success_at = CURRENT_TIMESTAMP,
                        last_error_message = NULL,
                        last_error_at = NULL,
                        skip_next_occurrence = FALSE,
                        skipped_occurrence_date = NULL,
                        is_active = FALSE,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE automatic_expense_id = %s
                      AND spa_id = %s
                """, (
                    posted_date,
                    automatic_expense_id,
                    spa_id,
                ))

                next_post_date = None

            else:
                cur.execute("""
                    UPDATE automatic_expenses
                    SET
                        next_post_date = %s,
                        last_processed_date = %s,
                        last_success_at = CURRENT_TIMESTAMP,
                        last_error_message = NULL,
                        last_error_at = NULL,
                        skip_next_occurrence = FALSE,
                        skipped_occurrence_date = NULL,
                        updated_at = CURRENT_TIMESTAMP
                    WHERE automatic_expense_id = %s
                      AND spa_id = %s
                """, (
                    next_post_date,
                    posted_date,
                    automatic_expense_id,
                    spa_id,
                ))

                if (
                    create_coach_alert
                    and posting_type == "scheduled"
                    and occurrence_id
                ):
                    amount_text = f"${amount:,.2f}"

                    if next_post_date:
                        next_date_text = (
                            f"{next_post_date.strftime('%B')} "
                            f"{next_post_date.day}, "
                            f"{next_post_date.year}"
                        )

                        coach_alert_message = (
                            f"{expense_name} was posted automatically "
                            f"for {amount_text}. Its next scheduled "
                            f"date is {next_date_text}."
                        )

                    else:
                        coach_alert_message = (
                            f"{expense_name} was posted automatically "
                            f"for {amount_text}. This recurring expense "
                            "has reached the end of its schedule."
                        )

                    cur.execute("""
                        UPDATE automatic_expense_occurrences
                        SET
                            coach_alert_required = TRUE,
                            coach_alert_message = %s,
                            coach_alert_acknowledged_at = NULL
                        WHERE occurrence_id = %s
                        AND spa_id = %s
                    """, (
                        coach_alert_message,
                        occurrence_id,
                        spa_id,
                    ))

        conn.commit()

        return {
            "success": True,
            "expense_id": expense_id,
            "posting_type": posting_type,
            "next_post_date": next_post_date,
        }

    except Exception:
        conn.rollback()

        app.logger.exception(
            "Failed to post recurring expense %s.",
            automatic_expense_id
        )

        return {
            "success": False,
            "message": (
                "The recurring expense payment "
                "could not be posted."
            )
        }

    finally:
        cur.close()
        conn.close()








###################################################
#
#       POST CURRENT AUTOMATIC EXPENSE
#
##############################################################




@app.route(
    "/automatic-expenses/<int:automatic_expense_id>/post-current",
    methods=["POST"]
)
@login_required
@spa_required
def post_current_automatic_expense(automatic_expense_id):
    spa_id = current_spa_id()

    result = post_automatic_expense_payment(
        automatic_expense_id=automatic_expense_id,
        spa_id=spa_id,
        posting_type="scheduled"
    )

    if not result.get("success"):
        flash(
            result.get(
                "message",
                "The current payment could not be posted."
            ),
            "error"
        )

        return redirect(
            url_for("automatic_expenses")
        )

    next_post_date = result.get("next_post_date")

    if next_post_date:
        next_date_text = (
            f"{next_post_date.strftime('%B')} "
            f"{next_post_date.day}, "
            f"{next_post_date.year}"
        )

        flash(
            f"Payment posted. "
            f"Next scheduled date: {next_date_text}.",
            "success"
        )

    else:
        flash(
            "Payment posted. This recurring expense "
            "has reached the end of its schedule.",
            "success"
        )

    return redirect(
        url_for("automatic_expenses")
    )







