@app.route("/edit_income/<int:income_id>", methods=["GET", "POST"])
@login_required
@spa_required
def edit_income(income_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to edit income.",
            "error"
        )
        return redirect(url_for("income_report"))

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT income_id
        FROM income
        WHERE income_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
        LIMIT 1
    """, (
        income_id,
        spa_id,
        business_unit_id
    ))

    if not cur.fetchone():
        cur.close()
        conn.close()
        flash(
            "Income record not found in this "
            "Provider Workspace.",
            "error"
        )
        return redirect(url_for("income_report"))

    if request.method == "POST":
        income_date = request.form.get("income_date") or None
        income_type = request.form.get("income_type", "").strip()  or "General"
        employee_id = request.form.get("employee_id") or None

        service_amount = float(request.form.get("service_amount") or 0)
        retail_amount = float(request.form.get("retail_amount") or 0)
        tax_amount = float(request.form.get("tax_amount") or 0)
        tip_amount = float(request.form.get("tip_amount") or 0)

        total_amount = round(service_amount + retail_amount + tax_amount + tip_amount, 2)

        payment_method = request.form.get("payment_method", "").strip()
        credit_processor_id = request.form.get("credit_processor_id") or None
        processor_payment_id = request.form.get("processor_payment_id") or None

        processing_fee_amount = 0.00
        net_received = total_amount
        processor_percentage_fee = 0.00
        processor_flat_fee = 0.00
        processor_additional_fee = 0.00

        card_based_methods = ["card", "credit card", "apple pay", "google pay", "square"]

        if payment_method.lower() in card_based_methods:
            if credit_processor_id:
                cur.execute("""
                    SELECT percentage_fee, flat_fee, additional_fee
                    FROM credit_processors
                    WHERE credit_processor_id = %s
                      AND spa_id = %s
                      AND is_active = TRUE
                """, (credit_processor_id, spa_id))
                processor_row = cur.fetchone()

                if processor_row:
                    processor_percentage_fee = float(processor_row[0] or 0)
                    processor_flat_fee = float(processor_row[1] or 0)
                    processor_additional_fee = float(processor_row[2] or 0)

                    processing_fee_amount = round(
                        (total_amount * (processor_percentage_fee / 100))
                        + processor_flat_fee
                        + processor_additional_fee,
                        2
                    )
                    net_received = round(total_amount - processing_fee_amount, 2)
        else:
            credit_processor_id = None
            processor_payment_id = None

        description = request.form.get("description") or None
        notes = request.form.get("notes") or None
        client_id = request.form.get("client_id") or None

        if employee_id:
            cur.execute("""
                SELECT employee_id
                FROM employees
                WHERE employee_id = %s
                  AND spa_id = %s
                  AND is_active = TRUE
                LIMIT 1
            """, (
                employee_id,
                spa_id
            ))

            if not cur.fetchone():
                cur.close()
                conn.close()
                flash(
                    "Selected employee is not available "
                    "for this business.",
                    "error"
                )
                return redirect(
                    url_for(
                        "edit_income",
                        income_id=income_id
                    )
                )

        if client_id:
            cur.execute("""
                SELECT client_id
                FROM clients
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
                LIMIT 1
            """, (
                client_id,
                spa_id,
                business_unit_id
            ))

            if not cur.fetchone():
                cur.close()
                conn.close()
                flash(
                    "Selected client is not available "
                    "in this Provider Workspace.",
                    "error"
                )
                return redirect(
                    url_for(
                        "edit_income",
                        income_id=income_id
                    )
                )

        cur.execute("""
            UPDATE income
            SET
                income_date = %s,
                income_type = %s,
                description = %s,
                service_amount = %s,
                retail_amount = %s,
                tax_amount = %s,
                tip_amount = %s,
                total_amount = %s,
                payment_method = %s,
                processor_payment_id = %s,
                notes = %s,
                employee_id = %s,
                credit_processor_id = %s,
                processing_fee_amount = %s,
                net_received = %s,
                processor_percentage_fee = %s,
                processor_flat_fee = %s,
                processor_additional_fee = %s,
                client_id = %s
            WHERE income_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
        """, (
            income_date,
            income_type,
            description,
            service_amount,
            retail_amount,
            tax_amount,
            tip_amount,
            total_amount,
            payment_method,
            processor_payment_id,
            notes,
            employee_id,
            credit_processor_id,
            processing_fee_amount,
            net_received,
            processor_percentage_fee,
            processor_flat_fee,
            processor_additional_fee,
            client_id,
            income_id,
            spa_id,
            business_unit_id
        ))

        if cur.rowcount != 1:
            conn.rollback()
            cur.close()
            conn.close()
            flash(
                "Income record could not be updated "
                "in this Provider Workspace.",
                "error"
            )
            return redirect(url_for("income_report"))

        conn.commit()
        cur.close()
        conn.close()

        flash("Income record updated successfully.", "success")
        return redirect(url_for("income_report"))

    cur.execute("""
        SELECT
            i.income_id,
            i.income_date,
            i.income_type,
            i.description,
            i.service_amount,
            i.retail_amount,
            i.tax_amount,
            i.tip_amount,
            i.total_amount,
            i.payment_method,
            i.processor_payment_id,
            i.notes,
            i.client_id,
            i.employee_id,
            i.credit_processor_id,
            c.first_name,
            c.last_name
        FROM income i
        LEFT JOIN clients c
          ON i.client_id = c.client_id
         AND c.spa_id = i.spa_id
         AND c.business_unit_id = i.business_unit_id
        WHERE i.income_id = %s
          AND i.spa_id = %s
          AND i.business_unit_id = %s
    """, (
        income_id,
        spa_id,
        business_unit_id
    ))
    income_record = cur.fetchone()

    cur.execute("""
        SELECT client_id, first_name, last_name
        FROM clients
        WHERE spa_id = %s
          AND business_unit_id = %s
        ORDER BY last_name, first_name
    """, (
        spa_id,
        business_unit_id
    ))
    clients = cur.fetchall()

    cur.execute("""
        SELECT employee_id, first_name, last_name
        FROM employees
        WHERE spa_id = %s
        ORDER BY last_name, first_name
    """, (spa_id,))
    employees = cur.fetchall()

    cur.execute("""
        SELECT credit_processor_id, credit_processor_name
        FROM credit_processors
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY credit_processor_name
    """, (spa_id,))
    credit_processors = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "edit_income.html",
        income_record=income_record,
        clients=clients,
        employees=employees,
        credit_processors=credit_processors
    )






