from flask import render_template, request, redirect, url_for, flash
from decimal import Decimal, InvalidOperation
from db import get_db_connection


@app.route("/add_general_income", methods=["GET", "POST"])
@login_required
@spa_required
def add_general_income():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to add income.",
            "error"
        )
        return redirect(url_for("income_report"))

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT client_id, first_name, last_name
        FROM clients
        WHERE spa_id = %s
          AND business_unit_id = %s
        ORDER BY last_name, first_name
    """, (
        spa_id,
        business_unit_id
    ))
    clients = cur.fetchall()

    cur.execute("""
        SELECT income_type_name
        FROM income_types
        WHERE spa_id = %s
        ORDER BY income_type_name
    """, (spa_id,))
    income_types = cur.fetchall()

    cur.execute("""
        SELECT payment_method
        FROM payment_methods
        WHERE spa_id = %s
        ORDER BY payment_method
    """, (spa_id,))
    payment_methods = cur.fetchall()

    if request.method == "POST":
        income_date = request.form.get("income_date")
        client_id = request.form.get("client_id")
        income_type = request.form.get("income_type")
        description = request.form.get("description", "").strip()
        service_amount = request.form.get("service_amount", "0").strip()
        retail_amount = request.form.get("retail_amount", "0").strip()
        tax_amount = request.form.get("tax_amount", "0").strip()
        total_amount = request.form.get("total_amount", "0").strip()
        payment_method = request.form.get("payment_method")
        processor_payment_id = request.form.get(
            "processor_payment_id",
            ""
        ).strip()
        notes = request.form.get("notes", "").strip()

        try:
            service_amount = Decimal(service_amount) if service_amount else Decimal("0.00")
            retail_amount = Decimal(retail_amount) if retail_amount else Decimal("0.00")
            tax_amount = Decimal(tax_amount) if tax_amount else Decimal("0.00")
            total_amount = Decimal(total_amount) if total_amount else Decimal("0.00")
        except InvalidOperation:
            flash("Please enter valid numeric amounts.", "error")
            cur.close()
            conn.close()
            return render_template(
                "add_general_income.html",
                clients=clients,
                income_types=income_types,
                payment_methods=payment_methods
            )

        if not income_date:
            flash("Income date is required.", "error")
            cur.close()
            conn.close()
            return render_template("add_general_income.html", clients=clients, income_types=income_types, payment_methods=payment_methods)

        if not income_type:
            flash("Income type is required.", "error")
            cur.close()
            conn.close()
            return render_template("add_general_income.html", clients=clients, income_types=income_types, payment_methods=payment_methods)

        if not payment_method:
            flash("Payment method is required.", "error")
            cur.close()
            conn.close()
            return render_template("add_general_income.html", clients=clients, income_types=income_types, payment_methods=payment_methods)

        if total_amount < 0:
            flash("Total amount cannot be negative.", "error")
            cur.close()
            conn.close()
            return render_template("add_general_income.html", clients=clients, income_types=income_types, payment_methods=payment_methods)

        if client_id == "":
            client_id = None

        # Client must belong to the current Provider Workspace.
        if client_id:
            cur.execute("""
                SELECT client_id
                FROM clients
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
                LIMIT 1
            """, (
                client_id,
                spa_id,
                business_unit_id
            ))

            if not cur.fetchone():
                flash(
                    "Selected client is not available "
                    "in this Provider Workspace.",
                    "error"
                )
                cur.close()
                conn.close()
                return render_template(
                    "add_general_income.html",
                    clients=clients,
                    income_types=income_types,
                    payment_methods=payment_methods
                )

        cur.execute("""
            INSERT INTO income (
                spa_id,
                business_unit_id,
                income_date,
                client_id,
                appointment_id,
                visit_id,
                income_type,
                description,
                service_amount,
                retail_amount,
                tax_amount,
                total_amount,
                payment_method,
                processor_payment_id,
                notes
            )
            VALUES (
                %s, %s, %s, %s,
                NULL, NULL,
                %s, %s, %s, %s,
                %s, %s, %s, %s,
                %s
            )
        """, (
            spa_id,
            business_unit_id,
            income_date,
            client_id,
            income_type,
            description,
            service_amount,
            retail_amount,
            tax_amount,
            total_amount,
            payment_method,
            processor_payment_id,
            notes
        ))

        conn.commit()
        flash("General income entry added successfully.", "success")

        cur.close()
        conn.close()
        return redirect(url_for("add_general_income"))

    cur.close()
    conn.close()

    return render_template(
        "add_general_income.html",
        clients=clients,
        income_types=income_types,
        payment_methods=payment_methods
    )



