@app.route("/quick_reschedule_appointment/<int:appointment_id>", methods=["POST"])
@login_required
@spa_required
def quick_reschedule_appointment(appointment_id):
    spa_id = current_spa_id()
    user_id = session.get("user_id")
    role = session.get("role")

    appointment_date = request.form.get("appointment_date")
    appointment_time = request.form.get("appointment_time")

    if not appointment_date or not appointment_time:
        flash("Date and time are required to reschedule.", "error")
        return redirect(url_for("calendar_view"))

    conn = get_db_connection()
    cur = conn.cursor()

    filter_sql = "WHERE appointment_id = %s"
    params = [appointment_id]

    if role != "master_admin":
        filter_sql += " AND spa_id = %s"
        params.append(spa_id)

    cur.execute(f"""
        SELECT
            spa_id,
            client_id,
            appointment_date,
            appointment_time,
            status,
            business_unit_id,
            duration_minutes,
            provider_employee_id,
            service_type_id
        FROM appointments
        {filter_sql}
    """, params)

    old_appt = cur.fetchone()

    if not old_appt:
        cur.close()
        conn.close()
        flash("Appointment not found or not authorized.", "error")
        return redirect(url_for("calendar_view"))

    appointment_spa_id = old_appt[0]
    client_id = old_appt[1]
    old_date = old_appt[2]
    old_time = old_appt[3]
    old_status = old_appt[4]
    appointment_business_unit_id = old_appt[5]
    duration_minutes = old_appt[6]
    provider_employee_id = old_appt[7]
    service_type_id = old_appt[8]


    availability = (
        _appointment_reschedule_is_available(
            cur=cur,
            spa_id=appointment_spa_id,
            business_unit_id=
                appointment_business_unit_id,
            appointment_date=appointment_date,
            appointment_time=appointment_time,
            duration_minutes=duration_minutes,
            provider_employee_id=
                provider_employee_id,
            service_type_id=service_type_id,
            exclude_appointment_id=
                appointment_id
        )
    )

    if not availability.get("valid"):
        conn.rollback()
        cur.close()
        conn.close()

        flash(
            availability.get("message")
            or (
                "That appointment time is no "
                "longer available."
            ),
            "error"
        )

        return redirect(
            url_for("calendar_view")
        )



    cur.execute(f"""
        UPDATE appointments
        SET appointment_date = %s,
            appointment_time = %s,
            updated_at = CURRENT_TIMESTAMP
        {filter_sql}
    """, (
        appointment_date,
        appointment_time,
        *params
    ))

    if cur.rowcount == 0:
        conn.rollback()
        cur.close()
        conn.close()
        flash("Appointment not found or not authorized.", "error")
        return redirect(url_for("calendar_view"))

    action_type = "rescheduled"

    if str(old_date) == appointment_date and str(old_time)[:5] == appointment_time[:5]:
        action_type = "updated"

    log_audit(
        cur,
        spa_id=appointment_spa_id,
        user_id=user_id,
        action_type=f"appointment_{action_type}",
        table_name="appointments",
        record_id=appointment_id,
        old_value=f"{old_date} {old_time} {old_status}",
        new_value=f"{appointment_date} {appointment_time} {old_status}",
        notes="Appointment quick rescheduled" if action_type == "rescheduled" else "Appointment quick updated"
    )

    log_appointment_history(
        cur,
        spa_id=appointment_spa_id,
        appointment_id=appointment_id,
        client_id=client_id,
        user_id=user_id,
        action_type=action_type,
        old_date=old_date,
        old_time=old_time,
        new_date=appointment_date,
        new_time=appointment_time,
        old_status=old_status,
        new_status=old_status,
        notes="Appointment quick rescheduled" if action_type == "rescheduled" else "Appointment quick updated"
    )

    conn.commit()
    cur.close()
    conn.close()

    flash("Appointment rescheduled successfully.", "success")
    return redirect(url_for("calendar_view"))








