@app.route("/appointment-details/<int:appointment_id>")
@login_required
@spa_required
def appointment_details(appointment_id):
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            a.appointment_id,                 -- 0
            a.appointment_date,               -- 1
            a.appointment_time,               -- 2
            a.status,                         -- 3
            c.first_name,                     -- 4
            c.last_name,                      -- 5
            c.phone,                          -- 6
            c.email,                          -- 7
            COALESCE(
                NULLIF(snt.service_name, ''),
                NULLIF(a.service_type, ''),
                NULLIF(a.external_service_name, ''),
                s.service_name,
                'Service not entered'
            ) AS service_name,                -- 8
            a.notes,                          -- 9
            a.external_source,                -- 10
            a.duration_minutes,               -- 11
            a.price_at_booking,               -- 12
            a.appointment_for,                -- 13
            a.provider_name_at_booking,       -- 14
            COALESCE(
                a.booking_for_other,
                FALSE
            ) AS booking_for_other,            -- 15
            a.service_recipient_client_id,     -- 16
            a.booking_channel,                 -- 17
            a.contact_verification_type,       -- 18
            a.booking_contact_name_submitted,  -- 19
            a.booking_contact_email_submitted, -- 20
            a.booking_contact_phone_submitted, -- 21
            COALESCE(
                a.contact_verification_resolved,
                FALSE
            ) AS contact_verification_resolved, -- 22
            a.todays_contact_name,             -- 23
            a.todays_contact_phone,            -- 24
            a.todays_contact_note              -- 25
        FROM appointments a
        JOIN clients c
            ON a.client_id = c.client_id
        AND a.spa_id = c.spa_id
        LEFT JOIN service_name_types snt
            ON a.service_type_id = snt.service_type_id
        AND a.spa_id = snt.spa_id
        LEFT JOIN services s
            ON a.service_id = s.service_id
        AND a.spa_id = s.spa_id
        WHERE a.appointment_id = %s
        AND a.spa_id = %s
    """, (appointment_id, spa_id))




    appt = cur.fetchone()

    if not appt:
        cur.close()
        conn.close()
        return {"error": "Appointment not found."}, 404


    # Opening the Appointment Command Center counts as owner review
    # for appointments from every source.
    cur.execute("""
        UPDATE appointments
        SET
            owner_reviewed = TRUE,
            owner_reviewed_at = COALESCE(owner_reviewed_at, NOW())
        WHERE appointment_id = %s
          AND spa_id = %s
          AND (
                COALESCE(owner_reviewed, FALSE) = FALSE
             OR owner_reviewed_at IS NULL
          )
    """, (
        appointment_id,
        spa_id
    ))

    # GoDaddy appointments also require import-review fields.
    cur.execute("""
        UPDATE appointments
        SET
            import_reviewed = TRUE,
            import_reviewed_at = COALESCE(import_reviewed_at, NOW()),
            import_reviewed_by = COALESCE(import_reviewed_by, %s),
            import_status = 'Reviewed'
        WHERE appointment_id = %s
          AND spa_id = %s
          AND LOWER(COALESCE(external_source, '')) = 'godaddy'
          AND (
                COALESCE(import_reviewed, FALSE) = FALSE
             OR COALESCE(import_status, '') <> 'Reviewed'
          )
    """, (
        session.get("user_id"),
        appointment_id,
        spa_id
    ))

    conn.commit()

    cur.close()
    conn.close()

    return {
        "appointment_id": appt[0],
        "appointment_date": appt[1].strftime("%Y-%m-%d") if appt[1] else "",
        "start_time": appt[2].strftime("%I:%M %p") if appt[2] else "",
        "raw_time": appt[2].strftime("%H:%M") if appt[2] else "",
        "status": appt[3] or "",

        "client_name":
            f"{appt[4] or ''} {appt[5] or ''}".strip(),

        "booked_by_name":
            f"{appt[4] or ''} {appt[5] or ''}".strip(),

        "appointment_for":
            appt[13]
            or f"{appt[4] or ''} {appt[5] or ''}".strip(),

        "booking_for_other":
            bool(appt[15]),

        "service_recipient_client_id":
            appt[16],

        "phone": appt[6] or "",
        "email": appt[7] or "",
        "service_name": appt[8] or "",
        "provider_name": appt[14] or "",
        "notes": appt[9] or "",
        "external_source": appt[10] or "",
        "duration_minutes": appt[11],
        "price_at_booking": appt[12],
        "booking_channel": appt[17] or "",
        "contact_verification_type":
            appt[18] or "",
        "booking_contact_name_submitted":
            appt[19] or "",
        "booking_contact_email_submitted":
            appt[20] or "",
        "booking_contact_phone_submitted":
            appt[21] or "",
        "contact_verification_resolved":
            bool(appt[22]),

        "todays_contact_name":
            appt[23]
            or f"{appt[4] or ''} {appt[5] or ''}".strip(),

        "todays_contact_phone":
            appt[24]
            or appt[6]
            or "",

        "todays_contact_note":
            appt[25]
            or ""
    }






@app.route(
    "/appointment/<int:appointment_id>/todays-contact",
    methods=["POST"]
)
@login_required
@spa_required
def save_appointment_todays_contact(appointment_id):
    spa_id = current_spa_id()

    submitted = request.get_json(
        silent=True
    ) or request.form

    contact_name = (
        submitted.get("todays_contact_name", "")
        or ""
    ).strip()

    contact_phone = (
        submitted.get("todays_contact_phone", "")
        or ""
    ).strip()

    contact_note = (
        submitted.get("todays_contact_note", "")
        or ""
    ).strip()

    if len(contact_name) > 150:
        return {
            "error":
                "Today's Contact name cannot exceed "
                "150 characters."
        }, 400

    if len(contact_phone) > 50:
        return {
            "error":
                "Today's Contact phone cannot exceed "
                "50 characters."
        }, 400

    if len(contact_note) > 2000:
        return {
            "error":
                "Today's Contact note cannot exceed "
                "2,000 characters."
        }, 400

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            UPDATE appointments
            SET
                todays_contact_name = %s,
                todays_contact_phone = %s,
                todays_contact_note = %s
            WHERE appointment_id = %s
              AND spa_id = %s
            RETURNING client_id
        """, (
            contact_name or None,
            contact_phone or None,
            contact_note or None,
            appointment_id,
            spa_id
        ))

        updated_row = cur.fetchone()

        if not updated_row:
            conn.rollback()

            return {
                "error": "Appointment not found."
            }, 404

        client_id = updated_row[0]

        cur.execute("""
            SELECT
                first_name,
                last_name,
                phone
            FROM clients
            WHERE client_id = %s
              AND spa_id = %s
        """, (
            client_id,
            spa_id
        ))

        client_row = cur.fetchone()

        conn.commit()

    except Exception as error:
        conn.rollback()

        print(
            "SAVE TODAY'S CONTACT ERROR:",
            error
        )

        return {
            "error":
                "Today's Contact could not be saved."
        }, 500

    finally:
        cur.close()
        conn.close()

    default_name = ""

    default_phone = ""

    if client_row:
        default_name = (
            f"{client_row[0] or ''} "
            f"{client_row[1] or ''}"
        ).strip()

        default_phone = (
            client_row[2]
            or ""
        )

    return {
        "success": True,
        "message": "Today's Contact saved.",
        "todays_contact_name":
            contact_name
            or default_name,
        "todays_contact_phone":
            contact_phone
            or default_phone,
        "todays_contact_note":
            contact_note
    }


