# DAY VIEW
# =========================================================

@app.route("/calendar/day")
@login_required
@spa_required
def calendar_day_view():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    display_date = resolve_calendar_view_date()

    spa_now = get_spa_now(spa_id)
    today = spa_now.date()
    now_time = spa_now.time()
    current_minutes = (
        now_time.hour * 60
        + now_time.minute
    )

    previous_date = display_date - timedelta(days=1)
    next_date = display_date + timedelta(days=1)

    # booking_business_hours uses:
    # 0 = Sunday through 6 = Saturday.
    day_of_week = (
        display_date.weekday() + 1
    ) % 7

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                a.appointment_date,                         -- 0
                a.appointment_time,                         -- 1
                c.first_name,                               -- 2
                c.last_name,                                -- 3
                COALESCE(
                    NULLIF(snt.service_name, ''),
                    NULLIF(a.service_type, ''),
                    NULLIF(a.external_service_name, ''),
                    s.service_name,
                    'Service not entered'
                ) AS service_name,                          -- 4
                a.status,                                   -- 5
                a.appointment_id,                           -- 6
                a.duration_minutes,                         -- 7
                a.price_at_booking,                         -- 8
                COALESCE(a.owner_reviewed, FALSE),          -- 9
                a.appointment_for,                          -- 10
                a.provider_name_at_booking,                 -- 11
                a.room_number,                              -- 12
                a.notes,                                    -- 13
                a.client_id,                                -- 14
                a.external_source,                          -- 15
                a.provider_employee_id,                     -- 16
                pe.first_name,                              -- 17
                pe.last_name,                               -- 18
                pe.employee_nickname,                       -- 19
                pe.provider_color_code                      -- 20
            FROM appointments a

            JOIN clients c
                ON a.client_id = c.client_id
               AND a.spa_id = c.spa_id

            LEFT JOIN service_name_types snt
                ON a.service_type_id = snt.service_type_id
               AND a.spa_id = snt.spa_id

            LEFT JOIN services s
                ON a.service_id = s.service_id
               AND a.spa_id = s.spa_id

            LEFT JOIN employees pe
                ON pe.employee_id = a.provider_employee_id
               AND pe.spa_id = a.spa_id

            WHERE a.appointment_date = %s
              AND a.spa_id = %s

            ORDER BY
                a.appointment_time,
                a.appointment_id
        """, (
            display_date,
            spa_id
        ))

        appointments = cur.fetchall()

        business_hour_rows = []
        provider_hour_rows = []

        if business_unit_id is not None:
            cur.execute("""
                SELECT
                    start_time,
                    end_time
                FROM booking_business_hours
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND day_of_week = %s
                  AND is_active = TRUE
                ORDER BY
                    start_time,
                    end_time
            """, (
                spa_id,
                business_unit_id,
                day_of_week
            ))

            business_hour_rows = cur.fetchall()

            cur.execute("""
                SELECT
                    pbh.provider_employee_id,
                    e.first_name,
                    e.last_name,
                    e.employee_nickname,
                    e.provider_color_code,
                    pbh.start_time,
                    pbh.end_time
                FROM provider_booking_hours pbh

                JOIN employees e
                  ON e.employee_id =
                     pbh.provider_employee_id
                 AND e.spa_id = pbh.spa_id

                WHERE pbh.spa_id = %s
                  AND pbh.business_unit_id = %s
                  AND pbh.day_of_week = %s
                  AND pbh.is_active = TRUE
                  AND e.is_active = TRUE

                ORDER BY
                    COALESCE(
                        NULLIF(
                            TRIM(e.employee_nickname),
                            ''
                        ),
                        NULLIF(
                            TRIM(e.first_name),
                            ''
                        ),
                        e.employee_id::TEXT
                    ),
                    e.last_name,
                    pbh.start_time,
                    pbh.end_time
            """, (
                spa_id,
                business_unit_id,
                day_of_week
            ))

            provider_hour_rows = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    def time_to_minutes(time_value):
        return (
            time_value.hour * 60
            + time_value.minute
        )

    def format_minutes(total_minutes):
        total_minutes = total_minutes % (24 * 60)
        hour = total_minutes // 60
        minute = total_minutes % 60

        return datetime.strptime(
            f"{hour:02d}:{minute:02d}",
            "%H:%M"
        ).strftime("%-I:%M %p")

    def provider_display_name(
        employee_id,
        first_name,
        last_name,
        nickname
    ):
        nickname = (nickname or "").strip()
        first_name = (first_name or "").strip()
        last_name = (last_name or "").strip()

        full_name = (
            f"{first_name} {last_name}".strip()
        )

        return (
            nickname
            or full_name
            or f"Employee {employee_id}"
        )

    business_periods = []

    for start_time, end_time in business_hour_rows:
        business_periods.append({
            "start_minutes":
                time_to_minutes(start_time),
            "end_minutes":
                time_to_minutes(end_time),
            "start_display":
                format_minutes(
                    time_to_minutes(start_time)
                ),
            "end_display":
                format_minutes(
                    time_to_minutes(end_time)
                )
        })

    providers_by_id = {}

    for row in provider_hour_rows:
        employee_id = row[0]

        if employee_id not in providers_by_id:
            providers_by_id[employee_id] = {
                "provider_employee_id":
                    employee_id,
                "provider_key":
                    str(employee_id),
                "display_name":
                    provider_display_name(
                        employee_id,
                        row[1],
                        row[2],
                        row[3]
                    ),
                "color":
                    row[4] or "#8B5CF6",
                "periods": []
            }

        providers_by_id[
            employee_id
        ]["periods"].append({
            "start_minutes":
                time_to_minutes(row[5]),
            "end_minutes":
                time_to_minutes(row[6]),
            "start_display":
                format_minutes(
                    time_to_minutes(row[5])
                ),
            "end_display":
                format_minutes(
                    time_to_minutes(row[6])
                )
        })

    # Include assigned providers who have an appointment
    # even if no provider-hours row exists for the date.
    for appt in appointments:
        employee_id = appt[16]

        if (
            employee_id is not None
            and employee_id not in providers_by_id
        ):
            providers_by_id[employee_id] = {
                "provider_employee_id":
                    employee_id,
                "provider_key":
                    str(employee_id),
                "display_name":
                    provider_display_name(
                        employee_id,
                        appt[17],
                        appt[18],
                        appt[19]
                    ),
                "color":
                    appt[20] or "#8B5CF6",
                "periods": []
            }

    has_unassigned = any(
        appt[16] is None
        for appt in appointments
    )

    provider_columns = list(
        providers_by_id.values()
    )

    if has_unassigned:
        provider_columns.append({
            "provider_employee_id": None,
            "provider_key": "unassigned",
            "display_name":
                "Any Available / Unassigned",
            "color": "#7A7A7A",
            "periods": []
        })

    timeline_appointments = []

    for appt in appointments:
        start_minutes = (
            time_to_minutes(appt[1])
            if appt[1]
            else 0
        )

        duration_minutes = int(
            appt[7] or 30
        )

        end_minutes = min(
            start_minutes + duration_minutes,
            24 * 60
        )

        recipient_name = (
            appt[10]
            or (
                f"{appt[2] or ''} "
                f"{appt[3] or ''}"
            ).strip()
            or "Client"
        )

        timeline_appointments.append({
            "appointment_id": appt[6],
            "provider_employee_id":
                appt[16],
            "provider_key":
                str(appt[16])
                if appt[16] is not None
                else "unassigned",
            "start_minutes": start_minutes,
            "end_minutes": end_minutes,
            "duration_minutes":
                duration_minutes,
            "start_display":
                format_minutes(start_minutes),
            "recipient_name":
                recipient_name,
            "service_name":
                appt[4] or "Service not entered",
            "provider_name":
                appt[11] or "Any Available",
            "room_number":
                appt[12] or "",
            "status":
                (appt[5] or "").strip().lower(),
            "owner_reviewed":
                bool(appt[9]),
            "external_source":
                appt[15] or ""
        })

    range_starts = []
    range_ends = []

    for period in business_periods:
        range_starts.append(
            period["start_minutes"]
        )
        range_ends.append(
            period["end_minutes"]
        )

    for provider in provider_columns:
        for period in provider["periods"]:
            range_starts.append(
                period["start_minutes"]
            )
            range_ends.append(
                period["end_minutes"]
            )

    for appt in timeline_appointments:
        range_starts.append(
            appt["start_minutes"]
        )
        range_ends.append(
            appt["end_minutes"]
        )

    if range_starts and range_ends:
        timeline_start_minutes = (
            min(range_starts) // 30
        ) * 30

        timeline_end_minutes = (
            (
                max(range_ends) + 29
            ) // 30
        ) * 30
    else:
        timeline_start_minutes = 8 * 60
        timeline_end_minutes = 6 * 60 + 12 * 60

    timeline_start_minutes = max(
        0,
        timeline_start_minutes
    )

    timeline_end_minutes = min(
        24 * 60,
        timeline_end_minutes
    )

    if (
        timeline_end_minutes
        <= timeline_start_minutes
    ):
        timeline_end_minutes = min(
            24 * 60,
            timeline_start_minutes + 60
        )

    time_markers = []

    for marker_minutes in range(
        timeline_start_minutes,
        timeline_end_minutes + 1,
        30
    ):
        time_markers.append({
            "minutes": marker_minutes,
            "label":
                format_minutes(marker_minutes)
        })

    active_appointments = [
        appt
        for appt in appointments
        if (appt[5] or "").strip().lower()
        not in {"cancelled", "canceled"}
    ]

    appointment_count = len(
        active_appointments
    )

    return render_template(
        "calendar_day_view.html",
        display_date=display_date,
        previous_date=previous_date,
        next_date=next_date,
        today=today,
        now_time=now_time,
        current_minutes=current_minutes,
        appointments=appointments,
        appointment_count=appointment_count,
        business_periods=business_periods,
        provider_columns=provider_columns,
        timeline_appointments=(
            timeline_appointments
        ),
        timeline_start_minutes=(
            timeline_start_minutes
        ),
        timeline_end_minutes=(
            timeline_end_minutes
        ),
        timeline_total_minutes=(
            timeline_end_minutes
            - timeline_start_minutes
        ),
        time_markers=time_markers
    )


# =========================================================
# MONTH VIEW
# =========================================================

@app.route("/calendar/month")
@login_required
@spa_required
def calendar_month_view():
    import calendar as pycalendar
    from datetime import date, timedelta

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    selected_date = resolve_calendar_view_date()

    month_start = selected_date.replace(day=1)

    previous_month_date = (
        month_start - timedelta(days=1)
    ).replace(day=1)

    next_month_date = (
        month_start.replace(day=28)
        + timedelta(days=4)
    ).replace(day=1)

    today = get_spa_now(spa_id).date()

    month_calendar = pycalendar.Calendar(
        firstweekday=6
    )

    calendar_weeks = (
        month_calendar.monthdatescalendar(
            month_start.year,
            month_start.month
        )
    )

    while len(calendar_weeks) < 6:
        next_week_start = (
            calendar_weeks[-1][-1]
            + timedelta(days=1)
        )

        calendar_weeks.append([
            next_week_start
            + timedelta(days=day_offset)
            for day_offset in range(7)
        ])

    grid_start = calendar_weeks[0][0]
    grid_end = calendar_weeks[-1][-1]

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                a.appointment_date,
                a.appointment_id,
                COALESCE(
                    a.duration_minutes,
                    30
                ) AS duration_minutes,
                LOWER(
                    COALESCE(a.status, '')
                ) AS appointment_status,
                a.provider_employee_id,
                COALESCE(
                    NULLIF(
                        TRIM(e.employee_nickname),
                        ''
                    ),
                    NULLIF(
                        TRIM(
                            CONCAT_WS(
                                ' ',
                                e.first_name,
                                e.last_name
                            )
                        ),
                        ''
                    ),
                    NULLIF(
                        TRIM(
                            a.provider_name_at_booking
                        ),
                        ''
                    ),
                    'Any Available'
                ) AS provider_name,
                COALESCE(
                    NULLIF(
                        TRIM(e.provider_color_code),
                        ''
                    ),
                    '#8B5CF6'
                ) AS provider_color
            FROM appointments a

            LEFT JOIN employees e
              ON e.employee_id =
                 a.provider_employee_id
             AND e.spa_id = a.spa_id

            WHERE a.spa_id = %s
              AND a.appointment_date
                  BETWEEN %s AND %s

            ORDER BY
                a.appointment_date,
                a.appointment_time,
                a.appointment_id
        """, (
            spa_id,
            grid_start,
            grid_end
        ))

        appointment_rows = cur.fetchall()

        provider_minutes_by_weekday = {
            day_index: 0
            for day_index in range(7)
        }

        if business_unit_id is not None:
            cur.execute("""
                SELECT
                    day_of_week,
                    start_time,
                    end_time
                FROM provider_booking_hours
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND is_active = TRUE
                ORDER BY
                    day_of_week,
                    start_time,
                    end_time
            """, (
                spa_id,
                business_unit_id
            ))

            provider_hour_rows = cur.fetchall()

            for (
                day_of_week,
                start_time,
                end_time
            ) in provider_hour_rows:
                start_minutes = (
                    start_time.hour * 60
                    + start_time.minute
                )

                end_minutes = (
                    end_time.hour * 60
                    + end_time.minute
                )

                provider_minutes_by_weekday[
                    day_of_week
                ] += max(
                    0,
                    end_minutes - start_minutes
                )

    finally:
        cur.close()
        conn.close()

    day_data_by_date = {}

    for week in calendar_weeks:
        for calendar_date in week:
            day_data_by_date[calendar_date] = {
                "date": calendar_date,
                "is_current_month": (
                    calendar_date.month
                    == month_start.month
                ),
                "is_today": (
                    calendar_date == today
                ),
                "appointment_count": 0,
                "scheduled_minutes": 0,
                "provider_indicators": [],
                "density_level": 0,
                "utilization_percent": 0
            }

    provider_keys_by_date = {
        calendar_date: set()
        for calendar_date in day_data_by_date
    }

    for row in appointment_rows:
        appointment_date = row[0]
        appointment_status = row[3]

        if appointment_date not in day_data_by_date:
            continue

        if appointment_status in {
            "cancelled",
            "canceled"
        }:
            continue

        day_entry = day_data_by_date[
            appointment_date
        ]

        day_entry["appointment_count"] += 1
        day_entry["scheduled_minutes"] += int(
            row[2] or 30
        )

        provider_key = (
            row[4]
            if row[4] is not None
            else f"name:{row[5]}"
        )

        if (
            provider_key
            not in provider_keys_by_date[
                appointment_date
            ]
        ):
            provider_keys_by_date[
                appointment_date
            ].add(provider_key)

            day_entry[
                "provider_indicators"
            ].append({
                "provider_name":
                    row[5] or "Any Available",
                "provider_color":
                    row[6] or "#8B5CF6"
            })

    maximum_scheduled_minutes = max(
        (
            entry["scheduled_minutes"]
            for entry in day_data_by_date.values()
        ),
        default=0
    )

    for calendar_date, day_entry in (
        day_data_by_date.items()
    ):
        if day_entry["appointment_count"] == 0:
            continue

        # booking tables use:
        # 0 = Sunday through 6 = Saturday.
        day_of_week = (
            calendar_date.weekday() + 1
        ) % 7

        available_minutes = (
            provider_minutes_by_weekday.get(
                day_of_week,
                0
            )
        )

        if available_minutes > 0:
            utilization_ratio = min(
                day_entry["scheduled_minutes"]
                / available_minutes,
                1.0
            )
        elif maximum_scheduled_minutes > 0:
            utilization_ratio = min(
                day_entry["scheduled_minutes"]
                / maximum_scheduled_minutes,
                1.0
            )
        else:
            utilization_ratio = 0

        day_entry["utilization_percent"] = round(
            utilization_ratio * 100
        )

        if utilization_ratio <= 0.25:
            day_entry["density_level"] = 1
        elif utilization_ratio <= 0.50:
            day_entry["density_level"] = 2
        elif utilization_ratio <= 0.75:
            day_entry["density_level"] = 3
        else:
            day_entry["density_level"] = 4

    month_weeks = []

    for week in calendar_weeks:
        month_weeks.append([
            day_data_by_date[calendar_date]
            for calendar_date in week
        ])

    return render_template(
        "calendar_month_view.html",
        display_date=month_start,
        previous_month_date=previous_month_date,
        next_month_date=next_month_date,
        today=today,
        month_weeks=month_weeks
    )


