@app.route("/calendar/year")
@login_required
@spa_required
def calendar_year_view():
    import calendar as pycalendar
    from datetime import date, timedelta

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    selected_date = resolve_calendar_view_date()

    display_year = selected_date.year
    year_start = date(display_year, 1, 1)
    year_end = date(display_year, 12, 31)

    previous_year_date = date(
        display_year - 1,
        1,
        1
    )

    next_year_date = date(
        display_year + 1,
        1,
        1
    )

    today = get_spa_now(spa_id).date()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                a.appointment_date,
                COALESCE(
                    a.duration_minutes,
                    30
                ) AS duration_minutes,
                LOWER(
                    COALESCE(a.status, '')
                ) AS appointment_status,
                a.provider_employee_id,
                COALESCE(
                    NULLIF(
                        TRIM(e.employee_nickname),
                        ''
                    ),
                    NULLIF(
                        TRIM(
                            CONCAT_WS(
                                ' ',
                                e.first_name,
                                e.last_name
                            )
                        ),
                        ''
                    ),
                    NULLIF(
                        TRIM(
                            a.provider_name_at_booking
                        ),
                        ''
                    ),
                    'Any Available'
                ) AS provider_name,
                COALESCE(
                    NULLIF(
                        TRIM(e.provider_color_code),
                        ''
                    ),
                    '#8B5CF6'
                ) AS provider_color
            FROM appointments a

            LEFT JOIN employees e
              ON e.employee_id =
                 a.provider_employee_id
             AND e.spa_id = a.spa_id

            WHERE a.spa_id = %s
              AND a.appointment_date
                  BETWEEN %s AND %s

            ORDER BY
                a.appointment_date,
                a.appointment_time,
                a.appointment_id
        """, (
            spa_id,
            year_start,
            year_end
        ))

        appointment_rows = cur.fetchall()

        provider_minutes_by_weekday = {
            day_index: 0
            for day_index in range(7)
        }

        if business_unit_id is not None:
            cur.execute("""
                SELECT
                    day_of_week,
                    start_time,
                    end_time
                FROM provider_booking_hours
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND is_active = TRUE
                ORDER BY
                    day_of_week,
                    start_time,
                    end_time
            """, (
                spa_id,
                business_unit_id
            ))

            provider_hour_rows = cur.fetchall()

            for (
                day_of_week,
                start_time,
                end_time
            ) in provider_hour_rows:
                start_minutes = (
                    start_time.hour * 60
                    + start_time.minute
                )

                end_minutes = (
                    end_time.hour * 60
                    + end_time.minute
                )

                provider_minutes_by_weekday[
                    day_of_week
                ] += max(
                    0,
                    end_minutes - start_minutes
                )

    finally:
        cur.close()
        conn.close()

    day_data_by_date = {}

    calendar_date = year_start

    while calendar_date <= year_end:
        day_data_by_date[calendar_date] = {
            "date": calendar_date,
            "is_current_month": True,
            "is_today": calendar_date == today,
            "appointment_count": 0,
            "scheduled_minutes": 0,
            "provider_indicators": [],
            "density_level": 0,
            "utilization_percent": 0
        }

        calendar_date += timedelta(days=1)

    provider_keys_by_date = {
        calendar_date: set()
        for calendar_date in day_data_by_date
    }

    for row in appointment_rows:
        appointment_date = row[0]
        appointment_status = row[2]

        if appointment_date not in day_data_by_date:
            continue

        if appointment_status in {
            "cancelled",
            "canceled"
        }:
            continue

        day_entry = day_data_by_date[
            appointment_date
        ]

        day_entry["appointment_count"] += 1
        day_entry["scheduled_minutes"] += int(
            row[1] or 30
        )

        provider_key = (
            row[3]
            if row[3] is not None
            else f"name:{row[4]}"
        )

        if (
            provider_key
            not in provider_keys_by_date[
                appointment_date
            ]
        ):
            provider_keys_by_date[
                appointment_date
            ].add(provider_key)

            day_entry[
                "provider_indicators"
            ].append({
                "provider_name":
                    row[4] or "Any Available",
                "provider_color":
                    row[5] or "#8B5CF6"
            })

    maximum_scheduled_minutes = max(
        (
            entry["scheduled_minutes"]
            for entry in day_data_by_date.values()
        ),
        default=0
    )

    for calendar_date, day_entry in (
        day_data_by_date.items()
    ):
        if day_entry["appointment_count"] == 0:
            continue

        # Booking tables use:
        # 0 = Sunday through 6 = Saturday.
        day_of_week = (
            calendar_date.weekday() + 1
        ) % 7

        available_minutes = (
            provider_minutes_by_weekday.get(
                day_of_week,
                0
            )
        )

        if available_minutes > 0:
            utilization_ratio = min(
                day_entry["scheduled_minutes"]
                / available_minutes,
                1.0
            )

        elif maximum_scheduled_minutes > 0:
            utilization_ratio = min(
                day_entry["scheduled_minutes"]
                / maximum_scheduled_minutes,
                1.0
            )

        else:
            utilization_ratio = 0

        day_entry["utilization_percent"] = round(
            utilization_ratio * 100
        )

        if utilization_ratio <= 0.25:
            day_entry["density_level"] = 1
        elif utilization_ratio <= 0.50:
            day_entry["density_level"] = 2
        elif utilization_ratio <= 0.75:
            day_entry["density_level"] = 3
        else:
            day_entry["density_level"] = 4

    month_calendar = pycalendar.Calendar(
        firstweekday=6
    )

    year_months = []

    for month_number in range(1, 13):
        month_start = date(
            display_year,
            month_number,
            1
        )

        calendar_weeks = (
            month_calendar.monthdatescalendar(
                display_year,
                month_number
            )
        )

        while len(calendar_weeks) < 6:
            next_week_start = (
                calendar_weeks[-1][-1]
                + timedelta(days=1)
            )

            calendar_weeks.append([
                next_week_start
                + timedelta(days=day_offset)
                for day_offset in range(7)
            ])

        month_weeks = []
        month_appointment_count = 0
        month_scheduled_minutes = 0

        for week in calendar_weeks:
            week_entries = []

            for calendar_date in week:
                is_current_month = (
                    calendar_date.year
                    == display_year
                    and calendar_date.month
                    == month_number
                )

                if is_current_month:
                    day_entry = day_data_by_date[
                        calendar_date
                    ]

                    month_appointment_count += (
                        day_entry[
                            "appointment_count"
                        ]
                    )

                    month_scheduled_minutes += (
                        day_entry[
                            "scheduled_minutes"
                        ]
                    )

                    week_entries.append(
                        day_entry
                    )

                else:
                    week_entries.append({
                        "date": calendar_date,
                        "is_current_month": False,
                        "is_today": False,
                        "appointment_count": 0,
                        "scheduled_minutes": 0,
                        "provider_indicators": [],
                        "density_level": 0,
                        "utilization_percent": 0
                    })

            month_weeks.append(
                week_entries
            )

        year_months.append({
            "month_start": month_start,
            "month_name":
                month_start.strftime("%B"),
            "weeks": month_weeks,
            "appointment_count":
                month_appointment_count,
            "scheduled_minutes":
                month_scheduled_minutes
        })

    year_appointment_count = sum(
        month["appointment_count"]
        for month in year_months
    )

    year_scheduled_minutes = sum(
        month["scheduled_minutes"]
        for month in year_months
    )

    return render_template(
        "calendar_year_view.html",
        display_date=year_start,
        previous_year_date=previous_year_date,
        next_year_date=next_year_date,
        today=today,
        year_months=year_months,
        year_appointment_count=
            year_appointment_count,
        year_scheduled_minutes=
            year_scheduled_minutes
    )

@app.route("/daily_schedule")
@login_required
@spa_required
def daily_schedule():
    spa_id = current_spa_id()
    role = session.get("role")

    selected_date = request.args.get("date")

    if selected_date:
        display_date = datetime.strptime(selected_date, "%Y-%m-%d").date()
    else:
        display_date = get_spa_today()

    conn = get_db_connection()
    cur = conn.cursor()

    filter_sql = "WHERE a.appointment_date = %s"
    params = [display_date]

    if role != "master_admin":
        filter_sql += " AND a.spa_id = %s"
        params.append(spa_id)

    cur.execute(f"""
        SELECT
            a.appointment_id,                              -- 0
            a.client_id,                                   -- 1
            c.first_name,                                  -- 2
            c.last_name,                                   -- 3
            COALESCE(a.service_type, s.service_name),       -- 4
            a.appointment_time,                            -- 5
            a.duration_minutes,                            -- 6
            a.room_number,                                 -- 7
            a.status,                                      -- 8
            a.notes,                                       -- 9
            a.price_at_booking,                             -- 10
            a.provider_name_at_booking                      --11
        FROM appointments a
        JOIN clients c
            ON a.client_id = c.client_id
        AND a.spa_id = c.spa_id
        LEFT JOIN services s
            ON a.service_id = s.service_id
        AND a.spa_id = s.spa_id
        {filter_sql}
        ORDER BY a.appointment_time
    """, params)

    appointments = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "daily_schedule.html",
        appointments=appointments,
        display_date=display_date
    )






