from flask import render_template
from db import get_db_connection
from datetime import date, timedelta




@app.route("/dashboard")
@login_required
@spa_required
def dashboard():

    if session.get("role") == "master_admin":
       return redirect(url_for("feedback_admin"))

    spa_id = current_spa_id()
    conn = get_db_connection()
    cur = conn.cursor()

    spa_now = get_spa_now()
    today = spa_now.date()
    year_start = date(today.year, 1, 1)
    now_time = spa_now.time()

    # Safe defaults
    birthday_alert_count = 0
    expiring_gc_count = 0
    next_appt = None
    today_count = 0
    upcoming_count = 0
    completed_count = 0
    total_clients = 0
    revenue_today = 0.00
    todays_appointments = []
    upcoming_appointments = []
    top_services = []

    # Total clients
    cur.execute("""
        SELECT COUNT(*)
        FROM clients
        WHERE spa_id = %s
    """, (spa_id,))
    total_clients = cur.fetchone()[0] or 0

    # Revenue today
    cur.execute("""
        SELECT COALESCE(SUM(total_amount), 0)
        FROM income
        WHERE spa_id = %s
          AND income_date = %s
    """, (spa_id, today))
    revenue_today = cur.fetchone()[0] or 0.00

    # Birthday alert count
    # Adjust this query if your birthday table/logic differs
    cur.execute("""
        SELECT COUNT(*)
        FROM client_birthday_offers cbo
        JOIN clients c
            ON c.client_id = cbo.client_id
           AND c.spa_id = cbo.spa_id
        WHERE c.spa_id = %s
          AND cbo.offer_sent = FALSE
          AND cbo.birthday_year = %s
    """, (spa_id, today.year))
    birthday_alert_count = cur.fetchone()[0] or 0

    # Expiring gift certificate count
    cur.execute("""
        SELECT COUNT(*)
        FROM gift_certificates gc
        JOIN gift_certificate_statuses gcs
        ON gc.gift_certificate_status_id = gcs.gift_certificate_status_id
        WHERE gc.spa_id = %s
        AND gcs.status_name = 'Active'
        AND gc.amount_paid > 0
        AND gc.is_redeemed = FALSE
        AND gc.remaining_balance > 0
        AND gc.expires_date BETWEEN %s AND (%s + INTERVAL '60 days')
    """, (spa_id, today, today))
    expiring_gc_count = cur.fetchone()[0] or 0

    # Next appointment
    cur.execute("""
        SELECT
            a.appointment_id,
            c.first_name,
            c.last_name,
            a.appointment_date,
            a.appointment_time,
            s.service_name
        FROM appointments a
        JOIN clients c
            ON a.client_id = c.client_id
           AND a.spa_id = c.spa_id
        LEFT JOIN services s
            ON a.service_id = s.service_id
           AND a.spa_id = s.spa_id
        WHERE a.spa_id = %s
          AND a.status = 'booked'
          AND (
                a.appointment_date > %s
                OR (
                    a.appointment_date = %s
                    AND a.appointment_time >= %s
                )
              )
        ORDER BY a.appointment_date, a.appointment_time
        LIMIT 1
    """, (spa_id, today, today, now_time))
    row = cur.fetchone()
    if row:
        # Make it match template indexes:
        # next_appt[0] first_name
        # next_appt[1] last_name
        # next_appt[2] appointment_date
        # next_appt[3] appointment_time
        # next_appt[4] service_name
        next_appt = (row[1], row[2], row[3], row[4], row[5])

    # Today's appointments count
    cur.execute("""
        SELECT COUNT(*)
        FROM appointments
        WHERE spa_id = %s
          AND appointment_date = %s
    """, (spa_id, today))
    today_count = cur.fetchone()[0] or 0

    # Upcoming appointments count
    cur.execute("""
        SELECT COUNT(*)
        FROM appointments
        WHERE spa_id = %s
          AND status = 'booked'
          AND (
                appointment_date > %s
                OR (
                    appointment_date = %s
                    AND appointment_time > %s
                )
              )
    """, (spa_id, today, today, now_time))
    upcoming_count = cur.fetchone()[0] or 0

    # Completed appointments count
    cur.execute("""
        SELECT COUNT(*)
        FROM appointments
        WHERE spa_id = %s
          AND status = 'completed'
    """, (spa_id,))
    completed_count = cur.fetchone()[0] or 0


    cur.execute("""
        SELECT COALESCE(SUM(total_amount), 0)
        FROM income
        WHERE spa_id = %s
          AND income_date BETWEEN %s AND %s
    """, (spa_id, year_start, today))

    ytd_income = cur.fetchone()[0]


    cur.execute("""
        SELECT COALESCE(SUM(amount), 0)
        FROM expenses
        WHERE spa_id = %s
          AND expense_date BETWEEN %s AND %s
    """, (spa_id, year_start, today))

    ytd_expenses = cur.fetchone()[0]


    cur.execute("""
        SELECT COALESCE(SUM(amount), 0)
        FROM employee_compensation
        WHERE spa_id = %s
          AND compensation_date BETWEEN %s AND %s
    """, (spa_id, year_start, today))

    ytd_employee_compensation = cur.fetchone()[0]


    # Today's appointment table
    cur.execute("""
        SELECT
            a.appointment_id,      -- row[0]
            c.first_name,          -- row[1]
            c.last_name,           -- row[2]
            s.service_name,        -- row[3]
            a.appointment_date,    -- row[4]
            a.appointment_time,    -- row[5]
            a.status               -- row[6]
        FROM appointments a
        JOIN clients c ON a.client_id = c.client_id
        LEFT JOIN services s ON a.service_id = s.service_id
        WHERE a.spa_id = %s
          AND a.appointment_date = %s
        ORDER BY a.appointment_time
    """, (spa_id, today))
    todays_appointments = cur.fetchall()

    # Upcoming appointments table
    cur.execute("""
        SELECT
            a.appointment_id,      -- row[0]
            c.first_name,          -- row[1]
            c.last_name,           -- row[2]
            s.service_name,        -- row[3]
            a.appointment_date,    -- row[4]
            a.appointment_time,    -- row[5]
            a.status               -- row[6]
        FROM appointments a
        JOIN clients c ON a.client_id = c.client_id
        LEFT JOIN services s ON a.service_id = s.service_id
        WHERE a.spa_id = %s
          AND (
                a.appointment_date > %s
                OR (
                    a.appointment_date = %s
                    AND a.appointment_time > %s
                )
              )
        ORDER BY a.appointment_date, a.appointment_time
        LIMIT 10
    """, (spa_id, today, today, now_time))
    upcoming_appointments = cur.fetchall()

    # Top services
    cur.execute("""
        SELECT
            COALESCE(s.service_name, 'Unknown Service') AS service_name,
            COUNT(*) AS booked_count
        FROM appointments a
        LEFT JOIN services s ON a.service_id = s.service_id
        WHERE a.spa_id = %s
        GROUP BY COALESCE(s.service_name, 'Unknown Service')
        ORDER BY booked_count DESC, service_name ASC
        LIMIT 5
    """, (spa_id,))
    top_services = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "home.html",
        ytd_income=ytd_income,
        ytd_expenses=ytd_expenses,
        ytd_employee_compensation=ytd_employee_compensation,
        birthday_alert_count=birthday_alert_count,
        expiring_gc_count=expiring_gc_count,
        next_appt=next_appt,
        today_count=today_count,
        upcoming_count=upcoming_count,
        completed_count=completed_count,
        total_clients=total_clients,
        revenue_today=revenue_today,
        todays_appointments=todays_appointments,
        upcoming_appointments=upcoming_appointments,
        top_services=top_services
    )




# #######################################
#
#      MORNING BRIEFING. DAILY BRIEFING
#
# ##########################################



def calculate_business_health(
    dashboard,
    business_schedule_due=None,
    godaddy_unreviewed_count=0
):
    business_schedule_due = (
        business_schedule_due or []
    )

    score = 100
    factors = []

    def add_deduction(
        category,
        count,
        points,
        message
    ):
        nonlocal score

        if count <= 0:
            return

        score -= points

        factors.append({
            "category": category,
            "count": count,
            "points": points,
            "message": message,
        })

    # ---------------------------------------------------------
    # Recurring-expense processing failures
    # ---------------------------------------------------------
    failed_recurring = len(
        dashboard.get(
            "recurring_expenses_failed",
            []
        ) or []
    )

    add_deduction(
        category="Recurring Expense Failures",
        count=failed_recurring,
        points=min(
            failed_recurring * 20,
            40
        ),
        message=(
            f"{failed_recurring} recurring expense "
            f"{'has' if failed_recurring == 1 else 'have'} "
            "a processing failure."
        )
    )

    # ---------------------------------------------------------
    # Past-due recurring expenses
    # ---------------------------------------------------------
    past_due_recurring = len(
        dashboard.get(
            "recurring_expenses_past_due",
            []
        ) or []
    )

    add_deduction(
        category="Past-Due Recurring Expenses",
        count=past_due_recurring,
        points=min(
            past_due_recurring * 12,
            36
        ),
        message=(
            f"{past_due_recurring} recurring "
            f"{'expense is' if past_due_recurring == 1 else 'expenses are'} "
            "past due."
        )
    )

    # ---------------------------------------------------------
    # Reminder-only expenses due today
    # ---------------------------------------------------------
    due_today_recurring = (
        dashboard.get(
            "recurring_expenses_due_today",
            []
        )
        or []
    )

    reminder_only_due_today = sum(
        1
        for expense in due_today_recurring
        if expense.get(
            "processing_type"
        ) == "reminder_only"
    )

    add_deduction(
        category="Recurring Expenses Due Today",
        count=reminder_only_due_today,
        points=min(
            reminder_only_due_today * 5,
            15
        ),
        message=(
            f"{reminder_only_due_today} recurring "
            f"{'expense requires' if reminder_only_due_today == 1 else 'expenses require'} "
            "manual posting today."
        )
    )

    # ---------------------------------------------------------
    # Overdue appointments
    # ---------------------------------------------------------
    overdue_appointments = len(
        dashboard.get(
            "overdue_appointments",
            []
        ) or []
    )

    add_deduction(
        category="Overdue Appointments",
        count=overdue_appointments,
        points=min(
            overdue_appointments * 10,
            30
        ),
        message=(
            f"{overdue_appointments} "
            f"{'appointment needs' if overdue_appointments == 1 else 'appointments need'} "
            "closeout."
        )
    )

    # ---------------------------------------------------------
    # Unreviewed GoDaddy imports
    # ---------------------------------------------------------
    godaddy_unreviewed_count = int(
        godaddy_unreviewed_count or 0
    )

    add_deduction(
        category="GoDaddy Imports",
        count=godaddy_unreviewed_count,
        points=min(
            godaddy_unreviewed_count * 5,
            20
        ),
        message=(
            f"{godaddy_unreviewed_count} imported "
            f"{'appointment needs' if godaddy_unreviewed_count == 1 else 'appointments need'} "
            "review."
        )
    )

    # ---------------------------------------------------------
    # Business schedule responsibilities due
    # ---------------------------------------------------------
    business_schedule_due_count = len(
        business_schedule_due
    )

    add_deduction(
        category="Business Schedule",
        count=business_schedule_due_count,
        points=min(
            business_schedule_due_count * 6,
            18
        ),
        message=(
            f"{business_schedule_due_count} business "
            f"{'responsibility is' if business_schedule_due_count == 1 else 'responsibilities are'} "
            "due."
        )
    )

    score = max(
        0,
        min(100, score)
    )

    if score >= 90:
        label = "Excellent"
    elif score >= 80:
        label = "Good"
    elif score >= 65:
        label = "Needs Attention"
    else:
        label = "At Risk"

    if factors:
        summary = factors[0]["message"]
    else:
        summary = (
            "All monitored business operations are current."
        )

    return {
        "score": score,
        "label": label,
        "summary": summary,
        "issue_count": len(factors),

        "affected_item_count": sum(
            factor["count"]
            for factor in factors
        ),
        "factors": factors,
    }




