@app.route("/morning_briefing")
@login_required
@spa_required
@require_workspace_permission("can_view_daily_briefing")
def morning_briefing():

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    user_id = session["user_id"]

    spa_now = get_spa_now(spa_id)
    today = spa_now.date()
    tomorrow = today + timedelta(days=1)
    now_time = spa_now.time()

    dashboard = get_dashboard_data(
        spa_id=spa_id,
        business_unit_id=business_unit_id,
        spa_now=spa_now
    )

    business_health = {
        "score": None,
        "label": "Not Calculated"
    }

    conn = get_db_connection()
    cur = conn.cursor()


    # ---------------------------------------------------------
    # Start or resume today's Coach session
    # ---------------------------------------------------------
    coach_session = get_or_create_coach_daily_session(
        cur=cur,
        spa_id=spa_id,
        user_id=user_id,
        session_date=today
    )


    # ---------------------------------------------------------
    # Business schedule items due now
    # ---------------------------------------------------------
    cur.execute("""
        SELECT
            schedule_id,
            category,
            title,
            description,
            due_date,
            recurrence_type,
            recurrence_interval,
            reminder_days,
            is_required
        FROM business_schedule
        WHERE spa_id = %s
          AND is_active = TRUE
          AND COALESCE(is_completed, FALSE) = FALSE
          AND due_date IS NOT NULL
          AND due_date <= %s
        ORDER BY
            due_date ASC,
            category,
            title
        LIMIT 5
    """, (spa_id, today))

    business_schedule_due = cur.fetchall()

    # ---------------------------------------------------------
    # Business schedule items coming up within 14 days
    # ---------------------------------------------------------
    cur.execute("""
        SELECT
            schedule_id,
            category,
            title,
            description,
            due_date,
            recurrence_type,
            recurrence_interval,
            reminder_days,
            is_required
        FROM business_schedule
        WHERE spa_id = %s
          AND is_active = TRUE
          AND COALESCE(is_completed, FALSE) = FALSE
          AND due_date IS NOT NULL
          AND due_date > %s
          AND due_date <= %s + INTERVAL '14 days'
        ORDER BY
            due_date ASC,
            category,
            title
        LIMIT 5
    """, (spa_id, today, today))

    business_schedule_upcoming = cur.fetchall()

    # ---------------------------------------------------------
    # Priority action review
    # ---------------------------------------------------------
    priority_actions = []

    if dashboard.get("birthdays_today", 0) > 0:
        priority_actions.append({
            "icon": "🎂",
            "label": "Birthday today",
            "value": dashboard.get("birthdays_today", 0),
            "url": None,
            "category": "Client Care",
            "priority": 80
        })

    if dashboard.get("appointments_tomorrow", 0) > 0:
        priority_actions.append({
            "icon": "📅",
            "label": "Appointments tomorrow",
            "value": dashboard.get("appointments_tomorrow", 0),
            "url": url_for(
                "appointments",
                start_date=tomorrow.isoformat(),
                end_date=tomorrow.isoformat(),
                from_coach=1,
                coach_action="tomorrow"
            ),
            "category": "Appointments",
            "priority": 60
        })

    # ---------------------------------------------------------
    # GoDaddy imports awaiting review
    # ---------------------------------------------------------
    cur.execute("""
        SELECT COUNT(*)
        FROM appointments
        WHERE spa_id = %s
          AND external_source = 'godaddy'
          AND COALESCE(import_reviewed, FALSE) = FALSE
    """, (spa_id,))

    godaddy_unreviewed_count = cur.fetchone()[0] or 0

    if godaddy_unreviewed_count > 0:
        priority_actions.append({
            "icon": "📨",
            "label": "GoDaddy imports need review",
            "value": godaddy_unreviewed_count,
            "url": url_for("godaddy_imports"),
            "category": "Appointments",
            "priority": 90
        })


    # ---------------------------------------------------------
    # Overdue appointments awaiting closeout
    # ---------------------------------------------------------
    cur.execute("""
        SELECT
            a.appointment_id,
            a.appointment_date,
            a.appointment_time,
            a.status,
            c.first_name,
            c.last_name
        FROM appointments a
        LEFT JOIN clients c
            ON c.client_id = a.client_id
        WHERE a.spa_id = %s
        AND a.appointment_date < %s
        AND LOWER(COALESCE(a.status, '')) = 'booked'
        ORDER BY
            a.appointment_date ASC,
            a.appointment_time ASC
    """, (spa_id, today))

    overdue_appointments = cur.fetchall()

    dashboard["overdue_appointments"] = overdue_appointments


    # ---------------------------------------------------------
    # Recurring expenses requiring attention
    # ---------------------------------------------------------
    recurring_expense_window_end = (
        today + timedelta(days=7)
    )

    cur.execute("""
        SELECT
            automatic_expense_id,     -- 0
            expense_name,             -- 1
            vendor_name,              -- 2
            amount,                   -- 3
            frequency,                -- 4
            processing_type,          -- 5
            next_post_date,           -- 6
            last_error_message,       -- 7
            last_error_at             -- 8
        FROM automatic_expenses
        WHERE spa_id = %s
        AND is_active = TRUE
        AND (
                last_error_message IS NOT NULL
                OR next_post_date <= %s
            )
        ORDER BY
            CASE
                WHEN last_error_message IS NOT NULL THEN 1
                WHEN next_post_date < %s THEN 2
                WHEN next_post_date = %s THEN 3
                ELSE 4
            END,
            next_post_date ASC,
            expense_name ASC
    """, (
        spa_id,
        recurring_expense_window_end,
        today,
        today,
    ))

    recurring_expense_rows = cur.fetchall()

    recurring_expenses = [
        {
            "automatic_expense_id": row[0],
            "expense_name": row[1],
            "vendor_name": row[2],
            "amount": row[3],
            "frequency": row[4],
            "processing_type": row[5],
            "next_post_date": row[6],
            "last_error_message": row[7],
            "last_error_at": row[8],
        }
        for row in recurring_expense_rows
    ]

    recurring_expenses_failed = [
        expense
        for expense in recurring_expenses
        if expense["last_error_message"]
    ]

    recurring_expenses_past_due = [
        expense
        for expense in recurring_expenses
        if not expense["last_error_message"]
        and expense["next_post_date"]
        and expense["next_post_date"] < today
    ]

    recurring_expenses_due_today = [
        expense
        for expense in recurring_expenses
        if not expense["last_error_message"]
        and expense["next_post_date"] == today
    ]

    recurring_expenses_upcoming = [
        expense
        for expense in recurring_expenses
        if not expense["last_error_message"]
        and expense["next_post_date"]
        and today < expense["next_post_date"]
        <= recurring_expense_window_end
    ]

    dashboard["recurring_expenses_failed"] = (
        recurring_expenses_failed
    )

    dashboard["recurring_expenses_past_due"] = (
        recurring_expenses_past_due
    )

    dashboard["recurring_expenses_due_today"] = (
        recurring_expenses_due_today
    )

    dashboard["recurring_expenses_upcoming"] = (
        recurring_expenses_upcoming
    )

    # Add one action card using the most urgent status.
    if recurring_expenses_failed:
        priority_actions.append({
            "icon": "💳",
            "label": "Recurring expense processing failed",
            "value": len(recurring_expenses_failed),
            "url": url_for("automatic_expenses"),
            "category": "Recurring Expenses",
            "priority": 110
        })

    elif recurring_expenses_past_due:
        priority_actions.append({
            "icon": "💳",
            "label": "Recurring expenses past due",
            "value": len(recurring_expenses_past_due),
            "url": url_for("automatic_expenses"),
            "category": "Recurring Expenses",
            "priority": 105
        })

    elif recurring_expenses_due_today:
        priority_actions.append({
            "icon": "💳",
            "label": "Recurring expenses due today",
            "value": len(recurring_expenses_due_today),
            "url": url_for("automatic_expenses"),
            "category": "Recurring Expenses",
            "priority": 95
        })


    # ---------------------------------------------------------
    # Successful automatic payments awaiting Coach review
    # ---------------------------------------------------------
    cur.execute("""
        SELECT
            aeo.occurrence_id,              -- 0
            aeo.automatic_expense_id,       -- 1
            aeo.scheduled_date,             -- 2
            aeo.expense_id,                 -- 3
            aeo.coach_alert_message,        -- 4
            aeo.processed_at,               -- 5
            ae.expense_name,                -- 6
            ae.amount,                      -- 7
            ae.next_post_date               -- 8
        FROM automatic_expense_occurrences aeo

        JOIN automatic_expenses ae
          ON aeo.automatic_expense_id =
             ae.automatic_expense_id
         AND aeo.spa_id = ae.spa_id

        WHERE aeo.spa_id = %s
          AND aeo.occurrence_status = 'posted'
          AND aeo.coach_alert_required = TRUE
          AND aeo.coach_alert_acknowledged_at IS NULL
          AND aeo.coach_alert_message IS NOT NULL

        ORDER BY
            aeo.processed_at DESC,
            aeo.occurrence_id DESC

        LIMIT 5
    """, (spa_id,))

    recurring_expense_alert_rows = cur.fetchall()

    recurring_expense_alerts = [
        {
            "occurrence_id": row[0],
            "automatic_expense_id": row[1],
            "scheduled_date": row[2],
            "expense_id": row[3],
            "message": row[4],
            "processed_at": row[5],
            "expense_name": row[6],
            "amount": row[7],
            "next_post_date": row[8],
        }
        for row in recurring_expense_alert_rows
    ]

    dashboard["recurring_expense_alerts"] = (
        recurring_expense_alerts
    )

    # ---------------------------------------------------------
    # Calculate Business Health
    # ---------------------------------------------------------
    business_health = calculate_business_health(
        dashboard=dashboard,
        business_schedule_due=business_schedule_due,
        godaddy_unreviewed_count=(
            godaddy_unreviewed_count
        )
    )



    print(
        "[BUSINESS HEALTH DEBUG]",
        business_health,
        flush=True
    )

    print(
        "[TODAY BUSINESS DEBUG]",
        {
            key: value
            for key, value in dashboard.items()
            if any(
                word in key.lower()
                for word in (
                    "today",
                    "appointment",
                    "revenue"
                )
            )
        },
        flush=True
    )


    # ---------------------------------------------------------
    # Coach performs the review only after all data is collected
    # ---------------------------------------------------------

    coach_session = coach_session or {}

    coach_session["acknowledged_categories"] = (
        get_coach_acknowledgments(
            spa_id=spa_id,
            spa_now=spa_now
        )
    )


    coach_session["recommendation_mentions"] = (
        get_coach_recommendation_mentions(
            spa_id=spa_id,
            spa_now=spa_now
        )
    )

    coach = build_coach(
        dashboard,
        business_schedule_due=business_schedule_due,
        business_schedule_upcoming=business_schedule_upcoming,
        priority_actions=priority_actions,
        spa_now=spa_now,
        coach_session=coach_session
    )


    record_coach_interaction(
        cur=cur,
        coach_session_id=coach_session["coach_session_id"],
        spa_id=spa_id,
        user_id=user_id,
        coach=coach,
        message_type="briefing_open"
    )


    action_cards = build_action_cards(
        dashboard=dashboard,
        priority_actions=priority_actions
    )

    conn.commit()


    show_coach_welcome = (
        user_needs_coach_welcome(
            session.get("user_id")
        )
        and not session.get(
            "coach_welcome_dismissed",
            False
        )
    )


    cur.close()
    conn.close()

    show_login_splash = bool(
        session.pop("show_login_splash", False)
    )

    return render_template(
        "morning_briefing.html",
        dashboard=dashboard,
        business_health=business_health,
        today=today,
        business_schedule_due=business_schedule_due,
        business_schedule_upcoming=business_schedule_upcoming,
        priority_actions=priority_actions,
        godaddy_unreviewed_count=godaddy_unreviewed_count,
        coach=coach,
        coach_session=coach_session,
        spa_now=spa_now,
        action_cards=action_cards,
        show_coach_welcome=show_coach_welcome,
        show_login_splash=show_login_splash
    )








####################################################
#
#
#################################################


def get_coach_acknowledgments(
    spa_id,
    spa_now
):
    """
    Return Coach recommendation categories acknowledged
    today for the current spa.
    """

    today_key = spa_now.date().isoformat()
    spa_key = str(spa_id)

    all_acknowledgments = session.get(
        "coach_acknowledgments",
        {}
    )

    spa_acknowledgments = all_acknowledgments.get(
        spa_key,
        {}
    )

    # Begin a fresh acknowledgment list each day.
    if spa_acknowledgments.get("date") != today_key:
        spa_acknowledgments = {
            "date": today_key,
            "categories": []
        }

        all_acknowledgments[spa_key] = (
            spa_acknowledgments
        )

        session["coach_acknowledgments"] = (
            all_acknowledgments
        )

        session.modified = True

    return spa_acknowledgments.get(
        "categories",
        []
    )








###############################################################




def save_coach_acknowledgment(
    spa_id,
    spa_now,
    category
):
    """
    Mark one Coach recommendation category as acknowledged
    for the remainder of the current business day.
    """

    today_key = spa_now.date().isoformat()
    spa_key = str(spa_id)

    all_acknowledgments = session.get(
        "coach_acknowledgments",
        {}
    )

    spa_acknowledgments = all_acknowledgments.get(
        spa_key,
        {}
    )

    if spa_acknowledgments.get("date") != today_key:
        spa_acknowledgments = {
            "date": today_key,
            "categories": []
        }

    categories = set(
        spa_acknowledgments.get(
            "categories",
            []
        )
    )

    categories.add(category)

    spa_acknowledgments["categories"] = list(
        categories
    )

    all_acknowledgments[spa_key] = (
        spa_acknowledgments
    )

    session["coach_acknowledgments"] = (
        all_acknowledgments
    )

    session.modified = True










#################################
#
#   HELPERS
#
####################



def get_coach_recommendation_mentions(
    spa_id,
    spa_now
):
    # Return today's mention counts for each Coach category.

    today_key = spa_now.date().isoformat()
    spa_key = str(spa_id)

    all_mentions = session.get(
        "coach_recommendation_mentions",
        {}
    )

    spa_mentions = all_mentions.get(
        spa_key,
        {}
    )

    if spa_mentions.get("date") != today_key:
        return {}

    categories = spa_mentions.get(
        "categories",
        {}
    )

    if not isinstance(categories, dict):
        return {}

    return categories




#######################################
#
###########################



def record_coach_recommendation_mention(
    spa_id,
    spa_now,
    category
):
    """
    Record that Coach presented a recommendation category.
    Mention counts reset on the next local business day.
    """

    today_key = spa_now.date().isoformat()
    spa_key = str(spa_id)

    all_mentions = session.get(
        "coach_recommendation_mentions",
        {}
    )

    spa_mentions = all_mentions.get(
        spa_key,
        {}
    )

    if spa_mentions.get("date") != today_key:
        spa_mentions = {
            "date": today_key,
            "categories": {}
        }

    categories = spa_mentions.get(
        "categories",
        {}
    )

    if not isinstance(categories, dict):
        categories = {}

    current_count = int(
        categories.get(category) or 0
    )

    current_count += 1

    categories[category] = current_count
    spa_mentions["categories"] = categories
    all_mentions[spa_key] = spa_mentions

    session["coach_recommendation_mentions"] = (
        all_mentions
    )

    session.modified = True

    return current_count
















