@app.route(
    "/coach/acknowledge",
    methods=["POST"]
)
@login_required
@spa_required
def acknowledge_coach_recommendation():
    data = request.get_json(silent=True) or {}

    category = str(
        data.get("category") or ""
    ).strip()

    action = str(
        data.get("action") or "defer"
    ).strip().lower()

    occurrence_id = data.get("occurrence_id")

    if not category:
        return jsonify({
            "status": "error",
            "message": "Recommendation category is required."
        }), 400

    if len(category) > 100:
        return jsonify({
            "status": "error",
            "message": "Invalid recommendation category."
        }), 400

    allowed_actions = {
        "mention",
        "review",
        "defer",
        "pause_today",
        "keep_reminding",
        "acknowledge_alert"
    }

    if action not in allowed_actions:
        return jsonify({
            "status": "error",
            "message": "Invalid Coach action."
        }), 400

    spa_id = current_spa_id()
    spa_now = get_spa_now()

    mention_count = None

    if action == "acknowledge_alert":
        try:
            occurrence_id = int(occurrence_id)
        except (TypeError, ValueError):
            return jsonify({
                "status": "error",
                "message": "A valid occurrence ID is required."
            }), 400

        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                UPDATE automatic_expense_occurrences
                SET
                    coach_alert_acknowledged_at =
                        CURRENT_TIMESTAMP
                WHERE occurrence_id = %s
                AND spa_id = %s
                AND coach_alert_required = TRUE
                AND coach_alert_acknowledged_at IS NULL
            """, (
                occurrence_id,
                spa_id,
            ))

            if cur.rowcount == 0:
                conn.rollback()

                return jsonify({
                    "status": "error",
                    "message": (
                        "The recurring expense alert "
                        "was not found or was already acknowledged."
                    )
                }), 404

            conn.commit()

        except Exception:
            conn.rollback()

            app.logger.exception(
                "Failed to acknowledge recurring expense alert."
            )

            return jsonify({
                "status": "error",
                "message": (
                    "The recurring expense alert "
                    "could not be acknowledged."
                )
            }), 500

        finally:
            cur.close()
            conn.close()

    elif action == "mention":
        mention_count = (
            record_coach_recommendation_mention(
                spa_id=spa_id,
                spa_now=spa_now,
                category=category
            )
        )

    # review, defer, and keep_reminding do not hide
    # the recommendation for the remainder of the day.

    return jsonify({
        "status": "success",
        "category": category,
        "action": action,
        "mention_count": mention_count
    })











