@app.route("/daily-briefing/today")
@login_required
@spa_required
@require_workspace_permission("can_view_daily_briefing")
def daily_briefing_today():

    spa_id = current_spa_id()
    spa_now = get_spa_now(spa_id)
    today = spa_now.date()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            a.appointment_id,
            a.appointment_date,
            a.appointment_time,
            a.service_type,
            a.duration_minutes,
            a.price_at_booking,
            a.status,
            c.client_id,
            c.first_name,
            c.last_name,
            c.phone,
            c.email
        FROM appointments a
        LEFT JOIN clients c
            ON a.client_id = c.client_id
        WHERE a.spa_id = %s
          AND a.appointment_date = %s
          AND COALESCE(a.status, '') NOT IN ('Cancelled', 'Canceled')
        ORDER BY a.appointment_time ASC
    """, (spa_id, today))

    appointments = cur.fetchall()

    projected_revenue = sum(
        appt[5] or 0 for appt in appointments
    )

    appointment_count = len(appointments)

    cur.close()
    conn.close()

    return render_template(
        "daily_briefing_today.html",
        today=today,
        appointments=appointments,
        appointment_count=appointment_count,
        projected_revenue=projected_revenue,
        action_url=url_for("priority_actions")
    )









