@app.route("/business-schedule", methods=["GET", "POST"])
@login_required
@spa_required
def business_schedule():
    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    show_archived = request.args.get("show_archived") == "1"

    if request.method == "POST":
        category = request.form.get("category")
        title = request.form.get("title")
        description = request.form.get("description")
        due_date = request.form.get("due_date") or None
        recurrence_type = request.form.get("recurrence_type")
        recurrence_interval = request.form.get("recurrence_interval") or 1
        reminder_days = request.form.get("reminder_days") or 14
        is_required = bool(request.form.get("is_required"))

        cur.execute("""
            INSERT INTO business_schedule (
                spa_id,
                category,
                title,
                description,
                due_date,
                recurrence_type,
                recurrence_interval,
                reminder_days,
                is_required
            )
            VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s)
        """, (
            spa_id,
            category,
            title,
            description,
            due_date,
            recurrence_type,
            recurrence_interval,
            reminder_days,
            is_required
        ))

        conn.commit()
        flash("Business Schedule item added.", "success")
        return redirect(url_for("business_schedule"))



    if show_archived:
        cur.execute("""
            SELECT
                schedule_id,
                category,
                title,
                description,
                due_date,
                recurrence_type,
                recurrence_interval,
                reminder_days,
                is_required,
                is_completed,
                is_active
            FROM business_schedule
            WHERE spa_id = %s
            ORDER BY
                is_active DESC,
                due_date ASC NULLS LAST,
                category,
                title
        """, (spa_id,))
    else:
        cur.execute("""
            SELECT
                schedule_id,
                category,
                title,
                description,
                due_date,
                recurrence_type,
                recurrence_interval,
                reminder_days,
                is_required,
                is_completed,
                is_active
            FROM business_schedule
            WHERE spa_id = %s
              AND is_active = TRUE
            ORDER BY
                due_date ASC NULLS LAST,
                category,
                title
        """, (spa_id,))

    schedule_items = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "business_schedule.html",
        schedule_items=schedule_items,
        show_archived=show_archived
    )





