    spa_id = current_spa_id()

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT
            schedule_id,
            category,
            title,
            description,
            due_date,
            recurrence_type,
            is_required
        FROM business_schedule
        WHERE schedule_id = %s
          AND spa_id = %s
          AND is_active = TRUE
    """, (schedule_id, spa_id))

