    cur.execute("""
        INSERT INTO business_schedule (
            spa_id,
            category,
            title,
            description,
            due_date,
            recurrence_type,
            recurrence_interval,
            reminder_days,
            is_required,
            is_completed,
            is_active
        )
        SELECT
            spa_id,
            category,
            title || ' Copy',
            description,
            due_date,
            recurrence_type,
            recurrence_interval,
            reminder_days,
            is_required,
            FALSE,
            TRUE
        FROM business_schedule
        WHERE schedule_id = %s
          AND spa_id = %s
    """, (schedule_id, spa_id))

    conn.commit()
    cur.close()
    conn.close()

    flash("Business Schedule item duplicated.", "success")
    return redirect(url_for("business_schedule"))






