from datetime import date



@app.route("/appointments")
@login_required
@spa_required
def appointments():
    spa_id = current_spa_id()
    role = session.get("role")

    start_date = request.args.get("start_date", "").strip()
    end_date = request.args.get("end_date", "").strip()
    show_all = request.args.get("show_all", "").strip()

    from_coach = request.args.get("from_coach", "").strip() == "1"

    appointment_id_filter = request.args.get(
        "appointment_id",
        type=int
    )

    coach_action = request.args.get(
        "coach_action",
        ""
    ).strip().lower()


    status_filter = request.args.get(
        "status",
        request.args.get("filter", "")
    ).strip().lower()

    # Use the same business-local time helper used by Daily Briefing.
    spa_now = get_spa_now(spa_id)
    today = spa_now.date()
    today_str = today.isoformat()

    conn = get_db_connection()
    cur = conn.cursor()

    query = """
        SELECT
            a.appointment_id,
            a.client_id,
            c.first_name,
            c.last_name,
            COALESCE(s.service_name, a.external_service_name) AS service_name,
            a.appointment_date,
            a.appointment_time,
            a.status,
            a.notes
        FROM appointments a
        JOIN clients c
            ON a.client_id = c.client_id
           AND a.spa_id = c.spa_id
        LEFT JOIN service_name_types s
            ON a.service_type_id = s.service_type_id
           AND a.spa_id = s.spa_id
        WHERE 1=1
    """

    params = []

    if role != "master_admin":
        query += " AND a.spa_id = %s"
        params.append(spa_id)

    # ---------------------------------------------------------
    # Coach-selected appointment
    # ---------------------------------------------------------
    # A specific appointment overrides the normal status and
    # date filters so Coach can open past, current, or future
    # appointments directly.
    if appointment_id_filter:
        query += """
            AND a.appointment_id = %s
        """
        params.append(appointment_id_filter)


    else:
        # Overdue is a calculated status and always searches
        # past dates.
        if status_filter == "overdue":
            query += """
                AND a.appointment_date < %s
                AND LOWER(COALESCE(a.status, '')) = 'booked'
            """
            params.append(today)

        else:
            # Standard status filter.
            if status_filter:
                query += """
                    AND LOWER(COALESCE(a.status, '')) = %s
                """
                params.append(status_filter)

            # Apply an entered date range.
            if start_date and end_date:
                query += """
                    AND a.appointment_date BETWEEN %s AND %s
                """
                params.extend([
                    start_date,
                    end_date
                ])

            # With no status, no dates, and no Show All request,
            # default the page to today's appointments.
            elif not status_filter and show_all != "1":
                query += """
                    AND a.appointment_date = %s
                """
                params.append(today)



    query += " ORDER BY a.appointment_date, a.appointment_time"

    cur.execute(query, tuple(params))
    appointments = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "appointments.html",
        appointments=appointments,
        start_date=start_date,
        end_date=end_date,
        today_str=today_str,
        status_filter=status_filter,
        status_count=len(appointments),
        from_coach=from_coach,
        appointment_id_filter=appointment_id_filter,
        coach_action=coach_action
    )









