@app.route("/add_appointment", methods=["GET", "POST"])
@login_required
@spa_required
def add_appointment():
    user_id = session.get("user_id")
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to add an appointment.",
            "error"
        )

        return redirect(
            url_for("calendar_view")
        )

    client_id = request.args.get("client_id") or request.form.get("client_id") or ""
    selected_date = request.args.get("selected_date") or request.form.get("selected_date") or ""
    service_type = request.form.get("service_type", "").strip()

    conn = get_db_connection()
    cur = conn.cursor()

    clients = []
    providers = []
    service_types = []

    if request.method == "POST":
        client_id = (request.form.get("client_id") or "").strip()
        service_type_id = (request.form.get("service_type_id") or "").strip()

        duration_minutes_raw = (
            request.form.get("duration_minutes") or ""
        ).strip()

        price_at_booking_raw = (
            request.form.get("price_at_booking") or ""
        ).strip()

        appointment_date = (
            request.form.get("appointment_date") or ""
        ).strip()

        appointment_time = (
            request.form.get("appointment_time") or ""
        ).strip()

        status = (request.form.get("status") or "booked").strip()
        notes = (request.form.get("notes") or "").strip()
        incoming_booking_id = (
            request.form.get("incoming_booking_id") or ""
        ).strip()

        provider_employee_id_raw = (
        request.form.get("provider_employee_id") or ""
        ).strip()

        provider_employee_id = None
        provider_name_at_booking = "Any Available"


        print(f"Current spa_id = {spa_id}")
        print(f"Submitted provider ID = {provider_employee_id_raw!r}")


        if provider_employee_id_raw:
            try:
                provider_employee_id = int(provider_employee_id_raw)
            except (TypeError, ValueError):
                flash("Please select a valid provider.", "error")
                cur.close()
                conn.close()

                return redirect(url_for(
                    "add_appointment",
                    selected_date=selected_date
                ))

            cur.execute("""
                SELECT
                    employee_id,
                    employee_nickname,
                    first_name,
                    last_name
                FROM employees
                WHERE employee_id = %s
                AND spa_id = %s
                AND is_active = TRUE
            """, (provider_employee_id, spa_id))

            provider = cur.fetchone()

            print("Selected provider:", provider)


            if not provider:
                flash("The selected provider was not found or is inactive.", "error")
                cur.close()
                conn.close()

                return redirect(url_for(
                    "add_appointment",
                    selected_date=selected_date
                ))

            provider_name_at_booking = (
                provider[1]
                or f"{provider[2] or ''} {provider[3] or ''}".strip()
                or "Provider"
            )

        print(f"Current spa_id = {spa_id}")

        if not client_id:
            flash("Client is required.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("add_appointment", selected_date=selected_date))

        if not service_type_id:
            flash("Service is required.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("add_appointment", selected_date=selected_date))

        if not appointment_date or not appointment_time:
            flash("Appointment date and time are required.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("add_appointment", selected_date=selected_date))

        try:
            duration_minutes = int(duration_minutes_raw)
        except (TypeError, ValueError):
            flash("Session length must be entered in minutes.", "error")
            cur.close()
            conn.close()

            return redirect(url_for(
                "add_appointment",
                selected_date=selected_date
            ))

        if duration_minutes <= 0:
            flash("Session length must be greater than zero.", "error")
            cur.close()
            conn.close()

            return redirect(url_for(
                "add_appointment",
                selected_date=selected_date
            ))

        try:
            price_at_booking = float(price_at_booking_raw)
        except (TypeError, ValueError):
            flash("Service price must be a valid amount.", "error")
            cur.close()
            conn.close()

            return redirect(url_for(
                "add_appointment",
                selected_date=selected_date
            ))

        if price_at_booking < 0:
            flash("Service price cannot be negative.", "error")
            cur.close()
            conn.close()

            return redirect(url_for(
                "add_appointment",
                selected_date=selected_date
            ))


        cur.execute("""
            SELECT 1
            FROM clients
            WHERE client_id = %s
              AND spa_id = %s
        """, (client_id, spa_id))

        if not cur.fetchone():
            flash("Invalid client selected.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("add_appointment", selected_date=selected_date))

        cur.execute("""
            SELECT 1
            FROM service_name_types
            WHERE service_type_id = %s
              AND spa_id = %s
        """, (service_type_id, spa_id))

        if not cur.fetchone():
            flash("Invalid service selected.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("add_appointment", selected_date=selected_date))


        availability = (
            _appointment_reschedule_is_available(
                cur=cur,
                spa_id=spa_id,
                business_unit_id=business_unit_id,
                appointment_date=appointment_date,
                appointment_time=appointment_time,
                duration_minutes=duration_minutes,
                provider_employee_id=
                    provider_employee_id,
                service_type_id=service_type_id
            )
        )

        if not availability.get("valid"):
            conn.rollback()
            cur.close()
            conn.close()

            flash(
                availability.get("message")
                or (
                    "That appointment time is "
                    "no longer available."
                ),
                "error"
            )

            return redirect(url_for(
                "add_appointment",
                selected_date=appointment_date
            ))


        cur.execute("""
            INSERT INTO appointments (
                spa_id,
                business_unit_id,
                client_id,
                service_type_id,
                service_type,
                duration_minutes,
                price_at_booking,
                appointment_date,
                appointment_time,
                status,
                notes,
                provider_employee_id,
                provider_name_at_booking,
                owner_reviewed,
                owner_reviewed_at
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                %s, %s, %s,
                TRUE,
                CURRENT_TIMESTAMP
            )
            RETURNING appointment_id
        """, (
            spa_id,
            business_unit_id,
            client_id,
            service_type_id,
            service_type,
            duration_minutes,
            price_at_booking,
            appointment_date,
            appointment_time,
            status,
            notes,
            provider_employee_id,
            provider_name_at_booking
        ))

        appointment_id = cur.fetchone()[0]

        log_audit(
            cur,
            spa_id=spa_id,
            user_id=user_id,
            action_type="appointment_created",
            table_name="appointments",
            record_id=appointment_id,
            new_value=f"{appointment_date} {appointment_time}",
            notes="Appointment created"
        )

        log_appointment_history(
            cur,
            spa_id=spa_id,
            appointment_id=appointment_id,
            client_id=client_id,
            user_id=user_id,
            action_type="created",
            new_date=appointment_date,
            new_time=appointment_time,
            new_status=status,
            notes="Appointment created"
        )


        if incoming_booking_id:
            cur.execute("""
                UPDATE incoming_square_bookings
                SET status = 'imported',
                    reviewed_at = CURRENT_TIMESTAMP
                WHERE incoming_booking_id = %s
                  AND spa_id = %s
            """, (incoming_booking_id, spa_id))

            session.pop("incoming_booking_data", None)

        conn.commit()
        cur.close()
        conn.close()

        return redirect(url_for("daily_schedule", date=appointment_date))

    incoming_booking_id = request.args.get("incoming_booking_id", "")
    prefill_date = request.args.get("appointment_date", "") or selected_date
    prefill_time = request.args.get("appointment_time", "")
    prefill_service_name = request.args.get("service_name", "")






    client_search = request.args.get("client_search", "").strip()

    if client_search:
        cur.execute("""
            SELECT client_id, first_name, last_name
            FROM clients
            WHERE spa_id = %s
            AND active_client = TRUE
            AND last_name ILIKE %s
            ORDER BY last_name, first_name
        """, (spa_id, f"%{client_search}%"))

        clients = cur.fetchall()

        if len(clients) == 1:
            client_id = clients[0][0]

        elif len(clients) == 0:
            cur.close()
            conn.close()

            flash("No client found. Please add the client first.", "warning")

            return redirect(url_for(
                "add_new_client",
                selected_date=selected_date
            ))

    else:
        cur.execute("""
            SELECT client_id, first_name, last_name
            FROM clients
            WHERE spa_id = %s
            AND active_client = TRUE
            ORDER BY last_name, first_name
            LIMIT 25
        """, (spa_id,))

        clients = cur.fetchall()

    # Always load providers
    cur.execute("""
        SELECT
            employee_id,
            first_name,
            last_name,
            employee_nickname
        FROM employees
        WHERE spa_id = %s
        AND is_active = TRUE
        ORDER BY
            COALESCE(NULLIF(employee_nickname, ''), first_name),
            last_name
    """, (spa_id,))

    providers = cur.fetchall()

    print("Provider dropdown rows:", providers)

    # Always load service types
    cur.execute("""
        SELECT
            service_type_id,
            service_name,
            default_duration_minutes,
            default_price
        FROM service_name_types
        WHERE spa_id = %s
        AND is_active = TRUE
        ORDER BY service_name
    """, (spa_id,))

    service_types = cur.fetchall()



    return render_template(
        "add_appointment.html",
        clients=clients,
        service_types=service_types,
        selected_date=selected_date,
        client_id=client_id,
        incoming_booking_id=incoming_booking_id,
        prefill_date=prefill_date,
        prefill_time=prefill_time,
        prefill_service_name=prefill_service_name,
        providers=providers
    )










