@app.route("/edit_appointment/<int:appointment_id>", methods=["GET", "POST"])
@login_required
@spa_required
def edit_appointment(appointment_id):
    spa_id = current_spa_id()
    user_id = session.get("user_id")
    role = session.get("role")

    conn = get_db_connection()
    cur = conn.cursor()

    filter_sql = "WHERE appointment_id = %s"
    params = [appointment_id]

    if role != "master_admin":
        filter_sql += " AND spa_id = %s"
        params.append(spa_id)


    if request.method == "POST":
        service_type = request.form["service_type"].strip()
        price_at_booking = request.form["price_at_booking"].strip()
        appointment_date = request.form["appointment_date"]
        appointment_time = request.form["appointment_time"]
        duration = request.form["duration"]
        room_number = request.form["room_number"]
        notes = request.form["notes"].strip()

        duration_value = int(duration) if duration else None
        price_value = float(price_at_booking) if price_at_booking else None

        # Get the appointment before changing it
        cur.execute(f"""
            SELECT
                client_id,
                appointment_date,
                appointment_time,
                status,
                service_type,
                price_at_booking,
                duration_minutes,
                spa_id,
                business_unit_id,
                provider_employee_id,
                service_type_id
            FROM appointments
            {filter_sql}
        """, params)

        old_appt = cur.fetchone()

        if not old_appt:
            cur.close()
            conn.close()
            flash("Appointment not found.", "warning")
            return redirect(url_for("calendar_view"))

        client_id = old_appt[0]
        old_date = old_appt[1]
        old_time = old_appt[2]
        old_status = old_appt[3]
        old_service_type = old_appt[4]
        old_price = old_appt[5]
        old_duration = old_appt[6]

        appointment_spa_id = old_appt[7]
        appointment_business_unit_id = old_appt[8]
        provider_employee_id = old_appt[9]
        service_type_id = old_appt[10]

        schedule_changed = (
            str(old_date) != appointment_date
            or old_time.strftime("%H:%M")
                != appointment_time
            or int(old_duration or 0)
                != int(duration_value or 0)
        )

        if schedule_changed:
            availability = (
                _appointment_reschedule_is_available(
                    cur=cur,
                    spa_id=appointment_spa_id,
                    business_unit_id=
                        appointment_business_unit_id,
                    appointment_date=appointment_date,
                    appointment_time=appointment_time,
                    duration_minutes=(
                        duration_value
                        or old_duration
                        or 60
                    ),
                    provider_employee_id=
                        provider_employee_id,
                    service_type_id=service_type_id,
                    exclude_appointment_id=
                        appointment_id
                )
            )

            if not availability.get("valid"):
                conn.rollback()
                cur.close()
                conn.close()

                flash(
                    availability.get("message")
                    or (
                        "That appointment time is "
                        "no longer available."
                    ),
                    "error"
                )

                return redirect(url_for(
                    "edit_appointment",
                    appointment_id=appointment_id
                ))


        cur.execute(f"""
            UPDATE appointments
            SET
                service_type = %s,
                price_at_booking = %s,
                appointment_date = %s,
                appointment_time = %s,
                duration_minutes = %s,
                room_number = %s,
                notes = %s,
                updated_at = CURRENT_TIMESTAMP
            {filter_sql}
        """, (
            service_type,
            price_value,
            appointment_date,
            appointment_time,
            duration_value,
            room_number,
            notes,
            *params
        ))

        log_audit(
            cur,
            spa_id=spa_id,
            user_id=user_id,
            action_type="appointment_updated",
            table_name="appointments",
            record_id=appointment_id,
            old_value=(
                f"{old_date} {old_time} | "
                f"{old_service_type or 'No service'} | "
                f"${old_price or 0} | "
                f"{old_duration or 0} minutes"
            ),
            new_value=(
                f"{appointment_date} {appointment_time} | "
                f"{service_type or 'No service'} | "
                f"${price_value or 0} | "
                f"{duration_value or 0} minutes"
            ),
            notes="Appointment updated"
        )

        was_rescheduled = (
            str(old_date) != appointment_date
            or old_time.strftime("%H:%M") != appointment_time
        )

        log_appointment_history(
            cur,
            spa_id=spa_id,
            appointment_id=appointment_id,
            client_id=client_id,
            user_id=user_id,
            action_type="rescheduled" if was_rescheduled else "updated",
            old_date=old_date,
            old_time=old_time,
            new_date=appointment_date,
            new_time=appointment_time,
            old_status=old_status,
            new_status=old_status,
            notes="Appointment edited"
        )

        conn.commit()
        cur.close()
        conn.close()

        flash("Appointment updated successfully.", "success")
        return redirect(url_for("daily_schedule", date=appointment_date))


    cur.execute(f"""
        SELECT
            appointment_id,
            appointment_date,
            appointment_time,
            duration_minutes,
            room_number,
            notes,
            service_type,
            price_at_booking
        FROM appointments
        {filter_sql}
    """, params)

    appt = cur.fetchone()

    cur.close()
    conn.close()

    if not appt:
        flash("Appointment not found or not authorized.", "error")
        return redirect(url_for("appointments"))

    return render_template("edit_appointment.html", appt=appt)







