@app.route("/cancel_appointment/<int:appointment_id>", methods=["POST"])
@login_required
@spa_required
def cancel_appointment(appointment_id):
    spa_id = current_spa_id()
    user_id = session.get("user_id")
    role = session.get("role")
    return_week_start = (
        request.form.get("return_week_start")
        or ""
    ).strip()

    try:
        return_week_start = (
            datetime.strptime(
                return_week_start,
                "%Y-%m-%d"
            )
            .date()
            .isoformat()
        )
    except (TypeError, ValueError):
        return_week_start = None

    def return_to_calendar():
        if return_week_start:
            return redirect(url_for(
                "calendar_view",
                week_start=return_week_start,
                _anchor="week-view"
            ))

        return redirect(url_for(
            "calendar_view",
            _anchor="week-view"
        ))

    conn = get_db_connection()
    cur = conn.cursor()

    filter_sql = """
        WHERE appointment_id = %s
          AND (appointment_date + appointment_time) > CURRENT_TIMESTAMP
    """
    params = [appointment_id]

    if role != "master_admin":
        filter_sql += " AND spa_id = %s"
        params.append(spa_id)

    cur.execute(f"""
        SELECT client_id, appointment_date, appointment_time, status
        FROM appointments
        {filter_sql}
    """, params)

    appt = cur.fetchone()

    if not appt:
        conn.rollback()
        cur.close()
        conn.close()
        flash("Appointment not found or can no longer be cancelled.", "error")
        return return_to_calendar()

    client_id = appt[0]
    old_date = appt[1]
    old_time = appt[2]
    old_status = appt[3]

    cur.execute(f"""
        UPDATE appointments
        SET status = 'cancelled',
            updated_at = CURRENT_TIMESTAMP
        {filter_sql}
    """, params)

    if cur.rowcount == 0:
        conn.rollback()
        cur.close()
        conn.close()
        flash("Appointment not found or can no longer be cancelled.", "error")
        return return_to_calendar()

    log_audit(
        cur,
        spa_id=spa_id,
        user_id=user_id,
        action_type="appointment_cancelled",
        table_name="appointments",
        record_id=appointment_id,
        old_value=old_status,
        new_value="cancelled",
        notes="Appointment cancelled"
    )

    log_appointment_history(
        cur,
        spa_id=spa_id,
        appointment_id=appointment_id,
        client_id=client_id,
        user_id=user_id,
        action_type="cancelled",
        old_date=old_date,
        old_time=old_time,
        new_date=old_date,
        new_time=old_time,
        old_status=old_status,
        new_status="cancelled",
        notes="Appointment cancelled"
    )

    conn.commit()
    cur.close()
    conn.close()

    flash("Appointment cancelled.", "warning")
    return return_to_calendar()





