@app.route("/reschedule_appointment/<int:appointment_id>", methods=["GET", "POST"])
@login_required
@spa_required
def reschedule_appointment(appointment_id):
    spa_id = current_spa_id()
    user_id = session.get("user_id")
    role = session.get("role")

    conn = get_db_connection()
    cur = conn.cursor()

    appt_filter = "WHERE appointment_id = %s"
    appt_params = [appointment_id]

    if role != "master_admin":
        appt_filter += " AND spa_id = %s"
        appt_params.append(spa_id)

    if request.method == "POST":
        service_type_id = (request.form.get("service_type_id") or "").strip()
        appointment_date = (request.form.get("appointment_date") or "").strip()
        appointment_time = (request.form.get("appointment_time") or "").strip()
        status = (request.form.get("status") or "").strip()
        notes = (request.form.get("notes") or "").strip()
        original_date = (request.form.get("original_date") or "").strip()

        if not service_type_id or not appointment_date or not appointment_time or not status:
            flash("Please complete all required fields.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("reschedule_appointment", appointment_id=appointment_id))

        if role == "master_admin":
            cur.execute("""
                SELECT spa_id
                FROM appointments
                WHERE appointment_id = %s
            """, (appointment_id,))
            appt_spa = cur.fetchone()

            if not appt_spa:
                flash("Appointment not found.", "error")
                cur.close()
                conn.close()
                return redirect(url_for("appointments"))

            service_spa_id = appt_spa[0]
        else:
            service_spa_id = spa_id


        cur.execute(f"""
            SELECT
                client_id,
                appointment_date,
                appointment_time,
                status,
                business_unit_id,
                duration_minutes,
                provider_employee_id,
                service_type_id
            FROM appointments
            {appt_filter}
        """, appt_params)

        old_appt = cur.fetchone()

        if not old_appt:
            cur.close()
            conn.close()
            flash("Appointment not found or not authorized.", "error")
            return redirect(url_for("appointments"))

        client_id = old_appt[0]
        old_date = old_appt[1]
        old_time = old_appt[2]
        old_status = old_appt[3]
        appointment_business_unit_id = old_appt[4]
        duration_minutes = old_appt[5]
        provider_employee_id = old_appt[6]
        old_service_type_id = old_appt[7]

        cur.execute("""
            SELECT 1
            FROM service_name_types
            WHERE service_type_id = %s
              AND spa_id = %s
        """, (service_type_id, service_spa_id))

        if not cur.fetchone():
            flash("Invalid service selected.", "error")
            cur.close()
            conn.close()
            return redirect(url_for("reschedule_appointment", appointment_id=appointment_id))


        inactive_statuses = {
            "cancelled",
            "canceled",
            "completed",
            "no show",
            "no-show",
            "re-scheduled",
            "rescheduled"
        }

        old_status_normalized = (
            str(old_status or "")
            .strip()
            .lower()
        )

        target_status_normalized = (
            str(status or "")
            .strip()
            .lower()
        )

        schedule_changed = (
            str(old_date) != appointment_date
            or str(old_time)[:5]
                != appointment_time[:5]
            or str(old_service_type_id or "")
                != str(service_type_id)
        )

        reactivating_appointment = (
            old_status_normalized
                in inactive_statuses
            and target_status_normalized
                not in inactive_statuses
        )

        if (
            target_status_normalized
                not in inactive_statuses
            and (
                schedule_changed
                or reactivating_appointment
            )
        ):
            availability = (
                _appointment_reschedule_is_available(
                    cur=cur,
                    spa_id=service_spa_id,
                    business_unit_id=
                        appointment_business_unit_id,
                    appointment_date=
                        appointment_date,
                    appointment_time=
                        appointment_time,
                    duration_minutes=
                        duration_minutes,
                    provider_employee_id=
                        provider_employee_id,
                    service_type_id=
                        service_type_id,
                    exclude_appointment_id=
                        appointment_id
                )
            )

            if not availability.get("valid"):
                conn.rollback()
                cur.close()
                conn.close()

                flash(
                    availability.get("message")
                    or (
                        "That appointment time is "
                        "no longer available."
                    ),
                    "error"
                )

                return redirect(url_for(
                    "reschedule_appointment",
                    appointment_id=
                        appointment_id
                ))


        cur.execute(f"""
            UPDATE appointments
            SET
                service_type_id = %s,
                appointment_date = %s,
                appointment_time = %s,
                status = %s,
                notes = %s,
                updated_at = CURRENT_TIMESTAMP
            {appt_filter}
        """, (
            service_type_id,
            appointment_date,
            appointment_time,
            status,
            notes,
            *appt_params
        ))

        if cur.rowcount == 0:
            conn.rollback()
            cur.close()
            conn.close()
            flash("Appointment not found or not authorized.", "error")
            return redirect(url_for("appointments"))


        action_type = "rescheduled"

        if str(old_date) == appointment_date and str(old_time)[:5] == appointment_time[:5]:
            action_type = "updated"
        else:
            action_type = "rescheduled"


        log_audit(
            cur,
            spa_id=service_spa_id,
            user_id=user_id,
            action_type=f"appointment_{action_type}",
            table_name="appointments",
            record_id=appointment_id,
            old_value=f"{old_date} {old_time} {old_status}",
            new_value=f"{appointment_date} {appointment_time} {status}",
            notes="Appointment rescheduled" if action_type == "rescheduled" else "Appointment updated"
        )

        log_appointment_history(
            cur,
            spa_id=service_spa_id,
            appointment_id=appointment_id,
            client_id=client_id,
            user_id=user_id,
            action_type=action_type,
            old_date=old_date,
            old_time=old_time,
            new_date=appointment_date,
            new_time=appointment_time,
            old_status=old_status,
            new_status=status,
            notes="Appointment rescheduled" if action_type == "rescheduled" else "Appointment updated"
        )


        conn.commit()
        cur.close()
        conn.close()

        flash("Appointment rescheduled successfully.", "success")
        return redirect(url_for("daily_schedule", date=appointment_date or original_date))


    select_filter = "WHERE a.appointment_id = %s"
    select_params = [appointment_id]

    if role != "master_admin":
        select_filter += " AND a.spa_id = %s"
        select_params.append(spa_id)



    cur.execute(f"""
        SELECT
            a.appointment_id,
            a.client_id,
            c.first_name,
            c.last_name,
            a.service_type_id,
            a.appointment_date,
            a.appointment_time,
            a.status,
            a.notes,
            a.spa_id
        FROM appointments a
        JOIN clients c
            ON a.client_id = c.client_id
           AND a.spa_id = c.spa_id
        {select_filter}
    """, select_params)

    appointment = cur.fetchone()

    if not appointment:
        cur.close()
        conn.close()
        flash("Appointment not found or not authorized.", "error")
        return redirect(url_for("appointments"))

    appointment_spa_id = appointment[9]

    cur.execute("""
        SELECT service_type_id, service_name
        FROM service_name_types
        WHERE spa_id = %s
        ORDER BY service_name
    """, (appointment_spa_id,))

    service_types = cur.fetchall()

    cur.close()
    conn.close()

    return render_template(
        "reschedule_appointment.html",
        appointment=appointment,
        service_types=service_types
    )










