@app.route("/add_new_client_step2", methods=["GET", "POST"])
@login_required
@spa_required
def add_new_client_step2():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to add a client.",
            "error"
        )

        return redirect(
            url_for("client_history")
        )

    selected_date = request.args.get("selected_date") or request.form.get("selected_date") or ""

    step1 = session.get("new_client_step1")
    if not step1:
        return redirect(url_for("add_new_client"))

    if request.method == "POST":
        session["new_client_step2"] = {
            "emergency_contact_name": request.form.get("emergency_contact_name", "").strip(),
            "emergency_contact_phone": request.form.get("emergency_contact_phone", "").strip(),
            "referrer_type": request.form.get("referrer_type", "").strip(),
            "referred_by": request.form.get("referred_by", "").strip(),
            "referrer_name": request.form.get("referrer_name", "").strip(),
            "referrer_business_name": request.form.get("referrer_business_name", "").strip(),
            "referrer_phone": request.form.get("referrer_phone", "").strip(),
            "referrer_email": request.form.get("referrer_email", "").strip(),
            "notes_one": request.form.get("notes_one", "").strip(),
            "notes_two": request.form.get("notes_two", "").strip(),
            "notes_three": request.form.get("notes_three", "").strip(),
            "active_client": request.form.get("active_client", "true")
        }

        submitted_action = request.form.get(
            "action",
            ""
        )

        action = (
            "save"
            if submitted_action == "save_override"
            else submitted_action
        )

        if action == "back":
            return redirect(url_for("add_new_client", selected_date=selected_date))

        if action == "save":
            step1 = session.get("new_client_step1", {})
            step2 = session.get("new_client_step2", {})
            incoming_booking_data = session.get("incoming_booking_data", {})

            conn = get_db_connection()
            cur = conn.cursor()

            duplicate_matches = (
                find_possible_client_duplicates(
                    cur=cur,
                    spa_id=spa_id,
                    business_unit_id=business_unit_id,
                    first_name=step1.get(
                        "first_name",
                        ""
                    ),
                    last_name=step1.get(
                        "last_name",
                        ""
                    ),
                    phone=step1.get(
                        "phone",
                        ""
                    ),
                    email=step1.get(
                        "email",
                        ""
                    )
                )
            )

            duplicate_override_confirmed = (
                bool(
                    session.get(
                        "new_client_duplicate_override"
                    )
                )
                or submitted_action
                    == "save_override"
            )

            if (
                duplicate_matches
                and not duplicate_override_confirmed
            ):
                cur.execute("""
                    SELECT
                        client_id,
                        first_name,
                        last_name
                    FROM clients
                    WHERE spa_id = %s
                      AND business_unit_id = %s
                      AND active_client = TRUE
                    ORDER BY
                        last_name,
                        first_name
                """, (
                    spa_id,
                    business_unit_id
                ))

                clients_for_referral = (
                    cur.fetchall()
                )

                cur.close()
                conn.close()

                return render_template(
                    "add_new_client_step2.html",
                    step2_data=step2,
                    selected_date=selected_date,
                    clients_for_referral=(
                        clients_for_referral
                    ),
                    duplicate_matches=(
                        duplicate_matches
                    )
                )

            if (
                submitted_action
                == "save_override"
            ):
                session[
                    "new_client_duplicate_override"
                ] = True

            try:
                referred_by_value = None

                if (
                    step2.get("referrer_type") == "Client"
                    and step2.get("referred_by")
                ):
                    requested_referrer_id = (
                        step2.get("referred_by")
                    )

                    cur.execute("""
                        SELECT client_id
                        FROM clients
                        WHERE client_id = %s
                          AND spa_id = %s
                          AND business_unit_id = %s
                          AND active_client = TRUE
                        LIMIT 1
                    """, (
                        requested_referrer_id,
                        spa_id,
                        business_unit_id
                    ))

                    valid_referrer = cur.fetchone()

                    if not valid_referrer:
                        conn.rollback()

                        flash(
                            "Selected referring client is not "
                            "available in this Provider Workspace.",
                            "error"
                        )

                        cur.execute("""
                            SELECT
                                client_id,
                                first_name,
                                last_name
                            FROM clients
                            WHERE spa_id = %s
                              AND business_unit_id = %s
                              AND active_client = TRUE
                            ORDER BY
                                last_name,
                                first_name
                        """, (
                            spa_id,
                            business_unit_id
                        ))

                        clients_for_referral = (
                            cur.fetchall()
                        )

                        cur.close()
                        conn.close()

                        return render_template(
                            "add_new_client_step2.html",
                            step2_data=step2,
                            selected_date=selected_date,
                            clients_for_referral=(
                                clients_for_referral
                            ),
                            duplicate_matches=[]
                        )

                    referred_by_value = valid_referrer[0]

                cur.execute("""
                    INSERT INTO clients (
                        spa_id,
                        business_unit_id,
                        first_name,
                        last_name,
                        phone,
                        email,
                        birth_date,
                        address,
                        city,
                        state,
                        zip,
                        spa_location_id,
                        preferred_location_id,
                        client_status,
                        preferred_language,
                        ok_to_call,
                        ok_to_text,
                        ok_to_email,
                        preferred_contact_method,
                        emergency_contact_name,
                        emergency_contact_phone,
                        referred_by,
                        notes_one,
                        notes_two,
                        notes_three,
                        active_client
                    )
                    VALUES (
                        %s, %s, %s, %s, %s,
                        %s, %s, %s, %s, %s,
                        %s, %s, %s, %s, %s,
                        %s, %s, %s, %s, %s,
                        %s, %s, %s, %s, %s,
                        %s
                    )
                    RETURNING client_id
                """, (
                    spa_id,
                    business_unit_id,
                    step1.get("first_name", ""),
                    step1.get("last_name", ""),
                    step1.get("phone", ""),
                    step1.get("email", ""),
                    step1.get("birth_date") or None,
                    step1.get("address", ""),
                    step1.get("city", ""),
                    step1.get("state", ""),
                    step1.get("zip", ""),
                    step1.get("spa_location_id") or None,
                    step1.get("preferred_location_id") or None,
                    step1.get("client_status", "Current"),
                    step1.get("preferred_language") or None,
                    step1.get("ok_to_call", True),
                    step1.get("ok_to_text", True),
                    step1.get("ok_to_email", True),
                    step1.get("preferred_contact_method") or None,
                    step2.get("emergency_contact_name", ""),
                    step2.get("emergency_contact_phone", ""),
                    referred_by_value,
                    step2.get("notes_one", ""),
                    step2.get("notes_two", ""),
                    step2.get("notes_three", ""),
                    True if step2.get("active_client") == "true" else False
                ))

                new_client_id = cur.fetchone()[0]

                referrer_type = step2.get("referrer_type", "").strip()
                referred_by = step2.get("referred_by", "").strip()
                referrer_name = step2.get("referrer_name", "").strip()
                referrer_business_name = step2.get("referrer_business_name", "").strip()
                referrer_phone = step2.get("referrer_phone", "").strip()
                referrer_email = step2.get("referrer_email", "").strip()

                if (
                    referrer_type == "Client"
                    and referred_by_value
                ):
                    cur.execute("""
                        INSERT INTO referrals (
                            spa_id,
                            business_unit_id,
                            referred_client_id,
                            referrer_type,
                            referrer_client_id,
                            referral_date
                        )
                        VALUES (
                            %s, %s, %s, %s, %s,
                            CURRENT_DATE
                        )
                    """, (
                        spa_id,
                        business_unit_id,
                        new_client_id,
                        "Client",
                        int(referred_by_value)
                    ))

                elif referrer_type == "Non-Client" and referrer_name:
                    cur.execute("""
                        INSERT INTO referrals (
                            spa_id,
                            business_unit_id,
                            referred_client_id,
                            referrer_type,
                            referrer_name,
                            referrer_business_name,
                            referrer_phone,
                            referrer_email,
                            referral_date
                        )
                        VALUES (
                            %s, %s, %s, %s, %s,
                            %s, %s, %s, CURRENT_DATE
                        )
                    """, (
                        spa_id,
                        business_unit_id,
                        new_client_id,
                        "Non-Client",
                        referrer_name,
                        referrer_business_name or None,
                        referrer_phone or None,
                        referrer_email or None
                    ))

                conn.commit()

            finally:
                cur.close()
                conn.close()

            flash("Client added successfully!", "success")

            session.pop("new_client_step1", None)
            session.pop("new_client_step2", None)
            session.pop(
                "new_client_duplicate_override",
                None
            )

            if incoming_booking_data:
                session.pop("incoming_booking_data", None)
                return redirect(url_for(
                    "add_appointment",
                    client_id=new_client_id,
                    incoming_booking_id=incoming_booking_data.get("incoming_booking_id", ""),
                    appointment_date=incoming_booking_data.get("appointment_date", ""),
                    appointment_time=incoming_booking_data.get("appointment_time", ""),
                    service_name=incoming_booking_data.get("service_name", "")
                ))

            session.pop("incoming_booking_data", None)

            if selected_date:
                return redirect(url_for(
                    "add_appointment",
                    client_id=new_client_id,
                    selected_date=selected_date
                ))

            return redirect(url_for("client_history"))

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT client_id, first_name, last_name
        FROM clients
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND active_client = TRUE
        ORDER BY last_name, first_name
    """, (
        spa_id,
        business_unit_id
    ))

    clients_for_referral = cur.fetchall()

    cur.close()
    conn.close()

    step2_data = session.get("new_client_step2", {})

    return render_template(
        "add_new_client_step2.html",
        step2_data=step2_data,
        selected_date=selected_date,
        clients_for_referral=clients_for_referral,
        duplicate_matches=[]
    )






