@app.route("/edit_client/<int:client_id>", methods=["GET", "POST"])
@login_required
@spa_required
def edit_client(client_id):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to edit a client.",
            "error"
        )
        return redirect(url_for("client_history"))

    conn = get_db_connection()
    cur = conn.cursor()

    client_filter = """
        WHERE c.client_id = %s
          AND c.spa_id = %s
          AND c.business_unit_id = %s
    """
    client_params = [
        client_id,
        spa_id,
        business_unit_id
    ]

    cur.execute(f"""
        SELECT
            c.client_id,
            c.first_name,
            c.last_name,
            c.phone,
            c.email,
            c.birth_date,
            c.address,
            c.city,
            c.state,
            c.zip,
            c.spa_location_id,
            c.preferred_location_id,
            c.client_status,
            c.preferred_language,
            c.ok_to_call,
            c.ok_to_text,
            c.ok_to_email,
            c.preferred_contact_method,
            c.emergency_contact_name,
            c.emergency_contact_phone,
            c.referred_by,
            c.notes_one,
            c.notes_two,
            c.notes_three,
            c.active_client,
            c.spa_id,
            c.business_unit_id
        FROM clients c
        {client_filter}
    """, tuple(client_params))

    client = cur.fetchone()

    if not client:
        cur.close()
        conn.close()
        flash("Client not found or not authorized.", "error")
        return redirect(url_for("client_history"))

    client_spa_id = client[25]
    client_business_unit_id = client[26]

    # Load active locations for dropdowns
    cur.execute("""
        SELECT spa_location_id, location_name
        FROM spa_locations
        WHERE spa_id = %s
          AND is_active = TRUE
        ORDER BY location_name
    """, (client_spa_id,))

    locations = cur.fetchall()

    duplicate_matches = []

    if request.method == "POST":
        first_name = request.form.get("first_name", "").strip()
        last_name = request.form.get("last_name", "").strip()
        phone = request.form.get("phone", "").strip()
        email = request.form.get("email", "").strip()
        birth_date = request.form.get("birth_date") or None
        address = request.form.get("address", "").strip()
        city = request.form.get("city", "").strip()
        state = request.form.get("state", "").strip()
        zip_code = request.form.get("zip", "").strip()

        spa_location_id = request.form.get("spa_location_id") or None
        preferred_location_id = request.form.get("preferred_location_id") or None
        client_status = request.form.get("client_status", "Current").strip()
        preferred_language = request.form.get("preferred_language", "").strip() or None
        ok_to_call = "ok_to_call" in request.form
        ok_to_text = "ok_to_text" in request.form
        ok_to_email = "ok_to_email" in request.form
        preferred_contact_method = request.form.get("preferred_contact_method", "").strip() or None

        emergency_contact_name = request.form.get("emergency_contact_name", "").strip()
        emergency_contact_phone = request.form.get("emergency_contact_phone", "").strip()
        referred_by = request.form.get("referred_by", "").strip()
        notes_one = request.form.get("notes_one", "").strip()
        notes_two = request.form.get("notes_two", "").strip()
        notes_three = request.form.get("notes_three", "").strip()

        active_client = True if request.form.get("active_client") == "true" else False

        # Preserve submitted values if the update is blocked.
        submitted_client = list(client)

        submitted_client[1] = first_name
        submitted_client[2] = last_name
        submitted_client[3] = phone
        submitted_client[4] = email
        submitted_client[5] = birth_date
        submitted_client[6] = address
        submitted_client[7] = city
        submitted_client[8] = state
        submitted_client[9] = zip_code
        submitted_client[10] = spa_location_id
        submitted_client[11] = preferred_location_id
        submitted_client[12] = client_status
        submitted_client[13] = preferred_language
        submitted_client[14] = ok_to_call
        submitted_client[15] = ok_to_text
        submitted_client[16] = ok_to_email
        submitted_client[17] = preferred_contact_method
        submitted_client[18] = emergency_contact_name
        submitted_client[19] = emergency_contact_phone
        submitted_client[20] = referred_by
        submitted_client[21] = notes_one
        submitted_client[22] = notes_two
        submitted_client[23] = notes_three
        submitted_client[24] = active_client

        client = tuple(submitted_client)

        missing_required_fields = []

        required_fields = [
            ("First Name", first_name),
            ("Last Name", last_name),
            ("Client Status", client_status)
        ]

        for field_label, field_value in required_fields:
            if not str(field_value or "").strip():
                missing_required_fields.append(
                    field_label
                )

        duplicate_override = (
            request.form.get(
                "duplicate_override"
            ) == "1"
        )

        if not missing_required_fields:
            duplicate_matches = (
                find_possible_client_duplicates(
                    cur=cur,
                    spa_id=client_spa_id,
                    business_unit_id=client_business_unit_id,
                    first_name=first_name,
                    last_name=last_name,
                    phone=phone,
                    email=email,
                    exclude_client_id=client_id
                )
            )

        save_blocked = bool(
            missing_required_fields
            or (
                duplicate_matches
                and not duplicate_override
            )
        )

        if missing_required_fields:
            flash(
                "Please complete the required information: "
                + ", ".join(missing_required_fields)
                + ".",
                "error"
            )

        elif (
            duplicate_matches
            and not duplicate_override
        ):
            flash(
                "Possible duplicate client found. "
                "Please review the matching records "
                "before saving.",
                "warning"
            )

        if not save_blocked:
            cur.execute("""
                UPDATE clients
                SET first_name = %s,
                    last_name = %s,
                    phone = %s,
                    email = %s,
                    birth_date = %s,
                    address = %s,
                    city = %s,
                    state = %s,
                    zip = %s,
                    spa_location_id = %s,
                    preferred_location_id = %s,
                    client_status = %s,
                    preferred_language = %s,
                    ok_to_call = %s,
                    ok_to_text = %s,
                    ok_to_email = %s,
                    preferred_contact_method = %s,
                    emergency_contact_name = %s,
                    emergency_contact_phone = %s,
                    referred_by = %s,
                    notes_one = %s,
                    notes_two = %s,
                    notes_three = %s,
                    active_client = %s,
                    updated_at = CURRENT_TIMESTAMP
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
            """, (
                first_name,
                last_name,
                phone,
                email,
                birth_date,
                address,
                city,
                state,
                zip_code,
                spa_location_id,
                preferred_location_id,
                client_status,
                preferred_language,
                ok_to_call,
                ok_to_text,
                ok_to_email,
                preferred_contact_method,
                emergency_contact_name,
                emergency_contact_phone,
                referred_by,
                notes_one,
                notes_two,
                notes_three,
                active_client,
                client_id,
                client_spa_id,
                client_business_unit_id
            ))

            if cur.rowcount != 1:
                conn.rollback()
                cur.close()
                conn.close()

                flash(
                    "Client could not be updated in this "
                    "Provider Workspace.",
                    "error"
                )

                return redirect(
                    url_for(
                        "edit_client",
                        client_id=client_id
                    )
                )

            conn.commit()
            cur.close()
            conn.close()

            flash("Client updated successfully!", "success")
            return redirect(url_for("client_history"))

    # --- CLIENT SUMMARY DATA ---

    cur.execute("""
        SELECT COUNT(*)
        FROM appointments
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
          AND LOWER(status) = 'completed'
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    total_visits = cur.fetchone()[0]

    cur.execute("""
        SELECT COALESCE(SUM(total_amount), 0)
        FROM income
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    total_revenue = cur.fetchone()[0]

    cur.execute("""
        SELECT appointment_date
        FROM appointments
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
          AND LOWER(status) = 'completed'
        ORDER BY appointment_date DESC
        LIMIT 1
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    last_visit = cur.fetchone()

    cur.execute("""
        SELECT appointment_date, appointment_time
        FROM appointments
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
          AND LOWER(status) = 'booked'
          AND appointment_date >= CURRENT_DATE
        ORDER BY appointment_date, appointment_time
        LIMIT 1
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    next_appt = cur.fetchone()

    cur.execute("""
        SELECT
            appointment_id,
            appointment_date,
            appointment_time,
            duration_minutes,
            room_number,
            status,
            booking_channel,
            price_at_booking,
            notes
        FROM appointments
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
        ORDER BY appointment_date DESC, appointment_time DESC
        LIMIT 10
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    recent_appointments = cur.fetchall()

    cur.execute("""
        SELECT COALESCE(SUM(price_at_booking), 0)
        FROM appointments
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
          AND LOWER(status) = 'completed'
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    lifetime_value = cur.fetchone()[0]

    cur.execute("""
        SELECT COALESCE(AVG(price_at_booking), 0)
        FROM appointments
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
          AND LOWER(status) = 'completed'
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    average_ticket = cur.fetchone()[0]

    cur.execute("""
        SELECT COALESCE(SUM(amount), 0.00)
        FROM client_credit_transactions
        WHERE client_id = %s
          AND spa_id = %s
          AND business_unit_id = %s
    """, (
        client_id,
        client_spa_id,
        client_business_unit_id
    ))
    credit_balance = cur.fetchone()[0]

    cur.close()
    conn.close()

    return render_template(
        "edit_client.html",
        client=client,
        client_id=client_id,
        locations=locations,
        total_visits=total_visits,
        total_revenue=total_revenue,
        last_visit=last_visit,
        next_appt=next_appt,
        recent_appointments=recent_appointments,
        lifetime_value=lifetime_value,
        average_ticket=average_ticket,
        credit_balance=credit_balance,
        duplicate_matches=duplicate_matches
    )



