@app.route(
    "/booking/business-hours",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_business_hours():
    from datetime import datetime

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    user_id = session.get("user_id")

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to manage business hours.",
            "error"
        )
        return redirect(url_for("admin"))

    day_names = [
        "Sunday",
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday"
    ]

    if request.method == "POST":
        periods_to_save = []
        validation_errors = []

        # Preserve everything entered so the form can be
        # restored after a validation or database error.
        submitted_form_data = request.form.to_dict(
            flat=False
        )

        for day_of_week, day_name in enumerate(day_names):
            start_values = request.form.getlist(
                f"start_time_{day_of_week}"
            )

            end_values = request.form.getlist(
                f"end_time_{day_of_week}"
            )

            day_periods = []

            max_rows = max(
                len(start_values),
                len(end_values)
            )

            for row_index in range(max_rows):
                start_value = (
                    start_values[row_index].strip()
                    if row_index < len(start_values)
                    else ""
                )

                end_value = (
                    end_values[row_index].strip()
                    if row_index < len(end_values)
                    else ""
                )

                if not start_value and not end_value:
                    continue

                if not start_value or not end_value:
                    validation_errors.append(
                        f"{day_name}: both a start time "
                        f"and end time are required."
                    )
                    continue

                try:
                    start_time = datetime.strptime(
                        start_value,
                        "%H:%M"
                    ).time()

                    end_time = datetime.strptime(
                        end_value,
                        "%H:%M"
                    ).time()

                except ValueError:
                    validation_errors.append(
                        f"{day_name}: one or more times "
                        f"are invalid."
                    )
                    continue

                if end_time <= start_time:
                    validation_errors.append(
                        f"{day_name}: the end time must "
                        f"be later than the start time."
                    )
                    continue

                day_periods.append((
                    start_time,
                    end_time
                ))

            day_periods.sort(
                key=lambda period: period[0]
            )

            for period_index in range(
                1,
                len(day_periods)
            ):
                previous_period = day_periods[
                    period_index - 1
                ]

                current_period = day_periods[
                    period_index
                ]

                if (
                    current_period[0]
                    < previous_period[1]
                ):
                    validation_errors.append(
                        f"{day_name}: business-hour "
                        f"periods cannot overlap."
                    )
                    break

            for start_time, end_time in day_periods:
                periods_to_save.append((
                    spa_id,
                    business_unit_id,
                    day_of_week,
                    start_time,
                    end_time,
                    user_id,
                    user_id
                ))

        if validation_errors:
            session[
                "booking_business_hours_form"
            ] = submitted_form_data

            for error_message in validation_errors:
                flash(error_message, "error")

            return redirect(
                url_for("booking_business_hours")
            )

        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                DELETE FROM booking_business_hours
                WHERE spa_id = %s
                  AND business_unit_id = %s
            """, (
                spa_id,
                business_unit_id
            ))

            if periods_to_save:
                cur.executemany("""
                    INSERT INTO booking_business_hours (
                        spa_id,
                        business_unit_id,
                        day_of_week,
                        start_time,
                        end_time,
                        is_active,
                        created_by,
                        updated_by
                    )
                    VALUES (
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        TRUE,
                        %s,
                        %s
                    )
                """, periods_to_save)

            conn.commit()

            flash(
                "Business hours saved successfully.",
                "success"
            )

        except Exception as error:
            conn.rollback()

            print(
                "SAVE BOOKING BUSINESS HOURS ERROR:",
                error
            )

            session[
                "booking_business_hours_form"
            ] = submitted_form_data

            flash(
                "Business hours could not be saved.",
                "error"
            )

        finally:
            cur.close()
            conn.close()

        return redirect(
            url_for("booking_business_hours")
        )

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT unit_name
            FROM business_units
            WHERE business_unit_id = %s
              AND spa_id = %s
              AND is_active = TRUE
            LIMIT 1
        """, (
            business_unit_id,
            spa_id
        ))

        workspace_row = cur.fetchone()

        workspace_name = (
            workspace_row[0]
            if workspace_row
            else "Current Workspace"
        )

        cur.execute("""
            SELECT
                day_of_week,
                start_time,
                end_time
            FROM booking_business_hours
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND is_active = TRUE
            ORDER BY
                day_of_week,
                start_time,
                end_time
        """, (
            spa_id,
            business_unit_id
        ))

        hour_rows = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    hours_by_day = {
        day_index: []
        for day_index in range(7)
    }

    submitted_form_data = session.pop(
        "booking_business_hours_form",
        None
    )

    if submitted_form_data:
        for day_index in range(7):
            start_values = submitted_form_data.get(
                f"start_time_{day_index}",
                []
            )

            end_values = submitted_form_data.get(
                f"end_time_{day_index}",
                []
            )

            max_rows = max(
                len(start_values),
                len(end_values)
            )

            for row_index in range(max_rows):
                start_value = (
                    start_values[row_index]
                    if row_index < len(start_values)
                    else ""
                )

                end_value = (
                    end_values[row_index]
                    if row_index < len(end_values)
                    else ""
                )

                if not start_value and not end_value:
                    continue

                hours_by_day[day_index].append({
                    "start_time": start_value,
                    "end_time": end_value
                })

    else:
        for day_of_week, start_time, end_time in hour_rows:
            hours_by_day[day_of_week].append({
                "start_time": start_time.strftime("%H:%M"),
                "end_time": end_time.strftime("%H:%M")
            })

    return render_template(
        "booking/business_hours.html",
        day_names=day_names,
        hours_by_day=hours_by_day,
        workspace_name=workspace_name
    )


############################################
#
#   ONLINE BOOKING - PROVIDER HOURS
#
############################################


@app.route(
    "/booking/provider-hours",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_provider_hours():
    from datetime import datetime

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    user_id = session.get("user_id")

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to manage provider hours.",
            "error"
        )
        return redirect(url_for("admin"))

    day_names = [
        "Sunday",
        "Monday",
        "Tuesday",
        "Wednesday",
        "Thursday",
        "Friday",
        "Saturday"
    ]

    def format_booking_time(time_value):
        return datetime.strptime(
            time_value.strftime("%H:%M"),
            "%H:%M"
        ).strftime("%I:%M %p").lstrip("0")

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                e.employee_id,
                e.first_name,
                e.last_name,
                e.employee_nickname,
                er.role_name
            FROM employees e
            LEFT JOIN employee_roles er
              ON er.employee_role_id = e.employee_role_id
             AND er.spa_id = e.spa_id
            WHERE e.spa_id = %s
              AND e.is_active = TRUE
            ORDER BY
                e.last_name,
                e.first_name,
                e.employee_id
        """, (spa_id,))

        provider_rows = cur.fetchall()

        cur.execute("""
            SELECT
                day_of_week,
                start_time,
                end_time
            FROM booking_business_hours
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND is_active = TRUE
            ORDER BY
                day_of_week,
                start_time,
                end_time
        """, (
            spa_id,
            business_unit_id
        ))

        business_hour_rows = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    providers = []

    for row in provider_rows:
        employee_id = row[0]
        first_name = (row[1] or "").strip()
        last_name = (row[2] or "").strip()
        nickname = (row[3] or "").strip()
        role_name = (row[4] or "").strip()

        full_name = (
            f"{first_name} {last_name}".strip()
        )

        display_name = (
            nickname
            or full_name
            or f"Employee {employee_id}"
        )

        if role_name:
            display_name = (
                f"{display_name} — {role_name}"
            )

        providers.append({
            "employee_id": employee_id,
            "display_name": display_name
        })

    provider_ids = {
        provider["employee_id"]
        for provider in providers
    }

    if request.method == "POST":
        selected_provider_id = request.form.get(
            "provider_employee_id",
            type=int
        )
    else:
        selected_provider_id = request.args.get(
            "provider_employee_id",
            type=int
        )

    if selected_provider_id is None and providers:
        selected_provider_id = providers[0][
            "employee_id"
        ]

    if (
        selected_provider_id is not None
        and selected_provider_id not in provider_ids
    ):
        if request.method == "POST":
            flash(
                "The selected provider is not available.",
                "error"
            )
            return redirect(
                url_for("booking_provider_hours")
            )

        selected_provider_id = (
            providers[0]["employee_id"]
            if providers
            else None
        )

    business_hours_by_day = {
        day_index: []
        for day_index in range(7)
    }

    for day_of_week, start_time, end_time in (
        business_hour_rows
    ):
        business_hours_by_day[day_of_week].append({
            "start_raw": start_time,
            "end_raw": end_time,
            "start_time": start_time.strftime("%H:%M"),
            "end_time": end_time.strftime("%H:%M"),
            "start_display": format_booking_time(
                start_time
            ),
            "end_display": format_booking_time(
                end_time
            )
        })

    if request.method == "POST":
        submitted_form_data = request.form.to_dict(
            flat=False
        )

        periods_to_save = []
        validation_errors = []

        for day_of_week, day_name in enumerate(
            day_names
        ):
            start_values = request.form.getlist(
                f"start_time_{day_of_week}"
            )

            end_values = request.form.getlist(
                f"end_time_{day_of_week}"
            )

            day_periods = []

            max_rows = max(
                len(start_values),
                len(end_values)
            )

            for row_index in range(max_rows):
                start_value = (
                    start_values[row_index].strip()
                    if row_index < len(start_values)
                    else ""
                )

                end_value = (
                    end_values[row_index].strip()
                    if row_index < len(end_values)
                    else ""
                )

                if not start_value and not end_value:
                    continue

                if not start_value or not end_value:
                    validation_errors.append(
                        f"{day_name}: both a start time "
                        f"and end time are required."
                    )
                    continue

                try:
                    start_time = datetime.strptime(
                        start_value,
                        "%H:%M"
                    ).time()

                    end_time = datetime.strptime(
                        end_value,
                        "%H:%M"
                    ).time()

                except ValueError:
                    validation_errors.append(
                        f"{day_name}: one or more times "
                        f"are invalid."
                    )
                    continue

                if end_time <= start_time:
                    validation_errors.append(
                        f"{day_name}: the end time must "
                        f"be later than the start time."
                    )
                    continue

                business_periods = (
                    business_hours_by_day.get(
                        day_of_week,
                        []
                    )
                )

                inside_business_hours = any(
                    start_time >= period["start_raw"]
                    and end_time <= period["end_raw"]
                    for period in business_periods
                )

                if not inside_business_hours:
                    validation_errors.append(
                        f"{day_name}: provider hours "
                        f"must fall within one business-hours "
                        f"period."
                    )
                    continue

                day_periods.append((
                    start_time,
                    end_time
                ))

            day_periods.sort(
                key=lambda period: period[0]
            )

            for period_index in range(
                1,
                len(day_periods)
            ):
                previous_period = day_periods[
                    period_index - 1
                ]

                current_period = day_periods[
                    period_index
                ]

                if (
                    current_period[0]
                    < previous_period[1]
                ):
                    validation_errors.append(
                        f"{day_name}: provider-hour "
                        f"periods cannot overlap."
                    )
                    break

            for start_time, end_time in day_periods:
                periods_to_save.append((
                    spa_id,
                    business_unit_id,
                    selected_provider_id,
                    day_of_week,
                    start_time,
                    end_time,
                    user_id,
                    user_id
                ))

        if validation_errors:
            session[
                "booking_provider_hours_form"
            ] = {
                "spa_id": spa_id,
                "business_unit_id": business_unit_id,
                "provider_employee_id": (
                    selected_provider_id
                ),
                "form_data": submitted_form_data
            }

            for error_message in validation_errors:
                flash(error_message, "error")

            return redirect(
                url_for(
                    "booking_provider_hours",
                    provider_employee_id=(
                        selected_provider_id
                    )
                )
            )

        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                DELETE FROM provider_booking_hours
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND provider_employee_id = %s
            """, (
                spa_id,
                business_unit_id,
                selected_provider_id
            ))

            if periods_to_save:
                cur.executemany("""
                    INSERT INTO provider_booking_hours (
                        spa_id,
                        business_unit_id,
                        provider_employee_id,
                        day_of_week,
                        start_time,
                        end_time,
                        is_active,
                        created_by,
                        updated_by
                    )
                    VALUES (
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        TRUE,
                        %s,
                        %s
                    )
                """, periods_to_save)

            conn.commit()

            session.pop(
                "booking_provider_hours_form",
                None
            )

            flash(
                "Provider hours saved successfully.",
                "success"
            )

        except Exception as error:
            conn.rollback()

            session[
                "booking_provider_hours_form"
            ] = {
                "spa_id": spa_id,
                "business_unit_id": business_unit_id,
                "provider_employee_id": (
                    selected_provider_id
                ),
                "form_data": submitted_form_data
            }

            print(
                "SAVE PROVIDER BOOKING HOURS ERROR:",
                error
            )

            flash(
                "Provider hours could not be saved.",
                "error"
            )

        finally:
            cur.close()
            conn.close()

        return redirect(
            url_for(
                "booking_provider_hours",
                provider_employee_id=(
                    selected_provider_id
                )
            )
        )

    provider_hour_rows = []

    if selected_provider_id is not None:
        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                SELECT
                    day_of_week,
                    start_time,
                    end_time
                FROM provider_booking_hours
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND provider_employee_id = %s
                  AND is_active = TRUE
                ORDER BY
                    day_of_week,
                    start_time,
                    end_time
            """, (
                spa_id,
                business_unit_id,
                selected_provider_id
            ))

            provider_hour_rows = cur.fetchall()

        finally:
            cur.close()
            conn.close()

    provider_hours_by_day = {
        day_index: []
        for day_index in range(7)
    }

    preserved_form = session.get(
        "booking_provider_hours_form"
    )

    use_preserved_form = (
        preserved_form
        and preserved_form.get("spa_id") == spa_id
        and preserved_form.get(
            "business_unit_id"
        ) == business_unit_id
        and preserved_form.get(
            "provider_employee_id"
        ) == selected_provider_id
    )

    if use_preserved_form:
        submitted_form_data = preserved_form.get(
            "form_data",
            {}
        )

        session.pop(
            "booking_provider_hours_form",
            None
        )

        for day_index in range(7):
            start_values = submitted_form_data.get(
                f"start_time_{day_index}",
                []
            )

            end_values = submitted_form_data.get(
                f"end_time_{day_index}",
                []
            )

            max_rows = max(
                len(start_values),
                len(end_values)
            )

            for row_index in range(max_rows):
                start_value = (
                    start_values[row_index]
                    if row_index < len(start_values)
                    else ""
                )

                end_value = (
                    end_values[row_index]
                    if row_index < len(end_values)
                    else ""
                )

                if not start_value and not end_value:
                    continue

                provider_hours_by_day[
                    day_index
                ].append({
                    "start_time": start_value,
                    "end_time": end_value
                })

    else:
        for day_of_week, start_time, end_time in (
            provider_hour_rows
        ):
            provider_hours_by_day[
                day_of_week
            ].append({
                "start_time": start_time.strftime(
                    "%H:%M"
                ),
                "end_time": end_time.strftime(
                    "%H:%M"
                )
            })

    return render_template(
        "booking/provider_hours.html",
        providers=providers,
        selected_provider_id=selected_provider_id,
        day_names=day_names,
        provider_hours_by_day=(
            provider_hours_by_day
        ),
        business_hours_by_day=(
            business_hours_by_day
        )
    )


############################################
#
#   ONLINE BOOKING - PROVIDER SERVICES
#
############################################


@app.route(
    "/booking/provider-services",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_provider_services():
    from decimal import Decimal, InvalidOperation

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    user_id = session.get("user_id")

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to manage provider services.",
            "error"
        )
        return redirect(url_for("admin"))

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                e.employee_id,
                e.first_name,
                e.last_name,
                e.employee_nickname,
                er.role_name
            FROM employees e
            LEFT JOIN employee_roles er
              ON er.employee_role_id = e.employee_role_id
             AND er.spa_id = e.spa_id
            WHERE e.spa_id = %s
              AND e.is_active = TRUE
            ORDER BY
                e.last_name,
                e.first_name,
                e.employee_id
        """, (spa_id,))

        provider_rows = cur.fetchall()

        cur.execute("""
            SELECT
                service_type_id,
                service_name,
                default_duration_minutes,
                default_price
            FROM service_name_types
            WHERE spa_id = %s
              AND is_active = TRUE
            ORDER BY
                service_name,
                service_type_id
        """, (spa_id,))

        service_rows = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    providers = []

    for row in provider_rows:
        employee_id = row[0]
        first_name = (row[1] or "").strip()
        last_name = (row[2] or "").strip()
        nickname = (row[3] or "").strip()
        role_name = (row[4] or "").strip()

        full_name = (
            f"{first_name} {last_name}".strip()
        )

        display_name = (
            nickname
            or full_name
            or f"Employee {employee_id}"
        )

        if role_name:
            display_name = (
                f"{display_name} — {role_name}"
            )

        providers.append({
            "employee_id": employee_id,
            "display_name": display_name
        })

    provider_ids = {
        provider["employee_id"]
        for provider in providers
    }

    service_ids = {
        row[0]
        for row in service_rows
    }

    if request.method == "POST":
        selected_provider_id = request.form.get(
            "provider_employee_id",
            type=int
        )
    else:
        selected_provider_id = request.args.get(
            "provider_employee_id",
            type=int
        )

    if selected_provider_id is None and providers:
        selected_provider_id = providers[0][
            "employee_id"
        ]

    if (
        selected_provider_id is not None
        and selected_provider_id not in provider_ids
    ):
        if request.method == "POST":
            flash(
                "The selected provider is not available.",
                "error"
            )

            return redirect(
                url_for("booking_provider_services")
            )

        selected_provider_id = (
            providers[0]["employee_id"]
            if providers
            else None
        )

    if request.method == "POST":
        submitted_form_data = request.form.to_dict(
            flat=False
        )

        validation_errors = []
        assignments_to_save = []

        assigned_service_ids = set()

        for raw_service_id in request.form.getlist(
            "assigned_service_ids"
        ):
            try:
                service_type_id = int(raw_service_id)
            except (TypeError, ValueError):
                validation_errors.append(
                    "One selected service was invalid."
                )
                continue

            if service_type_id not in service_ids:
                validation_errors.append(
                    "One selected service is not available."
                )
                continue

            assigned_service_ids.add(
                service_type_id
            )

        service_lookup = {
            row[0]: {
                "service_name": row[1] or "Service",
                "default_duration_minutes": row[2],
                "default_price": row[3]
            }
            for row in service_rows
        }

        for service_type_id in sorted(
            assigned_service_ids
        ):
            service = service_lookup[
                service_type_id
            ]

            service_name = service[
                "service_name"
            ]

            duration_raw = (
                request.form.get(
                    f"duration_override_{service_type_id}"
                )
                or ""
            ).strip()

            price_raw = (
                request.form.get(
                    f"price_override_{service_type_id}"
                )
                or ""
            ).strip()

            buffer_before_raw = (
                request.form.get(
                    f"buffer_before_{service_type_id}"
                )
                or ""
            ).strip()

            buffer_after_raw = (
                request.form.get(
                    f"buffer_after_{service_type_id}"
                )
                or ""
            ).strip()

            duration_override = None
            price_override = None
            buffer_before = None
            buffer_after = None

            if duration_raw:
                try:
                    duration_override = int(
                        duration_raw
                    )
                except (TypeError, ValueError):
                    validation_errors.append(
                        f"{service_name}: duration override "
                        f"must be entered in minutes."
                    )
                else:
                    if (
                        duration_override < 1
                        or duration_override > 1440
                    ):
                        validation_errors.append(
                            f"{service_name}: duration override "
                            f"must be between 1 and 1,440 "
                            f"minutes."
                        )

            if price_raw:
                try:
                    price_override = Decimal(
                        price_raw
                    )
                except (
                    InvalidOperation,
                    TypeError,
                    ValueError
                ):
                    validation_errors.append(
                        f"{service_name}: price override "
                        f"must be a valid dollar amount."
                    )
                else:
                    if price_override < 0:
                        validation_errors.append(
                            f"{service_name}: price override "
                            f"cannot be negative."
                        )

            if buffer_before_raw:
                try:
                    buffer_before = int(
                        buffer_before_raw
                    )
                except (TypeError, ValueError):
                    validation_errors.append(
                        f"{service_name}: buffer before "
                        f"must be entered in minutes."
                    )
                else:
                    if (
                        buffer_before < 0
                        or buffer_before > 1440
                    ):
                        validation_errors.append(
                            f"{service_name}: buffer before "
                            f"must be between 0 and 1,440 "
                            f"minutes."
                        )

            if buffer_after_raw:
                try:
                    buffer_after = int(
                        buffer_after_raw
                    )
                except (TypeError, ValueError):
                    validation_errors.append(
                        f"{service_name}: buffer after "
                        f"must be entered in minutes."
                    )
                else:
                    if (
                        buffer_after < 0
                        or buffer_after > 1440
                    ):
                        validation_errors.append(
                            f"{service_name}: buffer after "
                            f"must be between 0 and 1,440 "
                            f"minutes."
                        )

            is_publicly_bookable = (
                request.form.get(
                    f"publicly_bookable_{service_type_id}"
                )
                == "1"
            )

            assignments_to_save.append((
                spa_id,
                business_unit_id,
                selected_provider_id,
                service_type_id,
                duration_override,
                price_override,
                buffer_before,
                buffer_after,
                is_publicly_bookable,
                user_id,
                user_id
            ))

        if validation_errors:
            session[
                "booking_provider_services_form"
            ] = {
                "spa_id": spa_id,
                "business_unit_id": business_unit_id,
                "provider_employee_id": (
                    selected_provider_id
                ),
                "form_data": submitted_form_data
            }

            for error_message in validation_errors:
                flash(error_message, "error")

            return redirect(
                url_for(
                    "booking_provider_services",
                    provider_employee_id=(
                        selected_provider_id
                    )
                )
            )

        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                DELETE FROM provider_service_types
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND provider_employee_id = %s
            """, (
                spa_id,
                business_unit_id,
                selected_provider_id
            ))

            if assignments_to_save:
                cur.executemany("""
                    INSERT INTO provider_service_types (
                        spa_id,
                        business_unit_id,
                        provider_employee_id,
                        service_type_id,
                        duration_override_minutes,
                        price_override,
                        buffer_before_minutes,
                        buffer_after_minutes,
                        is_publicly_bookable,
                        is_active,
                        created_by,
                        updated_by
                    )
                    VALUES (
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        TRUE,
                        %s,
                        %s
                    )
                """, assignments_to_save)

            conn.commit()

            session.pop(
                "booking_provider_services_form",
                None
            )

            flash(
                "Provider services saved successfully.",
                "success"
            )

        except Exception as error:
            conn.rollback()

            session[
                "booking_provider_services_form"
            ] = {
                "spa_id": spa_id,
                "business_unit_id": business_unit_id,
                "provider_employee_id": (
                    selected_provider_id
                ),
                "form_data": submitted_form_data
            }

            print(
                "SAVE PROVIDER SERVICES ERROR:",
                error
            )

            flash(
                "Provider services could not be saved.",
                "error"
            )

        finally:
            cur.close()
            conn.close()

        return redirect(
            url_for(
                "booking_provider_services",
                provider_employee_id=(
                    selected_provider_id
                )
            )
        )

    assignment_rows = []

    if selected_provider_id is not None:
        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                SELECT
                    service_type_id,
                    duration_override_minutes,
                    price_override,
                    buffer_before_minutes,
                    buffer_after_minutes,
                    is_publicly_bookable
                FROM provider_service_types
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND provider_employee_id = %s
                  AND is_active = TRUE
                ORDER BY service_type_id
            """, (
                spa_id,
                business_unit_id,
                selected_provider_id
            ))

            assignment_rows = cur.fetchall()

        finally:
            cur.close()
            conn.close()

    assignments_by_service = {
        row[0]: {
            "duration_override_minutes": row[1],
            "price_override": row[2],
            "buffer_before_minutes": row[3],
            "buffer_after_minutes": row[4],
            "is_publicly_bookable": bool(row[5])
        }
        for row in assignment_rows
    }

    preserved_form = session.get(
        "booking_provider_services_form"
    )

    use_preserved_form = (
        preserved_form
        and preserved_form.get("spa_id") == spa_id
        and preserved_form.get(
            "business_unit_id"
        ) == business_unit_id
        and preserved_form.get(
            "provider_employee_id"
        ) == selected_provider_id
    )

    preserved_form_data = {}

    if use_preserved_form:
        preserved_form_data = preserved_form.get(
            "form_data",
            {}
        )

        session.pop(
            "booking_provider_services_form",
            None
        )

    def preserved_value(field_name):
        values = preserved_form_data.get(
            field_name,
            []
        )

        if not values:
            return ""

        return values[0]

    preserved_assigned_ids = set()

    if use_preserved_form:
        for raw_service_id in preserved_form_data.get(
            "assigned_service_ids",
            []
        ):
            try:
                preserved_assigned_ids.add(
                    int(raw_service_id)
                )
            except (TypeError, ValueError):
                pass

    services = []

    for row in service_rows:
        service_type_id = row[0]
        service_name = row[1] or "Unnamed Service"
        default_duration = row[2]
        default_price = row[3]

        assignment = assignments_by_service.get(
            service_type_id
        )

        if use_preserved_form:
            assigned = (
                service_type_id
                in preserved_assigned_ids
            )

            duration_override = preserved_value(
                f"duration_override_{service_type_id}"
            )

            price_override = preserved_value(
                f"price_override_{service_type_id}"
            )

            buffer_before = preserved_value(
                f"buffer_before_{service_type_id}"
            )

            buffer_after = preserved_value(
                f"buffer_after_{service_type_id}"
            )

            is_publicly_bookable = (
                preserved_value(
                    f"publicly_bookable_{service_type_id}"
                )
                == "1"
            )

        else:
            assigned = assignment is not None

            duration_override = (
                ""
                if not assignment
                or assignment[
                    "duration_override_minutes"
                ] is None
                else str(
                    assignment[
                        "duration_override_minutes"
                    ]
                )
            )

            price_override = (
                ""
                if not assignment
                or assignment["price_override"] is None
                else format(
                    assignment["price_override"],
                    ".2f"
                )
            )

            buffer_before = (
                ""
                if not assignment
                or assignment[
                    "buffer_before_minutes"
                ] is None
                else str(
                    assignment[
                        "buffer_before_minutes"
                    ]
                )
            )

            buffer_after = (
                ""
                if not assignment
                or assignment[
                    "buffer_after_minutes"
                ] is None
                else str(
                    assignment[
                        "buffer_after_minutes"
                    ]
                )
            )

            is_publicly_bookable = (
                assignment[
                    "is_publicly_bookable"
                ]
                if assignment
                else False
            )

        if default_price is None:
            default_price_value = ""
            default_price_display = (
                "Standard price not set"
            )
        else:
            default_price_value = format(
                default_price,
                ".2f"
            )

            default_price_display = (
                f"${default_price:,.2f}"
            )

        services.append({
            "service_type_id": service_type_id,
            "service_name": service_name,
            "default_duration_minutes": (
                default_duration
                if default_duration is not None
                else "Not set"
            ),
            "default_price": default_price_value,
            "default_price_display": (
                default_price_display
            ),
            "assigned": assigned,
            "duration_override_minutes": (
                duration_override
            ),
            "price_override": price_override,
            "buffer_before_minutes": (
                buffer_before
            ),
            "buffer_after_minutes": buffer_after,
            "is_publicly_bookable": (
                is_publicly_bookable
            )
        })

    return render_template(
        "booking/provider_services.html",
        providers=providers,
        selected_provider_id=selected_provider_id,
        services=services
    )


############################################
#
#   ONLINE BOOKING - PROVIDER TIME OFF
#
############################################


@app.route(
    "/booking/provider-time-off",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_provider_time_off():
    from datetime import datetime, timedelta

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    user_id = session.get("user_id")

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to manage provider time off.",
            "error"
        )
        return redirect(url_for("admin"))

    spa_now = get_spa_now(spa_id)

    # Provider time-off values are stored as local
    # business wall-clock times without a timezone.
    if spa_now.tzinfo is not None:
        spa_now_local = spa_now.replace(tzinfo=None)
    else:
        spa_now_local = spa_now

    block_types = [
        (
            "time_off",
            "Vacation / Personal Time"
        ),
        (
            "blocked_time",
            "Meeting / Temporary Block"
        )
    ]

    block_type_labels = dict(block_types)

    view_filter = (
        request.args.get("view")
        or "upcoming"
    ).strip().lower()

    if view_filter not in {
        "upcoming",
        "history",
        "all"
    }:
        view_filter = "upcoming"

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                e.employee_id,
                e.first_name,
                e.last_name,
                e.employee_nickname,
                er.role_name
            FROM employees e
            LEFT JOIN employee_roles er
              ON er.employee_role_id = e.employee_role_id
             AND er.spa_id = e.spa_id
            WHERE e.spa_id = %s
              AND e.is_active = TRUE
            ORDER BY
                e.last_name,
                e.first_name,
                e.employee_id
        """, (spa_id,))

        provider_rows = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    providers = []

    for row in provider_rows:
        employee_id = row[0]
        first_name = (row[1] or "").strip()
        last_name = (row[2] or "").strip()
        nickname = (row[3] or "").strip()
        role_name = (row[4] or "").strip()

        full_name = (
            f"{first_name} {last_name}".strip()
        )

        display_name = (
            nickname
            or full_name
            or f"Employee {employee_id}"
        )

        filter_name = display_name

        if role_name:
            display_name = (
                f"{display_name} — {role_name}"
            )

        providers.append({
            "employee_id": employee_id,
            "display_name": display_name,
            "filter_name": filter_name
        })

    provider_ids = {
        provider["employee_id"]
        for provider in providers
    }

    filter_provider_id = request.args.get(
        "filter_provider_id",
        type=int
    )

    if filter_provider_id not in provider_ids:
        filter_provider_id = None

    preserved_session_key = (
        "booking_provider_time_off_form"
    )

    if request.method == "POST":
        provider_time_off_id = request.form.get(
            "provider_time_off_id",
            type=int
        )

        selected_provider_id = request.form.get(
            "provider_employee_id",
            type=int
        )

        block_type = (
            request.form.get("block_type")
            or ""
        ).strip()

        starts_at_raw = (
            request.form.get("starts_at")
            or ""
        ).strip()

        ends_at_raw = (
            request.form.get("ends_at")
            or ""
        ).strip()

        is_all_day = (
            request.form.get("is_all_day")
            == "1"
        )

        all_day_start_date_raw = (
            request.form.get(
                "all_day_start_date"
            )
            or ""
        ).strip()

        all_day_end_date_raw = (
            request.form.get(
                "all_day_end_date"
            )
            or ""
        ).strip()

        reason = (
            request.form.get("reason")
            or ""
        ).strip()

        submitted_form_data = {
            "provider_employee_id": (
                selected_provider_id
            ),
            "block_type": block_type,
            "starts_at": starts_at_raw,
            "ends_at": ends_at_raw,
            "is_all_day": is_all_day,

            "all_day_start_date":
                all_day_start_date_raw,

            "all_day_end_date":
                all_day_end_date_raw,

            "reason": reason
        }

        validation_errors = []

        if selected_provider_id not in provider_ids:
            validation_errors.append(
                "Select a valid active provider."
            )

        if block_type not in block_type_labels:
            validation_errors.append(
                "Select a valid block type."
            )

        starts_at = None
        ends_at = None

        if is_all_day:
            if not all_day_start_date_raw:
                validation_errors.append(
                    "A start date is required for "
                    "all-day time off."
                )

            if not all_day_end_date_raw:
                validation_errors.append(
                    "An end date is required for "
                    "all-day time off."
                )

            if (
                all_day_start_date_raw
                and all_day_end_date_raw
            ):
                try:
                    all_day_start_date = (
                        datetime.strptime(
                            all_day_start_date_raw,
                            "%Y-%m-%d"
                        ).date()
                    )

                    all_day_end_date = (
                        datetime.strptime(
                            all_day_end_date_raw,
                            "%Y-%m-%d"
                        ).date()
                    )

                    if (
                        all_day_end_date
                        < all_day_start_date
                    ):
                        validation_errors.append(
                            "The all-day end date cannot "
                            "be earlier than the start date."
                        )

                    else:
                        starts_at = datetime.combine(
                            all_day_start_date,
                            datetime.min.time()
                        )

                        ends_at = datetime.combine(
                            (
                                all_day_end_date
                                + timedelta(days=1)
                            ),
                            datetime.min.time()
                        )

                except ValueError:
                    validation_errors.append(
                        "The all-day date range is invalid."
                    )

        else:
            if not starts_at_raw:
                validation_errors.append(
                    "A start date and time are required."
                )
            else:
                try:
                    starts_at = datetime.fromisoformat(
                        starts_at_raw
                    )
                except ValueError:
                    validation_errors.append(
                        "The start date or time is invalid."
                    )

            if not ends_at_raw:
                validation_errors.append(
                    "An end date and time are required."
                )
            else:
                try:
                    ends_at = datetime.fromisoformat(
                        ends_at_raw
                    )
                except ValueError:
                    validation_errors.append(
                        "The end date or time is invalid."
                    )

        if (
            starts_at is not None
            and ends_at is not None
            and ends_at <= starts_at
        ):
            validation_errors.append(
                "The ending date and time must be "
                "later than the starting date and time."
            )

        if len(reason) > 255:
            validation_errors.append(
                "The reason or note cannot exceed "
                "255 characters."
            )

        existing_record = None

        if (
            provider_time_off_id is not None
            and not validation_errors
        ):
            conn = get_db_connection()
            cur = conn.cursor()

            try:
                cur.execute("""
                    SELECT
                        provider_time_off_id,
                        provider_employee_id,
                        starts_at,
                        ends_at,
                        is_active
                    FROM provider_time_off
                    WHERE provider_time_off_id = %s
                      AND spa_id = %s
                      AND business_unit_id = %s
                    LIMIT 1
                """, (
                    provider_time_off_id,
                    spa_id,
                    business_unit_id
                ))

                existing_record = cur.fetchone()

            finally:
                cur.close()
                conn.close()

            if not existing_record:
                validation_errors.append(
                    "The time-off record could not "
                    "be found."
                )

            elif not existing_record[4]:
                validation_errors.append(
                    "A cancelled time-off record cannot "
                    "be edited."
                )

            elif existing_record[3] <= spa_now_local:
                validation_errors.append(
                    "A past time-off record cannot "
                    "be edited."
                )

        if (
            not validation_errors
            and starts_at is not None
            and ends_at is not None
        ):
            conn = get_db_connection()
            cur = conn.cursor()

            try:
                overlap_query = """
                    SELECT
                        provider_time_off_id
                    FROM provider_time_off
                    WHERE spa_id = %s
                      AND business_unit_id = %s
                      AND provider_employee_id = %s
                      AND is_active = TRUE
                      AND starts_at < %s
                      AND ends_at > %s
                """

                overlap_params = [
                    spa_id,
                    business_unit_id,
                    selected_provider_id,
                    ends_at,
                    starts_at
                ]

                if provider_time_off_id is not None:
                    overlap_query += """
                        AND provider_time_off_id <> %s
                    """

                    overlap_params.append(
                        provider_time_off_id
                    )

                overlap_query += """
                    LIMIT 1
                """

                cur.execute(
                    overlap_query,
                    tuple(overlap_params)
                )

                overlapping_record = cur.fetchone()

            finally:
                cur.close()
                conn.close()

            if overlapping_record:
                validation_errors.append(
                    "This provider already has an "
                    "overlapping time-off block."
                )

        if validation_errors:
            session[preserved_session_key] = {
                "spa_id": spa_id,
                "business_unit_id": business_unit_id,
                "provider_time_off_id": (
                    provider_time_off_id
                ),
                "form_data": submitted_form_data
            }

            for error_message in validation_errors:
                flash(error_message, "error")

            redirect_values = {
                "provider_employee_id": (
                    selected_provider_id
                ),
                "view": view_filter
            }

            if provider_time_off_id is not None:
                redirect_values["edit_id"] = (
                    provider_time_off_id
                )

            return redirect(
                url_for(
                    "booking_provider_time_off",
                    **redirect_values
                )
            )

        conn = get_db_connection()
        cur = conn.cursor()

        try:
            if provider_time_off_id is not None:
                cur.execute("""
                    UPDATE provider_time_off
                    SET
                        provider_employee_id = %s,
                        starts_at = %s,
                        ends_at = %s,
                        block_type = %s,
                        reason = %s,
                        is_all_day = %s,
                        updated_at = CURRENT_TIMESTAMP,
                        updated_by = %s
                    WHERE provider_time_off_id = %s
                      AND spa_id = %s
                      AND business_unit_id = %s
                      AND is_active = TRUE
                """, (
                    selected_provider_id,
                    starts_at,
                    ends_at,
                    block_type,
                    reason or None,
                    is_all_day,
                    user_id,
                    provider_time_off_id,
                    spa_id,
                    business_unit_id
                ))

                if cur.rowcount == 0:
                    raise ValueError(
                        "Time-off record was not updated."
                    )

                success_message = (
                    "Provider time off updated "
                    "successfully."
                )

            else:
                cur.execute("""
                    INSERT INTO provider_time_off (
                        spa_id,
                        business_unit_id,
                        provider_employee_id,
                        starts_at,
                        ends_at,
                        block_type,
                        reason,
                        is_all_day,
                        is_active,
                        created_by,
                        updated_by
                    )
                    VALUES (
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        TRUE,
                        %s,
                        %s
                    )
                """, (
                    spa_id,
                    business_unit_id,
                    selected_provider_id,
                    starts_at,
                    ends_at,
                    block_type,
                    reason or None,
                    is_all_day,
                    user_id,
                    user_id
                ))

                success_message = (
                    "Provider time off added "
                    "successfully."
                )

            conn.commit()

            session.pop(
                preserved_session_key,
                None
            )

            flash(
                success_message,
                "success"
            )

        except Exception as error:
            conn.rollback()

            session[preserved_session_key] = {
                "spa_id": spa_id,
                "business_unit_id": business_unit_id,
                "provider_time_off_id": (
                    provider_time_off_id
                ),
                "form_data": submitted_form_data
            }

            print(
                "SAVE PROVIDER TIME OFF ERROR:",
                error
            )

            flash(
                "Provider time off could not be saved.",
                "error"
            )

        finally:
            cur.close()
            conn.close()

        redirect_values = {
            "provider_employee_id": (
                selected_provider_id
            ),
            "view": "upcoming"
        }

        if filter_provider_id is not None:
            redirect_values["filter_provider_id"] = (
                filter_provider_id
            )

        if (
            provider_time_off_id is not None
            and session.get(preserved_session_key)
        ):
            redirect_values["edit_id"] = (
                provider_time_off_id
            )

        return redirect(
            url_for(
                "booking_provider_time_off",
                **redirect_values
            )
        )

    edit_id = request.args.get(
        "edit_id",
        type=int
    )

    editing_time_off = None
    editing_row = None

    if edit_id is not None:
        conn = get_db_connection()
        cur = conn.cursor()

        try:
            cur.execute("""
                SELECT
                    provider_time_off_id,
                    provider_employee_id,
                    starts_at,
                    ends_at,
                    block_type,
                    reason,
                    is_active,
                    is_all_day
                FROM provider_time_off
                WHERE provider_time_off_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
                LIMIT 1
            """, (
                edit_id,
                spa_id,
                business_unit_id
            ))

            editing_row = cur.fetchone()

        finally:
            cur.close()
            conn.close()

        if not editing_row:
            flash(
                "The time-off record could not be found.",
                "error"
            )

            return redirect(
                url_for(
                    "booking_provider_time_off",
                    view=view_filter
                )
            )

        if not editing_row[6]:
            flash(
                "A cancelled time-off record cannot "
                "be edited.",
                "warning"
            )

            return redirect(
                url_for(
                    "booking_provider_time_off",
                    view="history"
                )
            )

        if editing_row[3] <= spa_now_local:
            flash(
                "A past time-off record cannot be edited.",
                "warning"
            )

            return redirect(
                url_for(
                    "booking_provider_time_off",
                    view="history"
                )
            )

        editing_time_off = {
            "provider_time_off_id": editing_row[0]
        }

    preserved_form = session.get(
        preserved_session_key
    )

    use_preserved_form = (
        preserved_form
        and preserved_form.get("spa_id") == spa_id
        and preserved_form.get(
            "business_unit_id"
        ) == business_unit_id
        and preserved_form.get(
            "provider_time_off_id"
        ) == edit_id
    )

    if use_preserved_form:
        form_data = preserved_form.get(
            "form_data",
            {}
        )

        session.pop(
            preserved_session_key,
            None
        )

    elif editing_row:
        form_data = {
            "provider_employee_id": editing_row[1],
            "starts_at": editing_row[2].strftime(
                "%Y-%m-%dT%H:%M"
            ),
            "ends_at": editing_row[3].strftime(
                "%Y-%m-%dT%H:%M"
            ),
            "block_type": editing_row[4],
            "reason": editing_row[5] or "",
            "is_all_day": bool(editing_row[7]),

            "all_day_start_date": (
                editing_row[2].date().isoformat()
                if editing_row[7]
                else ""
            ),

            "all_day_end_date": (
                (
                    editing_row[3]
                    - timedelta(days=1)
                ).date().isoformat()
                if editing_row[7]
                else ""
            )
        }

    else:
        selected_provider_id = request.args.get(
            "provider_employee_id",
            type=int
        )

        if selected_provider_id not in provider_ids:
            selected_provider_id = (
                providers[0]["employee_id"]
                if providers
                else None
            )

        form_data = {
            "provider_employee_id": (
                selected_provider_id
            ),
            "starts_at": "",
            "ends_at": "",
            "block_type": "time_off",
            "is_all_day": False,
            "all_day_start_date": "",
            "all_day_end_date": "",
            "reason": ""
        }

    selected_provider_id = form_data.get(
        "provider_employee_id"
    )

    records_query = """
        SELECT
            pto.provider_time_off_id,
            pto.provider_employee_id,
            pto.starts_at,
            pto.ends_at,
            pto.block_type,
            pto.reason,
            pto.is_active,
            pto.is_all_day,
            e.first_name,
            e.last_name,
            e.employee_nickname
        FROM provider_time_off pto
        JOIN employees e
          ON e.employee_id = pto.provider_employee_id
         AND e.spa_id = pto.spa_id
        WHERE pto.spa_id = %s
          AND pto.business_unit_id = %s
    """

    records_params = [
        spa_id,
        business_unit_id
    ]

    if filter_provider_id is not None:
        records_query += """
            AND pto.provider_employee_id = %s
        """

        records_params.append(
            filter_provider_id
        )

    if view_filter == "upcoming":
        records_query += """
            AND pto.is_active = TRUE
            AND pto.ends_at >= %s
        """

        records_params.append(
            spa_now_local
        )

        records_query += """
            ORDER BY
                pto.starts_at,
                pto.ends_at
        """

    elif view_filter == "history":
        records_query += """
            AND (
                pto.is_active = FALSE
                OR pto.ends_at < %s
            )
        """

        records_params.append(
            spa_now_local
        )

        records_query += """
            ORDER BY
                pto.starts_at DESC,
                pto.ends_at DESC
        """

    else:
        records_query += """
            ORDER BY
                pto.is_active DESC,
                pto.starts_at DESC,
                pto.ends_at DESC
        """

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute(
            records_query,
            tuple(records_params)
        )

        record_rows = cur.fetchall()

    finally:
        cur.close()
        conn.close()

    def format_local_time_off(value):
        date_part = value.strftime(
            "%m/%d/%Y"
        )

        time_part = value.strftime(
            "%I:%M %p"
        ).lstrip("0")

        return f"{date_part} {time_part}"

    time_off_records = []

    for row in record_rows:
        provider_time_off_id = row[0]
        provider_employee_id = row[1]
        starts_at = row[2]
        ends_at = row[3]
        block_type = row[4]
        reason = row[5]
        is_active = bool(row[6])
        is_all_day = bool(row[7])

        first_name = (row[8] or "").strip()
        last_name = (row[9] or "").strip()
        nickname = (row[10] or "").strip()

        provider_name = (
            nickname
            or f"{first_name} {last_name}".strip()
            or f"Employee {provider_employee_id}"
        )

        if not is_active:
            status = "Cancelled"
            status_class = "cancelled"

        elif ends_at < spa_now_local:
            status = "Past"
            status_class = "past"

        elif (
            starts_at <= spa_now_local
            and ends_at > spa_now_local
        ):
            status = "Current"
            status_class = "current"

        else:
            status = "Upcoming"
            status_class = "upcoming"

        if is_all_day:
            inclusive_end_date = (
                ends_at
                - timedelta(days=1)
            )

            starts_at_display = (
                starts_at.strftime("%m/%d/%Y")
                + " — All Day"
            )

            ends_at_display = (
                inclusive_end_date.strftime(
                    "%m/%d/%Y"
                )
                + " — All Day"
            )

        else:
            starts_at_display = (
                format_local_time_off(starts_at)
            )

            ends_at_display = (
                format_local_time_off(ends_at)
            )

        time_off_records.append({
            "provider_time_off_id": (
                provider_time_off_id
            ),
            "provider_employee_id": (
                provider_employee_id
            ),
            "provider_name": provider_name,
            "starts_at_display":
                starts_at_display,

            "ends_at_display":
                ends_at_display,

            "is_all_day": is_all_day,
            "block_type_display": (
                block_type_labels.get(
                    block_type,
                    block_type.replace(
                        "_",
                        " "
                    ).title()
                )
            ),
            "reason": reason,
            "is_active": is_active,
            "status": status,
            "status_class": status_class
        })

    return render_template(
        "booking/provider_time_off.html",
        providers=providers,
        block_types=block_types,
        form_data=form_data,
        editing_time_off=editing_time_off,
        selected_provider_id=selected_provider_id,
        filter_provider_id=filter_provider_id,
        time_off_records=time_off_records,
        view_filter=view_filter
    )


############################################
#
#   ONLINE BOOKING - CANCEL TIME OFF
#
############################################


@app.route(
    "/booking/provider-time-off/"
    "<int:provider_time_off_id>/deactivate",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def deactivate_provider_time_off(
    provider_time_off_id
):
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()
    user_id = session.get("user_id")

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required.",
            "error"
        )
        return redirect(url_for("admin"))

    selected_provider_id = None

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                provider_employee_id,
                is_active
            FROM provider_time_off
            WHERE provider_time_off_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
            FOR UPDATE
        """, (
            provider_time_off_id,
            spa_id,
            business_unit_id
        ))

        record = cur.fetchone()

        if not record:
            conn.rollback()

            flash(
                "The time-off record could not be found.",
                "error"
            )

        else:
            selected_provider_id = record[0]

            if not record[1]:
                conn.rollback()

                flash(
                    "This time-off block is already "
                    "cancelled.",
                    "warning"
                )

            else:
                cur.execute("""
                    UPDATE provider_time_off
                    SET
                        is_active = FALSE,
                        updated_at = CURRENT_TIMESTAMP,
                        updated_by = %s
                    WHERE provider_time_off_id = %s
                      AND spa_id = %s
                      AND business_unit_id = %s
                      AND is_active = TRUE
                """, (
                    user_id,
                    provider_time_off_id,
                    spa_id,
                    business_unit_id
                ))

                conn.commit()

                flash(
                    "Time-off block cancelled "
                    "successfully.",
                    "success"
                )

    except Exception as error:
        conn.rollback()

        print(
            "CANCEL PROVIDER TIME OFF ERROR:",
            error
        )

        flash(
            "The time-off block could not be "
            "cancelled.",
            "error"
        )

    finally:
        cur.close()
        conn.close()

    return redirect(
        url_for(
            "booking_provider_time_off",
            provider_employee_id=(
                selected_provider_id
            ),
            view="upcoming"
        )
    )


@app.route("/admin")
@login_required
@spa_required
def admin():
    spa_id = current_spa_id()

    current_timezone = get_current_spa_timezone(spa_id)
    utc_now = get_utc_now()
    spa_now = get_spa_now(spa_id)

    conn = get_db_connection()
    cur = conn.cursor()

    cur.execute("""
        SELECT dropdown_key, display_label
        FROM spa_dropdown_labels
        WHERE spa_id = %s
    """, (spa_id,))

    label_rows = cur.fetchall()
    dropdown_labels = {row[0]: row[1] for row in label_rows}

    cur.close()
    conn.close()

    return render_template(
        "admin.html",
        current_timezone=current_timezone,
        utc_now=utc_now,
        spa_now=spa_now,
        dropdown_labels=dropdown_labels
    )





