############################################
#
#       BOOKING AVAILABILITY ENGINE
#
############################################


def _booking_normalize_name(value):
    return " ".join(
        str(value or "").strip().lower().split()
    )


def _booking_intervals_overlap(
    first_start,
    first_end,
    second_start,
    second_end
):
    return (
        first_start < second_end
        and first_end > second_start
    )


def _appointment_reschedule_is_available(
    *,
    cur,
    spa_id,
    business_unit_id,
    appointment_date,
    appointment_time,
    duration_minutes,
    provider_employee_id,
    service_type_id,
    exclude_appointment_id=None
):
    """
    Serialize appointment changes with public booking and
    reject overlapping active appointments.
    """
    from datetime import datetime, timedelta

    def invalid(message):
        return {
            "valid": False,
            "message": message
        }

    try:
        spa_id = int(spa_id)
        business_unit_id = int(
            business_unit_id
        )

        if provider_employee_id is not None:
            provider_employee_id = int(
                provider_employee_id
            )

        if service_type_id is not None:
            service_type_id = int(
                service_type_id
            )

        if exclude_appointment_id is not None:
            exclude_appointment_id = int(
                exclude_appointment_id
            )

        duration_minutes = max(
            int(duration_minutes or 60),
            1
        )

        candidate_start = (
            datetime.fromisoformat(
                f"{appointment_date}T"
                f"{appointment_time}"
            )
        )

    except (TypeError, ValueError):
        return invalid(
            "Please enter a valid appointment "
            "date and time."
        )

    # -----------------------------------------------------
    # Use the same workspace transaction lock as public
    # booking confirmation.
    # -----------------------------------------------------

    cur.execute("""
        SELECT
            default_buffer_before_minutes,
            default_buffer_after_minutes
        FROM booking_settings
        WHERE spa_id = %s
          AND business_unit_id = %s
        FOR UPDATE
    """, (
        spa_id,
        business_unit_id
    ))

    booking_settings_row = cur.fetchone()

    if booking_settings_row:
        default_buffer_before = max(
            int(
                booking_settings_row[0]
                or 0
            ),
            0
        )

        default_buffer_after = max(
            int(
                booking_settings_row[1]
                or 0
            ),
            0
        )

    else:
        default_buffer_before = 0
        default_buffer_after = 0

        cur.execute("""
            SELECT pg_advisory_xact_lock(
                %s,
                %s
            )
        """, (
            spa_id,
            business_unit_id
        ))

    candidate_buffer_before = (
        default_buffer_before
    )

    candidate_buffer_after = (
        default_buffer_after
    )

    if (
        provider_employee_id is not None
        and service_type_id is not None
    ):
        cur.execute("""
            SELECT
                COALESCE(
                    buffer_before_minutes,
                    %s,
                    0
                ),
                COALESCE(
                    buffer_after_minutes,
                    %s,
                    0
                )
            FROM provider_service_types
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND provider_employee_id = %s
              AND service_type_id = %s
              AND is_active = TRUE
            LIMIT 1
        """, (
            default_buffer_before,
            default_buffer_after,
            spa_id,
            business_unit_id,
            provider_employee_id,
            service_type_id
        ))

        provider_service_row = (
            cur.fetchone()
        )

        if provider_service_row:
            candidate_buffer_before = max(
                int(
                    provider_service_row[0]
                    or 0
                ),
                0
            )

            candidate_buffer_after = max(
                int(
                    provider_service_row[1]
                    or 0
                ),
                0
            )

    candidate_end = (
        candidate_start
        + timedelta(
            minutes=duration_minutes
        )
    )

    candidate_block_start = (
        candidate_start
        - timedelta(
            minutes=candidate_buffer_before
        )
    )

    candidate_block_end = (
        candidate_end
        + timedelta(
            minutes=candidate_buffer_after
        )
    )

    cur.execute("""
        SELECT 1
        FROM appointments a

        LEFT JOIN service_name_types snt
          ON snt.service_type_id =
                a.service_type_id
         AND snt.spa_id = a.spa_id

        LEFT JOIN provider_service_types pst
          ON pst.spa_id = a.spa_id
         AND pst.business_unit_id =
                a.business_unit_id
         AND pst.provider_employee_id =
                a.provider_employee_id
         AND pst.service_type_id =
                a.service_type_id
         AND pst.is_active = TRUE

        WHERE a.spa_id = %s
          AND a.business_unit_id = %s
          AND a.appointment_date = %s

          AND (
                %s::INTEGER IS NULL
                OR a.appointment_id <> %s
              )

          AND LOWER(
                TRIM(
                    COALESCE(
                        a.status,
                        ''
                    )
                )
              ) NOT IN (
                'cancelled',
                'canceled',
                'completed',
                'no show',
                'no-show',
                're-scheduled',
                'rescheduled'
              )

          AND (
                %s::INTEGER IS NULL
                OR a.provider_employee_id = %s
                OR a.provider_employee_id IS NULL
              )

          AND (
                (
                    (
                        a.appointment_date
                        + a.appointment_time
                    )
                    - make_interval(
                        mins => COALESCE(
                            pst.buffer_before_minutes,
                            %s,
                            0
                        )
                    )
                ) < %s

                AND

                (
                    (
                        a.appointment_date
                        + a.appointment_time
                    )
                    + make_interval(
                        mins => (
                            COALESCE(
                                NULLIF(
                                    a.duration_minutes,
                                    0
                                ),
                                snt.default_duration_minutes,
                                60
                            )
                            + COALESCE(
                                pst.buffer_after_minutes,
                                %s,
                                0
                            )
                        )
                    )
                ) > %s
              )

        LIMIT 1
    """, (
        spa_id,
        business_unit_id,
        candidate_start.date(),
        exclude_appointment_id,
        exclude_appointment_id,
        provider_employee_id,
        provider_employee_id,
        default_buffer_before,
        candidate_block_end,
        default_buffer_after,
        candidate_block_start
    ))

    if cur.fetchone():
        if provider_employee_id is None:
            message = (
                "An existing appointment overlaps "
                "the selected time. Please choose "
                "another time."
            )
        else:
            message = (
                "That provider already has an "
                "overlapping appointment. Please "
                "choose another time."
            )

        return invalid(message)

    return {
        "valid": True,
        "message": ""
    }


def _booking_round_up_to_interval(
    value,
    interval_minutes
):
    from datetime import timedelta

    interval_minutes = max(
        int(interval_minutes or 1),
        1
    )

    day_start = value.replace(
        hour=0,
        minute=0,
        second=0,
        microsecond=0
    )

    total_minutes = (
        value.hour * 60
        + value.minute
    )

    if value.second or value.microsecond:
        total_minutes += 1

    rounded_minutes = (
        (
            total_minutes
            + interval_minutes
            - 1
        )
        // interval_minutes
    ) * interval_minutes

    return (
        day_start
        + timedelta(minutes=rounded_minutes)
    )


def _booking_merge_windows(windows):
    if not windows:
        return []

    sorted_windows = sorted(
        windows,
        key=lambda item: item[0]
    )

    merged = [
        [
            sorted_windows[0][0],
            sorted_windows[0][1]
        ]
    ]

    for window_start, window_end in sorted_windows[1:]:
        previous_start, previous_end = merged[-1]

        if window_start <= previous_end:
            merged[-1][1] = max(
                previous_end,
                window_end
            )
        else:
            merged.append(
                [window_start, window_end]
            )

    return [
        (window_start, window_end)
        for window_start, window_end in merged
    ]





def _booking_normalize_email(value):
    return str(
        value or ""
    ).strip().lower()


def _booking_normalize_phone(value):
    digits = "".join(
        character
        for character in str(value or "")
        if character.isdigit()
    )

    # Normalize a standard US country-code prefix.
    if (
        len(digits) == 11
        and digits.startswith("1")
    ):
        digits = digits[1:]

    return digits


def _booking_validate_selected_slot(
    cur,
    spa_id,
    business_unit_id,
    provider_employee_id,
    service_type_id,
    appointment_start,
    require_public=False
):
    """
    Revalidate one selected appointment time using the
    same rules as the booking availability engine.

    This function does not commit or acquire a database
    lock. The confirmation route must lock the selected
    provider/date before calling it.
    """
    from datetime import datetime, timedelta

    def invalid(reason):
        return {
            "valid": False,
            "reason": reason
        }

    try:
        spa_id = int(spa_id)
        business_unit_id = int(
            business_unit_id
        )
        provider_employee_id = int(
            provider_employee_id
        )
        service_type_id = int(
            service_type_id
        )
    except (TypeError, ValueError):
        return invalid(
            "Invalid booking selection."
        )

    if isinstance(appointment_start, str):
        try:
            appointment_start = (
                datetime.fromisoformat(
                    appointment_start
                )
            )
        except ValueError:
            return invalid(
                "Invalid appointment date or time."
            )

    if not isinstance(
        appointment_start,
        datetime
    ):
        return invalid(
            "Invalid appointment date or time."
        )

    # Booking times are stored as local business
    # wall-clock values without timezone information.
    appointment_start = (
        appointment_start.replace(
            tzinfo=None
        )
    )

    if (
        appointment_start.second != 0
        or appointment_start.microsecond != 0
    ):
        return invalid(
            "The selected time is not aligned "
            "to a valid booking interval."
        )

    # =====================================================
    # Booking settings
    # =====================================================

    cur.execute("""
        SELECT
            slot_interval_minutes,
            minimum_booking_notice_hours,
            maximum_booking_days_ahead,
            default_buffer_before_minutes,
            default_buffer_after_minutes,
            public_booking_enabled
        FROM booking_settings
        WHERE spa_id = %s
          AND business_unit_id = %s
    """, (
        spa_id,
        business_unit_id
    ))

    settings_row = cur.fetchone()

    if not settings_row:
        return invalid(
            "Booking settings were not found."
        )

    slot_interval_minutes = max(
        int(settings_row[0] or 15),
        1
    )

    minimum_notice_hours = max(
        int(settings_row[1] or 0),
        0
    )

    maximum_days_ahead = max(
        int(settings_row[2] or 90),
        0
    )

    default_buffer_before = max(
        int(settings_row[3] or 0),
        0
    )

    default_buffer_after = max(
        int(settings_row[4] or 0),
        0
    )

    public_booking_enabled = bool(
        settings_row[5]
    )

    if (
        require_public
        and not public_booking_enabled
    ):
        return invalid(
            "Online booking is not currently enabled."
        )

    local_now = get_spa_now(
        spa_id
    ).replace(tzinfo=None)

    earliest_allowed_start = (
        local_now
        + timedelta(
            hours=minimum_notice_hours
        )
    )

    latest_allowed_date = (
        local_now.date()
        + timedelta(
            days=maximum_days_ahead
        )
    )

    if (
        appointment_start.date()
        < local_now.date()
        or appointment_start.date()
        > latest_allowed_date
    ):
        return invalid(
            "The selected date is outside "
            "the allowed booking range."
        )

    if (
        appointment_start
        < earliest_allowed_start
    ):
        return invalid(
            "The minimum booking notice "
            "has not been met."
        )

    minutes_from_midnight = (
        appointment_start.hour * 60
        + appointment_start.minute
    )

    if (
        minutes_from_midnight
        % slot_interval_minutes
        != 0
    ):
        return invalid(
            "The selected time is not aligned "
            "to a valid booking interval."
        )

    # =====================================================
    # Provider-service assignment
    # =====================================================

    assignment_sql = """
        SELECT
            COALESCE(
                NULLIF(
                    TRIM(e.employee_nickname),
                    ''
                ),
                NULLIF(
                    TRIM(
                        CONCAT_WS(
                            ' ',
                            e.first_name,
                            e.last_name
                        )
                    ),
                    ''
                ),
                'Provider ' ||
                    e.employee_id::TEXT
            ) AS provider_name,

            snt.service_name,

            COALESCE(
                pst.duration_override_minutes,
                snt.default_duration_minutes
            ) AS duration_minutes,

            COALESCE(
                pst.price_override,
                snt.default_price
            ) AS price_at_booking,

            COALESCE(
                pst.buffer_before_minutes,
                %s,
                0
            ) AS buffer_before_minutes,

            COALESCE(
                pst.buffer_after_minutes,
                %s,
                0
            ) AS buffer_after_minutes,

            pst.is_publicly_bookable

        FROM provider_service_types pst

        JOIN employees e
          ON e.employee_id =
                pst.provider_employee_id
         AND e.spa_id = pst.spa_id

        JOIN service_name_types snt
          ON snt.service_type_id =
                pst.service_type_id
         AND snt.spa_id = pst.spa_id

        WHERE pst.spa_id = %s
          AND pst.business_unit_id = %s
          AND pst.provider_employee_id = %s
          AND pst.service_type_id = %s
          AND pst.is_active = TRUE
          AND e.is_active = TRUE
          AND snt.is_active = TRUE
    """

    assignment_params = [
        default_buffer_before,
        default_buffer_after,
        spa_id,
        business_unit_id,
        provider_employee_id,
        service_type_id
    ]

    if require_public:
        assignment_sql += """
          AND pst.is_publicly_bookable = TRUE
        """

    assignment_sql += """
        LIMIT 1
    """

    cur.execute(
        assignment_sql,
        tuple(assignment_params)
    )

    assignment_row = cur.fetchone()

    if not assignment_row:
        return invalid(
            "The selected provider does not "
            "offer this service."
        )

    provider_name = assignment_row[0]
    service_name = assignment_row[1]

    duration_minutes = int(
        assignment_row[2] or 0
    )

    price_at_booking = assignment_row[3]

    buffer_before_minutes = max(
        int(assignment_row[4] or 0),
        0
    )

    buffer_after_minutes = max(
        int(assignment_row[5] or 0),
        0
    )

    if duration_minutes <= 0:
        return invalid(
            "The selected service does not have "
            "a valid duration."
        )

    service_end = (
        appointment_start
        + timedelta(
            minutes=duration_minutes
        )
    )

    candidate_block_start = (
        appointment_start
        - timedelta(
            minutes=buffer_before_minutes
        )
    )

    candidate_block_end = (
        service_end
        + timedelta(
            minutes=buffer_after_minutes
        )
    )

    selected_date = (
        appointment_start.date()
    )

    if (
        candidate_block_start.date()
        != selected_date
        or candidate_block_end.date()
        != selected_date
    ):
        return invalid(
            "The selected appointment does not fit "
            "within one business day."
        )

    day_of_week = (
        selected_date.isoweekday()
    )

    # =====================================================
    # Business and provider working hours
    # =====================================================

    cur.execute("""
        SELECT
            start_time,
            end_time
        FROM booking_business_hours
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND day_of_week = %s
          AND is_active = TRUE
        ORDER BY start_time
    """, (
        spa_id,
        business_unit_id,
        day_of_week
    ))

    business_windows = [
        (
            datetime.combine(
                selected_date,
                row[0]
            ),
            datetime.combine(
                selected_date,
                row[1]
            )
        )
        for row in cur.fetchall()
    ]

    if not business_windows:
        return invalid(
            "The business is closed on "
            "the selected date."
        )

    cur.execute("""
        SELECT
            start_time,
            end_time
        FROM provider_booking_hours
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND provider_employee_id = %s
          AND day_of_week = %s
          AND is_active = TRUE
        ORDER BY start_time
    """, (
        spa_id,
        business_unit_id,
        provider_employee_id,
        day_of_week
    ))

    provider_windows = [
        (
            datetime.combine(
                selected_date,
                row[0]
            ),
            datetime.combine(
                selected_date,
                row[1]
            )
        )
        for row in cur.fetchall()
    ]

    if not provider_windows:
        return invalid(
            "The selected provider is not working "
            "on that date."
        )

    fits_working_window = False

    for (
        business_start,
        business_end
    ) in business_windows:

        for (
            provider_start,
            provider_end
        ) in provider_windows:

            working_start = max(
                business_start,
                provider_start
            )

            working_end = min(
                business_end,
                provider_end
            )

            if (
                working_start < working_end
                and candidate_block_start
                    >= working_start
                and candidate_block_end
                    <= working_end
            ):
                fits_working_window = True
                break

        if fits_working_window:
            break

    if not fits_working_window:
        return invalid(
            "The selected appointment does not fit "
            "within the provider's working hours."
        )

    # =====================================================
    # Provider time off and blocked time
    # =====================================================

    cur.execute("""
        SELECT 1
        FROM provider_time_off
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND provider_employee_id = %s
          AND is_active = TRUE
          AND starts_at < %s
          AND ends_at > %s
        LIMIT 1
    """, (
        spa_id,
        business_unit_id,
        provider_employee_id,
        candidate_block_end,
        candidate_block_start
    ))

    if cur.fetchone():
        return invalid(
            "The selected provider is unavailable "
            "at that time."
        )

    # =====================================================
    # Provider aliases for appointments that were created
    # before provider_employee_id was consistently stored
    # =====================================================

    cur.execute("""
        SELECT DISTINCT
            e.employee_id,
            e.employee_nickname,
            e.first_name,
            e.last_name
        FROM provider_service_types pst
        JOIN employees e
          ON e.employee_id =
                pst.provider_employee_id
         AND e.spa_id = pst.spa_id
        WHERE pst.spa_id = %s
          AND pst.business_unit_id = %s
          AND pst.is_active = TRUE
          AND e.is_active = TRUE
    """, (
        spa_id,
        business_unit_id
    ))

    alias_to_provider_ids = {}

    for row in cur.fetchall():
        employee_id = row[0]
        nickname = row[1]
        first_name = row[2]
        last_name = row[3]

        aliases = {
            _booking_normalize_name(
                nickname
            ),
            _booking_normalize_name(
                first_name
            ),
            _booking_normalize_name(
                " ".join(
                    value
                    for value in (
                        first_name,
                        last_name
                    )
                    if value
                )
            )
        }

        for alias in aliases:
            if not alias:
                continue

            alias_to_provider_ids.setdefault(
                alias,
                set()
            ).add(employee_id)

    # =====================================================
    # Existing appointment conflicts
    # =====================================================

    cur.execute("""
        SELECT
            a.appointment_id,
            a.appointment_time,

            COALESCE(
                NULLIF(
                    a.duration_minutes,
                    0
                ),
                snt.default_duration_minutes,
                60
            ) AS duration_minutes,

            a.provider_employee_id,
            a.provider_name_at_booking,

            COALESCE(
                pst.buffer_before_minutes,
                %s,
                0
            ) AS buffer_before_minutes,

            COALESCE(
                pst.buffer_after_minutes,
                %s,
                0
            ) AS buffer_after_minutes

        FROM appointments a

        LEFT JOIN service_name_types snt
          ON snt.service_type_id =
                a.service_type_id
         AND snt.spa_id = a.spa_id

        LEFT JOIN provider_service_types pst
          ON pst.spa_id = a.spa_id
         AND pst.business_unit_id =
                a.business_unit_id
         AND pst.provider_employee_id =
                a.provider_employee_id
         AND pst.service_type_id =
                a.service_type_id
         AND pst.is_active = TRUE

        WHERE a.spa_id = %s
          AND a.business_unit_id = %s
          AND a.appointment_date = %s

          AND LOWER(
                TRIM(
                    COALESCE(
                        a.status,
                        ''
                    )
                )
              ) NOT IN (
                'cancelled',
                'canceled',
                'completed',
                'no show',
                'no-show',
                're-scheduled',
                'rescheduled'
              )

        ORDER BY
            a.appointment_time,
            a.appointment_id
    """, (
        default_buffer_before,
        default_buffer_after,
        spa_id,
        business_unit_id,
        selected_date
    ))

    generic_provider_names = {
        "",
        "any",
        "any available",
        "any provider",
        "no preference",
        "unassigned"
    }

    for row in cur.fetchall():
        existing_time = row[1]

        if existing_time is None:
            continue

        existing_provider_id = row[3]
        applies_to_selected_provider = False

        if (
            existing_provider_id
            == provider_employee_id
        ):
            applies_to_selected_provider = True

        elif existing_provider_id is None:
            normalized_provider_name = (
                _booking_normalize_name(
                    row[4]
                )
            )

            matched_ids = (
                alias_to_provider_ids.get(
                    normalized_provider_name,
                    set()
                )
            )

            if (
                normalized_provider_name
                in generic_provider_names
            ):
                applies_to_selected_provider = True

            elif len(matched_ids) == 1:
                applies_to_selected_provider = (
                    provider_employee_id
                    in matched_ids
                )

            else:
                # An unrecognized or ambiguous legacy
                # provider blocks all providers safely.
                applies_to_selected_provider = True

        if not applies_to_selected_provider:
            continue

        existing_start = datetime.combine(
            selected_date,
            existing_time
        )

        existing_end = (
            existing_start
            + timedelta(
                minutes=int(row[2] or 60)
            )
        )

        existing_block_start = (
            existing_start
            - timedelta(
                minutes=int(row[5] or 0)
            )
        )

        existing_block_end = (
            existing_end
            + timedelta(
                minutes=int(row[6] or 0)
            )
        )

        if _booking_intervals_overlap(
            candidate_block_start,
            candidate_block_end,
            existing_block_start,
            existing_block_end
        ):
            return invalid(
                "That appointment time is no longer "
                "available."
            )

    return {
        "valid": True,
        "reason": "",

        "spa_id": spa_id,
        "business_unit_id":
            business_unit_id,

        "provider_employee_id":
            provider_employee_id,

        "provider_name":
            provider_name,

        "service_type_id":
            service_type_id,

        "service_name":
            service_name,

        "duration_minutes":
            duration_minutes,

        "price_at_booking":
            price_at_booking,

        "buffer_before_minutes":
            buffer_before_minutes,

        "buffer_after_minutes":
            buffer_after_minutes,

        "appointment_start":
            appointment_start,

        "appointment_date":
            appointment_start.date(),

        "appointment_time":
            appointment_start.time(),

        "service_end":
            service_end
    }




@app.route(
    "/booking/public-preview/confirm",
    methods=["POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_public_preview_confirm():
    """
    Internal-only booking confirmation test.

    This route creates a real local appointment, but it
    does not enable the public booking URL and does not
    send email or SMS.
    """
    import re
    from datetime import datetime

    spa_id = current_spa_id()
    business_unit_id = (
        current_business_unit_id()
    )

    service_type_id_raw = (
        request.form.get(
            "service_type_id"
        )
        or ""
    ).strip()

    provider_employee_id_raw = (
        request.form.get(
            "provider_employee_id"
        )
        or ""
    ).strip()

    appointment_start_raw = (
        request.form.get(
            "appointment_start"
        )
        or ""
    ).strip()

    first_name = (
        request.form.get("first_name")
        or ""
    ).strip()

    last_name = (
        request.form.get("last_name")
        or ""
    ).strip()

    phone = (
        request.form.get("phone")
        or ""
    ).strip()

    email = (
        request.form.get("email")
        or ""
    ).strip()

    notes = (
        request.form.get("notes")
        or ""
    ).strip()

    booking_for_other_raw = (
        request.form.get(
            "booking_for_other"
        )
        or "false"
    ).strip().lower()

    guest_first_name = (
        request.form.get(
            "guest_first_name"
        )
        or ""
    ).strip()

    guest_last_name = (
        request.form.get(
            "guest_last_name"
        )
        or ""
    ).strip()


    def failure_response(
        message,
        status_code=400,
        service_type_id=None
    ):
        back_arguments = {}

        if service_type_id:
            back_arguments[
                "service_type_id"
            ] = service_type_id

        return (
            render_template(
                "booking/"
                "public_booking_confirmation.html",
                success=False,
                preview_mode=True,
                message=message,
                back_url=url_for(
                    "booking_public_preview",
                    **back_arguments
                )
            ),
            status_code
        )


    if business_unit_id is None:
        return failure_response(
            "A valid Provider Workspace "
            "is required."
        )


    try:
        service_type_id = int(
            service_type_id_raw
        )

        provider_employee_id = int(
            provider_employee_id_raw
        )
    except (TypeError, ValueError):
        return failure_response(
            "The selected service or provider "
            "is invalid."
        )


    try:
        appointment_start = (
            datetime.fromisoformat(
                appointment_start_raw
            )
        )
    except (TypeError, ValueError):
        return failure_response(
            "The selected appointment time "
            "is invalid.",
            service_type_id=service_type_id
        )


    if appointment_start.tzinfo is not None:
        return failure_response(
            "The selected appointment time "
            "contains an unexpected timezone.",
            service_type_id=service_type_id
        )


    if (
        not first_name
        or not last_name
    ):
        return failure_response(
            "First and last name are required.",
            service_type_id=service_type_id
        )


    if (
        len(first_name) > 80
        or len(last_name) > 80
    ):
        return failure_response(
            "The client name is too long.",
            service_type_id=service_type_id
        )


    if booking_for_other_raw not in (
        "true",
        "false"
    ):
        return failure_response(
            "The appointment recipient selection "
            "is invalid.",
            service_type_id=service_type_id
        )

    booking_for_other = (
        booking_for_other_raw == "true"
    )

    if (
        booking_for_other
        and (
            not guest_first_name
            or not guest_last_name
        )
    ):
        return failure_response(
            "The guest's first and last name "
            "are required.",
            service_type_id=service_type_id
        )

    if (
        len(guest_first_name) > 80
        or len(guest_last_name) > 80
    ):
        return failure_response(
            "The guest name is too long.",
            service_type_id=service_type_id
        )

    if not booking_for_other:
        guest_first_name = ""
        guest_last_name = ""


    if len(phone) > 30:
        return failure_response(
            "The phone number is too long.",
            service_type_id=service_type_id
        )


    if len(email) > 150:
        return failure_response(
            "The email address is too long.",
            service_type_id=service_type_id
        )


    if len(notes) > 500:
        return failure_response(
            "Appointment notes cannot exceed "
            "500 characters.",
            service_type_id=service_type_id
        )


    normalized_email = (
        _booking_normalize_email(
            email
        )
    )

    normalized_phone = (
        _booking_normalize_phone(
            phone
        )
    )


    if not re.fullmatch(
        r"[^@\s]+@[^@\s]+\.[^@\s]+",
        normalized_email
    ):
        return failure_response(
            "Please enter a valid email address.",
            service_type_id=service_type_id
        )


    if len(normalized_phone) != 10:
        return failure_response(
            "Please enter a valid 10-digit "
            "phone number.",
            service_type_id=service_type_id
        )


    conn = get_db_connection()
    cur = conn.cursor()

    client_was_created = False

    try:
        # -------------------------------------------------
        # Serialize online confirmations for this workspace.
        #
        # A short row lock prevents two simultaneous
        # confirmations from both passing availability
        # validation before either appointment is inserted.
        # It also prevents duplicate client creation between
        # simultaneous online bookings in this workspace.
        # -------------------------------------------------

        cur.execute("""
            SELECT spa_id
            FROM booking_settings
            WHERE spa_id = %s
              AND business_unit_id = %s
            FOR UPDATE
        """, (
            spa_id,
            business_unit_id
        ))

        if not cur.fetchone():
            conn.rollback()

            return failure_response(
                "Booking settings were not found "
                "for this workspace.",
                service_type_id=service_type_id
            )


        # -------------------------------------------------
        # Revalidate after obtaining the transaction lock.
        # Never trust duration, price, provider name, or
        # service name posted by the browser.
        # -------------------------------------------------

        validation = (
            _booking_validate_selected_slot(
                cur=cur,
                spa_id=spa_id,
                business_unit_id=
                    business_unit_id,
                provider_employee_id=
                    provider_employee_id,
                service_type_id=
                    service_type_id,
                appointment_start=
                    appointment_start,
                require_public=False
            )
        )

        if not validation.get("valid"):
            conn.rollback()

            return failure_response(
                validation.get("reason")
                or (
                    "That appointment time "
                    "is no longer available."
                ),
                status_code=409,
                service_type_id=service_type_id
            )


        # -------------------------------------------------
        # Match an existing client by normalized email
        # or normalized phone.
        # -------------------------------------------------

        cur.execute("""
            SELECT
                client_id,
                first_name,
                last_name,
                phone,
                email
            FROM clients
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND (
                    LOWER(
                        TRIM(
                            COALESCE(email, '')
                        )
                    ) = %s

                    OR regexp_replace(
                        COALESCE(phone, ''),
                        '[^0-9]',
                        '',
                        'g'
                    ) IN (%s, %s)
                  )
            ORDER BY client_id
            FOR UPDATE
        """, (
            spa_id,
            business_unit_id,
            normalized_email,
            normalized_phone,
            "1" + normalized_phone
        ))

        candidate_clients = cur.fetchall()

        email_match_ids = set()
        phone_match_ids = set()
        candidate_by_id = {}

        for candidate in candidate_clients:
            candidate_client_id = candidate[0]

            candidate_by_id[
                candidate_client_id
            ] = candidate

            email_matches = (
                _booking_normalize_email(
                    candidate[4]
                )
                == normalized_email
            )

            phone_matches = (
                _booking_normalize_phone(
                    candidate[3]
                )
                == normalized_phone
            )

            if email_matches:
                email_match_ids.add(
                    candidate_client_id
                )

            if phone_matches:
                phone_match_ids.add(
                    candidate_client_id
                )


        # Multiple records using the same email or phone
        # cannot be safely matched automatically.
        if (
            len(email_match_ids) > 1
            or len(phone_match_ids) > 1
        ):
            conn.rollback()

            return failure_response(
                "The information provided does not match "
                "our records. Please contact the business "
                "to schedule your appointment.",
                status_code=409,
                service_type_id=service_type_id
            )


        client_was_created = False
        contact_verification_type = None
        matched_client_id = None

        # Email and phone both matched existing records.
        if email_match_ids and phone_match_ids:
            if email_match_ids != phone_match_ids:
                conn.rollback()

                return failure_response(
                    "The information provided does not match "
                    "our records. Please contact the business "
                    "to schedule your appointment.",
                    status_code=409,
                    service_type_id=service_type_id
                )

            matched_client_id = next(
                iter(email_match_ids)
            )

        # Email matched, but phone is different/new.
        elif email_match_ids:
            matched_client_id = next(
                iter(email_match_ids)
            )

            contact_verification_type = (
                "verify_phone"
            )

        # Phone matched, but email is different/new.
        elif phone_match_ids:
            matched_client_id = next(
                iter(phone_match_ids)
            )

            contact_verification_type = (
                "verify_email"
            )


        if matched_client_id is not None:
            client_id = matched_client_id

            # Public booking searches active and archived
            # clients. When an archived client is matched,
            # restore the existing client instead of creating
            # a duplicate record.
            cur.execute("""
                UPDATE clients
                SET active_client = TRUE
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
            """, (
                client_id,
                spa_id,
                business_unit_id
            ))

            matched_client = candidate_by_id[
                client_id
            ]

            existing_first_name = (
                matched_client[1] or ""
            ).strip()

            existing_last_name = (
                matched_client[2] or ""
            ).strip()

            submitted_name = " ".join(
                f"{first_name} {last_name}"
                .strip()
                .lower()
                .split()
            )

            existing_name = " ".join(
                f"{existing_first_name} "
                f"{existing_last_name}"
                .strip()
                .lower()
                .split()
            )

            if submitted_name != existing_name:
                contact_verification_type = (
                    "verify_client_information"
                )

        else:
            # ---------------------------------------------
            # Conservative online-booking contact defaults:
            #
            # Service phone calls: allowed
            # Service email: allowed
            # Service SMS: opted out
            # SMS marketing: opted out
            # Email marketing: not set
            # ---------------------------------------------

            cur.execute("""
                INSERT INTO clients (
                    spa_id,
                    business_unit_id,
                    first_name,
                    last_name,
                    phone,
                    email,
                    active_client,
                    client_status,
                    ok_to_call,
                    ok_to_text,
                    ok_to_email,
                    sms_opt_in,
                    sms_opt_out,
                    email_opt_in,
                    email_opt_out,
                    sms_marketing_status,
                    email_marketing_status
                )
                VALUES (
                    %s, %s, %s, %s, %s,
                    %s,
                    TRUE,
                    'Current',
                    TRUE,
                    FALSE,
                    TRUE,
                    FALSE,
                    TRUE,
                    TRUE,
                    FALSE,
                    'opt_out',
                    'not_set'
                )
                RETURNING client_id
            """, (
                spa_id,
                business_unit_id,
                first_name,
                last_name,
                phone,
                normalized_email
            ))

            client_id = cur.fetchone()[0]
            client_was_created = True


        booked_by_name = (
            f"{first_name} {last_name}"
        ).strip()

        appointment_for = (
            (
                f"{guest_first_name} "
                f"{guest_last_name}"
            ).strip()
            if booking_for_other
            else booked_by_name
        )

        service_recipient_client_id = (
            None
            if booking_for_other
            else client_id
        )


        # -------------------------------------------------
        # Insert using only authoritative values returned
        # by the server-side validator.
        # -------------------------------------------------

        cur.execute("""
            INSERT INTO appointments (
                spa_id,
                business_unit_id,
                client_id,
                service_type_id,
                service_type,
                appointment_for,
                appointment_date,
                appointment_time,
                duration_minutes,
                price_at_booking,
                status,
                notes,
                provider_employee_id,
                provider_name_at_booking,
                booking_channel,
                booking_for_other,
                service_recipient_client_id,
                contact_verification_type,
                booking_contact_name_submitted,
                booking_contact_email_submitted,
                booking_contact_phone_submitted,
                owner_reviewed,
                owner_reviewed_at
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s, %s, %s, %s, %s,
                'booked',
                %s, %s, %s,
                'public_preview',
                %s,
                %s,
                %s, %s, %s, %s,
                FALSE,
                NULL
            )
            RETURNING appointment_id
        """, (
            spa_id,
            business_unit_id,
            client_id,
            validation["service_type_id"],
            validation["service_name"],
            appointment_for,
            validation["appointment_date"],
            validation["appointment_time"],
            validation["duration_minutes"],
            validation["price_at_booking"],
            notes or None,
            validation[
                "provider_employee_id"
            ],
            validation["provider_name"],
            booking_for_other,
            service_recipient_client_id,
            contact_verification_type,
            (
                f"{first_name} {last_name}"
            ).strip()
            if contact_verification_type
            else None,
            normalized_email
            if contact_verification_type
            else None,
            phone
            if contact_verification_type
            else None
        ))

        appointment_id = cur.fetchone()[0]

        conn.commit()


        date_display = (
            validation["appointment_date"]
            .strftime(
                "%A, %B %d, %Y"
            )
            .replace(" 0", " ")
        )

        time_display = (
            validation["appointment_time"]
            .strftime("%I:%M %p")
            .lstrip("0")
        )

        price_display = (
            f"${validation['price_at_booking']:,.2f}"
        )


        return render_template(
            "booking/"
            "public_booking_confirmation.html",
            success=True,
            preview_mode=True,
            appointment_id=appointment_id,
            client_id=client_id,
            client_was_created=
                client_was_created,
            contact_verification_type=
                contact_verification_type,
            client_name=booked_by_name,
            booked_by_name=booked_by_name,
            appointment_for_name=
                appointment_for,
            booking_for_other=
                booking_for_other,
            service_name=
                validation["service_name"],
            provider_name=
                validation["provider_name"],
            date_display=date_display,
            time_display=time_display,
            duration_minutes=
                validation["duration_minutes"],
            price_display=price_display,
            back_url=url_for(
                "booking_public_preview",
                service_type_id=
                    service_type_id
            ),
            calendar_url=url_for(
                "calendar_view"
            )
        )

    except Exception:
        conn.rollback()

        app.logger.exception(
            "Internal public-booking preview "
            "confirmation failed."
        )

        return failure_response(
            "The appointment could not be saved. "
            "No changes were committed.",
            status_code=500,
            service_type_id=service_type_id
        )

    finally:
        cur.close()
        conn.close()






def _booking_get_public_csrf_token(
    public_booking_slug
):
    """
    Return a session-bound token for one public
    booking workspace.
    """
    import secrets

    public_booking_slug = str(
        public_booking_slug or ""
    ).strip().lower()

    token_record = session.get(
        "_public_booking_csrf",
        {}
    )

    if (
        not isinstance(token_record, dict)
        or token_record.get("slug")
            != public_booking_slug
        or not token_record.get("token")
    ):
        token_record = {
            "slug": public_booking_slug,
            "token": secrets.token_urlsafe(32)
        }

        session[
            "_public_booking_csrf"
        ] = token_record

    return token_record["token"]


def _booking_commit_appointment(
    *,
    cur,
    spa_id,
    business_unit_id,
    provider_employee_id,
    service_type_id,
    appointment_start,
    first_name,
    last_name,
    phone,
    normalized_phone,
    normalized_email,
    booking_for_other,
    guest_first_name,
    guest_last_name,
    notes,
    require_public,
    booking_channel
):
    """
    Lock, revalidate, match/create the client, and
    insert the appointment.

    The caller is responsible for commit or rollback.
    """

    def failure(
        message,
        status_code=400
    ):
        return {
            "success": False,
            "message": message,
            "status_code": status_code
        }


    # -----------------------------------------------------
    # Serialize confirmations for this booking workspace.
    # -----------------------------------------------------

    cur.execute("""
        SELECT spa_id
        FROM booking_settings
        WHERE spa_id = %s
          AND business_unit_id = %s
        FOR UPDATE
    """, (
        spa_id,
        business_unit_id
    ))

    if not cur.fetchone():
        return failure(
            "Booking settings were not found "
            "for this workspace."
        )


    # -----------------------------------------------------
    # Revalidate after acquiring the transaction lock.
    # -----------------------------------------------------

    validation = (
        _booking_validate_selected_slot(
            cur=cur,
            spa_id=spa_id,
            business_unit_id=
                business_unit_id,
            provider_employee_id=
                provider_employee_id,
            service_type_id=
                service_type_id,
            appointment_start=
                appointment_start,
            require_public=
                require_public
        )
    )

    if not validation.get("valid"):
        return failure(
            validation.get("reason")
            or (
                "That appointment time "
                "is no longer available."
            ),
            status_code=409
        )


    # -----------------------------------------------------
    # Match an existing client by normalized email or phone.
    # -----------------------------------------------------

    cur.execute("""
    SELECT
        client_id,
        first_name,
        last_name,
        phone,
        email
    FROM clients
    WHERE spa_id = %s
        AND business_unit_id = %s
        AND (
            LOWER(
                TRIM(
                    COALESCE(email, '')
                )
            ) = %s

            OR regexp_replace(
                COALESCE(phone, ''),
                '[^0-9]',
                '',
                'g'
            ) IN (%s, %s)
            )
    ORDER BY client_id
    FOR UPDATE
""", (
    spa_id,
    business_unit_id,
    normalized_email,
    normalized_phone,
    "1" + normalized_phone
))

    candidate_clients = cur.fetchall()

    email_match_ids = set()
    phone_match_ids = set()
    candidate_by_id = {}

    for candidate in candidate_clients:
        candidate_client_id = candidate[0]

        candidate_by_id[
            candidate_client_id
        ] = candidate

        email_matches = (
            _booking_normalize_email(
                candidate[4]
            )
            == normalized_email
        )

        phone_matches = (
            _booking_normalize_phone(
                candidate[3]
            )
            == normalized_phone
        )

        if email_matches:
            email_match_ids.add(
                candidate_client_id
            )

        if phone_matches:
            phone_match_ids.add(
                candidate_client_id
            )


    # Multiple records using the same identifier
    # cannot be safely matched automatically.
    if (
        len(email_match_ids) > 1
        or len(phone_match_ids) > 1
    ):
        return failure(
            "The information provided does not match "
            "our records. Please contact the business "
            "to schedule your appointment.",
            status_code=409
        )


    submitted_booking_name = (
        f"{first_name} {last_name}"
    ).strip()

    client_was_created = False
    contact_verification_type = None
    matched_client_id = None
    booked_by_name = submitted_booking_name

    # Both identifiers matched existing records.
    if email_match_ids and phone_match_ids:
        if email_match_ids != phone_match_ids:
            return failure(
                "The information provided does not match "
                "our records. Please contact the business "
                "to schedule your appointment.",
                status_code=409
            )

        matched_client_id = next(
            iter(email_match_ids)
        )

    # Email matched, but phone is different.
    elif email_match_ids:
        matched_client_id = next(
            iter(email_match_ids)
        )

        contact_verification_type = (
            "verify_phone"
        )

    # Phone matched, but email is different.
    elif phone_match_ids:
        matched_client_id = next(
            iter(phone_match_ids)
        )

        contact_verification_type = (
            "verify_email"
        )


    if matched_client_id is not None:
        client_id = matched_client_id

        # Public online booking searches active and archived
        # clients. Reactivate a matched archived record rather
        # than creating a duplicate client.
        cur.execute("""
            UPDATE clients
            SET active_client = TRUE
            WHERE client_id = %s
              AND spa_id = %s
              AND business_unit_id = %s
        """, (
            client_id,
            spa_id,
            business_unit_id
        ))

        matched_client = candidate_by_id[
            client_id
        ]

        existing_first_name = (
            matched_client[1] or ""
        ).strip()

        existing_last_name = (
            matched_client[2] or ""
        ).strip()

        existing_client_name = (
            f"{existing_first_name} "
            f"{existing_last_name}"
        ).strip()

        if existing_client_name:
            booked_by_name = (
                existing_client_name
            )

        submitted_name_normalized = " ".join(
            submitted_booking_name
            .lower()
            .split()
        )

        existing_name_normalized = " ".join(
            existing_client_name
            .lower()
            .split()
        )

        if (
            submitted_name_normalized
            != existing_name_normalized
        ):
            contact_verification_type = (
                "verify_client_information"
            )

    else:
        # Conservative service-contact defaults.
        # No SMS or marketing consent is assumed.

        cur.execute("""
            INSERT INTO clients (
                spa_id,
                business_unit_id,
                first_name,
                last_name,
                phone,
                email,
                active_client,
                client_status,
                ok_to_call,
                ok_to_text,
                ok_to_email,
                sms_opt_in,
                sms_opt_out,
                email_opt_in,
                email_opt_out,
                sms_marketing_status,
                email_marketing_status
            )
            VALUES (
                %s, %s, %s, %s, %s,
                %s,
                TRUE,
                'Current',
                TRUE,
                FALSE,
                TRUE,
                FALSE,
                TRUE,
                TRUE,
                FALSE,
                'opt_out',
                'not_set'
            )
            RETURNING client_id
        """, (
            spa_id,
            business_unit_id,
            first_name,
            last_name,
            phone,
            normalized_email
        ))

        client_id = cur.fetchone()[0]
        client_was_created = True






    # Keep the existing client name when a client was matched.
    # Use the submitted name only when the name itself needs review.
    appointment_for = (
        (
            f"{guest_first_name} "
            f"{guest_last_name}"
        ).strip()
        if booking_for_other
        else (
            submitted_booking_name
            if contact_verification_type
                == "verify_client_information"
            else booked_by_name
        )
    )

    service_recipient_client_id = (
        None
        if booking_for_other
        else client_id
    )


    # -----------------------------------------------------
    # Insert only server-authoritative appointment values.
    # -----------------------------------------------------

    cur.execute("""
        INSERT INTO appointments (
            spa_id,
            business_unit_id,
            client_id,
            service_type_id,
            service_type,
            appointment_for,
            appointment_date,
            appointment_time,
            duration_minutes,
            price_at_booking,
            status,
            notes,
            provider_employee_id,
            provider_name_at_booking,
            booking_channel,
            booking_for_other,
            service_recipient_client_id,
            contact_verification_type,
            booking_contact_name_submitted,
            booking_contact_email_submitted,
            booking_contact_phone_submitted,
            owner_reviewed,
            owner_reviewed_at
        )
        VALUES (
            %s, %s, %s, %s, %s,
            %s, %s, %s, %s, %s,
            'booked',
            %s, %s, %s, %s,
            %s, %s,
            %s, %s, %s, %s,
            FALSE,
            NULL
        )
        RETURNING appointment_id
    """, (
        spa_id,
        business_unit_id,
        client_id,
        validation["service_type_id"],
        validation["service_name"],
        appointment_for,
        validation["appointment_date"],
        validation["appointment_time"],
        validation["duration_minutes"],
        validation["price_at_booking"],
        notes or None,
        validation["provider_employee_id"],
        validation["provider_name"],
        booking_channel,
        booking_for_other,
        service_recipient_client_id,
        contact_verification_type,
        submitted_booking_name
        if contact_verification_type
        else None,
        normalized_email
        if contact_verification_type
        else None,
        phone
        if contact_verification_type
        else None
    ))

    appointment_id = cur.fetchone()[0]

    return {
        "success": True,
        "appointment_id": appointment_id,
        "client_id": client_id,
        "client_was_created":
            client_was_created,
        "client_name": booked_by_name,
        "booked_by_name": booked_by_name,
        "appointment_for_name":
            appointment_for,
        "booking_for_other":
            booking_for_other,
        "service_recipient_client_id":
            service_recipient_client_id,
        "contact_verification_type":
            contact_verification_type,
        "validation": validation
    }


def _booking_build_public_availability(
    cur,
    spa_id,
    business_unit_id,
    service_type_id,
    selected_provider_id,
    selected_date
):
    """
    Build public-booking availability using the same
    operating-hour, provider-hour, buffer, time-off,
    appointment, notice, and booking-window rules used
    by the internal availability engine.
    """
    from datetime import datetime, timedelta

    def format_windows(windows):
        displays = []

        for window_start, window_end in windows:
            start_display = (
                window_start
                .strftime("%I:%M %p")
                .lstrip("0")
            )

            end_display = (
                window_end
                .strftime("%I:%M %p")
                .lstrip("0")
            )

            displays.append(
                f"{start_display}–{end_display}"
            )

        return ", ".join(displays)

    def result(
        *,
        results=None,
        message="",
        provider_id="any",
        date_display="",
        business_hours_display=""
    ):
        results = list(results or [])

        return {
            "availability_searched": True,
            "availability_results": results,
            "total_slot_count": sum(
                len(item.get("slots", []))
                for item in results
            ),
            "availability_message": message,
            "selected_provider_id": provider_id,
            "date_display": date_display,
            "business_hours_display":
                business_hours_display
        }


    try:
        spa_id = int(spa_id)
        business_unit_id = int(
            business_unit_id
        )
        service_type_id = int(
            service_type_id
        )
    except (TypeError, ValueError):
        return result(
            message="The selected service is invalid."
        )


    if isinstance(selected_date, str):
        try:
            selected_date = (
                datetime.strptime(
                    selected_date,
                    "%Y-%m-%d"
                ).date()
            )
        except ValueError:
            return result(
                message="Please select a valid date."
            )


    if selected_date is None:
        return result(
            message="Please select a date."
        )


    selected_provider_value = str(
        selected_provider_id or "any"
    ).strip().lower()


    # =====================================================
    # Booking settings
    # =====================================================

    cur.execute("""
        SELECT
            slot_interval_minutes,
            minimum_booking_notice_hours,
            maximum_booking_days_ahead,
            default_buffer_before_minutes,
            default_buffer_after_minutes,
            allow_any_provider,
            public_booking_enabled
        FROM booking_settings
        WHERE spa_id = %s
          AND business_unit_id = %s
    """, (
        spa_id,
        business_unit_id
    ))

    settings_row = cur.fetchone()

    if not settings_row:
        return result(
            message="Booking settings were not found."
        )


    slot_interval_minutes = max(
        int(settings_row[0] or 15),
        1
    )

    minimum_notice_hours = max(
        int(settings_row[1] or 0),
        0
    )

    maximum_days_ahead = max(
        int(settings_row[2] or 90),
        0
    )

    default_buffer_before = max(
        int(settings_row[3] or 0),
        0
    )

    default_buffer_after = max(
        int(settings_row[4] or 0),
        0
    )

    allow_any_provider = bool(
        settings_row[5]
    )

    public_booking_enabled = bool(
        settings_row[6]
    )


    if not public_booking_enabled:
        return result(
            message=(
                "Online booking is not currently enabled."
            )
        )


    local_now = get_spa_now(
        spa_id
    ).replace(tzinfo=None)

    earliest_allowed_start = (
        local_now
        + timedelta(
            hours=minimum_notice_hours
        )
    )

    latest_allowed_date = (
        local_now.date()
        + timedelta(
            days=maximum_days_ahead
        )
    )


    if (
        selected_date < local_now.date()
        or selected_date > latest_allowed_date
    ):
        return result(
            message=(
                "The selected date is outside "
                "the available booking range."
            )
        )


    date_display = (
        selected_date
        .strftime("%A, %B %d, %Y")
        .replace(" 0", " ")
    )


    if (
        selected_provider_value == "any"
        and not allow_any_provider
    ):
        return result(
            message="Please select a provider.",
            date_display=date_display
        )


    normalized_provider_id = "any"

    if selected_provider_value != "any":
        try:
            normalized_provider_id = int(
                selected_provider_value
            )
        except (TypeError, ValueError):
            return result(
                message=(
                    "The selected provider is invalid."
                ),
                date_display=date_display
            )


    # =====================================================
    # Public provider-service assignments
    # =====================================================

    assignment_sql = """
        SELECT
            e.employee_id,

            COALESCE(
                NULLIF(
                    TRIM(e.employee_nickname),
                    ''
                ),
                NULLIF(
                    TRIM(
                        CONCAT_WS(
                            ' ',
                            e.first_name,
                            e.last_name
                        )
                    ),
                    ''
                ),
                'Provider ' ||
                    e.employee_id::TEXT
            ) AS provider_name,

            COALESCE(
                pst.duration_override_minutes,
                snt.default_duration_minutes
            ) AS duration_minutes,

            COALESCE(
                pst.price_override,
                snt.default_price
            ) AS price_at_booking,

            COALESCE(
                pst.buffer_before_minutes,
                %s,
                0
            ) AS buffer_before_minutes,

            COALESCE(
                pst.buffer_after_minutes,
                %s,
                0
            ) AS buffer_after_minutes

        FROM provider_service_types pst

        JOIN employees e
          ON e.employee_id =
                pst.provider_employee_id
         AND e.spa_id = pst.spa_id

        JOIN service_name_types snt
          ON snt.service_type_id =
                pst.service_type_id
         AND snt.spa_id = pst.spa_id

        WHERE pst.spa_id = %s
          AND pst.business_unit_id = %s
          AND pst.service_type_id = %s
          AND pst.is_active = TRUE
          AND pst.is_publicly_bookable = TRUE
          AND e.is_active = TRUE
          AND snt.is_active = TRUE
    """

    assignment_params = [
        default_buffer_before,
        default_buffer_after,
        spa_id,
        business_unit_id,
        service_type_id
    ]


    if normalized_provider_id != "any":
        assignment_sql += """
          AND e.employee_id = %s
        """

        assignment_params.append(
            normalized_provider_id
        )


    assignment_sql += """
        ORDER BY provider_name
    """


    cur.execute(
        assignment_sql,
        tuple(assignment_params)
    )

    assignments = []

    for row in cur.fetchall():
        duration_minutes = int(
            row[2] or 0
        )

        if duration_minutes <= 0:
            continue

        assignments.append({
            "provider_employee_id": row[0],
            "provider_name": row[1],
            "duration_minutes":
                duration_minutes,
            "price_at_booking": row[3],
            "buffer_before_minutes": max(
                int(row[4] or 0),
                0
            ),
            "buffer_after_minutes": max(
                int(row[5] or 0),
                0
            )
        })


    if not assignments:
        return result(
            message=(
                "No eligible provider is currently "
                "available for this service."
            ),
            provider_id=normalized_provider_id,
            date_display=date_display,
            business_hours_display="Closed"
        )


    provider_ids = [
        assignment["provider_employee_id"]
        for assignment in assignments
    ]

    day_of_week = selected_date.isoweekday()

    day_start = datetime.combine(
        selected_date,
        datetime.min.time()
    )

    day_end = (
        day_start
        + timedelta(days=1)
    )


    # =====================================================
    # Business hours
    # =====================================================

    cur.execute("""
        SELECT
            start_time,
            end_time
        FROM booking_business_hours
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND day_of_week = %s
          AND is_active = TRUE
        ORDER BY start_time
    """, (
        spa_id,
        business_unit_id,
        day_of_week
    ))

    business_windows = []

    for row in cur.fetchall():
        window_start = datetime.combine(
            selected_date,
            row[0]
        )

        window_end = datetime.combine(
            selected_date,
            row[1]
        )

        if window_end > window_start:
            business_windows.append(
                (
                    window_start,
                    window_end
                )
            )


    if not business_windows:
        return result(
            results=[
                {
                    "provider_employee_id":
                        assignment[
                            "provider_employee_id"
                        ],
                    "provider_name":
                        assignment["provider_name"],
                    "slots": [],
                    "availability_summary_reason":
                        (
                            "The business is closed "
                            "on this date."
                        )
                }
                for assignment in assignments
            ],
            provider_id=normalized_provider_id,
            date_display=date_display
        )


    # =====================================================
    # Provider working hours
    # =====================================================

    cur.execute("""
        SELECT
            provider_employee_id,
            start_time,
            end_time
        FROM provider_booking_hours
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND day_of_week = %s
          AND is_active = TRUE
          AND provider_employee_id =
                ANY(%s)
        ORDER BY
            provider_employee_id,
            start_time
    """, (
        spa_id,
        business_unit_id,
        day_of_week,
        provider_ids
    ))

    provider_windows = {
        provider_id: []
        for provider_id in provider_ids
    }

    for row in cur.fetchall():
        window_start = datetime.combine(
            selected_date,
            row[1]
        )

        window_end = datetime.combine(
            selected_date,
            row[2]
        )

        if window_end > window_start:
            provider_windows.setdefault(
                row[0],
                []
            ).append(
                (
                    window_start,
                    window_end
                )
            )


    # =====================================================
    # Provider time off
    # =====================================================

    cur.execute("""
        SELECT
            provider_employee_id,
            starts_at,
            ends_at
        FROM provider_time_off
        WHERE spa_id = %s
          AND business_unit_id = %s
          AND provider_employee_id =
                ANY(%s)
          AND is_active = TRUE
          AND starts_at < %s
          AND ends_at > %s
        ORDER BY starts_at
    """, (
        spa_id,
        business_unit_id,
        provider_ids,
        day_end,
        day_start
    ))

    provider_time_off = {
        provider_id: []
        for provider_id in provider_ids
    }

    for row in cur.fetchall():
        provider_time_off.setdefault(
            row[0],
            []
        ).append(
            (
                row[1],
                row[2]
            )
        )


    # =====================================================
    # Provider aliases used by legacy appointments
    # =====================================================

    cur.execute("""
        SELECT DISTINCT
            e.employee_id,
            e.employee_nickname,
            e.first_name,
            e.last_name
        FROM provider_service_types pst

        JOIN employees e
          ON e.employee_id =
                pst.provider_employee_id
         AND e.spa_id = pst.spa_id

        WHERE pst.spa_id = %s
          AND pst.business_unit_id = %s
          AND pst.is_active = TRUE
          AND e.is_active = TRUE
    """, (
        spa_id,
        business_unit_id
    ))

    alias_to_provider_ids = {}

    for row in cur.fetchall():
        employee_id = row[0]

        aliases = {
            _booking_normalize_name(row[1]),
            _booking_normalize_name(row[2]),
            _booking_normalize_name(
                " ".join(
                    value
                    for value in (
                        row[2],
                        row[3]
                    )
                    if value
                )
            )
        }

        for alias in aliases:
            if not alias:
                continue

            alias_to_provider_ids.setdefault(
                alias,
                set()
            ).add(employee_id)


    # =====================================================
    # Existing appointment blocks
    # =====================================================

    cur.execute("""
        SELECT
            a.appointment_time,

            COALESCE(
                NULLIF(
                    a.duration_minutes,
                    0
                ),
                snt.default_duration_minutes,
                60
            ) AS duration_minutes,

            a.provider_employee_id,
            a.provider_name_at_booking,

            COALESCE(
                pst.buffer_before_minutes,
                %s,
                0
            ) AS buffer_before_minutes,

            COALESCE(
                pst.buffer_after_minutes,
                %s,
                0
            ) AS buffer_after_minutes

        FROM appointments a

        LEFT JOIN service_name_types snt
          ON snt.service_type_id =
                a.service_type_id
         AND snt.spa_id = a.spa_id

        LEFT JOIN provider_service_types pst
          ON pst.spa_id = a.spa_id
         AND pst.business_unit_id =
                a.business_unit_id
         AND pst.provider_employee_id =
                a.provider_employee_id
         AND pst.service_type_id =
                a.service_type_id
         AND pst.is_active = TRUE

        WHERE a.spa_id = %s
          AND a.business_unit_id = %s
          AND a.appointment_date = %s

          AND LOWER(
                TRIM(
                    COALESCE(
                        a.status,
                        ''
                    )
                )
              ) NOT IN (
                'cancelled',
                'canceled',
                'completed',
                'no show',
                'no-show',
                're-scheduled',
                'rescheduled'
              )

        ORDER BY a.appointment_time
    """, (
        default_buffer_before,
        default_buffer_after,
        spa_id,
        business_unit_id,
        selected_date
    ))

    appointment_blocks = {
        provider_id: []
        for provider_id in provider_ids
    }

    selected_provider_ids = set(
        provider_ids
    )

    generic_provider_names = {
        "",
        "any",
        "any available",
        "any provider",
        "no preference",
        "unassigned"
    }


    for row in cur.fetchall():
        if row[0] is None:
            continue

        existing_start = datetime.combine(
            selected_date,
            row[0]
        )

        existing_end = (
            existing_start
            + timedelta(
                minutes=int(row[1] or 60)
            )
        )

        existing_block_start = (
            existing_start
            - timedelta(
                minutes=int(row[4] or 0)
            )
        )

        existing_block_end = (
            existing_end
            + timedelta(
                minutes=int(row[5] or 0)
            )
        )


        target_provider_ids = set()

        if row[2] is not None:
            if row[2] in selected_provider_ids:
                target_provider_ids.add(
                    row[2]
                )

        else:
            normalized_name = (
                _booking_normalize_name(
                    row[3]
                )
            )

            matched_ids = (
                alias_to_provider_ids.get(
                    normalized_name,
                    set()
                )
            )

            if (
                normalized_name
                in generic_provider_names
            ):
                target_provider_ids = set(
                    selected_provider_ids
                )

            elif len(matched_ids) == 1:
                target_provider_ids = (
                    matched_ids
                    & selected_provider_ids
                )

            else:
                target_provider_ids = set(
                    selected_provider_ids
                )


        for provider_id in target_provider_ids:
            appointment_blocks.setdefault(
                provider_id,
                []
            ).append(
                (
                    existing_block_start,
                    existing_block_end
                )
            )


    # =====================================================
    # Build available slots
    # =====================================================

    def round_up_to_interval(value):
        midnight = datetime.combine(
            value.date(),
            datetime.min.time()
        )

        elapsed_minutes = int(
            (value - midnight)
            .total_seconds()
            // 60
        )

        if value.second or value.microsecond:
            elapsed_minutes += 1

        rounded_minutes = (
            (
                elapsed_minutes
                + slot_interval_minutes
                - 1
            )
            // slot_interval_minutes
            * slot_interval_minutes
        )

        return (
            midnight
            + timedelta(
                minutes=rounded_minutes
            )
        )


    availability_results = []


    for assignment in assignments:
        provider_id = assignment[
            "provider_employee_id"
        ]

        duration_minutes = assignment[
            "duration_minutes"
        ]

        buffer_before = assignment[
            "buffer_before_minutes"
        ]

        buffer_after = assignment[
            "buffer_after_minutes"
        ]

        working_windows = []

        for (
            business_start,
            business_end
        ) in business_windows:

            for (
                provider_start,
                provider_end
            ) in provider_windows.get(
                provider_id,
                []
            ):
                working_start = max(
                    business_start,
                    provider_start
                )

                working_end = min(
                    business_end,
                    provider_end
                )

                if working_start < working_end:
                    working_windows.append(
                        (
                            working_start,
                            working_end
                        )
                    )


        slots_by_value = {}


        for (
            working_start,
            working_end
        ) in working_windows:

            earliest_service_start = (
                working_start
                + timedelta(
                    minutes=buffer_before
                )
            )

            earliest_service_start = max(
                earliest_service_start,
                earliest_allowed_start
            )

            latest_service_start = (
                working_end
                - timedelta(
                    minutes=(
                        duration_minutes
                        + buffer_after
                    )
                )
            )

            candidate_start = (
                round_up_to_interval(
                    earliest_service_start
                )
            )


            while (
                candidate_start
                <= latest_service_start
            ):
                service_end = (
                    candidate_start
                    + timedelta(
                        minutes=duration_minutes
                    )
                )

                candidate_block_start = (
                    candidate_start
                    - timedelta(
                        minutes=buffer_before
                    )
                )

                candidate_block_end = (
                    service_end
                    + timedelta(
                        minutes=buffer_after
                    )
                )


                blocked = any(
                    _booking_intervals_overlap(
                        candidate_block_start,
                        candidate_block_end,
                        blocked_start,
                        blocked_end
                    )
                    for (
                        blocked_start,
                        blocked_end
                    ) in provider_time_off.get(
                        provider_id,
                        []
                    )
                )


                if not blocked:
                    blocked = any(
                        _booking_intervals_overlap(
                            candidate_block_start,
                            candidate_block_end,
                            blocked_start,
                            blocked_end
                        )
                        for (
                            blocked_start,
                            blocked_end
                        ) in appointment_blocks.get(
                            provider_id,
                            []
                        )
                    )


                if not blocked:
                    slot_value = (
                        candidate_start.isoformat(
                            timespec="minutes"
                        )
                    )

                    slots_by_value[
                        slot_value
                    ] = {
                        "value": slot_value,
                        "display": (
                            candidate_start
                            .strftime("%I:%M %p")
                            .lstrip("0")
                        )
                    }


                candidate_start += timedelta(
                    minutes=slot_interval_minutes
                )


        slots = [
            slots_by_value[key]
            for key in sorted(
                slots_by_value
            )
        ]


        if not provider_windows.get(
            provider_id
        ):
            summary_reason = (
                "This provider is not working "
                "on the selected date."
            )

        elif not working_windows:
            summary_reason = (
                "This provider has no working hours "
                "within business hours on this date."
            )

        elif not slots:
            if provider_time_off.get(provider_id):
                summary_reason = (
                    "This provider is unavailable "
                    "on the selected date."
                )
            else:
                summary_reason = (
                    "No available times remain for "
                    "this provider on the selected date."
                )

        else:
            summary_reason = ""


        availability_results.append({
            "provider_employee_id":
                provider_id,
            "provider_name":
                assignment["provider_name"],
            "slots": slots,

            "has_provider_time_off": bool(
                provider_time_off.get(provider_id)
            ),

            "provider_hours_display": (
                format_windows(
                    provider_windows.get(
                        provider_id,
                        []
                    )
                )
                or "Not scheduled"
            ),

            "availability_summary_reason":
                summary_reason
        })


    return result(
        results=availability_results,
        provider_id=normalized_provider_id,
        date_display=date_display,
        business_hours_display=
            format_windows(business_windows)
    )


def _render_public_booking_page(
    public_booking_slug,
    preview_mode=False,
    availability_context=None
):
    from datetime import datetime, timedelta

    availability_context = dict(
        availability_context or {}
    )

    public_booking_slug = str(
        public_booking_slug or ""
    ).strip().lower()

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT
                bs.spa_id,
                bs.business_unit_id,
                bs.public_booking_enabled,

                s.spa_name,
                bu.unit_name,

                s.business_address_line1,
                s.business_address_line2,
                s.city,
                s.state,
                s.zip_code,

                bs.minimum_booking_notice_hours,
                bs.maximum_booking_days_ahead,
                bs.allow_any_provider

            FROM booking_settings bs

            JOIN business_units bu
              ON bu.business_unit_id =
                    bs.business_unit_id
             AND bu.spa_id = bs.spa_id

            JOIN spas s
              ON s.spa_id = bs.spa_id

            WHERE bs.public_booking_slug = %s
              AND bu.is_active = TRUE
              AND s.active = TRUE

            LIMIT 1
        """, (public_booking_slug,))

        booking_row = cur.fetchone()

        if not booking_row:
            return render_template(
                "booking/public_booking.html",
                booking_not_found=True,
                booking_disabled=False,
                preview_mode=False,
                business_name="Online Booking",
                organization_name="",
                business_address="",
                services=[],
                website_color_scheme="peach_cream",
                include_marketing_sms_consent=False
            ), 404

        spa_id = booking_row[0]
        business_unit_id = booking_row[1]
        public_booking_enabled = bool(
            booking_row[2]
        )

        spa_name = str(
            booking_row[3] or ""
        ).strip()

        unit_name = str(
            booking_row[4] or ""
        ).strip()

        business_name = (
            unit_name
            or spa_name
            or "Online Booking"
        )

        website_color_scheme = "peach_cream"
        include_marketing_sms_consent = False

        cur.execute("""
            SELECT
                website_color_scheme,
                include_marketing_sms_in_10dlc_application
            FROM public_website_settings
            WHERE spa_id = %s
              AND business_unit_id = %s
        """, (
            spa_id,
            business_unit_id,
        ))

        website_setting_row = cur.fetchone()

        if website_setting_row:
            website_color_scheme = str(
                website_setting_row[0]
                or "peach_cream"
            ).strip().lower()

            include_marketing_sms_consent = bool(
                website_setting_row[1]
            )

        organization_name = ""

        if (
            spa_name
            and unit_name
            and spa_name != unit_name
        ):
            organization_name = spa_name

        address_lines = []

        for address_value in (
            booking_row[5],
            booking_row[6]
        ):
            address_value = str(
                address_value or ""
            ).strip()

            if address_value:
                address_lines.append(
                    address_value
                )

        city_state_zip = ", ".join(
            value
            for value in (
                str(booking_row[7] or "").strip(),
                str(booking_row[8] or "").strip()
            )
            if value
        )

        zip_code = str(
            booking_row[9] or ""
        ).strip()

        if city_state_zip and zip_code:
            city_state_zip += f" {zip_code}"

        elif zip_code:
            city_state_zip = zip_code

        if city_state_zip:
            address_lines.append(
                city_state_zip
            )

        business_address = " • ".join(
            address_lines
        )

        booking_disabled = (
            not public_booking_enabled
        )

        minimum_booking_notice_hours = int(
            booking_row[10] or 0
        )

        maximum_booking_days_ahead = int(
            booking_row[11] or 90
        )

        allow_any_provider = bool(
            booking_row[12]
        )

        local_now = get_spa_now(
            spa_id
        ).replace(tzinfo=None)

        minimum_date = (
            local_now.date().isoformat()
        )

        maximum_date = (
            local_now.date()
            + timedelta(
                days=maximum_booking_days_ahead
            )
        ).isoformat()

        services = []

        if public_booking_enabled or preview_mode:
            service_sql = """
                SELECT
                    snt.service_type_id,
                    snt.service_name,

                    MIN(
                        COALESCE(
                            pst.duration_override_minutes,
                            snt.default_duration_minutes
                        )
                    ) AS duration_minutes,

                    MIN(
                        COALESCE(
                            pst.price_override,
                            snt.default_price
                        )
                    ) AS service_price,

                    COUNT(
                        DISTINCT
                        pst.provider_employee_id
                    ) AS provider_count,

                    BOOL_OR(
                        COALESCE(
                            pst.is_publicly_bookable,
                            FALSE
                        )
                    ) AS publicly_bookable

                FROM provider_service_types pst

                JOIN service_name_types snt
                  ON snt.service_type_id =
                        pst.service_type_id
                 AND snt.spa_id = pst.spa_id

                JOIN employees e
                  ON e.employee_id =
                        pst.provider_employee_id
                 AND e.spa_id = pst.spa_id

                WHERE pst.spa_id = %s
                  AND pst.business_unit_id = %s
                  AND pst.is_active = TRUE
                  AND snt.is_active = TRUE
                  AND e.is_active = TRUE
            """

            service_params = [
                spa_id,
                business_unit_id
            ]

            if not preview_mode:
                service_sql += """
                  AND pst.is_publicly_bookable = TRUE
                """

            service_sql += """
                GROUP BY
                    snt.service_type_id,
                    snt.service_name

                ORDER BY
                    snt.service_name
            """

            cur.execute(
                service_sql,
                tuple(service_params)
            )

            for row in cur.fetchall():
                service_price = row[3]

                price_display = ""

                if service_price is not None:
                    price_display = (
                        f"${service_price:,.2f}"
                    )

                services.append({
                    "service_type_id": row[0],
                    "service_name": row[1],

                    "duration_minutes":
                        int(row[2] or 0),

                    "price_display":
                        price_display,

                    "provider_count":
                        int(row[4] or 0),

                    "publicly_bookable":
                        bool(row[5])
                })

        selected_service_id = (
            availability_context.get(
                "selected_service_id"
            )
        )

        if selected_service_id in (
            None,
            ""
        ):
            selected_service_raw = (
                request.args.get(
                    "service_type_id",
                    ""
                ).strip()
            )

            if selected_service_raw:
                try:
                    selected_service_id = int(
                        selected_service_raw
                    )
                except (TypeError, ValueError):
                    selected_service_id = None

        selected_service = next(
            (
                service
                for service in services
                if service[
                    "service_type_id"
                ] == selected_service_id
            ),
            None
        )

        eligible_providers = []

        if selected_service:
            provider_sql = """
                SELECT DISTINCT
                    e.employee_id,

                    COALESCE(
                        NULLIF(
                            TRIM(
                                e.employee_nickname
                            ),
                            ''
                        ),
                        NULLIF(
                            TRIM(
                                CONCAT_WS(
                                    ' ',
                                    e.first_name,
                                    e.last_name
                                )
                            ),
                            ''
                        ),
                        'Provider ' ||
                            e.employee_id::TEXT
                    ) AS provider_name

                FROM provider_service_types pst

                JOIN employees e
                  ON e.employee_id =
                        pst.provider_employee_id
                 AND e.spa_id = pst.spa_id

                WHERE pst.spa_id = %s
                  AND pst.business_unit_id = %s
                  AND pst.service_type_id = %s
                  AND pst.is_active = TRUE
                  AND e.is_active = TRUE
            """

            provider_params = [
                spa_id,
                business_unit_id,
                selected_service_id
            ]

            if not preview_mode:
                provider_sql += """
                  AND pst.is_publicly_bookable = TRUE
                """

            provider_sql += """
                ORDER BY
                    provider_name
            """

            cur.execute(
                provider_sql,
                tuple(provider_params)
            )

            eligible_providers = [
                {
                    "employee_id": row[0],
                    "provider_name": row[1]
                }
                for row in cur.fetchall()
            ]

        selected_provider_id = (
            availability_context.get(
                "selected_provider_id",
                request.args.get(
                    "provider_employee_id",
                    "any"
                )
            )
        )

        selected_date = (
            availability_context.get(
                "selected_date",
                request.args.get(
                    "booking_date",
                    ""
                )
            )
        )

        availability_searched = bool(
            availability_context.get(
                "availability_searched",
                False
            )
        )

        availability_results = list(
            availability_context.get(
                "availability_results",
                []
            )
        )

        total_slot_count = int(
            availability_context.get(
                "total_slot_count",
                0
            )
        )

        selected_service_name = str(
            availability_context.get(
                "selected_service_name",
                (
                    selected_service[
                        "service_name"
                    ]
                    if selected_service
                    else ""
                )
            )
            or ""
        )

        date_display = str(
            availability_context.get(
                "date_display",
                ""
            )
            or ""
        )

        business_hours_display = str(
            availability_context.get(
                "business_hours_display",
                ""
            )
            or ""
        )


        availability_message = str(
            availability_context.get(
                "availability_message",
                ""
            )
            or ""
        )

        coach_booking_advice = None


        # Real public GET availability search.
        #
        # Preview mode continues using the existing
        # authenticated availability-test route.
        if (
            not preview_mode
            and public_booking_enabled
            and selected_service
            and selected_date
        ):
            public_availability = (
                _booking_build_public_availability(
                    cur=cur,
                    spa_id=spa_id,
                    business_unit_id=
                        business_unit_id,
                    service_type_id=
                        selected_service_id,
                    selected_provider_id=
                        selected_provider_id,
                    selected_date=
                        selected_date
                )
            )

            availability_searched = bool(
                public_availability[
                    "availability_searched"
                ]
            )

            availability_results = list(
                public_availability[
                    "availability_results"
                ]
            )

            total_slot_count = int(
                public_availability[
                    "total_slot_count"
                ]
            )

            availability_message = str(
                public_availability[
                    "availability_message"
                ]
                or ""
            )

            selected_provider_id = (
                public_availability[
                    "selected_provider_id"
                ]
            )

            date_display = str(
                public_availability[
                    "date_display"
                ]
                or ""
            )

            business_hours_display = str(
                public_availability.get(
                    "business_hours_display",
                    ""
                )
                or ""
            )

            def first_coach_option(
                availability_data
            ):
                earliest_option = None

                for provider_result in (
                    availability_data.get(
                        "availability_results",
                        []
                    )
                ):
                    provider_slots = list(
                        provider_result.get(
                            "slots",
                            []
                        )
                    )

                    if not provider_slots:
                        continue

                    first_slot = provider_slots[0]

                    coach_option = {
                        "slot_value":
                            first_slot.get("value", ""),

                        "slot_display":
                            first_slot.get("display", ""),

                        "provider_id":
                            provider_result.get(
                                "provider_employee_id"
                            ),

                        "provider_name":
                            str(
                                provider_result.get(
                                    "provider_name",
                                    "Provider"
                                )
                                or "Provider"
                            ),

                        "date_display":
                            str(
                                availability_data.get(
                                    "date_display",
                                    ""
                                )
                                or ""
                            )
                    }

                    if (
                        earliest_option is None
                        or coach_option["slot_value"]
                        < earliest_option["slot_value"]
                    ):
                        earliest_option = coach_option

                return earliest_option


            earliest_coach_option = (
                first_coach_option(
                    public_availability
                )
            )


            if earliest_coach_option:
                coach_booking_advice = {
                    "title": "Next Available Time",

                    "message": (
                        f"{earliest_coach_option['provider_name']}'s "
                        f"next available time for "
                        f"{selected_service_name} on "
                        f"{date_display} is "
                        f"{earliest_coach_option['slot_display']}."
                    ),

                    "options": [
                        earliest_coach_option
                    ]
                }

            else:
                try:
                    selected_date_value = (
                        selected_date
                        if not isinstance(
                            selected_date,
                            str
                        )
                        else datetime.strptime(
                            selected_date,
                            "%Y-%m-%d"
                        ).date()
                    )
                except (TypeError, ValueError):
                    selected_date_value = None

                nearby_options = []

                if selected_date_value is not None:
                    earliest_search_date = (
                        local_now.date()
                    )

                    latest_search_date = (
                        local_now.date()
                        + timedelta(
                            days=(
                                maximum_booking_days_ahead
                            )
                        )
                    )

                    earlier_date = (
                        selected_date_value
                        - timedelta(days=1)
                    )

                    while (
                        earlier_date
                        >= earliest_search_date
                    ):
                        earlier_availability = (
                            _booking_build_public_availability(
                                cur=cur,
                                spa_id=spa_id,
                                business_unit_id=
                                    business_unit_id,
                                service_type_id=
                                    selected_service_id,
                                selected_provider_id=
                                    selected_provider_id,
                                selected_date=
                                    earlier_date
                            )
                        )

                        earlier_option = (
                            first_coach_option(
                                earlier_availability
                            )
                        )

                        if earlier_option:
                            nearby_options.append(
                                earlier_option
                            )
                            break

                        earlier_date -= timedelta(
                            days=1
                        )

                    later_date = (
                        selected_date_value
                        + timedelta(days=1)
                    )

                    while (
                        later_date
                        <= latest_search_date
                    ):
                        later_availability = (
                            _booking_build_public_availability(
                                cur=cur,
                                spa_id=spa_id,
                                business_unit_id=
                                    business_unit_id,
                                service_type_id=
                                    selected_service_id,
                                selected_provider_id=
                                    selected_provider_id,
                                selected_date=
                                    later_date
                            )
                        )

                        later_option = (
                            first_coach_option(
                                later_availability
                            )
                        )

                        if later_option:
                            nearby_options.append(
                                later_option
                            )
                            break

                        later_date += timedelta(
                            days=1
                        )

                nearby_options.sort(
                    key=lambda option: (
                        option.get(
                            "slot_value",
                            ""
                        )
                    )
                )

                if nearby_options:
                    current_reasons = [
                        str(
                            provider_result.get(
                                "availability_summary_reason",
                                ""
                            )
                            or ""
                        )
                        for provider_result
                        in availability_results
                    ]

                    business_closed = any(
                        "business is closed"
                        in reason.lower()
                        for reason in current_reasons
                    )

                    provider_time_off_results = [
                        provider_result
                        for provider_result
                        in availability_results
                        if provider_result.get(
                            "has_provider_time_off"
                        )
                    ]

                    provider_unavailable = (
                        len(availability_results) == 1
                        and len(
                            provider_time_off_results
                        ) == 1
                    )

                    if business_closed:
                        coach_title = (
                            "Business Closed"
                        )

                        coach_message = (
                            f"The business is closed on "
                            f"{date_display}. Here are the "
                            f"closest available times for "
                            f"{selected_service_name}."
                        )

                    elif provider_unavailable:
                        unavailable_provider_name = str(
                            provider_time_off_results[0]
                            .get(
                                "provider_name",
                                "Provider"
                            )
                            or "Provider"
                        )

                        coach_title = (
                            "Provider Unavailable"
                        )

                        coach_message = (
                            f"{unavailable_provider_name} "
                            f"is unavailable on "
                            f"{date_display}. Here are "
                            f"{unavailable_provider_name}'s "
                            f"closest available times for "
                            f"{selected_service_name}."
                        )

                    else:
                        coach_title = (
                            "Nearby Availability"
                        )

                        coach_message = (
                            f"No times are available on "
                            f"{date_display}. Here are the "
                            f"closest available times for "
                            f"{selected_service_name}."
                        )

                    coach_booking_advice = {
                        "title": coach_title,
                        "message": coach_message,
                        "options": nearby_options
                    }

        minimum_date = (
            availability_context.get(
                "minimum_date",
                minimum_date
            )
        )

        maximum_date = (
            availability_context.get(
                "maximum_date",
                maximum_date
            )
        )

        booking_csrf_token = ""

        if (
            not preview_mode
            and public_booking_enabled
        ):
            booking_csrf_token = (
                _booking_get_public_csrf_token(
                    public_booking_slug
                )
            )


        return render_template(
            "booking/public_booking.html",
            booking_not_found=False,
            booking_disabled=booking_disabled,
            preview_mode=preview_mode,

            public_booking_slug=
                public_booking_slug,

            business_name=business_name,
            organization_name=organization_name,
            business_address=business_address,

            services=services,
            selected_service_id=
                selected_service_id,
            selected_service=
                selected_service,

            eligible_providers=
                eligible_providers,

            allow_any_provider=
                allow_any_provider,

            minimum_booking_notice_hours=
                minimum_booking_notice_hours,

            minimum_date=minimum_date,
            maximum_date=maximum_date,

            selected_provider_id=
                selected_provider_id,
            selected_date=selected_date,

            availability_searched=
                availability_searched,
            availability_results=
                availability_results,
            total_slot_count=
                total_slot_count,

            selected_service_name=
                selected_service_name,
            date_display=date_display,

            business_hours_display=
                business_hours_display,

            availability_message=
                availability_message,

            coach_booking_advice=
                coach_booking_advice,

            website_color_scheme=
                website_color_scheme,

            include_marketing_sms_consent=
                include_marketing_sms_consent,

            booking_csrf_token=
                booking_csrf_token
        )

    finally:
        cur.close()
        conn.close()


def _queue_public_booking_confirmation_email(
    cur,
    spa_id,
    business_unit_id,
    appointment_id,
    client_id,
    recipient_email,
    booked_by_name,
    appointment_for_name,
    booking_for_other,
    service_name,
    provider_name,
    appointment_date,
    appointment_time,
    duration_minutes,
    price_at_booking
):
    """
    Add one public-booking confirmation email to the
    Email Automation Queue.

    The appointment must already be committed before
    this helper is called.
    """

    import re
    from html import escape

    cur.execute("""
        SELECT
            COALESCE(
                NULLIF(TRIM(bu.unit_name), ''),
                NULLIF(TRIM(s.spa_name), ''),
                'Your Appointment Provider'
            ),
            COALESCE(
                NULLIF(
                    TRIM(
                        pws.appointment_contact_email
                    ),
                    ''
                ),
                ''
            ),
            COALESCE(
                NULLIF(
                    TRIM(
                        pws.appointment_contact_phone
                    ),
                    ''
                ),
                ''
            )
        FROM business_units bu

        JOIN spas s
          ON s.spa_id = bu.spa_id

        LEFT JOIN public_website_settings pws
          ON pws.spa_id = s.spa_id

        WHERE bu.spa_id = %s
          AND bu.business_unit_id = %s
        LIMIT 1
    """, (
        spa_id,
        business_unit_id
    ))

    workspace_row = cur.fetchone()

    workspace_name = (
        workspace_row[0]
        if workspace_row and workspace_row[0]
        else "Your Appointment Provider"
    )

    business_email = (
        workspace_row[1]
        if workspace_row and workspace_row[1]
        else ""
    )

    business_phone_raw = (
        workspace_row[2]
        if workspace_row and workspace_row[2]
        else ""
    )

    phone_digits = re.sub(
        r"\D",
        "",
        business_phone_raw
    )

    business_phone_display = (
        business_phone_raw
    )

    business_phone_tel = ""

    if (
        len(phone_digits) == 11
        and phone_digits.startswith("1")
    ):
        local_phone = phone_digits[1:]

        business_phone_display = (
            f"({local_phone[:3]}) "
            f"{local_phone[3:6]}-"
            f"{local_phone[6:]}"
        )

        business_phone_tel = (
            f"+1{local_phone}"
        )

    elif len(phone_digits) == 10:
        business_phone_display = (
            f"({phone_digits[:3]}) "
            f"{phone_digits[3:6]}-"
            f"{phone_digits[6:]}"
        )

        business_phone_tel = (
            f"+1{phone_digits}"
        )

    elif phone_digits:
        business_phone_tel = (
            f"+{phone_digits}"
        )

    date_display = (
        appointment_date
        .strftime("%A, %B %d, %Y")
        .replace(" 0", " ")
    )

    time_display = (
        appointment_time
        .strftime("%I:%M %p")
        .lstrip("0")
    )

    price_display = (
        f"${price_at_booking:,.2f}"
    )

    subject_line = (
        f"Appointment Confirmed — {workspace_name}"
    )

    if booking_for_other:
        appointment_intro = (
            f"Your appointment for "
            f"{appointment_for_name} with "
            f"{workspace_name} is confirmed."
        )

        recipient_details = (
            f"Booked By: {booked_by_name}\n"
            f"Appointment For: "
            f"{appointment_for_name}\n"
        )

    else:
        appointment_intro = (
            f"Your appointment with "
            f"{workspace_name} is confirmed."
        )

        recipient_details = (
            f"Appointment For: "
            f"{appointment_for_name}\n"
        )

    if business_email and business_phone_display:
        assistance_text = (
            f"For assistance with your appointment, "
            f"contact {workspace_name} at "
            f"{business_email} or call "
            f"{business_phone_display}."
        )

    elif business_email:
        assistance_text = (
            f"For assistance with your appointment, "
            f"contact {workspace_name} at "
            f"{business_email}."
        )

    elif business_phone_display:
        assistance_text = (
            f"For assistance with your appointment, "
            f"contact {workspace_name} by calling "
            f"{business_phone_display}."
        )

    else:
        assistance_text = (
            f"For assistance with your appointment, "
            f"contact {workspace_name} directly."
        )

    text_body = (
        f"Hello {booked_by_name},\n\n"
        f"{appointment_intro}\n\n"
        f"Confirmation Number: {appointment_id}\n"
        f"{recipient_details}"
        f"Service: {service_name}\n"
        f"Provider: {provider_name}\n"
        f"Date: {date_display}\n"
        f"Time: {time_display}\n"
        f"Duration: {duration_minutes} minutes\n"
        f"Price: {price_display}\n\n"
        f"Please contact {workspace_name} directly "
        f"if you need to make changes to the "
        f"appointment.\n\n"
        f"We look forward to seeing you!\n\n"
        f"----------------------------------------\n\n"
        f"This email was sent by Peach Suite Pro "
        f"on behalf of {workspace_name} regarding "
        f"your appointment. Please review all "
        f"booking details before taking action.\n\n"
        f"{assistance_text}\n\n"
        f"Peach Suite Pro provides the online "
        f"booking and business-management technology. "
        f"{workspace_name} is responsible for the "
        f"services, appointments, policies, and "
        f"client support."
    )

    safe_workspace_name = escape(
        str(workspace_name or "")
    )

    safe_booked_by_name = escape(
        str(booked_by_name or "")
    )

    safe_appointment_for_name = escape(
        str(appointment_for_name or "")
    )

    safe_service_name = escape(
        str(service_name or "")
    )

    safe_provider_name = escape(
        str(provider_name or "")
    )

    safe_date_display = escape(
        str(date_display or "")
    )

    safe_time_display = escape(
        str(time_display or "")
    )

    safe_price_display = escape(
        str(price_display or "")
    )

    safe_business_email = escape(
        str(business_email or "")
    )

    safe_business_email_attr = escape(
        str(business_email or ""),
        quote=True
    )

    safe_business_phone_display = escape(
        str(business_phone_display or "")
    )

    safe_business_phone_tel = escape(
        str(business_phone_tel or ""),
        quote=True
    )

    recipient_rows = ""

    if booking_for_other:
        recipient_rows = f"""
            <tr>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                    font-weight:600;
                    width:165px;
                ">
                    Booked By
                </td>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                ">
                    {safe_booked_by_name}
                </td>
            </tr>
        """

    recipient_rows += f"""
        <tr>
            <td style="
                padding:8px 12px;
                border-bottom:1px solid #e8e8e8;
                font-weight:600;
                width:165px;
            ">
                Appointment For
            </td>
            <td style="
                padding:8px 12px;
                border-bottom:1px solid #e8e8e8;
            ">
                {safe_appointment_for_name}
            </td>
        </tr>
    """

    if business_email and business_phone_display:
        assistance_html = f"""
            For assistance with your appointment,
            contact {safe_workspace_name} at
            <a
                href="mailto:{safe_business_email_attr}"
                style="color:#555555;"
            >
                {safe_business_email}
            </a>
            or call
            <a href="tel:{safe_business_phone_tel}" style="color:#555555;">{safe_business_phone_display}</a>.
        """

    elif business_email:
        assistance_html = f"""
            For assistance with your appointment,
            contact {safe_workspace_name} at
            <a
                href="mailto:{safe_business_email_attr}"
                style="color:#555555;"
            >
                {safe_business_email}
            </a>.
        """

    elif business_phone_display:
        assistance_html = f"""
            For assistance with your appointment,
            contact {safe_workspace_name} by calling
            <a
                href="tel:{safe_business_phone_tel}"
                style="color:#555555;"
            >
                {safe_business_phone_display}
            </a>.
        """

    else:
        assistance_html = f"""
            For assistance with your appointment,
            contact {safe_workspace_name} directly.
        """

    html_body = f"""
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8">
    <meta
        name="viewport"
        content="width=device-width, initial-scale=1"
    >
    <title>{escape(subject_line)}</title>
</head>

<body style="
    margin:0;
    padding:24px 12px;
    background:#f6f6f6;
    font-family:Arial, Helvetica, sans-serif;
    color:#333333;
">
    <div style="
        max-width:640px;
        margin:0 auto;
        padding:28px;
        background:#ffffff;
        border:1px solid #e7e7e7;
        border-radius:12px;
    ">
        <h1 style="
            margin:0 0 18px;
            font-size:26px;
            line-height:1.25;
            color:#222222;
        ">
            Appointment Confirmed
        </h1>

        <p style="
            margin:0 0 14px;
            font-size:16px;
            line-height:1.6;
        ">
            Hello {safe_booked_by_name},
        </p>

        <p style="
            margin:0 0 22px;
            font-size:16px;
            line-height:1.6;
        ">
            {escape(appointment_intro)}
        </p>

        <table
            role="presentation"
            style="
                width:100%;
                border-collapse:collapse;
                margin:0 0 22px;
                font-size:15px;
                line-height:1.45;
                border:1px solid #e8e8e8;
            "
        >
            <tr>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                    font-weight:600;
                    width:165px;
                ">
                    Confirmation Number
                </td>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                ">
                    {escape(str(appointment_id))}
                </td>
            </tr>

            {recipient_rows}

            <tr>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                    font-weight:600;
                ">
                    Service
                </td>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                ">
                    {safe_service_name}
                </td>
            </tr>

            <tr>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                    font-weight:600;
                ">
                    Provider
                </td>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                ">
                    {safe_provider_name}
                </td>
            </tr>

            <tr>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                    font-weight:600;
                ">
                    Date
                </td>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                ">
                    {safe_date_display}
                </td>
            </tr>

            <tr>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                    font-weight:600;
                ">
                    Time
                </td>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                ">
                    {safe_time_display}
                </td>
            </tr>

            <tr>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                    font-weight:600;
                ">
                    Duration
                </td>
                <td style="
                    padding:8px 12px;
                    border-bottom:1px solid #e8e8e8;
                ">
                    {int(duration_minutes)} minutes
                </td>
            </tr>

            <tr>
                <td style="
                    padding:8px 12px;
                    font-weight:600;
                ">
                    Price
                </td>
                <td style="padding:8px 12px;">
                    {safe_price_display}
                </td>
            </tr>
        </table>

        <p style="
            margin:0 0 14px;
            font-size:15px;
            line-height:1.6;
        ">
            Please contact {safe_workspace_name}
            directly if you need to make changes to
            the appointment.
        </p>

        <p style="
            margin:0 0 26px;
            font-size:15px;
            line-height:1.6;
        ">
            We look forward to seeing you!
        </p>

        <div style="
            padding-top:18px;
            border-top:1px solid #dddddd;
        ">
            <p style="
                margin:0 0 12px;
                font-size:12px;
                line-height:1.55;
                color:#666666;
            ">
                This email was sent by Peach Suite Pro
                on behalf of {safe_workspace_name}
                regarding your appointment. Please
                review all booking details before
                taking action.
            </p>

            <p style="
                margin:0 0 12px;
                font-size:12px;
                line-height:1.55;
                color:#666666;
            ">
                {assistance_html}
            </p>

            <p style="
                margin:0;
                font-size:12px;
                line-height:1.55;
                color:#666666;
            ">
                Peach Suite Pro provides the online
                booking and business-management
                technology. {safe_workspace_name} is
                responsible for the services,
                appointments, policies, and client
                support.
            </p>
        </div>
    </div>
</body>
</html>
""".strip()

    cur.execute("""
        INSERT INTO email_queue (
            spa_id,
            business_unit_id,
            client_id,
            appointment_id,
            email_type,
            recipient_email,
            recipient_name,
            subject_line,
            text_body,
            html_body,
            status,
            scheduled_for,
            next_attempt_at
        )
        VALUES (
            %s,
            %s,
            %s,
            %s,
            'booking_confirmation',
            %s,
            %s,
            %s,
            %s,
            %s,
            'pending',
            CURRENT_TIMESTAMP,
            CURRENT_TIMESTAMP
        )
        ON CONFLICT DO NOTHING
        RETURNING email_queue_id
    """, (
        spa_id,
        business_unit_id,
        client_id,
        appointment_id,
        recipient_email,
        booked_by_name,
        subject_line,
        text_body,
        html_body
    ))

    queued_row = cur.fetchone()

    if not queued_row:
        return None

    return queued_row[0]


@app.route("/book/<public_booking_slug>")
def public_booking(public_booking_slug):
    return _render_public_booking_page(
        public_booking_slug,
        preview_mode=False
    )







@app.route(
    "/book/<public_booking_slug>/confirm",
    methods=["POST"]
)
def public_booking_confirm(
    public_booking_slug
):
    import hmac
    import re
    from datetime import datetime

    website_color_scheme = "peach_cream"

    public_booking_slug = str(
        public_booking_slug or ""
    ).strip().lower()


    def failure_response(
        message,
        status_code=400,
        service_type_id=None
    ):
        back_arguments = {
            "public_booking_slug":
                public_booking_slug
        }

        if service_type_id:
            back_arguments[
                "service_type_id"
            ] = service_type_id

        return (
            render_template(
                "booking/"
                "public_booking_confirmation.html",
                success=False,
                preview_mode=False,
                website_color_scheme=
                    website_color_scheme,
                message=message,
                back_url=url_for(
                    "public_booking",
                    **back_arguments
                )
            ),
            status_code
        )


    # -----------------------------------------------------
    # Booking-specific CSRF protection.
    # -----------------------------------------------------

    submitted_token = (
        request.form.get("csrf_token")
        or ""
    ).strip()

    token_record = session.get(
        "_public_booking_csrf",
        {}
    )

    expected_token = ""

    if (
        isinstance(token_record, dict)
        and token_record.get("slug")
            == public_booking_slug
    ):
        expected_token = str(
            token_record.get("token")
            or ""
        )


    if (
        not submitted_token
        or not expected_token
        or not hmac.compare_digest(
            submitted_token,
            expected_token
        )
    ):
        return failure_response(
            "Your booking page expired or could not "
            "be verified. Please return to the booking "
            "page and try again.",
            status_code=400
        )


    # Simple honeypot for automated form submissions.
    if (
        request.form.get("website")
        or ""
    ).strip():
        return failure_response(
            "The appointment could not be confirmed.",
            status_code=400
        )


    service_type_id_raw = (
        request.form.get(
            "service_type_id"
        )
        or ""
    ).strip()

    provider_employee_id_raw = (
        request.form.get(
            "provider_employee_id"
        )
        or ""
    ).strip()

    appointment_start_raw = (
        request.form.get(
            "appointment_start"
        )
        or ""
    ).strip()

    first_name = (
        request.form.get("first_name")
        or ""
    ).strip()

    last_name = (
        request.form.get("last_name")
        or ""
    ).strip()

    phone = (
        request.form.get("phone")
        or ""
    ).strip()

    email = (
        request.form.get("email")
        or ""
    ).strip()

    notes = (
        request.form.get("notes")
        or ""
    ).strip()

    service_sms_consent = (
        request.form.get("service_sms_consent")
        == "1"
    )

    marketing_sms_consent = (
        request.form.get("marketing_sms_consent")
        == "1"
    )


    booking_for_other_raw = (
        request.form.get(
            "booking_for_other"
        )
        or "false"
    ).strip().lower()

    guest_first_name = (
        request.form.get(
            "guest_first_name"
        )
        or ""
    ).strip()

    guest_last_name = (
        request.form.get(
            "guest_last_name"
        )
        or ""
    ).strip()


    try:
        service_type_id = int(
            service_type_id_raw
        )

        provider_employee_id = int(
            provider_employee_id_raw
        )
    except (TypeError, ValueError):
        return failure_response(
            "The selected service or provider "
            "is invalid."
        )


    try:
        appointment_start = (
            datetime.fromisoformat(
                appointment_start_raw
            )
        )
    except (TypeError, ValueError):
        return failure_response(
            "The selected appointment time "
            "is invalid.",
            service_type_id=service_type_id
        )


    if appointment_start.tzinfo is not None:
        return failure_response(
            "The selected appointment time "
            "contains an unexpected timezone.",
            service_type_id=service_type_id
        )


    if not first_name or not last_name:
        return failure_response(
            "First and last name are required.",
            service_type_id=service_type_id
        )


    if (
        len(first_name) > 80
        or len(last_name) > 80
    ):
        return failure_response(
            "The client name is too long.",
            service_type_id=service_type_id
        )


    if booking_for_other_raw not in (
        "true",
        "false"
    ):
        return failure_response(
            "The appointment recipient selection "
            "is invalid.",
            service_type_id=service_type_id
        )

    booking_for_other = (
        booking_for_other_raw == "true"
    )

    if (
        booking_for_other
        and (
            not guest_first_name
            or not guest_last_name
        )
    ):
        return failure_response(
            "The guest's first and last name "
            "are required.",
            service_type_id=service_type_id
        )

    if (
        len(guest_first_name) > 80
        or len(guest_last_name) > 80
    ):
        return failure_response(
            "The guest name is too long.",
            service_type_id=service_type_id
        )

    if not booking_for_other:
        guest_first_name = ""
        guest_last_name = ""


    if len(phone) > 30:
        return failure_response(
            "The phone number is too long.",
            service_type_id=service_type_id
        )


    if len(email) > 150:
        return failure_response(
            "The email address is too long.",
            service_type_id=service_type_id
        )


    if len(notes) > 500:
        return failure_response(
            "Appointment notes cannot exceed "
            "500 characters.",
            service_type_id=service_type_id
        )


    normalized_email = (
        _booking_normalize_email(
            email
        )
    )

    normalized_phone = (
        _booking_normalize_phone(
            phone
        )
    )


    if not re.fullmatch(
        r"[^@\s]+@[^@\s]+\.[^@\s]+",
        normalized_email
    ):
        return failure_response(
            "Please enter a valid email address.",
            service_type_id=service_type_id
        )


    if len(normalized_phone) != 10:
        return failure_response(
            "Please enter a valid 10-digit "
            "phone number.",
            service_type_id=service_type_id
        )


    conn = get_db_connection()
    cur = conn.cursor()

    try:
        # Resolve the workspace from the public slug.
        cur.execute("""
            SELECT
                bs.spa_id,
                bs.business_unit_id,
                s.spa_name,
                bu.unit_name
            FROM booking_settings bs

            JOIN business_units bu
              ON bu.business_unit_id =
                    bs.business_unit_id
             AND bu.spa_id = bs.spa_id

            JOIN spas s
              ON s.spa_id = bs.spa_id

            WHERE bs.public_booking_slug = %s
              AND bs.public_booking_enabled = TRUE
              AND bu.is_active = TRUE
              AND s.active = TRUE
            LIMIT 1
        """, (public_booking_slug,))

        booking_row = cur.fetchone()

        if not booking_row:
            conn.rollback()

            return failure_response(
                "Online booking is not currently "
                "available for this business.",
                status_code=404,
                service_type_id=service_type_id
            )


        spa_id = booking_row[0]
        business_unit_id = booking_row[1]

        spa_name = str(
            booking_row[2] or ""
        ).strip()

        unit_name = str(
            booking_row[3] or ""
        ).strip()

        business_name = (
            unit_name
            or spa_name
            or "This business"
        )

        website_color_scheme = "peach_cream"
        include_marketing_sms_consent = False

        cur.execute("""
            SELECT
                website_color_scheme,
                include_marketing_sms_in_10dlc_application
            FROM public_website_settings
            WHERE spa_id = %s
              AND business_unit_id = %s
        """, (
            spa_id,
            business_unit_id,
        ))

        website_setting_row = cur.fetchone()

        if website_setting_row:
            website_color_scheme = str(
                website_setting_row[0]
                or "peach_cream"
            ).strip().lower()

            include_marketing_sms_consent = bool(
                website_setting_row[1]
            )

        # Never accept a forged marketing-consent field
        # when the business has not enabled that option.
        marketing_sms_consent = bool(
            marketing_sms_consent
            and include_marketing_sms_consent
        )


        confirmation = (
            _booking_commit_appointment(
                cur=cur,
                spa_id=spa_id,
                business_unit_id=
                    business_unit_id,
                provider_employee_id=
                    provider_employee_id,
                service_type_id=
                    service_type_id,
                appointment_start=
                    appointment_start,
                first_name=first_name,
                last_name=last_name,
                phone=phone,
                normalized_phone=
                    normalized_phone,
                normalized_email=
                    normalized_email,
                booking_for_other=
                    booking_for_other,
                guest_first_name=
                    guest_first_name,
                guest_last_name=
                    guest_last_name,
                notes=notes,
                require_public=True,
                booking_channel=
                    "public_online"
            )
        )


        if not confirmation.get("success"):
            conn.rollback()

            return failure_response(
                confirmation.get("message")
                or (
                    "The appointment could not "
                    "be confirmed."
                ),
                status_code=confirmation.get(
                    "status_code",
                    400
                ),
                service_type_id=service_type_id
            )


        if service_sms_consent:

            client_id = confirmation["client_id"]

            service_consent_version = (
                "public_service_sms_2026_08_04"
            )

            service_consent_text = (
                "I agree to receive service-related text "
                f"messages from {business_name} at the number "
                "I provided about this appointment, including "
                "appointment confirmations, reminders, "
                "scheduling updates, and cancellations. "
                "Message frequency varies. Message and data "
                "rates may apply. Reply STOP to opt out or "
                "HELP for help. Consent is not a condition "
                "of purchase. Mobile opt-in information will "
                "not be sold or shared with third parties for "
                "promotional or marketing purposes. "
                f"Consent text version: {service_consent_version}."
            )

            cur.execute("""
                UPDATE clients
                SET
                    sms_opt_in = TRUE,
                    sms_opt_out = FALSE,
                    sms_consent_timestamp =
                        CURRENT_TIMESTAMP
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
            """, (
                client_id,
                spa_id,
                business_unit_id
            ))

            cur.execute("""
                INSERT INTO sms_consent_log (
                    spa_id,
                    business_unit_id,
                    client_id,
                    phone_number,
                    consent_given,
                    consent_method,
                    consent_text
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s)
            """, (
                spa_id,
                business_unit_id,
                client_id,
                phone,
                True,
                "public_website_booking_service_checkbox",
                service_consent_text
            ))

            add_consent_record(
                cur=cur,
                spa_id=spa_id,
                client_id=client_id,
                consent_type="SMS",
                consent_status=True,
                consent_source=(
                    "Public Website Booking "
                    "Service SMS Checkbox"
                ),
                consent_note=(
                    "Client voluntarily selected the "
                    "optional service SMS consent checkbox. "
                    f"Consent text version: "
                    f"{service_consent_version}."
                ),
                updated_by=None,
                business_unit_id=business_unit_id
            )


        if marketing_sms_consent:

            client_id = confirmation["client_id"]

            marketing_consent_version = (
                "public_marketing_sms_2026_08_04"
            )

            marketing_consent_text = (
                "I agree to receive recurring promotional "
                f"and marketing text messages from "
                f"{business_name} at the number I provided, "
                "including special offers, service "
                "promotions, skincare tips, and event "
                "announcements. Message frequency varies. "
                "Message and data rates may apply. Reply "
                "STOP to opt out or HELP for help. Consent "
                "is not a condition of purchase. Mobile "
                "opt-in information will not be sold or "
                "shared with third parties for promotional "
                "or marketing purposes. "
                f"Consent text version: "
                f"{marketing_consent_version}."
            )

            cur.execute("""
                UPDATE clients
                SET
                    sms_marketing_status = 'opt_in'
                WHERE client_id = %s
                  AND spa_id = %s
                  AND business_unit_id = %s
            """, (
                client_id,
                spa_id,
                business_unit_id
            ))

            cur.execute("""
                INSERT INTO sms_consent_log (
                    spa_id,
                    business_unit_id,
                    client_id,
                    phone_number,
                    consent_given,
                    consent_method,
                    consent_text
                )
                VALUES (%s, %s, %s, %s, %s, %s, %s)
            """, (
                spa_id,
                business_unit_id,
                client_id,
                phone,
                True,
                "public_website_booking_marketing_checkbox",
                marketing_consent_text
            ))

            add_consent_record(
                cur=cur,
                spa_id=spa_id,
                client_id=client_id,
                consent_type="SMS Marketing",
                consent_status=True,
                consent_source=(
                    "Public Website Booking "
                    "Marketing SMS Checkbox"
                ),
                consent_note=(
                    "Client voluntarily selected the "
                    "separate optional marketing SMS "
                    "consent checkbox. Consent text version: "
                    f"{marketing_consent_version}."
                ),
                updated_by=None,
                business_unit_id=business_unit_id
            )


        conn.commit()


        # -------------------------------------------------
        # Queue the confirmation email only after the
        # appointment transaction has committed.
        #
        # This is a separate transaction so an email queue
        # problem can never undo a confirmed appointment.
        # -------------------------------------------------

        email_queued = False

        try:
            validation = confirmation[
                "validation"
            ]

            queued_email_id = (
                _queue_public_booking_confirmation_email(
                    cur=cur,
                    spa_id=spa_id,
                    business_unit_id=
                        business_unit_id,
                    appointment_id=
                        confirmation[
                            "appointment_id"
                        ],
                    client_id=
                        confirmation[
                            "client_id"
                        ],
                    recipient_email=
                        normalized_email,
                    booked_by_name=
                        confirmation[
                            "booked_by_name"
                        ],
                    appointment_for_name=
                        confirmation[
                            "appointment_for_name"
                        ],
                    booking_for_other=
                        confirmation[
                            "booking_for_other"
                        ],
                    service_name=
                        validation[
                            "service_name"
                        ],
                    provider_name=
                        validation[
                            "provider_name"
                        ],
                    appointment_date=
                        validation[
                            "appointment_date"
                        ],
                    appointment_time=
                        validation[
                            "appointment_time"
                        ],
                    duration_minutes=
                        validation[
                            "duration_minutes"
                        ],
                    price_at_booking=
                        validation[
                            "price_at_booking"
                        ]
                )
            )

            conn.commit()

            if queued_email_id:
                email_queued = True

                app.logger.info(
                    "Public booking confirmation "
                    "email queued. "
                    "appointment_id=%s "
                    "email_queue_id=%s",
                    confirmation[
                        "appointment_id"
                    ],
                    queued_email_id
                )

        except Exception:
            conn.rollback()

            app.logger.exception(
                "Appointment was confirmed, but "
                "the confirmation email could not "
                "be queued. appointment_id=%s",
                confirmation[
                    "appointment_id"
                ]
            )


        # Successful tokens are single-use.
        current_token_record = session.get(
            "_public_booking_csrf",
            {}
        )

        if (
            isinstance(
                current_token_record,
                dict
            )
            and current_token_record.get(
                "slug"
            ) == public_booking_slug
        ):
            session.pop(
                "_public_booking_csrf",
                None
            )


        validation = confirmation[
            "validation"
        ]

        date_display = (
            validation["appointment_date"]
            .strftime("%A, %B %d, %Y")
            .replace(" 0", " ")
        )

        time_display = (
            validation["appointment_time"]
            .strftime("%I:%M %p")
            .lstrip("0")
        )

        price_display = (
            f"${validation['price_at_booking']:,.2f}"
        )


        return render_template(
            "booking/"
            "public_booking_confirmation.html",
            success=True,
            preview_mode=False,

            appointment_id=
                confirmation["appointment_id"],

            client_id=
                confirmation["client_id"],

            client_was_created=
                confirmation[
                    "client_was_created"
                ],

            contact_verification_type=
                confirmation.get(
                    "contact_verification_type"
                ),

            client_name=
                confirmation["booked_by_name"],

            booked_by_name=
                confirmation["booked_by_name"],

            appointment_for_name=
                confirmation[
                    "appointment_for_name"
                ],

            booking_for_other=
                confirmation[
                    "booking_for_other"
                ],

            email_queued=email_queued,

            service_name=
                validation["service_name"],

            provider_name=
                validation["provider_name"],

            date_display=date_display,
            time_display=time_display,

            duration_minutes=
                validation["duration_minutes"],

            price_display=price_display,

            website_color_scheme=
                website_color_scheme,

            back_url=url_for(
                "public_booking",
                public_booking_slug=
                    public_booking_slug
            )
        )

    except Exception:
        conn.rollback()

        app.logger.exception(
            "Public online booking confirmation failed."
        )

        return failure_response(
            "The appointment could not be saved. "
            "No changes were committed.",
            status_code=500,
            service_type_id=service_type_id
        )

    finally:
        cur.close()
        conn.close()




@app.route(
    "/booking/control-center",
    methods=["GET", "POST"]
)
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_control_center():
    spa_id = current_spa_id()
    business_unit_id = (
        current_business_unit_id()
    )
    user_id = session.get("user_id")

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to manage online booking.",
            "error"
        )

        return redirect(
            url_for("calendar_view")
        )

    conn = get_db_connection()
    cur = conn.cursor()

    def get_booking_readiness():
        cur.execute("""
            SELECT
                COUNT(
                    DISTINCT pst.service_type_id
                ) AS service_count,

                COUNT(
                    DISTINCT pst.provider_employee_id
                ) AS provider_count,

                COUNT(*) AS assignment_count

            FROM provider_service_types pst

            JOIN service_name_types snt
              ON snt.service_type_id =
                    pst.service_type_id
             AND snt.spa_id = pst.spa_id

            JOIN employees e
              ON e.employee_id =
                    pst.provider_employee_id
             AND e.spa_id = pst.spa_id

            WHERE pst.spa_id = %s
              AND pst.business_unit_id = %s
              AND pst.is_active = TRUE
              AND pst.is_publicly_bookable = TRUE
              AND snt.is_active = TRUE
              AND e.is_active = TRUE
        """, (
            spa_id,
            business_unit_id
        ))

        public_row = cur.fetchone()

        public_service_count = int(
            public_row[0] or 0
        )

        public_provider_count = int(
            public_row[1] or 0
        )

        public_assignment_count = int(
            public_row[2] or 0
        )


        cur.execute("""
            SELECT COUNT(*)
            FROM booking_business_hours
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND is_active = TRUE
        """, (
            spa_id,
            business_unit_id
        ))

        business_hours_count = int(
            cur.fetchone()[0] or 0
        )


        cur.execute("""
            SELECT COUNT(
                DISTINCT pbh.provider_employee_id
            )
            FROM provider_booking_hours pbh
            WHERE pbh.spa_id = %s
              AND pbh.business_unit_id = %s
              AND pbh.is_active = TRUE

              AND EXISTS (
                    SELECT 1
                    FROM provider_service_types pst
                    WHERE pst.spa_id =
                            pbh.spa_id
                      AND pst.business_unit_id =
                            pbh.business_unit_id
                      AND pst.provider_employee_id =
                            pbh.provider_employee_id
                      AND pst.is_active = TRUE
                      AND pst.is_publicly_bookable = TRUE
              )
        """, (
            spa_id,
            business_unit_id
        ))

        providers_with_hours = int(
            cur.fetchone()[0] or 0
        )


        cur.execute("""
            SELECT COUNT(*)
            FROM provider_time_off
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND is_active = TRUE
              AND ends_at >= CURRENT_TIMESTAMP
        """, (
            spa_id,
            business_unit_id
        ))

        upcoming_time_off_count = int(
            cur.fetchone()[0] or 0
        )


        cur.execute("""
            SELECT COUNT(*)
            FROM appointments
            WHERE spa_id = %s
              AND business_unit_id = %s
              AND booking_channel =
                    'public_online'
              AND appointment_date >= CURRENT_DATE
              AND LOWER(
                    TRIM(
                        COALESCE(status, '')
                    )
                  ) NOT IN (
                    'cancelled',
                    'canceled'
                  )
        """, (
            spa_id,
            business_unit_id
        ))

        upcoming_online_appointments = int(
            cur.fetchone()[0] or 0
        )


        services_ready = (
            public_service_count > 0
        )

        business_hours_ready = (
            business_hours_count > 0
        )

        provider_hours_ready = (
            public_provider_count > 0
            and providers_with_hours
                == public_provider_count
        )

        ready_to_enable = all((
            services_ready,
            business_hours_ready,
            provider_hours_ready
        ))

        return {
            "public_service_count":
                public_service_count,

            "public_provider_count":
                public_provider_count,

            "public_assignment_count":
                public_assignment_count,

            "business_hours_count":
                business_hours_count,

            "providers_with_hours":
                providers_with_hours,

            "upcoming_time_off_count":
                upcoming_time_off_count,

            "upcoming_online_appointments":
                upcoming_online_appointments,

            "services_ready":
                services_ready,

            "business_hours_ready":
                business_hours_ready,

            "provider_hours_ready":
                provider_hours_ready,

            "ready_to_enable":
                ready_to_enable
        }


    try:
        cur.execute("""
            SELECT
                bs.booking_settings_id,
                bs.slot_interval_minutes,
                bs.minimum_booking_notice_hours,
                bs.maximum_booking_days_ahead,
                bs.default_buffer_before_minutes,
                bs.default_buffer_after_minutes,
                bs.allow_any_provider,
                bs.public_booking_enabled,
                bs.public_booking_slug,
                bs.updated_at,

                COALESCE(
                    NULLIF(
                        TRIM(bu.unit_name),
                        ''
                    ),
                    NULLIF(
                        TRIM(s.spa_name),
                        ''
                    ),
                    'Booking Workspace'
                ) AS workspace_name,

                s.spa_name

            FROM booking_settings bs

            JOIN business_units bu
              ON bu.business_unit_id =
                    bs.business_unit_id
             AND bu.spa_id = bs.spa_id

            JOIN spas s
              ON s.spa_id = bs.spa_id

            WHERE bs.spa_id = %s
              AND bs.business_unit_id = %s
            LIMIT 1
        """, (
            spa_id,
            business_unit_id
        ))

        settings_row = cur.fetchone()

        if not settings_row:
            flash(
                "Booking settings were not found "
                "for this workspace.",
                "error"
            )

            return redirect(
                url_for(
                    "booking_availability_test"
                )
            )


        if request.method == "POST":
            errors = []

            def parse_integer(
                field_name,
                field_label,
                minimum_value,
                maximum_value
            ):
                raw_value = (
                    request.form.get(
                        field_name
                    )
                    or ""
                ).strip()

                try:
                    value = int(raw_value)
                except (TypeError, ValueError):
                    errors.append(
                        f"{field_label} must be "
                        f"a whole number."
                    )

                    return None

                if (
                    value < minimum_value
                    or value > maximum_value
                ):
                    errors.append(
                        f"{field_label} must be between "
                        f"{minimum_value} and "
                        f"{maximum_value}."
                    )

                return value


            slot_interval_minutes = parse_integer(
                "slot_interval_minutes",
                "Slot interval",
                5,
                60
            )

            minimum_booking_notice_hours = (
                parse_integer(
                    "minimum_booking_notice_hours",
                    "Minimum booking notice",
                    0,
                    720
                )
            )

            maximum_booking_days_ahead = (
                parse_integer(
                    "maximum_booking_days_ahead",
                    "Maximum booking window",
                    1,
                    365
                )
            )

            default_buffer_before_minutes = (
                parse_integer(
                    "default_buffer_before_minutes",
                    "Default buffer before",
                    0,
                    240
                )
            )

            default_buffer_after_minutes = (
                parse_integer(
                    "default_buffer_after_minutes",
                    "Default buffer after",
                    0,
                    240
                )
            )


            allowed_slot_intervals = {
                5,
                10,
                15,
                20,
                30,
                60
            }

            if (
                slot_interval_minutes is not None
                and slot_interval_minutes
                    not in allowed_slot_intervals
            ):
                errors.append(
                    "Slot interval must be 5, 10, "
                    "15, 20, 30, or 60 minutes."
                )


            allow_any_provider = (
                "allow_any_provider"
                in request.form
            )

            public_booking_enabled = (
                "public_booking_enabled"
                in request.form
            )


            readiness = get_booking_readiness()

            if (
                public_booking_enabled
                and not readiness[
                    "ready_to_enable"
                ]
            ):
                errors.append(
                    "Public booking cannot be enabled "
                    "until public services, business "
                    "hours, and provider hours are ready."
                )


            if errors:
                for error in errors:
                    flash(error, "error")

            else:
                cur.execute("""
                    UPDATE booking_settings
                    SET
                        slot_interval_minutes = %s,
                        minimum_booking_notice_hours = %s,
                        maximum_booking_days_ahead = %s,
                        default_buffer_before_minutes = %s,
                        default_buffer_after_minutes = %s,
                        allow_any_provider = %s,
                        public_booking_enabled = %s,
                        updated_at = CURRENT_TIMESTAMP,
                        updated_by = %s
                    WHERE spa_id = %s
                      AND business_unit_id = %s
                """, (
                    slot_interval_minutes,
                    minimum_booking_notice_hours,
                    maximum_booking_days_ahead,
                    default_buffer_before_minutes,
                    default_buffer_after_minutes,
                    allow_any_provider,
                    public_booking_enabled,
                    user_id,
                    spa_id,
                    business_unit_id
                ))

                conn.commit()

                flash(
                    "Online booking settings saved.",
                    "success"
                )

                return redirect(
                    url_for(
                        "booking_control_center"
                    )
                )


        # Reload after validation or GET.
        cur.execute("""
            SELECT
                bs.booking_settings_id,
                bs.slot_interval_minutes,
                bs.minimum_booking_notice_hours,
                bs.maximum_booking_days_ahead,
                bs.default_buffer_before_minutes,
                bs.default_buffer_after_minutes,
                bs.allow_any_provider,
                bs.public_booking_enabled,
                bs.public_booking_slug,
                bs.updated_at,

                COALESCE(
                    NULLIF(
                        TRIM(bu.unit_name),
                        ''
                    ),
                    NULLIF(
                        TRIM(s.spa_name),
                        ''
                    ),
                    'Booking Workspace'
                ) AS workspace_name,

                s.spa_name

            FROM booking_settings bs

            JOIN business_units bu
              ON bu.business_unit_id =
                    bs.business_unit_id
             AND bu.spa_id = bs.spa_id

            JOIN spas s
              ON s.spa_id = bs.spa_id

            WHERE bs.spa_id = %s
              AND bs.business_unit_id = %s
            LIMIT 1
        """, (
            spa_id,
            business_unit_id
        ))

        settings_row = cur.fetchone()

        settings = {
            "booking_settings_id":
                settings_row[0],

            "slot_interval_minutes":
                settings_row[1],

            "minimum_booking_notice_hours":
                settings_row[2],

            "maximum_booking_days_ahead":
                settings_row[3],

            "default_buffer_before_minutes":
                settings_row[4],

            "default_buffer_after_minutes":
                settings_row[5],

            "allow_any_provider":
                bool(settings_row[6]),

            "public_booking_enabled":
                bool(settings_row[7]),

            "public_booking_slug":
                settings_row[8],

            "updated_at":
                settings_row[9],

            "workspace_name":
                settings_row[10],

            "spa_name":
                settings_row[11]
        }

        readiness = get_booking_readiness()

        public_booking_url = url_for(
            "public_booking",
            public_booking_slug=
                settings[
                    "public_booking_slug"
                ],
            _external=True
        )

        return render_template(
            "booking/"
            "booking_control_center.html",
            settings=settings,
            readiness=readiness,
            public_booking_url=
                public_booking_url
        )

    finally:
        cur.close()
        conn.close()


@app.route("/booking/public-preview")
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_public_preview():
    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to preview public booking.",
            "error"
        )

        return redirect(
            url_for("booking_availability_test")
        )

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        cur.execute("""
            SELECT public_booking_slug
            FROM booking_settings
            WHERE spa_id = %s
              AND business_unit_id = %s
        """, (
            spa_id,
            business_unit_id
        ))

        row = cur.fetchone()

    finally:
        cur.close()
        conn.close()

    if not row:
        flash(
            "Booking settings were not found "
            "for this workspace.",
            "error"
        )

        return redirect(
            url_for("booking_availability_test")
        )

    return _render_public_booking_page(
        row[0],
        preview_mode=True
    )


@app.route("/booking/availability-test")
@login_required
@spa_required
@require_workspace_permission(
    "can_manage_online_booking"
)
def booking_availability_test():
    from datetime import datetime, timedelta

    spa_id = current_spa_id()
    business_unit_id = current_business_unit_id()

    if business_unit_id is None:
        flash(
            "A valid Provider Workspace is required "
            "to test booking availability.",
            "error"
        )

        return redirect(
            url_for("calendar_view")
        )

    spa_now = get_spa_now(spa_id)

    # Availability records use local business wall-clock
    # values stored without timezone information.
    local_now = spa_now.replace(tzinfo=None)

    conn = get_db_connection()
    cur = conn.cursor()

    try:
        # =================================================
        # Booking settings
        # =================================================

        cur.execute("""
            SELECT
                slot_interval_minutes,
                minimum_booking_notice_hours,
                maximum_booking_days_ahead,
                default_buffer_before_minutes,
                default_buffer_after_minutes,
                allow_any_provider,
                public_booking_enabled
            FROM booking_settings
            WHERE spa_id = %s
              AND business_unit_id = %s
        """, (
            spa_id,
            business_unit_id
        ))

        settings_row = cur.fetchone()

        if settings_row:
            settings = {
                "slot_interval_minutes":
                    settings_row[0] or 15,

                "minimum_booking_notice_hours":
                    settings_row[1] or 0,

                "maximum_booking_days_ahead":
                    settings_row[2] or 90,

                "default_buffer_before_minutes":
                    settings_row[3] or 0,

                "default_buffer_after_minutes":
                    settings_row[4] or 0,

                "allow_any_provider":
                    bool(settings_row[5]),

                "public_booking_enabled":
                    bool(settings_row[6])
            }
        else:
            settings = {
                "slot_interval_minutes": 15,
                "minimum_booking_notice_hours": 24,
                "maximum_booking_days_ahead": 90,
                "default_buffer_before_minutes": 0,
                "default_buffer_after_minutes": 0,
                "allow_any_provider": True,
                "public_booking_enabled": False
            }

        minimum_date_value = local_now.date()

        maximum_date_value = (
            minimum_date_value
            + timedelta(
                days=settings[
                    "maximum_booking_days_ahead"
                ]
            )
        )

        # =================================================
        # Services with active provider assignments
        #
        # This is an internal test page, so active
        # assignments are included even when their public
        # booking checkbox is currently disabled.
        # =================================================

        cur.execute("""
            SELECT DISTINCT
                snt.service_type_id,
                snt.service_name
            FROM provider_service_types pst
            JOIN service_name_types snt
              ON snt.service_type_id =
                    pst.service_type_id
             AND snt.spa_id = pst.spa_id
            WHERE pst.spa_id = %s
              AND pst.business_unit_id = %s
              AND pst.is_active = TRUE
              AND snt.is_active = TRUE
            ORDER BY
                snt.service_name
        """, (
            spa_id,
            business_unit_id
        ))

        services = [
            {
                "service_type_id": row[0],
                "service_name": row[1]
            }
            for row in cur.fetchall()
        ]

        # =================================================
        # Providers with active service assignments
        # =================================================

        cur.execute("""
            SELECT DISTINCT
                e.employee_id,

                COALESCE(
                    NULLIF(
                        TRIM(e.employee_nickname),
                        ''
                    ),
                    NULLIF(
                        TRIM(
                            CONCAT_WS(
                                ' ',
                                e.first_name,
                                e.last_name
                            )
                        ),
                        ''
                    ),
                    'Provider ' ||
                        e.employee_id::TEXT
                ) AS provider_name,

                e.employee_nickname,
                e.first_name,
                e.last_name
            FROM provider_service_types pst
            JOIN employees e
              ON e.employee_id =
                    pst.provider_employee_id
             AND e.spa_id = pst.spa_id
            WHERE pst.spa_id = %s
              AND pst.business_unit_id = %s
              AND pst.is_active = TRUE
              AND e.is_active = TRUE
            ORDER BY
                provider_name
        """, (
            spa_id,
            business_unit_id
        ))

        providers = []

        for row in cur.fetchall():
            providers.append({
                "employee_id": row[0],
                "provider_name": row[1],
                "employee_nickname": row[2],
                "first_name": row[3],
                "last_name": row[4]
            })

        # =================================================
        # Request selections
        # =================================================

        selected_service_raw = (
            request.args.get(
                "service_type_id",
                ""
            ).strip()
        )

        selected_provider_raw = (
            request.args.get(
                "provider_employee_id",
                "any"
            ).strip()
            or "any"
        )

        selected_date_raw = (
            request.args.get(
                "booking_date",
                ""
            ).strip()
        )

        show_diagnostics = (
            request.args.get(
                "show_diagnostics",
                ""
            ) == "1"
        )

        public_preview_mode = (
            request.args.get(
                "public_preview",
                ""
            ) == "1"
        )

        searched = bool(
            selected_service_raw
            and selected_date_raw
        )

        selected_service_id = None
        selected_provider_id = (
            "any"
            if selected_provider_raw == "any"
            else None
        )

        selected_date_value = minimum_date_value
        selected_date = minimum_date_value.isoformat()

        selected_service_name = ""
        date_display = ""
        availability_results = []
        total_slot_count = 0
        unassigned_conflict_count = 0

        if selected_service_raw:
            try:
                selected_service_id = int(
                    selected_service_raw
                )
            except (TypeError, ValueError):
                flash(
                    "Invalid service selected.",
                    "error"
                )

                return redirect(
                    url_for(
                        "booking_availability_test"
                    )
                )

        if selected_provider_raw != "any":
            try:
                selected_provider_id = int(
                    selected_provider_raw
                )
            except (TypeError, ValueError):
                flash(
                    "Invalid provider selected.",
                    "error"
                )

                return redirect(
                    url_for(
                        "booking_availability_test"
                    )
                )

        if selected_date_raw:
            try:
                selected_date_value = (
                    datetime.strptime(
                        selected_date_raw,
                        "%Y-%m-%d"
                    ).date()
                )

                selected_date = (
                    selected_date_value.isoformat()
                )

            except ValueError:
                flash(
                    "Invalid booking date selected.",
                    "error"
                )

                return redirect(
                    url_for(
                        "booking_availability_test"
                    )
                )

        if searched:
            if (
                selected_date_value
                < minimum_date_value
                or selected_date_value
                > maximum_date_value
            ):
                flash(
                    "The selected date is outside "
                    "the allowed booking range.",
                    "error"
                )

                return redirect(
                    url_for(
                        "booking_availability_test"
                    )
                )

            service_match = next(
                (
                    service
                    for service in services
                    if service[
                        "service_type_id"
                    ] == selected_service_id
                ),
                None
            )

            if not service_match:
                flash(
                    "The selected service is not "
                    "available for booking.",
                    "error"
                )

                return redirect(
                    url_for(
                        "booking_availability_test"
                    )
                )

            selected_service_name = (
                service_match["service_name"]
            )

            date_display = (
                f"{selected_date_value.strftime('%A, %B')} "
                f"{selected_date_value.day}, "
                f"{selected_date_value.year}"
            )

            day_of_week = (
                selected_date_value.isoweekday()
            )

            day_start = datetime.combine(
                selected_date_value,
                datetime.min.time()
            )

            day_end = (
                day_start
                + timedelta(days=1)
            )

            earliest_allowed_start = (
                local_now
                + timedelta(
                    hours=settings[
                        "minimum_booking_notice_hours"
                    ]
                )
            )

            # =============================================
            # Business operating windows
            # =============================================

            cur.execute("""
                SELECT
                    start_time,
                    end_time
                FROM booking_business_hours
                WHERE spa_id = %s
                  AND business_unit_id = %s
                  AND day_of_week = %s
                  AND is_active = TRUE
                ORDER BY
                    start_time
            """, (
                spa_id,
                business_unit_id,
                day_of_week
            ))

            business_windows = [
                (
                    datetime.combine(
                        selected_date_value,
                        row[0]
                    ),
                    datetime.combine(
                        selected_date_value,
                        row[1]
                    )
                )
                for row in cur.fetchall()
            ]

            # =============================================
            # Provider-service assignments
            # =============================================

            assignment_sql = """
                SELECT
                    pst.provider_employee_id,

                    COALESCE(
                        NULLIF(
                            TRIM(
                                e.employee_nickname
                            ),
                            ''
                        ),
                        NULLIF(
                            TRIM(
                                CONCAT_WS(
                                    ' ',
                                    e.first_name,
                                    e.last_name
                                )
                            ),
                            ''
                        ),
                        'Provider ' ||
                            e.employee_id::TEXT
                    ) AS provider_name,

                    COALESCE(
                        pst.duration_override_minutes,
                        snt.default_duration_minutes
                    ) AS duration_minutes,

                    COALESCE(
                        pst.buffer_before_minutes,
                        %s,
                        0
                    ) AS buffer_before_minutes,

                    COALESCE(
                        pst.buffer_after_minutes,
                        %s,
                        0
                    ) AS buffer_after_minutes

                FROM provider_service_types pst

                JOIN employees e
                  ON e.employee_id =
                        pst.provider_employee_id
                 AND e.spa_id = pst.spa_id

                JOIN service_name_types snt
                  ON snt.service_type_id =
                        pst.service_type_id
                 AND snt.spa_id = pst.spa_id

                WHERE pst.spa_id = %s
                  AND pst.business_unit_id = %s
                  AND pst.service_type_id = %s
                  AND pst.is_active = TRUE
                  AND snt.is_active = TRUE
                  AND e.is_active = TRUE
            """

            assignment_params = [
                settings[
                    "default_buffer_before_minutes"
                ],
                settings[
                    "default_buffer_after_minutes"
                ],
                spa_id,
                business_unit_id,
                selected_service_id
            ]

            if selected_provider_id != "any":
                assignment_sql += """
                  AND pst.provider_employee_id = %s
                """

                assignment_params.append(
                    selected_provider_id
                )

            assignment_sql += """
                ORDER BY
                    provider_name
            """

            cur.execute(
                assignment_sql,
                tuple(assignment_params)
            )

            assignments = [
                {
                    "provider_employee_id": row[0],
                    "provider_name": row[1],
                    "duration_minutes":
                        int(row[2] or 0),

                    "buffer_before_minutes":
                        int(row[3] or 0),

                    "buffer_after_minutes":
                        int(row[4] or 0)
                }
                for row in cur.fetchall()
                if int(row[2] or 0) > 0
            ]

            # =============================================
            # Provider alias map for legacy/imported
            # appointments that do not yet have an
            # employee ID.
            # =============================================

            alias_to_provider_ids = {}

            for provider in providers:
                provider_aliases = {
                    _booking_normalize_name(
                        provider["provider_name"]
                    ),
                    _booking_normalize_name(
                        provider[
                            "employee_nickname"
                        ]
                    ),
                    _booking_normalize_name(
                        provider["first_name"]
                    ),
                    _booking_normalize_name(
                        " ".join(
                            part
                            for part in [
                                provider["first_name"],
                                provider["last_name"]
                            ]
                            if part
                        )
                    )
                }

                for alias in provider_aliases:
                    if not alias:
                        continue

                    alias_to_provider_ids.setdefault(
                        alias,
                        set()
                    ).add(
                        provider["employee_id"]
                    )

            # =============================================
            # Existing blocking appointments
            # =============================================

            cur.execute("""
                SELECT
                    a.appointment_id,
                    a.appointment_time,

                    COALESCE(
                        NULLIF(
                            a.duration_minutes,
                            0
                        ),
                        snt.default_duration_minutes,
                        60
                    ) AS duration_minutes,

                    a.provider_employee_id,
                    a.provider_name_at_booking,

                    COALESCE(
                        pst.buffer_before_minutes,
                        %s,
                        0
                    ) AS buffer_before_minutes,

                    COALESCE(
                        pst.buffer_after_minutes,
                        %s,
                        0
                    ) AS buffer_after_minutes

                FROM appointments a

                LEFT JOIN service_name_types snt
                  ON snt.service_type_id =
                        a.service_type_id
                 AND snt.spa_id = a.spa_id

                LEFT JOIN provider_service_types pst
                  ON pst.spa_id = a.spa_id
                 AND pst.business_unit_id =
                        a.business_unit_id
                 AND pst.provider_employee_id =
                        a.provider_employee_id
                 AND pst.service_type_id =
                        a.service_type_id
                 AND pst.is_active = TRUE

                WHERE a.spa_id = %s
                  AND a.business_unit_id = %s
                  AND a.appointment_date = %s

                  AND LOWER(
                        TRIM(
                            COALESCE(
                                a.status,
                                ''
                            )
                        )
                      ) NOT IN (
                        'cancelled',
                        'canceled',
                        'completed',
                        'no show',
                        'no-show',
                        're-scheduled',
                        'rescheduled'
                      )

                ORDER BY
                    a.appointment_time,
                    a.appointment_id
            """, (
                settings[
                    "default_buffer_before_minutes"
                ],
                settings[
                    "default_buffer_after_minutes"
                ],
                spa_id,
                business_unit_id,
                selected_date_value
            ))

            appointment_blocks = []
            generic_provider_names = {
                "",
                "any",
                "any available",
                "any provider",
                "no preference",
                "unassigned"
            }

            for row in cur.fetchall():
                appointment_time = row[1]

                if appointment_time is None:
                    continue

                appointment_start = (
                    datetime.combine(
                        selected_date_value,
                        appointment_time
                    )
                )

                appointment_end = (
                    appointment_start
                    + timedelta(
                        minutes=int(row[2] or 60)
                    )
                )

                blocked_start = (
                    appointment_start
                    - timedelta(
                        minutes=int(row[5] or 0)
                    )
                )

                blocked_end = (
                    appointment_end
                    + timedelta(
                        minutes=int(row[6] or 0)
                    )
                )

                provider_employee_id = row[3]
                ambiguous_provider = False

                if provider_employee_id is None:
                    normalized_provider_name = (
                        _booking_normalize_name(
                            row[4]
                        )
                    )

                    matched_ids = (
                        alias_to_provider_ids.get(
                            normalized_provider_name,
                            set()
                        )
                    )

                    if (
                        normalized_provider_name
                        in generic_provider_names
                    ):
                        ambiguous_provider = True

                    elif len(matched_ids) == 1:
                        provider_employee_id = next(
                            iter(matched_ids)
                        )

                    else:
                        ambiguous_provider = True

                if ambiguous_provider:
                    unassigned_conflict_count += 1

                appointment_blocks.append({
                    "appointment_id": row[0],
                    "provider_employee_id":
                        provider_employee_id,

                    "ambiguous_provider":
                        ambiguous_provider,

                    "starts_at": blocked_start,
                    "ends_at": blocked_end,

                    "appointment_start":
                        appointment_start,

                    "appointment_end":
                        appointment_end,

                    "buffer_before_minutes":
                        int(row[5] or 0),

                    "buffer_after_minutes":
                        int(row[6] or 0)
                })

            # =============================================
            # Calculate each provider's available slots
            # =============================================

            slot_interval_minutes = max(
                int(
                    settings[
                        "slot_interval_minutes"
                    ]
                    or 15
                ),
                1
            )

            for assignment in assignments:
                provider_employee_id = (
                    assignment[
                        "provider_employee_id"
                    ]
                )

                duration_minutes = (
                    assignment[
                        "duration_minutes"
                    ]
                )

                buffer_before_minutes = (
                    assignment[
                        "buffer_before_minutes"
                    ]
                )

                buffer_after_minutes = (
                    assignment[
                        "buffer_after_minutes"
                    ]
                )

                # -----------------------------------------
                # Provider working windows
                # -----------------------------------------

                cur.execute("""
                    SELECT
                        start_time,
                        end_time
                    FROM provider_booking_hours
                    WHERE spa_id = %s
                      AND business_unit_id = %s
                      AND provider_employee_id = %s
                      AND day_of_week = %s
                      AND is_active = TRUE
                    ORDER BY
                        start_time
                """, (
                    spa_id,
                    business_unit_id,
                    provider_employee_id,
                    day_of_week
                ))

                provider_windows = [
                    (
                        datetime.combine(
                            selected_date_value,
                            row[0]
                        ),
                        datetime.combine(
                            selected_date_value,
                            row[1]
                        )
                    )
                    for row in cur.fetchall()
                ]

                # Provider hours must also fall inside
                # business operating hours.
                working_windows = []

                for (
                    provider_start,
                    provider_end
                ) in provider_windows:

                    for (
                        business_start,
                        business_end
                    ) in business_windows:

                        overlap_start = max(
                            provider_start,
                            business_start
                        )

                        overlap_end = min(
                            provider_end,
                            business_end
                        )

                        if overlap_start < overlap_end:
                            working_windows.append(
                                (
                                    overlap_start,
                                    overlap_end
                                )
                            )

                working_windows = (
                    _booking_merge_windows(
                        working_windows
                    )
                )

                availability_summary_reason = ""

                if not business_windows:
                    availability_summary_reason = (
                        "The business is closed on "
                        "the selected date."
                    )

                elif not provider_windows:
                    availability_summary_reason = (
                        "This provider has no working "
                        "hours on the selected date."
                    )

                elif not working_windows:
                    availability_summary_reason = (
                        "The provider's working hours "
                        "do not overlap the business's "
                        "operating hours."
                    )

                # -----------------------------------------
                # Provider time off and blocked time
                # -----------------------------------------

                cur.execute("""
                    SELECT
                        starts_at,
                        ends_at,
                        block_type,
                        reason
                    FROM provider_time_off
                    WHERE spa_id = %s
                      AND business_unit_id = %s
                      AND provider_employee_id = %s
                      AND is_active = TRUE
                      AND starts_at < %s
                      AND ends_at > %s
                    ORDER BY
                        starts_at
                """, (
                    spa_id,
                    business_unit_id,
                    provider_employee_id,
                    day_end,
                    day_start
                ))

                provider_time_off = [
                    {
                        "starts_at": row[0],
                        "ends_at": row[1],
                        "block_type": row[2],
                        "reason": row[3]
                    }
                    for row in cur.fetchall()
                ]

                provider_appointments = [
                    block
                    for block in appointment_blocks
                    if (
                        block[
                            "ambiguous_provider"
                        ]
                        or block[
                            "provider_employee_id"
                        ] == provider_employee_id
                    )
                ]

                slots = []
                blocked_slots = []
                seen_slot_values = set()

                for (
                    working_start,
                    working_end
                ) in working_windows:

                    earliest_window_start = (
                        working_start
                        + timedelta(
                            minutes=
                                buffer_before_minutes
                        )
                    )

                    candidate_start = (
                        _booking_round_up_to_interval(
                            earliest_window_start,
                            slot_interval_minutes
                        )
                    )

                    while True:
                        service_end = (
                            candidate_start
                            + timedelta(
                                minutes=duration_minutes
                            )
                        )

                        candidate_block_start = (
                            candidate_start
                            - timedelta(
                                minutes=
                                    buffer_before_minutes
                            )
                        )

                        candidate_block_end = (
                            service_end
                            + timedelta(
                                minutes=
                                    buffer_after_minutes
                            )
                        )

                        if (
                            candidate_block_end
                            > working_end
                        ):
                            break

                        blocked_reasons = []

                        if (
                            candidate_start
                            < earliest_allowed_start
                        ):
                            blocked_reasons.append(
                                "Minimum booking notice "
                                "has not been met."
                            )

                        for block in provider_time_off:
                            if not (
                                _booking_intervals_overlap(
                                    candidate_block_start,
                                    candidate_block_end,
                                    block["starts_at"],
                                    block["ends_at"]
                                )
                            ):
                                continue

                            if (
                                block["block_type"]
                                == "blocked_time"
                            ):
                                time_off_label = (
                                    "Meeting or temporary "
                                    "blocked time"
                                )
                            else:
                                time_off_label = (
                                    "Vacation or personal "
                                    "time"
                                )

                            reason_text = str(
                                block["reason"] or ""
                            ).strip()

                            if reason_text:
                                time_off_label += (
                                    f" — {reason_text}"
                                )

                            if (
                                time_off_label
                                not in blocked_reasons
                            ):
                                blocked_reasons.append(
                                    time_off_label
                                )

                        for block in provider_appointments:
                            if not (
                                _booking_intervals_overlap(
                                    candidate_block_start,
                                    candidate_block_end,
                                    block["starts_at"],
                                    block["ends_at"]
                                )
                            ):
                                continue

                            appointment_start_display = (
                                block[
                                    "appointment_start"
                                ]
                                .strftime("%I:%M %p")
                                .lstrip("0")
                            )

                            appointment_end_display = (
                                block[
                                    "appointment_end"
                                ]
                                .strftime("%I:%M %p")
                                .lstrip("0")
                            )

                            if block["ambiguous_provider"]:
                                appointment_label = (
                                    "Unassigned appointment "
                                    f"#{block['appointment_id']} "
                                    "is being treated as "
                                    "blocking all providers"
                                )
                            else:
                                appointment_label = (
                                    "Existing appointment "
                                    f"#{block['appointment_id']}"
                                )

                            appointment_label += (
                                " — "
                                f"{appointment_start_display}"
                                " to "
                                f"{appointment_end_display}"
                            )

                            if (
                                block[
                                    "buffer_before_minutes"
                                ]
                                or block[
                                    "buffer_after_minutes"
                                ]
                            ):
                                appointment_label += (
                                    " including configured "
                                    "buffer time"
                                )

                            if (
                                appointment_label
                                not in blocked_reasons
                            ):
                                blocked_reasons.append(
                                    appointment_label
                                )

                        slot_value = (
                            candidate_start.strftime(
                                "%Y-%m-%dT%H:%M"
                            )
                        )

                        slot_display = (
                            candidate_start
                            .strftime("%I:%M %p")
                            .lstrip("0")
                        )

                        if not blocked_reasons:
                            if (
                                slot_value
                                not in seen_slot_values
                            ):
                                slots.append({
                                    "value": slot_value,
                                    "display": slot_display
                                })

                                seen_slot_values.add(
                                    slot_value
                                )

                        elif show_diagnostics:
                            blocked_slots.append({
                                "value": slot_value,
                                "display": slot_display,
                                "reasons": blocked_reasons
                            })

                        candidate_start += timedelta(
                            minutes=
                                slot_interval_minutes
                        )

                if (
                    not slots
                    and not availability_summary_reason
                ):
                    if provider_time_off:
                        availability_summary_reason = (
                            "The provider is unavailable "
                            "on the selected date."
                        )
                    else:
                        availability_summary_reason = (
                            "Every eligible start time is "
                            "blocked by booking notice or "
                            "an existing appointment."
                        )

                availability_results.append({
                    "provider_employee_id":
                        provider_employee_id,

                    "provider_name":
                        assignment[
                            "provider_name"
                        ],

                    "duration_minutes":
                        duration_minutes,

                    "buffer_before_minutes":
                        buffer_before_minutes,

                    "buffer_after_minutes":
                        buffer_after_minutes,

                    "slots": slots,
                    "blocked_slots": blocked_slots,

                    "has_provider_time_off":
                        bool(provider_time_off),

                    "availability_summary_reason":
                        availability_summary_reason
                })

            total_slot_count = sum(
                len(result["slots"])
                for result in availability_results
            )

        if public_preview_mode:
            cur.execute("""
                SELECT public_booking_slug
                FROM booking_settings
                WHERE spa_id = %s
                  AND business_unit_id = %s
            """, (
                spa_id,
                business_unit_id
            ))

            slug_row = cur.fetchone()

            if not slug_row:
                flash(
                    "Public booking settings were "
                    "not found for this workspace.",
                    "error"
                )

                return redirect(
                    url_for(
                        "booking_public_preview"
                    )
                )

            return _render_public_booking_page(
                slug_row[0],
                preview_mode=True,
                availability_context={
                    "selected_service_id":
                        selected_service_id,

                    "selected_provider_id":
                        selected_provider_id,

                    "selected_date":
                        selected_date,

                    "minimum_date":
                        minimum_date_value
                        .isoformat(),

                    "maximum_date":
                        maximum_date_value
                        .isoformat(),

                    "availability_searched":
                        searched,

                    "availability_results":
                        availability_results,

                    "total_slot_count":
                        total_slot_count,

                    "selected_service_name":
                        selected_service_name,

                    "date_display":
                        date_display
                }
            )

        return render_template(
            "booking/availability_test.html",

            services=services,
            providers=providers,
            settings=settings,

            searched=searched,
            show_diagnostics=show_diagnostics,

            selected_service_id=
                selected_service_id,

            selected_provider_id=
                selected_provider_id,

            selected_date=selected_date,

            selected_service_name=
                selected_service_name,

            date_display=date_display,

            minimum_date=
                minimum_date_value.isoformat(),

            maximum_date=
                maximum_date_value.isoformat(),

            availability_results=
                availability_results,

            total_slot_count=
                total_slot_count,

            unassigned_conflict_count=
                unassigned_conflict_count
        )

    finally:
        cur.close()
        conn.close()


