    try:
        cur.execute("""
            SELECT COUNT(*)
            FROM reminder_queue
            WHERE status = 'pending'
              AND scheduled_for <= NOW()
        """)
        count = cur.fetchone()[0]

        print(f"Pending reminders ready to send: {count}", flush=True)

    finally:
        cur.close()
        conn.close()


