def process_email_automation_queue(
    batch_size=20,
    email_queue_id=None
):
    """
    Process ready messages from the Email Automation Queue.

    email_queue_id may be supplied for a controlled
    one-record test.
    """

    try:
        batch_size = int(batch_size)
    except (TypeError, ValueError):
        batch_size = 20

    batch_size = max(
        1,
        min(batch_size, 100)
    )

    summary = {
        "processed_count": 0,
        "sent_count": 0,
        "retry_count": 0,
        "failed_count": 0
    }


    while (
        summary["processed_count"]
        < batch_size
    ):
        conn = get_db_connection()
        cur = conn.cursor()

        try:
            if email_queue_id is not None:
                cur.execute("""
                    SELECT
                        email_queue_id,
                        spa_id,
                        client_id,
                        appointment_id,
                        email_type,
                        recipient_email,
                        subject_line,
                        text_body,
                        html_body,
                        attempt_count,
                        maximum_attempts
                    FROM email_queue
                    WHERE email_queue_id = %s
                      AND status = 'pending'
                      AND scheduled_for
                            <= CURRENT_TIMESTAMP
                      AND next_attempt_at
                            <= CURRENT_TIMESTAMP
                      AND attempt_count
                            < maximum_attempts
                    FOR UPDATE SKIP LOCKED
                """, (
                    email_queue_id,
                ))

            else:
                cur.execute("""
                    SELECT
                        email_queue_id,
                        spa_id,
                        client_id,
                        appointment_id,
                        email_type,
                        recipient_email,
                        subject_line,
                        text_body,
                        html_body,
                        attempt_count,
                        maximum_attempts
                    FROM email_queue
                    WHERE status = 'pending'
                      AND scheduled_for
                            <= CURRENT_TIMESTAMP
                      AND next_attempt_at
                            <= CURRENT_TIMESTAMP
                      AND attempt_count
                            < maximum_attempts
                    ORDER BY
                        scheduled_for,
                        email_queue_id
                    FOR UPDATE SKIP LOCKED
                    LIMIT 1
                """)

            row = cur.fetchone()

            if not row:
                conn.rollback()
                break

            (
                selected_queue_id,
                spa_id,
                client_id,
                appointment_id,
                email_type,
                recipient_email,
                subject_line,
                text_body,
                html_body,
                previous_attempt_count,
                maximum_attempts
            ) = row

            attempt_count = int(
                previous_attempt_count or 0
            ) + 1

            maximum_attempts = int(
                maximum_attempts or 1
            )

            cur.execute("""
                UPDATE email_queue
                SET
                    status = 'processing',
                    attempt_count = %s,
                    last_attempt_at =
                        CURRENT_TIMESTAMP,
                    error_message = NULL,
                    updated_at =
                        CURRENT_TIMESTAMP
                WHERE email_queue_id = %s
            """, (
                attempt_count,
                selected_queue_id
            ))

            conn.commit()

        except Exception:
            conn.rollback()
            raise

        finally:
            cur.close()
            conn.close()


        sent_successfully = False
        provider_status = None
        provider_message_id = None
        error_message = None

        if email_type == "booking_confirmation":
            final_text_body = (
                str(text_body or "").strip()
            )

            final_html_body = (
                str(html_body or "").strip()
                or None
            )

        else:
            final_text_body = add_email_footer(
                text_body
            )

            # Preserve the existing text-only
            # behavior for all other queue types.
            final_html_body = None

        try:
            response = send_email(
                to=recipient_email,
                subject=subject_line,
                body=final_text_body,
                html_body=final_html_body,
                add_footer=False
            )

            provider_status = str(
                response.status_code
            )

            if (
                200
                <= response.status_code
                < 300
            ):
                sent_successfully = True

                try:
                    response_data = response.json()

                    provider_message_id = (
                        str(
                            response_data.get("id")
                            or ""
                        ).strip()
                        or None
                    )

                except Exception:
                    provider_message_id = None

            else:
                response_text = str(
                    response.text or ""
                ).strip()

                error_message = (
                    f"Mailgun returned HTTP "
                    f"{response.status_code}"
                )

                if response_text:
                    error_message += (
                        f": {response_text[:2000]}"
                    )

        except Exception as exc:
            error_message = (
                f"{type(exc).__name__}: {exc}"
            )[:4000]


        conn = get_db_connection()
        cur = conn.cursor()

        try:
            notes = (
                f"Email Automation Queue "
                f"#{selected_queue_id}; "
                f"appointment_id="
                f"{appointment_id or 'none'}; "
                f"attempt={attempt_count}"
            )

            if sent_successfully:
                cur.execute("""
                    UPDATE email_queue
                    SET
                        status = 'sent',
                        sent_at =
                            CURRENT_TIMESTAMP,
                        provider_message_id = %s,
                        provider_status = %s,
                        text_body = %s,
                        error_message = NULL,
                        updated_at =
                            CURRENT_TIMESTAMP
                    WHERE email_queue_id = %s
                """, (
                    provider_message_id,
                    provider_status,
                    final_text_body,
                    selected_queue_id
                ))

                cur.execute("""
                    INSERT INTO email_send_log (
                        spa_id,
                        client_id,
                        email_type,
                        recipient_email,
                        subject_line,
                        sent_status,
                        sent_date,
                        error_message,
                        notes,
                        sent_at
                    )
                    VALUES (
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        'Sent',
                        CURRENT_TIMESTAMP,
                        NULL,
                        %s,
                        CURRENT_TIMESTAMP
                    )
                """, (
                    spa_id,
                    client_id,
                    email_type,
                    recipient_email,
                    subject_line,
                    notes
                ))

                summary["sent_count"] += 1

            else:
                error_message = (
                    error_message
                    or "Email delivery failed."
                )[:4000]

                retry_available = (
                    attempt_count
                    < maximum_attempts
                )

                if retry_available:
                    cur.execute("""
                        UPDATE email_queue
                        SET
                            status = 'pending',
                            next_attempt_at =
                                CURRENT_TIMESTAMP
                                + (
                                    %s
                                    * INTERVAL '5 minutes'
                                  ),
                            provider_status = %s,
                            error_message = %s,
                            updated_at =
                                CURRENT_TIMESTAMP
                        WHERE email_queue_id = %s
                    """, (
                        attempt_count,
                        provider_status,
                        error_message,
                        selected_queue_id
                    ))

                    summary["retry_count"] += 1

                else:
                    cur.execute("""
                        UPDATE email_queue
                        SET
                            status = 'failed',
                            provider_status = %s,
                            error_message = %s,
                            updated_at =
                                CURRENT_TIMESTAMP
                        WHERE email_queue_id = %s
                    """, (
                        provider_status,
                        error_message,
                        selected_queue_id
                    ))

                    summary["failed_count"] += 1

                cur.execute("""
                    INSERT INTO email_send_log (
                        spa_id,
                        client_id,
                        email_type,
                        recipient_email,
                        subject_line,
                        sent_status,
                        sent_date,
                        error_message,
                        notes,
                        sent_at
                    )
                    VALUES (
                        %s,
                        %s,
                        %s,
                        %s,
                        %s,
                        'Failed',
                        NULL,
                        %s,
                        %s,
                        CURRENT_TIMESTAMP
                    )
                """, (
                    spa_id,
                    client_id,
                    email_type,
                    recipient_email,
                    subject_line,
                    error_message,
                    notes
                ))

            conn.commit()

        except Exception:
            conn.rollback()
            raise

        finally:
            cur.close()
            conn.close()


        summary["processed_count"] += 1

        if email_queue_id is not None:
            break


    return summary



