def scheduled_process_email_automation_queue():
    """
    Scheduled wrapper for the Email Automation Queue.

    Exceptions are contained so one failed scheduler run
    cannot stop the remaining background jobs.
    """

    try:
        summary = process_email_automation_queue(
            batch_size=20
        )

        if summary["processed_count"] > 0:
            print(
                "[EMAIL AUTOMATION] "
                f"Processed: {summary['processed_count']} | "
                f"Sent: {summary['sent_count']} | "
                f"Retry: {summary['retry_count']} | "
                f"Failed: {summary['failed_count']}",
                flush=True
            )

    except Exception:
        app.logger.exception(
            "Scheduled email automation queue "
            "processing failed."
        )

        print(
            "[EMAIL AUTOMATION] "
            "Scheduled processing failed.",
            flush=True
        )


def start_scheduler():
    scheduler = BackgroundScheduler()

    scheduler.add_job(
        scheduled_send_pending_reminders,
        "interval",
        minutes=1,
        id="send_pending_reminders_job",
        replace_existing=True
    )

    scheduler.add_job(
        scheduled_process_email_automation_queue,
        "interval",
        minutes=1,
        id="process_email_automation_queue_job",
        replace_existing=True,
        coalesce=True,
        max_instances=1,
        misfire_grace_time=60
    )

    scheduler.add_job(
        scheduled_generate_birthdays,
        "cron",
        hour=8,
        minute=0,
        id="birthday_reminders_job",
        replace_existing=True
    )

    scheduler.add_job(
        scheduled_process_due_automatic_expenses,
        "interval",
        hours=1,
        id="process_due_automatic_expenses_job",
        replace_existing=True,
        coalesce=True,
        max_instances=1,
        misfire_grace_time=3600,
        next_run_time=datetime.now()
    )


    scheduler.add_job(
        lambda: poll_gmail_for_godaddy_bookings(1),
        "interval",
        minutes=5,
        id="poll_gmail_godaddy_bookings",
        replace_existing=True
    )


    scheduler.start()
    print("Scheduler started.", flush=True)



    log_scheduler("System logging initialized.")











